window.QUIZ_DATA = {"title":"CÂU HỎI TRẮC NGHIỆM TƯ TƯỞNG HỒ CHÍ MINH","chapters":[{"id":"I","title":"KHÁI NIỆM, ĐỐI TƯỢNG, PHƯƠNG PHÁP NGHIÊN CỨU VÀ Ý NGHĨA HỌC TẬP MÔN TƯ TƯỞNG HỒ CHÍ MINH","questions":[{"n":1,"sec":"","stem":"Khái niệm tư tưởng Hồ Chí Minh lần đầu tiên được Đảng ta đưa ra tại Đại hội đại biểu toàn quốc lần thứ mấy?","answer":"A","options":[{"key":"A","text":"Đại hội đại biểu toàn quốc lần thứ VII (1991)"},{"key":"B","text":"Đại hội đại biểu toàn quốc lần thứ X (2006)"},{"key":"C","text":"Đại hội đại biểu toàn quốc lần thứ XI (2011)"},{"key":"D","text":"Đại hội đại biểu toàn quốc lần thứ XII (2016)"}]},{"n":2,"sec":"","stem":"Theo định nghĩa được đưa ra tại Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam ( năm 2011), “tư tưởng Hồ Chí Minh” là?","answer":"D","options":[{"key":"A","text":"Một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam"},{"key":"B","text":"Kết quả của sự vận dụng và phát triển sáng tạo chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta, kế thừa và phát triển các giá trị truyền thống tốt đẹp của dân tộc, tiếp thu tinh hoa văn hóa nhân loại"},{"key":"C","text":"Là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của nhân dân ta giành thắng lợi"},{"key":"D","text":"Cả A, B và C"}]},{"n":3,"sec":"","stem":"Theo Văn kiện Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam ( năm 2011), tư tưởng Hồ Chí Minh được hiểu là gì?","answer":"C","options":[{"key":"A","text":"Là một học thuyết kinh tế chính trị do Hồ Chí Minh sáng lập."},{"key":"B","text":"Là những nhận thức cá nhân mang tính triết lý sống của Chủ tịch Hồ Chí Minh."},{"key":"C","text":"Là một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam"},{"key":"D","text":"Là một trường phái chính trị riêng biệt của Hồ Chí Minh."}]},{"n":4,"sec":"","stem":"Khái niệm: “Tư tưởng Hồ Chí Minh là một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam, kết quả của sự vận dụng và phát triển sáng tạo chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta, kế thừa và phát triển các giá trị truyền thống tốt đẹp của dân tộc, tiếp thu tinh hoa văn hóa nhân loại; là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của nhân dân ta giành thắng lợi” được đưa ra tại Đại hội nào của Đảng Cộng sản Việt Nam?","answer":"C","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ X (2006)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ XI (2011)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ XII (2016)"}]},{"n":5,"sec":"","stem":"Khái niệm “tư tưởng Hồ Chí Minh” được đưa ra tại Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam ( năm 2011) đã làm rõ những nội dung nào sau đây?","answer":"D","options":[{"key":"A","text":"Nêu rõ bản chất khoa học, cách mạng cũng như nội dung cơ bản tư tưởng Hồ Chí Minh"},{"key":"B","text":"Nêu lên cơ sở thành tư tưởng Hồ Chí Minh"},{"key":"C","text":"Nêu lên ý nghĩa của tư tưởng Hồ Chí Minh"},{"key":"D","text":"Cả A, B và C"}]},{"n":6,"sec":"","stem":"Điền từ còn thiếu vào (_____)? ““Tư tưởng Hồ Chí Minh là một hệ thống quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của (_____), kết quả của sự vận dụng và phát triển sáng tạo (_____) vào điều kiện cụ thể của nước ta, kế thừa và phát triển các giá trị truyền thống tốt đẹp của dân tộc, tiếp thu tinh hoa văn hóa nhân loại; là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của nhân dân ta giành thắng lợi” (Đảng Cộng sản Việt Nam (2011), Văn kiện Đại hội Đại biểu toàn quốc lần thứ XI, Nxb Chính trị quốc gia, Hà Nội, 2011, Tr. 88.)","answer":"A","options":[{"key":"A","text":"Cách mạng Việt Nam, chủ nghĩa Mác - Lênin"},{"key":"B","text":"Cách mạng vô sản, chủ nghĩa Mác - Lênin"},{"key":"C","text":"Cách mạng xã hội chủ nghĩa, chủ nghĩa Mác - Lênin"},{"key":"D","text":"Chủ nghĩa Mác - Lênin, cách mạng Việt Nam"}]},{"n":7,"sec":"","stem":"Cơ sở hình thành tư tưởng Hồ Chí Minh là?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa Mác - Lênin, nhân tố chủ quan Hồ Chí Minh, Nho giáo"},{"key":"B","text":"Chủ nghĩa Mác - Lênin, truyền thống dân tộc, nhân tố chủ quan Hồ Chí Minh"},{"key":"C","text":"Chủ nghĩa Mác - Lênin, giá trị truyền thống tốt đẹp của dân tộc, tinh hoa văn hóa nhân loại"},{"key":"D","text":"Chủ nghĩa Mác - Lênin, tinh hoa văn hóa nhân loại, truyền thống yêu nước"}]},{"n":8,"sec":"","stem":"Cơ sở hình thành tư tưởng Hồ Chí Minh KHÔNG bao gồm yếu tố nào sau đây?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa Mác - Lênin"},{"key":"B","text":"Tư tưởng phương Đông và phương Tây"},{"key":"C","text":"Các phong trào cách mạng ở Trung Quốc"},{"key":"D","text":"Truyền thống tốt đẹp của dân tộc"}]},{"n":9,"sec":"","stem":"Theo Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam ( năm 2011), tư tưởng Hồ Chí Minh được hình thành trên cơ sở nào là cơ bản nhất?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa Mác - Lênin"},{"key":"B","text":"Chủ nghĩa dân tộc và truyền thống châu Á"},{"key":"C","text":"Nho giáo và Khổng học"},{"key":"D","text":"Phong trào cách mạng tư sản phương Tây"}]},{"n":10,"sec":"","stem":"Tư tưởng Hồ Chí Minh là kết quả của sự vận dụng và phát triển sáng tạo chủ nghĩa nào?","answer":"D","options":[{"key":"A","text":"Chủ nghĩa tư bản phương Tây"},{"key":"B","text":"Chủ nghĩa dân tộc"},{"key":"C","text":"Chủ nghĩa Khổng Tử"},{"key":"D","text":"Chủ nghĩa Mác - Lênin"}]},{"n":11,"sec":"","stem":"Một trong những nội dung cốt lõi của tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Khẳng định chủ trương phát triển nền kinh tế tư bản hiện đại"},{"key":"B","text":"Ưu tiên tuyệt đối hóa phát triển cá nhân"},{"key":"C","text":"Khẳng định mục tiêu xây dựng một nước Việt Nam hòa bình, độc lập, dân chủ và giàu mạnh"},{"key":"D","text":"Đặt văn hóa lên trên chính trị trong mọi hoàn cảnh"}]},{"n":12,"sec":"","stem":"Theo tư tưởng Hồ Chí Minh, con đường phát triển của dân tộc Việt là gì?","answer":"C","options":[{"key":"A","text":"Phát triển kinh tế thị trường theo mô hình tư bản chủ nghĩa"},{"key":"B","text":"Phát triển độc lập, không theo bất kỳ lý luận nào"},{"key":"C","text":"Độc lập dân tộc gắn liền với chủ nghĩa xã hội"},{"key":"D","text":"Cải cách hành chính song song với giáo dục tri thức"}]},{"n":13,"sec":"","stem":"Nội dung cốt lõi của tư tưởng Hồ Chí Minh là?","answer":"C","options":[{"key":"A","text":"Phát triển kinh tế thị trường theo mô hình tư bản chủ nghĩa"},{"key":"B","text":"Phát triển độc lập, không theo bất kỳ lý luận nào"},{"key":"C","text":"Độc lập dân tộc gắn liền với chủ nghĩa xã hội"},{"key":"D","text":"Cải cách hành chính song song với giáo dục tri thức"}]},{"n":14,"sec":"","stem":"Ý nghĩa của tư tưởng Hồ Chí Minh theo Đại hội XI (2011) được thể hiện rõ nhất ở điểm nào?","answer":"D","options":[{"key":"A","text":"Là lý thuyết nghiên cứu mang tính học thuật đơn thuần"},{"key":"B","text":"Chỉ phù hợp trong bối cảnh chiến tranh"},{"key":"C","text":"Là di sản tư tưởng mang tính văn hóa, không có giá trị thực tiễn"},{"key":"D","text":"Là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta"}]},{"n":15,"sec":"","stem":"Tư tưởng Hồ Chí Minh tiếp thu những yếu tố nào trong quá trình hình thành?","answer":"C","options":[{"key":"A","text":"Chỉ các giá trị văn hóa phương Đông"},{"key":"B","text":"Chủ nghĩa Mác - Lênin và các tôn giáo lớn"},{"key":"C","text":"Chủ nghĩa Mác - Lênin, truyền thống dân tộc và tinh hoa văn hóa nhân loại"},{"key":"D","text":"Văn hóa phương Tây và chủ nghĩa cá nhân"}]},{"n":16,"sec":"","stem":"Tư tưởng Hồ Chí Minh được đánh giá là hệ thống lớn vì lý do nào?","answer":"C","options":[{"key":"A","text":"Bao gồm các chính sách cụ thể về ngân sách quốc gia"},{"key":"B","text":"Chỉ tập trung vào lĩnh vực giáo dục và đào tạo"},{"key":"C","text":"Bao gồm các quan điểm, nguyên tắc, phương pháp về cách mạng Việt Nam ở tầm chiến lược"},{"key":"D","text":"Là hệ thống quản lý hành chính theo hướng hiện đại"}]},{"n":17,"sec":"","stem":"Trong tư tưởng Hồ Chí Minh, mối quan hệ giữa dân tộc và thời đại được nhìn nhận như thế nào?","answer":"D","options":[{"key":"A","text":"Ưu tiên dân tộc, xem nhẹ thời đại"},{"key":"B","text":"Cách ly dân tộc với ảnh hưởng toàn cầu"},{"key":"C","text":"Tự chủ dân tộc nhưng phản đối hội nhập quốc tế"},{"key":"D","text":"Kết hợp sức mạnh dân tộc với sức mạnh thời đại"}]},{"n":18,"sec":"","stem":"Tư tưởng Hồ Chí Minh có vị trí như thế nào trong hệ thống tư tưởng Đảng Cộng sản Việt Nam?","answer":"C","options":[{"key":"A","text":"Là bộ phận rất quan trọng trong hệ thống tư tưởng của Đảng"},{"key":"B","text":"Là bộ phận rất quan trọng trong hệ thống tư tưởng của Đảng"},{"key":"C","text":"Là bộ phận nền tảng, kim chỉ nam cho hành động của Đảng"},{"key":"D","text":"Là một bọ phận trong hệ thống tư tưởng của Đảng"}]},{"n":19,"sec":"","stem":"Đại hội nào của Đảng đã nêu rõ: “Đường lối chính trị, nền nếp làm việc và đạo đức cách mạng của Đảng ta hiện nay là đường lối, tác phong và đạo đức Hồ Chủ tịch... Toàn Đảng hãy ra sức học tập đường lối chính trị, tác phong và đạo đức cách mạng của Hồ Chủ tịch; sự học tập ấy, là điều kiện tiên quyết làm cho Đảng mạnh và làm cho cách mạng đi mau đến thắng lợi hoàn toàn”?","answer":"B","options":[{"key":"A","text":"Đại hội đại biểu lần thứ I của Đảng (3/1935)"},{"key":"B","text":"Đại hội đại biểu lần thứ II của Đảng (2/1951)"},{"key":"C","text":"Đại hội đại biểu lần thứ III của Đảng (9/1960)"},{"key":"D","text":"Đại hội đại biểu lần thứ IV của Đảng (12/1976)"}]},{"n":20,"sec":"","stem":"Đại hội nào của Đảng đã đánh giá: “ Thắng lợi to lớn của sự nghiệp chống Mỹ, cứu nước cũng như những trang sử chói lọi của cách mạng Việt Nam ngót nửa thế kỷ nay mãi mãi gắn liền với tên tuổi của Chủ tịch Hồ Chí Minh, người sáng lập và rèn luyện Đảng ta, người khai sinh nền Cộng hòa Dân chủ Việt Nam, người vun trồng khối đại đoàn kết dân tộc và xây dựng lực lượng vũ trang cách mạng, vị lãnh tụ thiên tài của giai cấp công nhân và nhân dân ta, người anh hùng dân tộc vĩ đại, người chiến sĩ lỗi lạc của phong trào cộng sản và công nhân quốc tế”?","answer":"A","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":21,"sec":"","stem":"Đại hội nào của Đảng nhấn mạnh: “Đảng phải đặc biệt coi trọng việc tổ chức học tập một cách có hệ thống tư tưởng, đạo đức, tác phong của Chủ tịch Hồ Chí Minh trong toàn Đảng”?","answer":"B","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":22,"sec":"","stem":"Đại hội nào của Đảng đã đề ra đường lối đổi mới toàn diện ở nước ta, trong đó nhấn mạnh: “Đảng ta phải nắm vững bản chất cách mạng và khoa học của chủ nghĩa Mác - Lênin, kế thừa di sản quý báu về tư tưởng và lý luận cách mạng của Chủ tịch Hồ Chí Minh”?","answer":"C","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":23,"sec":"","stem":"Đại hội nào của Đảng là một mốc lớn khi nêu cao tư tưởng Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":24,"sec":"","stem":"Đại hội nào của Đảng khẳng định: “Đảng lấy Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động”?","answer":"D","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":25,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Đại hội VII (1991) của Đảng khẳng định: “Đảng lấy Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh làm (_____), (_____)”?","answer":"B","options":[{"key":"A","text":"Nền tảng lý luận, kim chỉ nam cho hành động"},{"key":"B","text":"Nền tảng tư tưởng, kim chỉ nam cho hành động"},{"key":"C","text":"Nền tảng chính trị, kim chỉ nam cho hành động"},{"key":"D","text":"Nền tảng chính trị, kim chỉ nam cho hành động"}]},{"n":26,"sec":"","stem":"“Đảng lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng và kim chỉ nam cho mọi hành động cách mạng”. Câu nói trên được Đảng ta khẳng định lần đầu tiên tại Đại hội đại biểu toàn quốc lần thứ mấy?","answer":"D","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IV (1976)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ V (1982)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"}]},{"n":27,"sec":"","stem":"Nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng và cách mạng Việt Nam là?","answer":"D","options":[{"key":"A","text":"Chủ nghĩa yêu nước"},{"key":"B","text":"Chủ nghĩa Mác – Lênin"},{"key":"C","text":"Tư tưởng Hồ Chí Minh"},{"key":"D","text":"Chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh"}]},{"n":28,"sec":"","stem":"Đại hội nào của Đảng khi đề cập đến tư tưởng Hồ Chí Minh, đã nêu rõ: “Sự nghiệp cách mạng của Đảng và của nhân dân ta 76 năm qua đã khẳng định rằng tư tưởng vĩ đại của Người cùng với chủ nghĩa Mác – Lênin mãi mãi là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng và cách mạng Việt Nam, là tài sản tinh thần vô giá của Đảng và dân tộc ta. Tư tưởng đó đã dẫn dắt chúng ta trên mỗi chặng đường xây dựng và phát triển đất nước, là ngọn cờ thắng lợi của cách mạng Việt Nam, là sức mạnh tập hợp và đoàn kết toàn dân tộc trong sự nghiệp cách mạng của chúng ta hôm nay và mai sau”?","answer":"D","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ VI (1986)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ VII (1991)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ IX (2001)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ X (2006)"}]},{"n":29,"sec":"","stem":"Đại hội nào của Đảng khẳng định quan điểm chỉ đạo là: “Kiên định và vận dụng phát triển sáng tạo chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh”?","answer":"D","options":[{"key":"A","text":"Đại hội Đại biểu toàn quốc lần thứ IX (2001)"},{"key":"B","text":"Đại hội Đại biểu toàn quốc lần thứ X (2006)"},{"key":"C","text":"Đại hội Đại biểu toàn quốc lần thứ XI (2011)"},{"key":"D","text":"Đại hội Đại biểu toàn quốc lần thứ XIII (2021)"}]},{"n":30,"sec":"","stem":"Hồ Chí Minh được Đại hội đồng UNESCO ra Nghị quyết công nhận là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam vào năm nào?","answer":"C","options":[{"key":"A","text":"1969"},{"key":"B","text":"1985"},{"key":"C","text":"1987"},{"key":"D","text":"1990"}]},{"n":31,"sec":"","stem":"Tổ chức Giáo dục, Khoa học và Văn hóa của Liên hợp quốc (UNESCO), tại Khóa họp Đại Hội đồng lần thứ 24 ở Pari, từ ngày 20-10- 1987 đến ngày 20 -11-1987, đã ra Nghị quyết số 24C/18.6.5 về kỷ niệm 100 năm Ngày sinh của Chủ tịch Hồ Chí Minh, theo đó ghi nhận Chủ tịch Hồ Chí Minh là?","answer":"C","options":[{"key":"A","text":"Anh hùng giải phóng dân tộc vĩ đại và doanh nhân văn hóa thế giới"},{"key":"B","text":"Anh hùng giải phóng dân tộc và danh nhân văn hóa kiệt xuất của thế giới"},{"key":"C","text":"Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam"},{"key":"D","text":"Anh hùng dân tộc vĩ đại và Nhà văn hóa kiệt xuất của Việt Nam"}]},{"n":32,"sec":"","stem":"Chọn từ điền vào chỗ trống để hoàn thiện câu: Văn kiện Đại hội XI của Đảng chỉ rõ: Tư tưởng Hồ Chí Minh… cho cuộc đấu tranh của nhân dân ta giành thắng lợi, là …to lớn của Đảng và của dân tộc ta.","answer":"B","options":[{"key":"A","text":"Mở đường; tài sản tinh thần"},{"key":"B","text":"Soi đường; tài sản tinh thần"},{"key":"C","text":"Chỉ đường; tài sản tinh thần"},{"key":"D","text":"Dẫn đường; tài sản tinh thần"}]},{"n":33,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Môn học Tư tưởng Hồ Chí Minh thuộc chuyên ngành nào?","answer":"B","options":[{"key":"A","text":"Lịch sử Đảng"},{"key":"B","text":"Hồ Chí Minh học (nằm trong ngành Khoa học chính trị)"},{"key":"C","text":"Xây dựng Đảng"},{"key":"D","text":"Văn hóa học"}]},{"n":34,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Đối tượng nghiên cứu của môn học tư tưởng Hồ Chí Minh là?","answer":"B","options":[{"key":"A","text":"Lịch sử cách mạng Việt Nam hiện đại"},{"key":"B","text":"Hệ thống quan điểm, tư tưởng Hồ Chí Minh thể hiện trong di sản của Người"},{"key":"C","text":"Các tư tưởng tiến bộ của thế giới"},{"key":"D","text":"Các cuộc kháng chiến chống ngoại xâm"}]},{"n":35,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Ngoài việc nghiên cứu hệ thống quan điểm, tư tưởng của Hồ Chí Minh, môn học còn nghiên cứu điều gì?","answer":"B","options":[{"key":"A","text":"Di sản văn hóa vật thể gắn với Hồ Chí Minh"},{"key":"B","text":"Quá trình vận động và hiện thực hóa tư tưởng của Người trong thực tiễn"},{"key":"C","text":"Những ảnh hưởng của phương Tây đến Hồ Chí Minh"},{"key":"D","text":"Các học thuyết mâu thuẫn với tư tưởng Hồ Chí Minh"}]},{"n":36,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Môn học tư tưởng Hồ Chí Minh có đối tượng nghiên cứu là?","answer":"B","options":[{"key":"A","text":"Hệ thống các quan điểm sáng tạo của chủ nghĩa Mác - Lênin được thể hiện trong di sản của Hồ Chí Minh và quá trình hệ thống quan điểm đó vận động trong thực tiễn cách mạng Việt Nam"},{"key":"B","text":"Hệ thống các quan điểm toàn diện và sâu sắc về những vấn đề cơ bản của cách mạng Việt Nam phản ánh trong toàn bộ di sản của Người và quá trình hệ thống quan điểm đó vận động trong thực tiễn"},{"key":"C","text":"Hệ thống các quan điểm toàn diện và hệ thống về những vấn đề cơ bản của cách mạng tư sản dân quyền phản ánh trong toàn bộ di sản của Người và quá trình hệ thống quan điểm đó vận động trong thực tiễn"},{"key":"D","text":"Cả A, B và C"}]},{"n":37,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Điền từ còn thiếu vào (_____)? Trong quá trình hiện thực hóa hệ thống quan điểm của Hồ Chí Minh, cách mạng Việt Nam luôn (_____) và (_____) sáng tạo hệ thống quan điểm đó trong những điều kiện mới.","answer":"A","options":[{"key":"A","text":"Vận dụng - phát triển"},{"key":"B","text":"Tiếp thu - mô phỏng"},{"key":"C","text":"Bảo tồn - kế thừa"},{"key":"D","text":"Sao chép - áp đặt"}]},{"n":38,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Đâu KHÔNG phải là mục tiêu phấn đấu của Hồ Chí Minh theo tư tưởng của Người?","answer":"C","options":[{"key":"A","text":"Giải phóng dân tộc"},{"key":"B","text":"Giải phóng xã hội"},{"key":"C","text":"Giải phóng cá nhân"},{"key":"D","text":"Giải phóng con người"}]},{"n":39,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Đối tượng nghiên cứu của môn học tư tưởng Hồ Chí Minh KHÔNG bao gồm yếu tố nào sau đây?","answer":"C","options":[{"key":"A","text":"Quá trình vận động và phát triển của tư tưởng Hồ Chí Minh trong thực tiễn"},{"key":"B","text":"Toàn bộ hệ thống quan điểm của Hồ Chí Minh trong di sản của Người"},{"key":"C","text":"Những đóng góp của các nhà lý luận phương Tây vào cách mạng Việt Nam"},{"key":"D","text":"Việc hiện thực hóa tư tưởng Hồ Chí Minh trong cách mạng Việt Nam"}]},{"n":40,"sec":"II – ĐỐI TƯỢNG NGHIÊN CỨU","stem":"Theo nội dung môn học, tư tưởng Hồ Chí Minh phản ánh trong?","answer":"C","options":[{"key":"A","text":"Các nghiên cứu của các nhà sử học Việt Nam"},{"key":"B","text":"Các tác phẩm của chủ nghĩa Mác - Lênin"},{"key":"C","text":"Những bài nói, bài viết, trong hoạt động cách mạng và trong cuộc sống hằng ngày của Hồ Chí Minh"},{"key":"D","text":"Các văn kiện của Đảng từ năm 1986"}]},{"n":41,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Cơ sở phương pháp luận của việc nghiên cứu tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phép biện chứng cổ điển phương Đông"},{"key":"B","text":"Triết học phương Tây hiện đại"},{"key":"C","text":"Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử Mác - Lênin"},{"key":"D","text":"Chủ nghĩa nhân đạo phương Tây"}]},{"n":42,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phương pháp luận của việc nghiên cứu tư tưởng Hồ Chí Minh lấy cơ sở từ đâu?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa xã hội không tưởng và triết học phương Đông"},{"key":"B","text":"Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử Mác - Lênin"},{"key":"C","text":"Chủ nghĩa dân tộc và phong trào giải phóng dân tộc"},{"key":"D","text":"Nho giáo và tư tưởng phương Tây"}]},{"n":43,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Theo phương pháp luận Hồ Chí Minh, việc suy nghĩ và hành động cần đặt trong bối cảnh nào?","answer":"D","options":[{"key":"A","text":"Tình hình quốc tế hiện đại"},{"key":"B","text":"Các quy tắc phổ quát của phương Tây"},{"key":"C","text":"Chỉ trong khuôn khổ lý thuyết Mác – Lênin"},{"key":"D","text":"Điều kiện và hoàn cảnh cụ thể mà Hồ Chí Minh sống và hoạt động"}]},{"n":44,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Một yêu cầu quan trọng khi nghiên cứu tư tưởng Hồ Chí Minh là gì?","answer":"B","options":[{"key":"A","text":"Áp dụng phương pháp tư biện để phân tích sâu sắc"},{"key":"B","text":"Trung thành với phương pháp luận của chủ nghĩa Mác – Lênin và của chính Hồ Chí Minh"},{"key":"C","text":"Ưu tiên cách tiếp cận từ văn hóa phương Tây"},{"key":"D","text":"Dựa vào tài liệu báo chí đương đại để suy diễn"}]},{"n":45,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Có bao nhiêu nguyên tắc phương pháp luận khi nghiên cứu tư tưởng Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"4 nguyên tắc"},{"key":"B","text":"5 nguyên tắc"},{"key":"C","text":"6 nguyên tắc"},{"key":"D","text":"7 nguyên tắc"}]},{"n":46,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Đâu KHÔNG PHẢI cơ sở phương pháp luận của việc nghiên cứu tư tưởng Hồ Chí Minh?","answer":"A","options":[{"key":"A","text":"Phương pháp chuyên ngành, liên ngành"},{"key":"B","text":"Quan điểm kế thừa và phát triển"},{"key":"C","text":"Thống nhất tính đảng và tính khoa học"},{"key":"D","text":"Quan điểm toàn diện và hệ thống"}]},{"n":47,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Đâu là tên của một nguyên tắc và quan điểm phương pháp luận trong nghiên cứu tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Thống nhất tính Đảng và tính nhân dân"},{"key":"B","text":"Quan điểm lịch sử - thực tiễn"},{"key":"C","text":"Thống nhất lý luận và thực tiễn"},{"key":"D","text":"Quan điểm toàn diện và cụ thể"}]},{"n":48,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Một trong những nguyên tắc cơ bản trong phương pháp luận nghiên cứu tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Kết hợp giữa lý thuyết và thực tiễn phương Tây"},{"key":"B","text":"Tôn trọng tuyệt đối tư tưởng phương Đông"},{"key":"C","text":"Thống nhất giữa tính đảng và tính khoa học"},{"key":"D","text":"Dựa hoàn toàn vào cảm nhận cá nhân về tư tưởng"}]},{"n":49,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Nguyên tắc “Thống nhất giữa tính đảng và tính khoa học” trong nghiên cứu tư tưởng Hồ Chí Minh được hiểu như thế nào?","answer":"A","options":[{"key":"A","text":"Phải đứng trên lập trường giai cấp công nhân, đứng trên quan điểm của chủ nghĩa Mác-Lênin, quán triệt cương lĩnh, đường lối, quan điểm của Đảng Cộng sản Việt Nam để nhận thức và phân tích những quan điểm của Hồ Chí Minh"},{"key":"B","text":"Phải đứng trên lập trường của giai cấp bị bóc lột như vô sản và nông dân, quan điểm của chủ nghĩa Mác -Lênin, quan điểm của Đảng Cộng sản Việt Nam và phải đảm bảo tính khách quan, khoa học khi phản bác và luận giải"},{"key":"C","text":"Phải đứng trên lập trường của tầng lớp và giai cấp yếu thế hơn như trí thức hoặc nông dân và quan điểm của chủ nghĩa Mác-Lênin để nhận thức. Đồng thời phải đảm bảo tính khách quan, khoa học khi phân tích, đánh giá"},{"key":"D","text":"Không có đáp án nào đúng"}]},{"n":50,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Vì sao việc thống nhất giữa tính đảng và tính khoa học lại là nguyên tắc cơ bản trong nghiên cứu tư tưởng Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Vì tư tưởng Hồ Chí Minh không thể hiểu được nếu không đứng trên quan điểm cá nhân"},{"key":"B","text":"Vì chỉ có cán bộ Đảng mới hiểu tư tưởng Hồ Chí Minh"},{"key":"C","text":"Vì cần đảm bảo sự lãnh đạo tuyệt đối của Đảng"},{"key":"D","text":"Vì chỉ khi thống nhất tính đảng và tính khoa học thì mới hiểu rõ và sâu sắc tư tưởng Hồ Chí Minh"}]},{"n":51,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Nguyên tắc nào sau đây giúp người nghiên cứu hiểu rõ và sâu sắc tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Sử dụng các học thuyết triết học hiện đại phương Tây"},{"key":"B","text":"Tôn trọng truyền thống dân tộc Việt Nam"},{"key":"C","text":"Thống nhất giữa tính đảng và tính khoa học"},{"key":"D","text":"Chỉ tập trung vào bối cảnh quốc tế"}]},{"n":52,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hồ Chí Minh nhấn mạnh mối quan hệ giữa lý luận và thực tiễn như thế nào?","answer":"B","options":[{"key":"A","text":"Chỉ có thực tiễn mới tạo ra kết quả cách mạng"},{"key":"B","text":"Lý luận sinh ra từ thực tiễn và lại chỉ đạo thực tiễn"},{"key":"C","text":"Lý luận độc lập hoàn toàn với thực tiễn"},{"key":"D","text":"Thực tiễn phải theo lý luận một cách máy móc"}]},{"n":53,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hồ Chí Minh vừa coi trọng lý luận, vừa coi trọng thực tiễn vì?","answer":"D","options":[{"key":"A","text":"Vì lý luận và thực tiễn là hai mặt đối lập không thể dung hòa"},{"key":"B","text":"Vì thực tiễn luôn quan trọng hơn lý luận"},{"key":"C","text":"Vì lý luận là dành cho nghiên cứu, còn thực tiễn là dành cho hành động"},{"key":"D","text":"Vì thực tiễn khái quát nên lý luận và chính lý luận lại chỉ đạo thực tiễn"}]},{"n":54,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Theo Hồ Chí Minh, lý luận chân chính là gì?","answer":"C","options":[{"key":"A","text":"Là lý luận do các nhà triết học phương Tây xây dựng"},{"key":"B","text":"Là lý luận trừu tượng, mang tính khái quát cao"},{"key":"C","text":"Là lý luận rút ra từ thực tế, rồi lại đem kiểm nghiệm trong thực tiễn"},{"key":"D","text":"Là lý luận mang tính chủ quan, do cá nhân tự xây dựng"}]},{"n":55,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hồ Chí Minh phê phán thái độ nào sau đây trong nhận thức và vận dụng lý luận?","answer":"D","options":[{"key":"A","text":"Coi trọng lý luận hơn thực tiễn"},{"key":"B","text":"Học Học thuộc lòng lý luận Mác - Lênin"},{"key":"C","text":"Đưa lý luận vào giáo dục phổ thông"},{"key":"D","text":"“Mắc bệnh khinh lý luận” hoặc “lý luận suông”"}]},{"n":56,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Theo Hồ Chí Minh, nếu chỉ học lý luận mà không thực hành, con người sẽ giống như gì?","answer":"C","options":[{"key":"A","text":"Một chiến sĩ chưa qua huấn luyện"},{"key":"B","text":"Một người đi trong đêm"},{"key":"C","text":"Một cái hòm đựng sách"},{"key":"D","text":"Một cái máy thiếu nhiên liệu"}]},{"n":57,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Câu nói nào sau đây thể hiện rõ quan điểm của Hồ Chí Minh về lý luận và thực tiễn?","answer":"B","options":[{"key":"A","text":"“Lý luận phải độc lập với thực tiễn mới chính xác”"},{"key":"B","text":"“Lý luận như cái tên, thực hành như cái đích để bắn”"},{"key":"C","text":"“Không có thực tiễn, lý luận vẫn là chân lý”"},{"key":"D","text":"“Chỉ lý luận mới tạo ra hành động cách mạng”"}]},{"n":58,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Theo Hồ Chí Minh, điều gì xảy ra nếu không có lý luận dẫn đường?","answer":"C","options":[{"key":"A","text":"Con người sẽ dễ trở nên cực đoan"},{"key":"B","text":"Cách mạng sẽ chậm phát triển"},{"key":"C","text":"Lúng túng như nhắm mắt mà đi"},{"key":"D","text":"Không học lý luận thì không làm được nhà khoa học"}]},{"n":59,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Luận điểm: “Có kinh nghiệm mà không có lý luận, cũng như một mắt sáng, một mắt mờ” của Hồ Chí Minh nói lên điều gì?","answer":"D","options":[{"key":"A","text":"Nhấn mạnh vai trò của thực tiễn"},{"key":"B","text":"Nhấn mạnh sự thống nhất giữa lý luận và thực tiễn"},{"key":"C","text":"Chỉ ra căn bệnh “lý luận suông”"},{"key":"D","text":"Nhấn mạnh vai trò của lý luận"}]},{"n":60,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Điền từ còn thiếu vào (_____)? Về lý luân, Người cho rằng: “Lý luận là đem (_____) trong lịch sử, trong kinh nghiệm, trong các cuộc tranh đấu, xem xét, so sánh thật kỹ lưỡng rõ ràng, làm thành kết luận. Rồi lại đem nó chứng minh với thực tế. Đó là lý luận chân chính. Lý luận như cái kim chỉ nam, nó chỉ phương hướng cho chúng ta trong công việc thực tế. Không có lý luận thì lúng túng như nhắm mắt mà đi” (Hồ Chí Minh: Toàn tập, Nxb. Chính trị Quốc gia, Hà Nội, 2011, t.5, tr.273)","answer":"B","options":[{"key":"A","text":"Giá trị"},{"key":"B","text":"Thực tế"},{"key":"C","text":"Bài học"},{"key":"D","text":"Sự kiện"}]},{"n":61,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Theo Hồ Chí Minh, học chủ nghĩa Mác – Lênin để làm gì?","answer":"B","options":[{"key":"A","text":"Học thuộc các luận điểm lý luận"},{"key":"B","text":"Để phân tích và giải quyết các vấn đề cụ thể của cách mạng Việt Nam"},{"key":"C","text":"Để nâng cao trình độ của bản thân"},{"key":"D","text":"Để có phương pháp làm việc khoa học"}]},{"n":62,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Điền từ còn thiếu vào (_____)? Cùng với chủ nghĩa duy vật biện chứng, cần vận dụng (_____) vào việc nghiên cứu tư tưởng Hồ Chí Minh.","answer":"C","options":[{"key":"A","text":"Chủ nghĩa yêu nước"},{"key":"B","text":"Chủ nghĩa duy vật cách mạng"},{"key":"C","text":"Chủ nghĩa duy vật lịch sử"},{"key":"D","text":"Chủ nghĩa cộng sản"}]},{"n":63,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Trong nghiên cứu Tư tưởng Hồ Chí Minh, quan điểm lịch sử - cụ thể yêu cầu điều gì?","answer":"C","options":[{"key":"A","text":"Chỉ xem xét tư tưởng Hồ Chí Minh trong điều kiện hiện tại"},{"key":"B","text":"Tách rời tư tưởng Hồ Chí Minh ra khỏi bối cảnh lịch sử"},{"key":"C","text":"Xem xét tư tưởng Hồ Chí Minh trong quá trình hình thành, phát triển và đổi mới qua các giai đoạn lịch sử"},{"key":"D","text":"Đánh giá tư tưởng Hồ Chí Minh theo cảm tính cá nhân"}]},{"n":64,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Ai là người có quan điểm phương pháp luận sâu sắc về việc xem xét sự vật trong mối quan hệ lịch sử - cụ thể?","answer":"C","options":[{"key":"A","text":"Các nhà Khổng học cổ đại"},{"key":"B","text":"Friedrich Nietzsche"},{"key":"C","text":"V.I. Lênin"},{"key":"D","text":"Adam Smith"}]},{"n":65,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Nắm vững quan điểm lịch sử - cụ thể giúp người học Tư tưởng Hồ Chí Minh đạt được điều gì?","answer":"A","options":[{"key":"A","text":"Nhận thức rõ được bản chất cách mạng, sáng tạo của tư tưởng Hồ Chí Minh trong từng giai đoạn"},{"key":"B","text":"Chỉ tiếp cận ngôn ngữ tư tưởng"},{"key":"C","text":"Chỉ nhìn thấy sự ảnh hưởng của Nho giáo trong tư tưởng Hồ Chí Minh"},{"key":"D","text":"Tập trung vào tư tưởng Hồ Chí Minh như một hiện tượng tôn giáo"}]},{"n":66,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Quan điểm toàn diện và hệ thống trong nghiên cứu Tư tưởng Hồ Chí Minh yêu cầu điều gì?","answer":"B","options":[{"key":"A","text":"Nghiên cứu các bộ phận của tư tưởng một cách riêng lẻ, độc lập"},{"key":"B","text":"Xem xét tư tưởng Hồ Chí Minh như một hệ thống thống nhất, gắn kết giữa các yếu tố"},{"key":"C","text":"Chỉ tập trung vào yếu tố cốt lõi là độc lập dân tộc"},{"key":"D","text":"Phân tích tư tưởng Hồ Chí Minh từ các khía cạnh tâm linh"}]},{"n":67,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Điều gì sẽ xảy ra nếu tách rời một yếu tố trong tư tưởng Hồ Chí Minh khỏi tổng thể hệ thống?","answer":"C","options":[{"key":"A","text":"Làm cho tư tưởng đó trở nên khách quan hơn"},{"key":"B","text":"Có thể giúp hiểu sâu sắc yếu tố đó hơn"},{"key":"C","text":"Dẫn đến hiểu sai lệch, phiến diện tư tưởng Hồ Chí Minh"},{"key":"D","text":"Giúp hệ thống tư tưởng trở nên linh hoạt hơn"}]},{"n":68,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Tư tưởng Hồ Chí Minh đặt trọng tâm vào vấn đề gì trong hệ thống các mối quan hệ cách mạng?","answer":"C","options":[{"key":"A","text":"Vấn đề ngoại giao và liên minh quân sự"},{"key":"B","text":"Vấn đề địa lý chiến lược"},{"key":"C","text":"Mối quan hệ giữa dân tộc và giai cấp"},{"key":"D","text":"Mối quan hệ giữa tín ngưỡng và tôn giáo"}]},{"n":69,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hạt nhân cốt lõi của hệ thống tư tưởng Hồ Chí Minh là gì?","answer":"D","options":[{"key":"A","text":"Tình yêu thiên nhiên và hòa bình"},{"key":"B","text":"Tư tưởng trung dung, ôn hòa"},{"key":"C","text":"Tư tưởng tập quyền và kiểm soát"},{"key":"D","text":"Tư tưởng độc lập, tự do, dân chủ và chủ nghĩa xã hội"}]},{"n":70,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Tư tưởng Hồ Chí Minh giúp giải quyết các mối quan hệ cách mạng Việt Nam như thế nào?","answer":"A","options":[{"key":"A","text":"Theo cách biện chứng, phù hợp từng thời kỳ"},{"key":"B","text":"Theo tư duy tách biệt, phi lịch sử"},{"key":"C","text":"Theo các chỉ đạo cứng nhắc từ quốc tế"},{"key":"D","text":"Theo cách cứng nhắc, công thức"}]},{"n":71,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Trong quan điểm toàn diện và hệ thống, khi xem xét một vấn đề, Hồ Chí Minh thường làm gì?","answer":"B","options":[{"key":"A","text":"Giao phó cho quần chúng tự quyết định"},{"key":"B","text":"Xem xét tổng thể, xác định trọng điểm theo từng thời kỳ"},{"key":"C","text":"Chỉ nhìn vào yếu tố chủ quan"},{"key":"D","text":"Chỉ chú trọng phần kết quả cuối cùng"}]},{"n":72,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Quan điểm kế thừa và phát triển trong tư tưởng Hồ Chí Minh nhấn mạnh điều gì?","answer":"C","options":[{"key":"A","text":"Luôn tuân thủ tuyệt đối tư tưởng cũ"},{"key":"B","text":"Không thay đổi tư tưởng để giữ tính ổn định"},{"key":"C","text":"Biết kế thừa, vận dụng và phát triển sáng tạo tư tưởng của Người trong điều kiện lịch sử mới, trong bối cảnh cụ thể của đất nước và quốc tế"},{"key":"D","text":"Chỉ học thuộc lòng tư tưởng Hồ Chí Minh"}]},{"n":73,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phương pháp luận Hồ Chí Minh cho rằng, con người phải luôn luôn thích nghi với mọi hoàn cảnh. Muốn thích nghi, thì cần làm gì?","answer":"A","options":[{"key":"A","text":"Luôn luôn tự đổi mới để phát triển"},{"key":"B","text":"Giữ nguyên cách sống cũ"},{"key":"C","text":"Tránh tiếp xúc với sự thay đổi"},{"key":"D","text":"Phụ thuộc vào người khác để thích nghi"}]},{"n":74,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hồ Chí Minh nhìn nhận sự vật và hiện tượng như thế nào?","answer":"C","options":[{"key":"A","text":"Là những thứ bất biến"},{"key":"B","text":"Luôn ổn định và không thay đổi"},{"key":"C","text":"Luôn vận động, biến đổi không ngừng"},{"key":"D","text":"Có thể bị đóng khung theo khuôn mẫu"}]},{"n":75,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Hồ Chí Minh cho rằng, để phát triển bền vững, con ng ười cần làm gì?","answer":"D","options":[{"key":"A","text":"Giữ lại tất cả truyền thống cũ"},{"key":"B","text":"Chống lại sự thay đổi"},{"key":"C","text":"Tập trung vào phát triển kinh tế là đủ"},{"key":"D","text":"Giải phóng mọi trở lực, trở lực bên ngoài, trở lực bên trong, thậm chí trở lực nằm ngay trong mỗi con người"}]},{"n":76,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phát triển trong tư tưởng Hồ Chí Minh là quá trình như thế nào?","answer":"A","options":[{"key":"A","text":"Là quá trình khẳng định cái mới, phủ định cái cũ"},{"key":"B","text":"Phát triển một chiều, không cần phủ định"},{"key":"C","text":"Là quá trình bảo tồn cái cũ"},{"key":"D","text":"Chỉ phát triển dựa trên lý luận của người khác"}]},{"n":77,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Một số phương pháp chủ yếu thường được sử dụng để nghiên cứu tư tưởng Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Phương pháp lôgíc, phương pháp lịch sử và sự kết hợp hai phương pháp này"},{"key":"B","text":"Phương pháp phân tích văn bản kết hợp với nghiên cứu hoạt động thực tiễn của Hồ Chí Minh"},{"key":"C","text":"Phương pháp chuyên ngành, liên ngành"},{"key":"D","text":"Cả A, B và C"}]},{"n":78,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Một trong những phương pháp quan trọng khi nghiên cứu tư tưởng Hồ Chí Minh là?","answer":"A","options":[{"key":"A","text":"Phương pháp phân tích văn bản kết hợp nghiên cứu hoạt động thực tiễn của Hồ Chí Minh"},{"key":"B","text":"Phương pháp phân tích văn bản"},{"key":"C","text":"Phương pháp kết hợp nghiên cứu hoạt động thực tiễn của Hồ Chí Minh"},{"key":"D","text":"Phương pháp logic"}]},{"n":79,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phương pháp lôgíc có vai trò gì trong nghiên cứu tư tưởng Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Trình bày các sự kiện theo thời gian"},{"key":"B","text":"Đưa ra cảm nhận cá nhân về tư tưởng"},{"key":"C","text":"Chỉ dùng để phân tích văn bản"},{"key":"D","text":"Nghiên cứu một cách tổng quát nhằm tìm ra được bản chất vốn có của sự vật, hiện tượng và khái quát thành lý luận"}]},{"n":80,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phương pháp lịch sử được vận dụng trong nghiên cứu tư tưởng Hồ Chí Minh nhằm?","answer":"A","options":[{"key":"A","text":"Nghiên cứu sự vật và hiện tượng theo trình tự thời gian, quá trình diễn biến đi từ phát sinh, phát triển đến hệ quả của nó"},{"key":"B","text":"Gạt bỏ yếu tố thời gian để tiếp cận bản chất"},{"key":"C","text":"Phân tích sự vật theo logic toán học"},{"key":"D","text":"Nhấn mạnh yếu tố cảm tính trong nghiên cứu"}]},{"n":81,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Vì sao cần kết hợp phương pháp lôgíc và phương pháp lịch sử khi nghiên cứu tư tưởng Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Vì chúng là hai phương pháp đối lập nhau"},{"key":"B","text":"Vì chỉ dùng một phương pháp là chưa đủ để hiểu hết tư tưởng của Người"},{"key":"C","text":"Vì không thể dùng phương pháp nào trong thực tế"},{"key":"D","text":"Vì cả hai chỉ có ý nghĩa tượng trưng"}]},{"n":82,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Một phương pháp quan trọng khác trong nghiên cứu tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phân tích tâm linh và tín ngưỡng của Người"},{"key":"B","text":"Phân tích các công trình nghiên cứu nước ngoài"},{"key":"C","text":"Phân tích văn bản kết hợp với nghiên cứu hoạt động thực tiễn của Hồ Chí Minh"},{"key":"D","text":"Tập trung vào lời kể truyền miệng từ nhân dân"}]},{"n":83,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Tư tưởng Hồ Chí Minh còn có vai trò như thế nào sau khi Người qua đời?","answer":"B","options":[{"key":"A","text":"Không còn giá trị vì điều kiện xã hội đã thay đổi"},{"key":"B","text":"Có vai trò làm nền tảng tư tưởng và kim c hỉ nam cho hành động của toàn Đảng, toàn dân phấn đấu cho mục tiêu của cách mạng Việt Nam"},{"key":"C","text":"Chỉ còn giá trị lịch sử, không có tính định hướng"},{"key":"D","text":"Chỉ nên nghiên cứu trong khuôn khổ học thuật"}]},{"n":84,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Tư tưởng Hồ Chí Minh không những cần thiết trong hành trang của dân tộc Việt Nam ở thế kỷ XX mà còn?","answer":"B","options":[{"key":"A","text":"Có ảnh hưởng đến một số nước láng giềng"},{"key":"B","text":"Tiếp tục đi với dân tộc Việt Nam ở thế kỷ XXI và các thế kỷ tiếp theo; không những góp phần thúc đẩy sự phát triển tiến bộ, văn minh của nhân loại trong những thời kỳ trước đây mà còn cả trong tương lai"},{"key":"C","text":"Chỉ áp dụng cho thế kỷ XX"},{"key":"D","text":"Không còn giá trị trong bối cảnh toàn cầu hóa"}]},{"n":85,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Vì sao cần sử dụng phương pháp chuyên ngành và liên ngành trong nghiên cứu tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Vì tư tưởng Hồ Chí Minh chủ yếu là tư tưởng quân sự"},{"key":"B","text":"Vì Hồ Chí Minh không có hệ thống tư tưởng rõ ràng"},{"key":"C","text":"Vì Hồ Chí Minh thể hiện tư tưởng của mình thông qua nhiều lĩnh vực như chính trị, triết học, kinh tế, văn hóa, quân sự, v.v."},{"key":"D","text":"Vì các tác phẩm của Hồ Chí Minh rất khó hiểu"}]},{"n":86,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Để nghiên cứu tư tưởng Hồ Chí Minh đạt được trình độ khoa học ngày một cao hơn, cần phải làm gì?","answer":"D","options":[{"key":"A","text":"Dùng duy nhất phương pháp phân tích văn bản"},{"key":"B","text":"Giữ nguyên các phương pháp cũ, không thay đổi"},{"key":"C","text":"Chỉ sử dụng phương pháp của ngành triết học"},{"key":"D","text":"Đổi mới và hiện đại hóa các phương pháp nghiên cứu trên cơ sở không ngừng phát triển và hoàn thiện về lý luận và phương pháp luận khoa học nói chung"}]},{"n":87,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Phương pháp nghiên cứu cụ thể trong nghiên cứu tư tưởng Hồ Chí Minh cần dựa vào yếu tố nào?","answer":"C","options":[{"key":"A","text":"Sở thích cá nhân của người nghiên cứu"},{"key":"B","text":"Tính ngẫu nhiên và linh hoạt"},{"key":"C","text":"Yêu cầu nghiên cứu nội dung cụ thể của tư tưởng Hồ Chí Minh"},{"key":"D","text":"Các phương pháp được sử dụng trong các ngành khoa học tự nhiên"}]},{"n":88,"sec":"III – PHƯƠNG PHÁP NGHIÊN CỨU","stem":"Tại sao cần áp dụng các phương pháp phân tích, tổng hợp, so sánh trong nghiên cứu tư tưởng Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Vì đây là những phương pháp dễ áp dụng"},{"key":"B","text":"Vì chỉ có các phương pháp này mới giúp hiểu được tư tưởng Hồ Chí Minh"},{"key":"C","text":"Vì chúng là các phương pháp phổ biến t rong nghiên cứu văn học, lịch sử"},{"key":"D","text":"Vì chúng giúp tiếp cận nội dung tư tưởng Hồ Chí Minh một cách logic, hệ thống, khoa học"}]},{"n":89,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Học tập môn học Tư tưởng Hồ Chí Minh góp phần nâng cao năng lực nào dưới đây?","answer":"B","options":[{"key":"A","text":"Năng lực hoạt động thể chất"},{"key":"B","text":"Năng lực tư duy lý luận"},{"key":"C","text":"Năng lực kinh doanh"},{"key":"D","text":"Năng lực lao động sản xuất"}]},{"n":90,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Một trong những ý nghĩa của việc học tập tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Góp phần mở rộng thị trường kinh tế quốc tế"},{"key":"B","text":"Giúp sinh viên tiếp cận khoa học công nghệ hiện đại"},{"key":"C","text":"Giáo dục và định hướng thực hành đạo đức cách mạng, củng cố niềm tin khoa học gắn liền với trau dồi tình cảm cách mạng, bồi dưỡng lòng yêu nước cho sinh viên"},{"key":"D","text":"Tăng cường hợp tác với các nước tư bản phát triển"}]},{"n":91,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Học tập môn Tư tưởng Hồ Chí Minh giúp sinh viên?","answer":"B","options":[{"key":"A","text":"Trở thành doanh nhân thành đạt"},{"key":"B","text":"Biết phê phán, đấu tranh với các quan điểm sai trái để bảo vệ sự trong sáng của chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh, đường lối, chủ trương của Đảng, chính sách, pháp luật của Nhà nước"},{"key":"C","text":"Lựa chọn ngành nghề phù hợp với bản thân"},{"key":"D","text":"Phát triển kỹ năng làm việc nhóm"}]},{"n":92,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Theo nội dung học tập, môn Tư tưởng Hồ Chí Minh giúp sinh viên hình thành?","answer":"C","options":[{"key":"A","text":"Tư duy phản biện xã hội hiện đại"},{"key":"B","text":"Năng lực lãnh đạo trong doanh nghiệp"},{"key":"C","text":"Phương pháp làm việc, niềm tin và tình cảm cách mạng"},{"key":"D","text":"Kỹ năng ngoại ngữ chuyên ngành"}]},{"n":93,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Mục tiêu cao cả của đất nước theo tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Trở thành nước công nghiệp phát triển theo hướng hiện đại hóa"},{"key":"B","text":"Xây dựng một xã hội có nền văn hóa truyền thống"},{"key":"C","text":"Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"D","text":"Trở thành trung tâm kinh tế khu vực châu Á"}]},{"n":94,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Việc học môn Tư tưởng Hồ Chí Minh trang bị cho sinh viên điều gì?","answer":"A","options":[{"key":"A","text":"Tri thức khoa học về hệ thống quan điểm toàn diện và sâu sắc về cách mạng Việt Nam"},{"key":"B","text":"Kỹ năng công nghệ thông tin ứng dụng"},{"key":"C","text":"Năng lực quản lý tài chính cá nhân"},{"key":"D","text":"Kỹ năng lãnh đạo trong tổ chức đoàn thể"}]},{"n":95,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Môn học tư tưởng Hồ Chí Minh góp phần củng cố cho sinh viên điều gì?","answer":"D","options":[{"key":"A","text":"Khả năng tư duy phản biện xã hội hiện đại"},{"key":"B","text":"Kỹ năng hội nhập quốc tế"},{"key":"C","text":"Kiến thức chuyên sâu về lĩnh vực khoa học tự nhiên"},{"key":"D","text":"Lập trường, quan điểm cách mạng trên nền tảng chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh"}]},{"n":96,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Mong muốn cuối cùng của Chủ tịch Hồ Chí Minh, toàn Đảng, toàn dân ta cần phấn đấu xây dựng đất nước như thế nào?","answer":"C","options":[{"key":"A","text":"Trở thành quốc gia hàng đầu khu vực Đông Nam Á"},{"key":"B","text":"Trở thành quốc gia có nền công nghiệp phát triển"},{"key":"C","text":"Hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"D","text":"Nền kinh tế tri thức phát triển vượt bậc"}]},{"n":97,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Qua nghiên cứu môn học Tư tưởng Hồ Chí Minh, người học có điều kiện hiểu biết về?","answer":"A","options":[{"key":"A","text":"Cuộc đời và sự nghiệp của Hồ Chí Minh"},{"key":"B","text":"Các chiến lược phát triển kinh tế của các nước phát triển"},{"key":"C","text":"Các mô hình giáo dục phương Tây hiện đại"},{"key":"D","text":"Kỹ năng quản lý tài chính cá nhân"}]},{"n":98,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Môn học Tư tưởng Hồ Chí Minh giúp sinh viên có điều kiện thực hành điều gì trong cuộc sống?","answer":"B","options":[{"key":"A","text":"Đạo đức nghề nghiệp trong môi trường doanh nghiệp quốc tế"},{"key":"B","text":"Đạo đức cách mạng, chống chủ nghĩa cá nhân"},{"key":"C","text":"Kỹ năng giao tiếp bằng tiếng Anh trong công việc"},{"key":"D","text":"Phát triển các mô hình khởi nghiệp sáng tạo"}]},{"n":99,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Việc học tập tư tưởng Hồ Chí Minh giúp sinh viên nâng cao điều gì trong đời sống chính trị?","answer":"C","options":[{"key":"A","text":"Khả năng tranh luận chính trị đa chiều"},{"key":"B","text":"Sự hiểu biết về các chế độ chính trị phương Tây"},{"key":"C","text":"Bản lĩnh chính trị và trách nhiệm công dân"},{"key":"D","text":"Tư duy phản biện trong phân tích chính sách"}]},{"n":100,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Thông qua nghiên cứu môn học tư tưởng Hồ Chí Minh, sinh viên thường xuyên tu dưỡng, rèn luyện bản thân mình theo?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa tư bản hiện đại"},{"key":"B","text":"Đạo đức kinh doanh toàn cầu"},{"key":"C","text":"Tư tưởng, đạo đức, phong cách Hồ Chí Minh"},{"key":"D","text":"Tư tưởng đổi mới toàn diện giáo dục đại học"}]},{"n":101,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Qua nghiên cứu môn học tư tưởng Hồ Chí Minh, người học có điều kiện vận dụng tốt hơn những kiến thức và kỹ năng đã nghiên cứu, học tập vào việc gì?","answer":"D","options":[{"key":"A","text":"Xây dựng các chương trình đào tạo quốc tế"},{"key":"B","text":"Vận dụng phong cách lãnh đạo của phương Tây"},{"key":"C","text":"Thực hiện các chiến lược kinh tế tư nhân"},{"key":"D","text":"Xây dựng phương pháp học tập, tu dưỡng, rèn luyện phù hợp với điều kiện bản thân"}]},{"n":102,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Theo tư tưởng Hồ Chí Minh, phương châm nào sau đây được nhấn mạnh trong phong cách công tác?","answer":"B","options":[{"key":"A","text":"Nói đi đôi với làm"},{"key":"B","text":"Dĩ bất biến, ứng vạn biến"},{"key":"C","text":"Tiên học lễ, hậu học văn"},{"key":"D","text":"Học, học nữa , học mãi"}]},{"n":103,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Phong cách nào dưới đây KHÔNG được đề cập đến trong tư tưởng Hồ Chí Minh theo nội dung bài học?","answer":"C","options":[{"key":"A","text":"Phong cách tư duy"},{"key":"B","text":"Phong cách sinh hoạt"},{"key":"C","text":"Phong cách kiến trúc"},{"key":"D","text":"Phong cách làm việc"}]},{"n":104,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Tư tưởng Hồ Chí Minh giúp sinh viên hoàn thiện điều gì?","answer":"C","options":[{"key":"A","text":"Kỹ năng tin học văn phòng"},{"key":"B","text":"Kỹ năng giao tiếp đa ngôn ngữ"},{"key":"C","text":"Nhân cách và phẩm chất đạo đức"},{"key":"D","text":"Khả năng hoạch định chính sách đối ngoại"}]},{"n":105,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Phong cách công tác của Hồ Chí Minh KHÔNG bao gồm nội dung nào dưới đây?","answer":"A","options":[{"key":"A","text":"Phong cách đầu tư"},{"key":"B","text":"Phong cách ứng xử"},{"key":"C","text":"Phong cách làm việc"},{"key":"D","text":"Phong cách diễn đạt"}]},{"n":106,"sec":"IV- Ý NGHĨA CỦA VIỆC HỌC TẬP MÔN HỌC TƯ TƯỞNG HỒ CHÍ","stem":"Việc học tập tư tưởng Hồ Chí Minh giúp sinh viên trở thành?","answer":"C","options":[{"key":"A","text":"Doanh nhân có trách nhiệm xã hội"},{"key":"B","text":"Người tiên phong trong nghiên cứu học thuật"},{"key":"C","text":"Chiến sĩ tiên phong trong sự nghiệp xây dựng và bảo vệ Tổ quốc"},{"key":"D","text":"Nhà ngoại giao có tầm nhìn toàn cầu"}]}]},{"id":"II","title":"CƠ SỞ, QUÁ TRÌNH HÌNH THÀNH VÀ PHÁT TRIỂN TƯ TƯỞNG HỒ CHÍ MINH","questions":[{"n":1,"sec":"","stem":"Thực dân Pháp bắt đầu tiến hành xâm lược Việt Nam vào năm nào?","answer":"A","options":[{"key":"A","text":"1858"},{"key":"B","text":"1883"},{"key":"C","text":"1862"},{"key":"D","text":"1871"}]},{"n":2,"sec":"","stem":"Triều đình nhà Nguyễn đã có thái độ gì trước hành động xâm lược của thực dân Pháp?","answer":"C","options":[{"key":"A","text":"Cương quyết kháng chiến đến cùng"},{"key":"B","text":"Lập tức đầu hàng, không chống cự"},{"key":"C","text":"Lần lượt ký các hiệp ước đầu hàng, trở thành tay sai"},{"key":"D","text":"Đóng cửa quan hệ với phương Tây để tự cô lập"}]},{"n":3,"sec":"","stem":"Các cuộc khởi nghĩa chống Pháp ở miền Nam vào cuối thế kỷ XIX tiêu biểu là của ai?","answer":"C","options":[{"key":"A","text":"Nguyễn Thiện Thuật và Đinh Công Tráng"},{"key":"B","text":"Phan Đình Phùng và Trần Tấn"},{"key":"C","text":"Nguyễn Trung Trực và Trương Định"},{"key":"D","text":"Hoàng Hoa Thám và Phạm Bành"}]},{"n":4,"sec":"","stem":"Ở miền Bắc, các cuộc khởi nghĩa chống Pháp có sự tham gia của ai sau đây?","answer":"C","options":[{"key":"A","text":"Phan Đình Phùng và Đặng Như Mai"},{"key":"B","text":"Trương Định và Nguyễn Trung Trực."},{"key":"C","text":"Nguyễn Thiện Thuật, Phạm Bành, Đinh Công Tráng. Nguyễn Quang Bích, Hoàng Hoa Thám"},{"key":"D","text":"Trần Tấn và Phan Đình Phùng"}]},{"n":5,"sec":"","stem":"Ở miền Trung, các cuộc khởi nghĩa chống Pháp có sự tham gia của ai sau đây?","answer":"A","options":[{"key":"A","text":"Trần Tấn, Đặng Như Mai, Phan Đình Phùng"},{"key":"B","text":"Phan Đình Phùng và Trần Tấn"},{"key":"C","text":"Nguyễn Trung Trực và Trương Định"},{"key":"D","text":"Hoàng Hoa Thám và Phạm Bành"}]},{"n":6,"sec":"","stem":"Các cuộc khởi nghĩa dưới ngọn cờ \"Cần Vương\" do các sĩ phu, văn thân lãnh đạo đều thất bại. Điều đó chứng tỏ?","answer":"A","options":[{"key":"A","text":"Tư tưởng phong kiến tỏ ra lỗi thời trước các nhiệm vụ lịch sử"},{"key":"B","text":"Phong trào thiếu sự hỗ trợ từ các tầng lớp nhân dân thành thị và nông thôn"},{"key":"C","text":"Sự phối hợp giữa các địa phương không hiệu quả và bị chia rẽ nghiêm trọng"},{"key":"D","text":"Thực dân Pháp có ưu thế quân sự tuyệt đối và hệ thống phòng thủ hiện đại"}]},{"n":7,"sec":"","stem":"Các cuộc khởi nghĩa chống Pháp cuối thế kỷ XIX mang ý nghĩa gì nổi bật nhất?","answer":"B","options":[{"key":"A","text":"Là biểu hiện của sự phản kháng nông dân đơn lẻ không có tổ chức"},{"key":"B","text":"Thể hiện tinh thần yêu nước mạnh mẽ của nhân dân Việt Nam"},{"key":"C","text":"Là sự khởi đầu cho công cuộc kháng chiến chống Nhật sau này"},{"key":"D","text":"Là kết quả của chủ trương cải cách của triều đình nhà Nguyễn"}]},{"n":8,"sec":"","stem":"Phong trào \"Cần Vương\" mang ý nghĩa gì?","answer":"C","options":[{"key":"A","text":"Thay đổi thể chế chính trị sang cộng hòa tư sản"},{"key":"B","text":"Cải cách kinh tế để phát triển đất nước"},{"key":"C","text":"Giúp vua cứu nước, kháng chiến chống Pháp"},{"key":"D","text":"Thiết lập một nhà nước dân chủ hiện đại"}]},{"n":9,"sec":"","stem":"Giai cấp phong kiến trong giai đoạn cuối thế kỷ XIX đã thể hiện điều gì?","answer":"A","options":[{"key":"A","text":"Suy tàn, bất lực trong việc bảo vệ độc lập dân tộc"},{"key":"B","text":"Vững mạnh, đoàn kết với nhân dân chống ngoại xâm"},{"key":"C","text":"Chủ động tiến hành cải cách chính trị sâu rộng"},{"key":"D","text":"Thiết lập được liên minh quân sự với các nước láng giềng"}]},{"n":10,"sec":"","stem":"Sau khi đã hoàn thành căn bản việc bình định Việt Nam về mặt quân sự, thực dân Pháp đã làm gì?","answer":"C","options":[{"key":"A","text":"Tiến hành cải cách giáo dục để đào tạo nguồn nhân lực cho chính quyền mới"},{"key":"B","text":"Tăng cường liên minh quân sự với triều đình nhà Nguyễn nhằm giữ ổn định"},{"key":"C","text":"Đẩy mạnh khai thác thuộc địa , biến Việt Nam từ một nước phong kiến thành nước thuộc địa và phong kiến"},{"key":"D","text":"Bắt đầu cải cách hành chính theo mô hình Nhật Bản"}]},{"n":11,"sec":"","stem":"Nền kinh tế Việt Nam dưới ách thống trị của thực dân Pháp là nền kinh tế như thế nào?","answer":"A","options":[{"key":"A","text":"Nền kinh tế nông nghiệp lạc hậu với khoảng 95% dân số là nông dân"},{"key":"B","text":"Kinh tế công nghiệp phát triển mạnh tại các thành phố lớn"},{"key":"C","text":"Kinh tế hàng hải và thương mại chiếm ưu thế"},{"key":"D","text":"Kinh tế thị trường định hướng xã hội chủ nghĩa phát triển mạnh"}]},{"n":12,"sec":"","stem":"Ngoài giai cấp địa chủ người Việt, giai cấp địa chủ còn bao gồm thành phần nào?","answer":"A","options":[{"key":"A","text":"Điền chủ người Pháp và nước ngoài"},{"key":"B","text":"Các quý tộc châu Á nhập cư vào Việt Nam"},{"key":"C","text":"Những thương nhân lớn người Trung Quốc"},{"key":"D","text":"Những người giàu có từ các tỉnh phía Nam"}]},{"n":13,"sec":"","stem":"Mâu thuẫn nào là mâu thuẫn cơ bản trong xã hội phong kiến Việt Nam cuối thế kỷ XIX?","answer":"C","options":[{"key":"A","text":"Giữa công nhân và tiểu tư sản"},{"key":"B","text":"Giữa tư sản và tri thức"},{"key":"C","text":"Giữa nông dân và địa chủ phong kiến"},{"key":"D","text":"Giữa nông dân và công nhân"}]},{"n":14,"sec":"","stem":"Một mâu thuẫn mới xuất hiện trong xã hội Việ t Nam do tác động của Pháp là?","answer":"D","options":[{"key":"A","text":"Mâu thuẫn giữa nhà Nguyễn với các lực lượng dân chủ"},{"key":"B","text":"Mâu thuẫn giữa nông dân và tư sản địa phương"},{"key":"C","text":"Mâu thuẫn giữa trí thức và tầng lớp công chức"},{"key":"D","text":"Mâu thuẫn giữa toàn thể nhân dân Việt Nam với thực dân Pháp"}]},{"n":15,"sec":"","stem":"Tác động của chính sách khai thác thuộc địa của Pháp đối với xã hội Việt Nam là gì?","answer":"A","options":[{"key":"A","text":"Dẫn tới sự biến đổi về cơ cấu giai cấp, tầng lớp trong xã hội"},{"key":"B","text":"Thúc đẩy công nghiệp nặng phát triển mạnh mẽ"},{"key":"C","text":"Tạo điều kiện hình thành chính quyền dân chủ kiểu mới"},{"key":"D","text":"Làm tăng cường quyền lực của triều đình nhà Nguyễn"}]},{"n":16,"sec":"","stem":"Giai cấp nào mới xuất hiện trong xã hội Việt Nam dưới tác động của chính sách khai thác thuộc địa?","answer":"D","options":[{"key":"A","text":"Giai cấp tăng lữ và quý tộc mới"},{"key":"B","text":"Giai cấp thương nhân và đại điền chủ"},{"key":"C","text":"Giai cấp nông dân và địa chủ nhỏ"},{"key":"D","text":"Giai cấp công nhân, giai cấp tư sản và tầng lớp tiểu tư sản ở thành thị"}]},{"n":17,"sec":"","stem":"Phong trào Đông Du do ai khởi xướng và diễn ra trong thời gian nào?","answer":"B","options":[{"key":"A","text":"Lương Văn Can, từ năm 1906 đến 1908"},{"key":"B","text":"Phan Bội Châu, từ năm 1905 đến 1909"},{"key":"C","text":"Nguyễn Thái Học, từ năm 1927 đến 1930"},{"key":"D","text":"Phan Châu Trinh, từ năm 1906 đến 1908"}]},{"n":18,"sec":"","stem":"Phong trào Duy Tân do ai khởi xướng và diễn ra trong thời gian nào?","answer":"D","options":[{"key":"A","text":"Lương Văn Can, từ năm 1906 đến 1908"},{"key":"B","text":"Phan Bội Châu, từ năm 1905 đến 1909"},{"key":"C","text":"Nguyễn Thái Học, từ năm 1927 đến 1930"},{"key":"D","text":"Phan Châu Trinh, từ năm 1906 đến 1908"}]},{"n":19,"sec":"","stem":"Phong trào Đông Kinh Nghĩa Thục hoạt động trong khoảng thời gian nào?","answer":"B","options":[{"key":"A","text":"Từ tháng 5-1905 đến tháng 5-1906"},{"key":"B","text":"Từ tháng 3-1907 đến tháng 11-1907"},{"key":"C","text":"Từ tháng 6-1906 đến tháng 6-1908"},{"key":"D","text":"Từ tháng 2-1908 đến tháng 10-1909"}]},{"n":20,"sec":"","stem":"Phong trào chống sưu thuế, chống đi phu bùng nổ mạnh nhất ở đâu vào năm 1908?","answer":"B","options":[{"key":"A","text":"Bắc Kỳ"},{"key":"B","text":"Trung Kỳ"},{"key":"C","text":"Nam Kỳ"},{"key":"D","text":"Tây Nguyên"}]},{"n":21,"sec":"","stem":"Nguyên nhân sâu xa dẫn đến sự thất bại của các phong trào yêu nước theo khuynh hướng dân chủ tư sản ở Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Giai cấp phong kiến đã liên minh với thực dân để đàn áp các phong trào"},{"key":"B","text":"Do ảnh hưởng của cách mạng Trung Quốc và tư tưởng vô chính phủ"},{"key":"C","text":"Giai cấp tư sản Việt Nam còn non yếu, chưa đủ năng lực lãnh đạo cách mạng"},{"key":"D","text":"Do nhân dân chưa giác ngộ cách mạng, còn tin vào triều đình phong kiến"}]},{"n":22,"sec":"","stem":"Nguyên nhân trực tiếp khiến các phong trào yêu nước theo khuynh hướng dân chủ tư sản thất bại là gì?","answer":"C","options":[{"key":"A","text":"Thiếu sự lãnh đạo của các nước lớn có kinh nghiệm cách mạng"},{"key":"B","text":"Thiếu tổ chức quần chúng đông đảo để làm lực lượng cách mạng chủ đạo"},{"key":"C","text":"Các tổ chức và lãnh đạo phong trào chưa có đường lối, phương pháp cách mạng đúng đắn"},{"key":"D","text":"Chính quyền phong kiến còn đủ mạnh để đàn áp phong trào"}]},{"n":23,"sec":"","stem":"Trong hoàn cảnh khủng hoảng đường lối cứu nước, câu hỏi lớn nhất được đặt ra từ thực tiễn là gì?","answer":"D","options":[{"key":"A","text":"Làm thế nào để liên minh với các lực lượng quốc tế chống thực dân"},{"key":"B","text":"Ai là người đủ tài năng lãnh đạo cuộc đấu tranh giải phóng dân tộc"},{"key":"C","text":"Liệu phong trào công nông có đủ sức thay thế tầng lớp trí thức yêu nước không"},{"key":"D","text":"Cứu nước bằng con đường nào để có thể đi đến thắng lợi"}]},{"n":24,"sec":"","stem":"Yếu tố nào làm xuất hiện dấu hiệu của một thời đại mới trong cuộc đấu tranh giải phóng dân tộc ở Việt Nam?","answer":"B","options":[{"key":"A","text":"Sự tăng trưởng của tầng lớp trí thức Nho học"},{"key":"B","text":"Giai cấp công nhân ra đời và bước đầu tham gia vào phong trào đấu tranh"},{"key":"C","text":"Chính sách cải cách kinh tế của thực dân Pháp"},{"key":"D","text":"Sự hậu thuẫn từ cách mạng Nga và Trung Quốc"}]},{"n":25,"sec":"","stem":"Sự ra đời của giai cấp công nhân Việt Nam có ý nghĩa gì trong cuộc đấu tranh giải phóng dân tộc?","answer":"A","options":[{"key":"A","text":"Giai cấp công nhân là lực lượng tiên phong có khả năng lãnh đạo cách mạng"},{"key":"B","text":"Giai cấp công nhân mở rộng cơ sở liên minh với giai cấp phong kiến cải lương"},{"key":"C","text":"Tạo điều kiện để tiếp thu nhanh các tư tưởng phong kiến tiến bộ từ Trung Quốc"},{"key":"D","text":"Hỗ trợ phong trào tiểu tư sản trong việc khởi nghĩa vũ trang"}]},{"n":26,"sec":"","stem":"Đặc điểm của giai cấp công nhân Việt Nam vào cuối thế kỷ XIX là gì?","answer":"C","options":[{"key":"A","text":"Hình thành đông đảo và có tổ chức mạnh trong các ngành nông nghiệp"},{"key":"B","text":"Chưa hình thành rõ nét, chủ yếu vẫn là nông dân đi làm thuê"},{"key":"C","text":"Mới là một lực lượng ít ỏi, không ổn định về tổ chức và số lượng"},{"key":"D","text":"Phát triển nhanh chóng và trở thành giai cấp tiên phong từ rất sớm"}]},{"n":27,"sec":"","stem":"Giai cấp công nhân Việt Nam trở thành một giai cấp rõ rệt vào thời điểm nào?","answer":"B","options":[{"key":"A","text":"Sau Cách mạng Tháng Mười Nga 1917"},{"key":"B","text":"Trước Chiến tranh thế giới thứ nhất (1914–1918)"},{"key":"C","text":"Trong quá trình xây dựng chủ nghĩa xã hội ở miền Bắc"},{"key":"D","text":"Ngay sau khi thành lập Đảng Cộng sản Việt Nam"}]},{"n":28,"sec":"","stem":"Giai cấp công nhân Việt Nam chịu sự áp bức, bóc lột từ bao nhiêu tầng lớp?","answer":"C","options":[{"key":"A","text":"Một tầng: tư bản thực dân Pháp"},{"key":"B","text":"Hai tầng: thực dân và phong kiến"},{"key":"C","text":"Ba tầng: thực dân, tư bản, phong kiến"},{"key":"D","text":"Bốn tầng: thực dân, tư bản, phong kiến và lãnh chúa địa phương"}]},{"n":29,"sec":"","stem":"Hình thức đấu tranh ban đầu của công nhân Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Khởi nghĩa vũ trang có tổ chức"},{"key":"B","text":"Biểu tình chính trị quy mô lớn"},{"key":"C","text":"Đốt lán trại, bỏ trốn tập thể"},{"key":"D","text":"Thành lập công đoàn và liên minh công nông"}]},{"n":30,"sec":"","stem":"Hình thức đấu tranh nào đã xuất hiện sau các hành động tự phát ban đầu của công nhân Việt Nam?","answer":"B","options":[{"key":"A","text":"Tuyên truyền bằng sách báo cách mạng"},{"key":"B","text":"Đình công và bãi công mang tính tập thể, có tổ chức"},{"key":"C","text":"Tổ chức phong trào thi đua yêu nước trong sản xuất"},{"key":"D","text":"Lập chính quyền cách mạng tại các khu công nghiệp"}]},{"n":31,"sec":"","stem":"Theo Hồ Chí Minh, giai cấp công nhân có vai trò như thế nào trong sự nghiệp cách mạng?","answer":"C","options":[{"key":"A","text":"Là lực lượng hỗ trợ nông dân trong cách mạng ruộng đất"},{"key":"B","text":"Là lực lượng sản xuất chủ yếu trong nền kinh tế thị trường"},{"key":"C","text":"Là lực lượng tiên phong, cách mạng nhất, gan góc nhất"},{"key":"D","text":"Là giai cấp có khả năng cải cách xã hội bằng con đường hòa bình"}]},{"n":32,"sec":"","stem":"Điền từ còn thiếu vào (_____)? “Chỉ có giai cấp (_____) là dũng cảm nhất, cách mạng nhất, luôn luôn gan góc đương đầu với bọn đế quốc thực dân\"(Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.12, tr 407).","answer":"A","options":[{"key":"A","text":"Công nhân"},{"key":"B","text":"Nông dân"},{"key":"C","text":"Địa chủ"},{"key":"D","text":"Tư sản"}]},{"n":33,"sec":"","stem":"Ai là người đã truyền bá chủ nghĩa Mác – Lênin vào phong trào công nhân và yêu nước Việt Nam?","answer":"D","options":[{"key":"A","text":"Trần Phú"},{"key":"B","text":"Lê Duẩn"},{"key":"C","text":"Võ Nguyên Giáp"},{"key":"D","text":"Hồ Chí Minh"}]},{"n":34,"sec":"","stem":"Sự truyền bá chủ nghĩa Mác – Lênin vào Việt Nam gắn liền với việc chuẩn bị những yếu tố nào cho cách mạng?","answer":"C","options":[{"key":"A","text":"Chuẩn bị lực lượng vũ trang và hậu cần chiến lược"},{"key":"B","text":"Chuẩn bị nền tảng công nghiệp và quân sự hiện đại"},{"key":"C","text":"Chuẩn bị về lý luận chính trị, tư tưởng và tổ chức"},{"key":"D","text":"Chuẩn bị tài chính và hậu thuẫn từ quốc tế cộng sản"}]},{"n":35,"sec":"","stem":"Sự kiện nào đánh dấu bước chấm dứt sự khủng hoảng về đường lối cách mạng Việt Nam?","answer":"B","options":[{"key":"A","text":"Cách mạng Tháng Tám năm 1945"},{"key":"B","text":"Sự thành lập Đảng Cộng sản Việt Nam"},{"key":"C","text":"Phong trào Xô Viết Nghệ Tĩnh 1930"},{"key":"D","text":"Hội nghị thành lập Việt Minh năm 1941"}]},{"n":36,"sec":"","stem":"Vào cuối thế kỷ XIX - đầu thế kỷ XX, chủ nghĩa tư bản trên thế giới đã phát triển từ giai đoạn tự do cạnh tranh sang giai đoạn nào?","answer":"D","options":[{"key":"A","text":"Tự do cạnh tranh"},{"key":"B","text":"Tự do thương mại và công nghiệp nhẹ"},{"key":"C","text":"Tư bản hoang dã không kiểm soát"},{"key":"D","text":"Độc quyền (đế quốc chủ nghĩa)"}]},{"n":37,"sec":"","stem":"Đặc điểm nổi bật của tình hình thế giới dưới sự chi phối của các nước đế quốc là gì?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa xã hội phát triển mạnh mẽ trên toàn thế giới"},{"key":"B","text":"Các nền văn hóa bản địa được phục hồi và tôn trọng"},{"key":"C","text":"Phần lớn các nước châu Á, châu Phi và Mỹ Latinh trở thành thuộc địa và phụ thuộc của các nước đế quốc"},{"key":"D","text":"Phong trào tự do tôn giáo được bảo vệ bởi luật pháp quốc tế"}]},{"n":38,"sec":"","stem":"Ba mâu thuẫn cơ bản của chủ nghĩa tư bản được thể hiện rõ rệt vào đầu thế kỷ XX là gì?","answer":"B","options":[{"key":"A","text":"Giữa giai cấp nông dân và giai cấp địa chủ, giữa tư bản và nhà nước, giữa các khối liên minh"},{"key":"B","text":"Giữa giai cấp tư sản với giai cấp vô sản ở các nước tư bản; giữa các nước đế quốc với nhau; giữa các dân tộc thuộc địa và phụ thuộc với chủ nghĩa đế quốc"},{"key":"C","text":"Giữa chính phủ và tôn giáo; giữa phong kiến và đế quốc; giữa trí thức và nhân dân"},{"key":"D","text":"Giữa công nghiệp và nông nghiệp; giữa nội thị và ngoại vi; giữa giàu và nghèo"}]},{"n":39,"sec":"","stem":"Mâu thuẫn nào sau đây KHÔNG thuộc các mâu thuẫn cơ bản của chủ nghĩa tư bản đầu thế kỷ XX?","answer":"D","options":[{"key":"A","text":"Mâu thuẫn giữa giai cấp tư sản với giai cấp vô sản"},{"key":"B","text":"Mâu thuẫn giữa các nước đế quốc với nhau"},{"key":"C","text":"Mâu thuẫn giữa các dân tộc thuộc địa với chủ nghĩa đế quốc"},{"key":"D","text":"Mâu thuẫn giữa giai cấp nông dân và tầng lớp tăng lữ"}]},{"n":40,"sec":"","stem":"Phong trào giải phóng dân tộc ở các nước thuộc địa phát triển mạnh là do?","answer":"C","options":[{"key":"A","text":"Chính sách tự trị của các nước đế quốc"},{"key":"B","text":"Mong muốn của các tầng lớp quý tộc địa phương"},{"key":"C","text":"Mâu thuẫn dân tộc và khát vọng độc lập tự do của nhân dân các nước thuộc địa"},{"key":"D","text":"Sự bất ổn về khí hậu và thiên tai lan rộng"}]},{"n":41,"sec":"","stem":"Thành tựu nổi bật nhất của Cách mạng Tháng Mười Nga là gì?","answer":"C","options":[{"key":"A","text":"Đưa Liên Xô trở thành siêu cường kinh tế ngay lập tức"},{"key":"B","text":"Xây dựng một chính thể quân chủ lập hiến kiểu mới"},{"key":"C","text":"Đánh đổ giai cấp tư sản và giai cấp địa chủ phong kiến, lập nên một xã hội mới – xã hội xã hội chủ nghĩa"},{"key":"D","text":"Phân chia lại thị trường thuộc địa cho các đế quốc nhỏ"}]},{"n":42,"sec":"","stem":"Cách mạng Tháng Mười Nga mở ra thời đại lịch sử nào cho nhân loại?","answer":"C","options":[{"key":"A","text":"Thời đại khôi phục chế độ quân chủ ở châu Âu"},{"key":"B","text":"Thời đại phục hưng dân chủ tư sản phương Tây"},{"key":"C","text":"Thời đại quá độ từ chủ nghĩa tư bản lên chủ nghĩa xã hội trên phạm vi toàn thế giới"},{"key":"D","text":"Thời đại chủ nghĩa đế quốc mở rộng sang Mỹ Latinh"}]},{"n":43,"sec":"","stem":"Ý nghĩa lớn nhất của Cách mạng Tháng Mười Nga đối với các dân tộc thuộc địa là gì?","answer":"B","options":[{"key":"A","text":"Xây dựng các khối quân sự mạnh để chống thực dân"},{"key":"B","text":"Mở ra con đường giải phóng cho các dân tộc bị áp bức trên thế giới"},{"key":"C","text":"Cung cấp mô hình đấu tranh vũ trang kiểu cũ"},{"key":"D","text":"Khuyến khích các nước thuộc địa xin gia nhập Liên Xô"}]},{"n":44,"sec":"","stem":"Quốc tế Cộng sản được thành lập vào thời gian nào? Ở đâu?","answer":"B","options":[{"key":"A","text":"Ngày 1-1-1918 tại Petrograd"},{"key":"B","text":"Ngày 2-3-1919 tại Mátxcơva"},{"key":"C","text":"Ngày 5-5-1920 tại Berlin"},{"key":"D","text":"Ngày 10-10-1921 tại Paris"}]},{"n":45,"sec":"","stem":"Ai là người sáng lập và lãnh đạo Quốc tế Cộng sản vào thời điểm thành lập?","answer":"D","options":[{"key":"A","text":"Karl Marx"},{"key":"B","text":"Leon Trotsky"},{"key":"C","text":"Joseph Stalin"},{"key":"D","text":"V.I. Lênin"}]},{"n":46,"sec":"","stem":"Dưới sự lãnh đạo của Lênin, Quốc tế Cộng sản thực hiện nhiệm vụ gì?","answer":"A","options":[{"key":"A","text":"Đẩy mạnh việc truyền bá chủ nghĩa Mác - Lênin và kinh nghiệm Cách mạng Tháng Mười Nga ra khắp thế giới"},{"key":"B","text":"Xây dựng đế chế thuộc địa kiểu mới"},{"key":"C","text":"Phát triển liên minh giữa các nhà nước quân chủ chống lại tư sản"},{"key":"D","text":"Tái lập nền kinh tế thị trường hỗn hợp ở châu Âu"}]},{"n":47,"sec":"","stem":"Quốc tế Cộng sản còn được biết đến với tên gọi nào sau đây?","answer":"B","options":[{"key":"A","text":"Quốc tế xã hội thứ hai"},{"key":"B","text":"Quốc tế thứ ba"},{"key":"C","text":"Quốc tế vô sản"},{"key":"D","text":"Hội nghị quốc tế giải phóng dân tộc"}]},{"n":48,"sec":"","stem":"Yếu tố nào sau đây ảnh hưởng sâu sắc tới Hồ Chí Minh trên hành trình đi ra thế giới tìm mục tiêu và con đường cứu nước?","answer":"A","options":[{"key":"A","text":"Cách mạng Tháng Mười Nga thắng lợi, sự ra đời của nhà nước Xôviết, Quốc tế Cộng sản và thực tiễn xây dựng chủ nghĩa xã hội ở Liên Xô cùng với sự phát triển mạnh mẽ phong trào cộng sản, công nhân và phong trào giải phóng dân tộc trên thế giới"},{"key":"B","text":"Phong trào Đông Du của Phan Bội Châu"},{"key":"C","text":"Sự thất bại của các phong trào cải cách ở Nhật Bản"},{"key":"D","text":"Phong trào Cần Vương và Hương Khê"}]},{"n":49,"sec":"2. Cơ sở lý luận","stem":"Giá trị truyền thống nào được coi là xuyên suốt và nổi bật nhất trong lịch sử dân tộc Việt Nam?","answer":"B","options":[{"key":"A","text":"Truyền thống hiếu học và sùng đạo tổ tiên"},{"key":"B","text":"Chủ nghĩa yêu nước"},{"key":"C","text":"Truyền thống nghệ thuật và thơ ca dân gian"},{"key":"D","text":"Chủ nghĩa thực dụng gắn với sinh tồn trong chiến tranh"}]},{"n":50,"sec":"2. Cơ sở lý luận","stem":"Tư tưởng Hồ Chí Minh được hình thành từ những nguồn gốc nào?","answer":"D","options":[{"key":"A","text":"Những điều kiện lịch sử - xã hội trong nước và thế giới"},{"key":"B","text":"Những tiền đề tư tưởng – lý luận"},{"key":"C","text":"Những phẩm chất chủ quan Hồ Chí Minh"},{"key":"D","text":"Cả A, B và C"}]},{"n":51,"sec":"2. Cơ sở lý luận","stem":"Chọn câu trả lời đúng nhất: Mục đích tư tưởng Hồ Chí Minh là gì?","answer":"B","options":[{"key":"A","text":"Giải phóng dân tộc"},{"key":"B","text":"Giải phóng dân tộc, giải phóng giai cấp và giải phóng con người"},{"key":"C","text":"Giải phóng các dân tộc phương Đông"},{"key":"D","text":"Giải phóng giai cấp và giải phóng con người"}]},{"n":52,"sec":"2. Cơ sở lý luận","stem":"Nhờ tiếp thu yếu tố nào mà Nguyễn Ái Quốc đã từ một nhà yêu nước trở thành một người cộng sản?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa Mác – Lênin"},{"key":"B","text":"Chủ nghĩa yêu nước"},{"key":"C","text":"Chủ nghĩa Tam dân"},{"key":"D","text":"Văn hóa Phục hưng"}]},{"n":53,"sec":"2. Cơ sở lý luận","stem":"Chủ nghĩa yêu nước có vai trò như thế nào trong hành trình ra đi tìm đường cứu nước của Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Là động lực phụ sau khi bị thực dân đàn áp cá nhân"},{"key":"B","text":"Là tư tưởng cảm tính chịu ảnh hưởng từ các phong trào yêu nước tiền bối"},{"key":"C","text":"Là nền tảng tư tưởng, điểm xuất phát và động lực thúc đẩy hành động"},{"key":"D","text":"Là niềm tin mơ hồ được hình thành trong quá trình học tập ở Pháp"}]},{"n":54,"sec":"2. Cơ sở lý luận","stem":"Một trong những tiền đề tư tưởng, lý luận dẫn đến sự hình thành tư tưởng Hồ Chí Minh là?","answer":"A","options":[{"key":"A","text":"Giá trị truyền thống tốt đẹp của dân tộc Việt Nam"},{"key":"B","text":"Giá trị văn hiến dân tộc Việt Nam"},{"key":"C","text":"Giá trị tư tưởng dân tộc Việt Nam"},{"key":"D","text":"Giá trị văn minh dân tộc Việt Nam"}]},{"n":55,"sec":"2. Cơ sở lý luận","stem":"Điền từ còn thiếu vào (_____)? Trong Tuyên ngôn Độc lập, Hồ Chí Minh đã tr ịnh trọng tuyên bố với thế giới: “Nước Việt Nam có quyền hưởng (_____) và (_____), và sự thực đã thành một nước tự do và độc lập. Toàn thể dân Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mệnh và của cải để giữ vững quyền tự do và độc lập ấy”","answer":"D","options":[{"key":"A","text":"Hòa bình - hạnh phúc"},{"key":"B","text":"Công bằng - dân chủ"},{"key":"C","text":"Tự do - dân chủ"},{"key":"D","text":"Tự do - độc lập"}]},{"n":56,"sec":"2. Cơ sở lý luận","stem":"Tư tưởng “gốc có vững cây mới bền” của Hồ Chí Minh muốn nói đến vấn đề gì?","answer":"B","options":[{"key":"A","text":"Vai trò của hệ thống pháp luật trong điều hành đất nước"},{"key":"B","text":"Tầm quan trọng của nhân dân trong sự nghiệp cách mạng"},{"key":"C","text":"Mối quan hệ giữa chính quyền trung ương và địa phương"},{"key":"D","text":"Ý nghĩa của đoàn kết dân tộc trong phát triển kinh tế"}]},{"n":57,"sec":"2. Cơ sở lý luận","stem":"Những phẩm chất truyền thống nào của dân tộc Việt Nam được Hồ Chí Minh đặc biệt coi trọng?","answer":"C","options":[{"key":"A","text":"Giản dị, tiết kiệm, cam chịu và tuân phục"},{"key":"B","text":"Nho nhã, cầu toàn, tín ngưỡng cao và ngại xung đột"},{"key":"C","text":"Cần cù, dũng cảm, sáng tạo, lạc quan và vì nghĩa, thương người"},{"key":"D","text":"Trung dung, thân thiện, kín đáo và không ưa đổi mới"}]},{"n":58,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh được coi là biểu tượng tích hợp văn hóa nào?","answer":"D","options":[{"key":"A","text":"Văn hóa cổ đại và hiện đại châu Âu"},{"key":"B","text":"Văn hóa châu Á cổ truyền và chủ nghĩa khắc kỷ Hy Lạp"},{"key":"C","text":"Văn hóa nông nghiệp và văn hóa đô thị"},{"key":"D","text":"Văn hóa phương Đông và phương Tây"}]},{"n":59,"sec":"2. Cơ sở lý luận","stem":"Tinh hoa văn hoá, tư tưởng phương Đông kết tinh trong mấy học thuyết lớn?","answer":"B","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]},{"n":60,"sec":"2. Cơ sở lý luận","stem":"Tinh hoa văn hoá, tư tưởng phương Đông kết tinh trong ba học thuyết lớn, đó là?","answer":"A","options":[{"key":"A","text":"Nho giáo, Phật giáo, Lão giáo"},{"key":"B","text":"Nho giáo, Hồi giáo, Phật giáo"},{"key":"C","text":"Phật giáo, Ấn Độ giáo, Lão giáo"},{"key":"D","text":"Lão giáo, Nho giáo, Thiên Chúa giáo"}]},{"n":61,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đánh giá như thế nào về tư tưởng Khổng Tử?","answer":"C","options":[{"key":"A","text":"Khổng Tử là nhà cách mạng, nên các tư tưởng của ông đều đúng và cần học theo"},{"key":"B","text":"Khổng Tử là phong kiến, tư tưởng lỗi thời nên không có giá trị sử dụng"},{"key":"C","text":"Tuy Khổng Tử là phong kiến và và tuy trong học thuyết của Khổng Tử có nhiều điều không đúng, song những điều hay trong đó thì chúng ta nên học"},{"key":"D","text":"Hồ Chí Minh không nhắc đến Khổng Tử trong tư tưởng của mình"}]},{"n":62,"sec":"2. Cơ sở lý luận","stem":"Theo Hồ Chí Minh, ưu điểm lớn nhất của học thuyết Khổng Tử là gì?","answer":"C","options":[{"key":"A","text":"Tinh thần hiếu học"},{"key":"B","text":"Quản lý xã hội bằng đạo đức"},{"key":"C","text":"Sự tu dưỡng đạo đức cá nhân"},{"key":"D","text":"Đề cao văn hoá, lễ giáo"}]},{"n":63,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh cho rằng việc quản lý xã hội nên dựa vào nguyên tắc nào sau đây, chịu ảnh hưởng từ Nho giáo?","answer":"C","options":[{"key":"A","text":"Pháp trị nghiêm khắc, lấy luật pháp làm trung tâm để điều hành đất nước"},{"key":"B","text":"Quân trị kết hợp tôn giáo để điều hành và răn dạy nhân dân"},{"key":"C","text":"Nhân trị, đức trị - coi trọng đạo đức và tình người trong điều hành xã hội"},{"key":"D","text":"Tư trị - mỗi người tự tu dưỡng để xây dựng đất nước"}]},{"n":64,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh kế thừa và đổi mới tư tưởng Nho giáo theo hướng nào?","answer":"B","options":[{"key":"A","text":"Giữ nguyên hoàn toàn đạo lý phong kiến, tôn vinh chế độ quân chủ nhân trị"},{"key":"B","text":"Kế thừa có chọn lọc tinh thần đạo đức như nhân, nghĩa, trí, dũng, tín, liêm"},{"key":"C","text":"Loại bỏ toàn bộ nội dung tư tưởng đạo đức cổ truyền để xây dựng mới"},{"key":"D","text":"Bài bác hoàn toàn vì cho rằng Nho giáo là công cụ phục vụ chế độ thực dân"}]},{"n":65,"sec":"2. Cơ sở lý luận","stem":"Trong công tác xây dựng Đảng, Hồ Chí Minh kế thừa tư tưởng nào của Nho giáo?","answer":"C","options":[{"key":"A","text":"Tư tưởng \"quân xử thần tử, thần bất tử bất trung\" để rèn luyện kỷ cương"},{"key":"B","text":"Tinh thần \"tu thân, tề gia, trị quốc, bình thiên hạ\" nhằm tăng tính kỷ luật"},{"key":"C","text":"Tinh thần trọng đạo đức trong việc tu dưỡng, rèn luyện cán bộ, đảng viên"},{"key":"D","text":"Triết lý lấy văn hóa lễ nghi để kiểm soát và hướng dẫn hành vi Đảng viên"}]},{"n":66,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đánh giá những giá trị đạo đức nào của Nho giáo là đáng học tập và phát huy?","answer":"D","options":[{"key":"A","text":"Lễ, nhạc, hình, phạt, quân thần phụ tử"},{"key":"B","text":"Phép tắc cung đình, quy định lễ nghĩa phong kiến"},{"key":"C","text":"Tư tưởng trung quân, ái quốc và tận trung với vua"},{"key":"D","text":"Nhân, nghĩa, trí, dũng, tín, liêm – nền tảng đạo đức xã hội"}]},{"n":67,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã tiếp thu những yếu tố tích cực nào của Phật giáo?","answer":"D","options":[{"key":"A","text":"Tư tưởng từ bi, vị tha, bác ái"},{"key":"B","text":"Yêu thương con người, khuyến khích làm việc thiện, chống lại điều ác"},{"key":"C","text":"Đề cao quyền bình đẳng con người và chân lý; khuyên con người sống hòa đồng, gắn bó với đất nước"},{"key":"D","text":"Cả A, B và C"}]},{"n":68,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã vận dụng tư tưởng nào của Đạo Phật để đoàn kết toàn dân trong kháng chiến?","answer":"B","options":[{"key":"A","text":"Tư tưởng thiền định để con người bình tâm khi bị áp bức"},{"key":"B","text":"Tư tưởng cứu khổ cứu nạn, hy sinh chống lại cái ác để cứu chúng sinh"},{"key":"C","text":"Tư tưởng vô ngã, khước từ đời sống vật chất để giữ lòng kiên định"},{"key":"D","text":"Tư tưởng xuất gia thoát tục để tránh ảnh hưởng tiêu cực từ chiến tranh"}]},{"n":69,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh chú trọng kế thừa, phát triển tư tưởng nào của Phật giáo vào việc xây dựng con người mới, xã hội mới Việt Nam hiện nay?","answer":"A","options":[{"key":"A","text":"Tư tưởng nhân bản, đạo đức tích cực"},{"key":"B","text":"Tư tưởng an phận thủ thường, tu hành tránh xa đời sống xã hội phức tạp"},{"key":"C","text":"Tư tưởng xuất gia thoát tục để tránh ảnh hưởng tiêu cực từ chiến tranh"},{"key":"D","text":"Tư tưởng vô ngã, khước từ đời sống vật chất để giữ lòng kiên định"}]},{"n":70,"sec":"2. Cơ sở lý luận","stem":"Theo Hồ Chí Minh, Phật giáo mang lại giá trị nào cho xã hội Việt Nam hiện đại?","answer":"C","options":[{"key":"A","text":"Giúp con người rút lui khỏi xã hội để giữ gìn sự trong sạch của tâm linh"},{"key":"B","text":"Mang lại sự bình đẳng giai cấp và xoá bỏ hoàn toàn tín ngưỡng truyền thống"},{"key":"C","text":"Đóng góp những tư tưởng nhân bản, đạo đức tích cực vào xây dựng xã hội mới"},{"key":"D","text":"Tạo ra tầng lớp xuất gia góp phần làm phong phú đời sống tinh thần cho đất nước"}]},{"n":71,"sec":"2. Cơ sở lý luận","stem":"Trong thư gửi Hội Phật tử năm 1947, Hồ Chí Minh liên hệ tinh thần Phật giáo với điều gì?","answer":"A","options":[{"key":"A","text":"Cuộc kháng chiến cứu quốc là hành động thể hiện lòng đại từ đại bi"},{"key":"B","text":"Sự giác ngộ của cá nhân và trách nhiệm với nghiệp báo tiền kiếp"},{"key":"C","text":"Cuộc sống hòa bình sau chiến tranh, hướng về tâm linh và cầu an"},{"key":"D","text":"Tăng ni, phật tử đóng vai trò lãnh đạo nhân dân trong cuộc kháng chiến"}]},{"n":72,"sec":"2. Cơ sở lý luận","stem":"Chọn đáp án trả lời đúng cho câu hỏi: Hồ Chí Minh đã tiếp thu những yếu tố tích cực nào của Phật giáo?","answer":"D","options":[{"key":"A","text":"Tư tưởng vị tha"},{"key":"B","text":"Tinh thần từ bi, bác ái"},{"key":"C","text":"Tinh thần cứu khổ, cứu nạn"},{"key":"D","text":"Cả A, B và C"}]},{"n":73,"sec":"2. Cơ sở lý luận","stem":"Tìm một điểm nhầm lẫn trong đoạn viết dưới đây: Một trong những nguồn gốc của tư tưởng Hồ Chí Minh là tiếp thu văn hóa phương Đông, cụ thể là?","answer":"B","options":[{"key":"A","text":"Những mặt tích cực của Nho giáo"},{"key":"B","text":"Triết học Hy Lạp cổ đại"},{"key":"C","text":"Tư tưởng vị tha của Phật giáo"},{"key":"D","text":"Tư tưởng Tam dân của Tôn Trung Sơn"}]},{"n":74,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh kế thừa tư tưởng nào của Lão giáo trong việc xây dựng đời sống tinh thần con người?","answer":"B","options":[{"key":"A","text":"Tinh thần hành động mạnh mẽ, đấu tranh bằng bạo lực để đạt mục tiêu"},{"key":"B","text":"Tư tưởng vô vi, thoát khỏi vòng danh lợi, sống hòa hợp với tự nhiên"},{"key":"C","text":"Chủ trương tu hành, ẩn dật hoàn toàn, tách khỏi đời sống xã hội"},{"key":"D","text":"Quan điểm “hữu vi thắng vô vi”, nhấn mạnh vào sự kiểm soát xã hội"}]},{"n":75,"sec":"2. Cơ sở lý luận","stem":"Từ tư tưởng Lão giáo, Hồ Chí Minh đã có hành động thực tiễn nào nổi bật để bảo vệ môi trường?","answer":"C","options":[{"key":"A","text":"Kêu gọi toàn dân di chuyển về nông thôn để sống gần thiên nhiên"},{"key":"B","text":"Phát động chương trình “Tu dưỡng tinh thần” trên cả nước"},{"key":"C","text":"Tổ chức “Tết trồng cây” nhằm bảo vệ sinh thái cho con người"},{"key":"D","text":"Khuyến khích xây dựng các khu rừng cách ly trong thành phố lớn"}]},{"n":76,"sec":"2. Cơ sở lý luận","stem":"Tư tưởng nào của Lão giáo được Hồ Chí Minh phát triển trong việc giáo dục cán bộ, đảng viên?","answer":"D","options":[{"key":"A","text":"Tư tưởng bất biến giữa dòng đời vạn biến để khẳng định lập trường giai cấp"},{"key":"B","text":"Tư tưởng thoát ly thế tục để giữ sự thuần khiết trong hành động chính trị"},{"key":"C","text":"Tư tưởng tránh xa chiến đấu, sống yên ổn, tự tại trong vòng kiểm soát"},{"key":"D","text":"Tư tưởng tránh ham muốn vật chất, sống cần kiệm, liêm chính, chí công vô tư"}]},{"n":77,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã khuyến khích hành động đúng với đạo lý, nghĩa là hành động như thế nào?","answer":"B","options":[{"key":"A","text":"Hành động theo nguyên tắc riêng, bất chấp quy luật khách quan"},{"key":"B","text":"Hành động đúng với quy luật tự nhiên và xã hội, phù hợp với đạo lý"},{"key":"C","text":"Hành động vì quyền lợi cá nhân trong khuôn khổ pháp luật hiện hành"},{"key":"D","text":"Hành động theo mệnh lệnh cấp trên, không cần suy xét đạo lý"}]},{"n":78,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã kế thừa và phát triển những tư tưởng nào của các nhà tư tưởng phương Đông cổ đại khác?","answer":"C","options":[{"key":"A","text":"Các học thuyết mê tín dị đoan để đoàn kết nhân dân theo tín ngưỡng"},{"key":"B","text":"Các triết lý quân trị chuyên chế để tổ chức bộ máy nhà nước"},{"key":"C","text":"Những quan điểm nhân đạo, quản trị xã hội như của Mặc Tử, Quản Tử"},{"key":"D","text":"Các tư tưởng thần quyền nhằm nâng cao vị thế lãnh đạo tinh thần"}]},{"n":79,"sec":"2. Cơ sở lý luận","stem":"Tư tưởng Hồ Chí Minh chịu ảnh hưởng từ trào lưu tư tưởng tiến bộ nào ở Trung Quốc?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa Duy tâm khách quan của Lý Trạch Phát"},{"key":"B","text":"Chủ nghĩa Tam dân của Tôn Trung Sơn"},{"key":"C","text":"Thuyết trung dung quân bình của Tăng Tử"},{"key":"D","text":"Chủ nghĩa dân tộc cực đoan bài ngoại thời Thanh Mạt"}]},{"n":80,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã phát triển chủ nghĩa Tam dân của Tôn Trung Sơn thành nội dung gì trong tư tưởng của mình?","answer":"C","options":[{"key":"A","text":"Tư tưởng giữ gìn bản sắc truyền thống, cô lập với chủ nghĩa tư bản"},{"key":"B","text":"Tư tưởng cải lương chính trị, hạn chế đấu tranh giai cấp"},{"key":"C","text":"Tư tưởng Độc lập - Tự do - Hạnh phúc theo con đường cách mạng vô sản"},{"key":"D","text":"Tư tưởng trung quân ái quốc kết hợp với phương pháp pháp trị"}]},{"n":81,"sec":"2. Cơ sở lý luận","stem":"Ngay từ khi còn nhỏ, Hồ Chí Minh đã tiếp cận khẩu hiệu nổi tiếng nào của Đại Cách mạng Pháp 1789?","answer":"D","options":[{"key":"A","text":"Tự do - Bình đẳng - Hữu nghị"},{"key":"B","text":"Công bằng - Bác ái - Dân sinh"},{"key":"C","text":"Công lý - Tự do - Dân quyền"},{"key":"D","text":"Tự do - Bình đẳng - Bác ái"}]},{"n":82,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã kế thừa, phát triển những quan điểm nào trong bản Tuyên ngôn Độc lập năm 1776 của Mỹ, bản Tuyên ngôn Nhân quyền và Dân quyền năm 1791 của Pháp?","answer":"C","options":[{"key":"A","text":"Tự do - Bình đẳng"},{"key":"B","text":"Công bằng - Bác ái"},{"key":"C","text":"Nhân quyền - dân quyền"},{"key":"D","text":"Bình đẳng - Bác ái"}]},{"n":83,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh đã kế thừa, phát triển những quan điểm nhân quyền, dân quyền trong bản Tuyên ngôn Độc lập năm 1776 của Mỹ, bản Tuyên ngôn Nhân quyền và Dân quyền năm 1791 của Pháp và đề xuất quan điểm về quyền?","answer":"D","options":[{"key":"A","text":"Quyền được bảo vệ bởi các quốc gia dân chủ tiên tiến"},{"key":"B","text":"Quyền tham chính trong một nhà nước pháp quyền hiện đại"},{"key":"C","text":"Quyền xây dựng xã hội chủ nghĩa trên nền tảng quốc tế cộng sản"},{"key":"D","text":"Quyền mưu cầu độc lập, tự do, hạnh phúc của các dân tộc"}]},{"n":84,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh trực tiếp nghiên cứu những triết gia nào thuộc phong trào Khai sáng phương Tây?","answer":"B","options":[{"key":"A","text":"Hêghen, Nitsche và Kăngt – đại diện triết học Đức hiện sinh"},{"key":"B","text":"Vonte, Rutxô, Môngtétxkiơ – các nhà tư tưởng dân chủ, pháp quyền; tìm hiểu chủ nghĩa Tam dân của Tôn Trung Sơn, Trung Quốc…"},{"key":"C","text":"Platon, Aristoteles và Socrates – các nhà tư tưởng Hy Lạp cổ đại"},{"key":"D","text":"J.S. Mill, Locke và Bentham – những nhà kinh tế học tự do Anh"}]},{"n":85,"sec":"2. Cơ sở lý luận","stem":"Theo Hồ Chí Minh, chủ nghĩa nào là “chân chính nhất, chắc chắn nhất, cách mạng nhất”?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa dân tộc dân chủ kiểu mới"},{"key":"B","text":"Chủ nghĩa Tam dân của Tôn Trung Sơn"},{"key":"C","text":"Chủ nghĩa Lênin"},{"key":"D","text":"Chủ nghĩa cải lương dân quyền"}]},{"n":86,"sec":"2. Cơ sở lý luận","stem":"Điền từ còn thiếu vào (_____)? “Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mạng nhất là (_____)” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.2, tr.289).","answer":"D","options":[{"key":"A","text":"Chủ nghĩa dân tộc dân chủ kiểu mới"},{"key":"B","text":"Chủ nghĩa Tam dân của Tôn Trung Sơn"},{"key":"C","text":"Chủ nghĩa cải lương dân quyền"},{"key":"D","text":"Chủ nghĩa Lênin"}]},{"n":87,"sec":"2. Cơ sở lý luận","stem":"Chủ nghĩa Mác – Lênin có vai trò như thế nào đối với tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Là lý thuyết chính trị phổ biến trên thế giới mà Hồ Chí Minh tham khảo một phần"},{"key":"B","text":"Là cơ sở của học thuyết xã hội dân sự hiện đại kết hợp với dân chủ phương Tây"},{"key":"C","text":"Là nền tảng tư tưởng, thế giới quan, phương pháp luận của tư tưởng Hồ Chí Minh"},{"key":"D","text":"Là một học thuyết song song với tư tưởng dân tộc cổ truyền mà Người phản biện"}]},{"n":88,"sec":"2. Cơ sở lý luận","stem":"Trong các tiền đề lý luận hình thành tư tưởng Hồ Chí Minh, tiền đề nào quan trọng nhất, có vai trò quyết định đối với việc hình thành tư tưởng của Người?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa Mác - Lênin"},{"key":"B","text":"Chủ nghĩa Tam dân của Tôn Trung Sơn"},{"key":"C","text":"Chủ nghĩa cải lương dân quyền"},{"key":"D","text":"Chủ nghĩa dân tộc dân chủ kiểu mới"}]},{"n":89,"sec":"2. Cơ sở lý luận","stem":"Tư tưởng Hồ Chí Minh được hình thành từ những tiền đề tư tưởng - lý luận nào?","answer":"D","options":[{"key":"A","text":"Chủ nghĩa Mác – Lênin"},{"key":"B","text":"Những giá trị truyền thống tốt đẹp của dân tộc"},{"key":"C","text":"Tinh hoa văn hóa nhân loại"},{"key":"D","text":"Cả A, B và C"}]},{"n":90,"sec":"2. Cơ sở lý luận","stem":"Hồ Chí Minh từng đánh giá như thế nào về học thuyết Khổng Tử, tôn giáo Giêsu, chủ nghĩa Mác và chủ nghĩa Tôn Dật Tiên?","answer":"C","options":[{"key":"A","text":"Mỗi học thuyết có những nhược điểm riêng, không thể kết hợp được"},{"key":"B","text":"Họ đều là các nhà cải cách mang tầm nhìn khu vực châu Á – Âu"},{"key":"C","text":"Họ đều có những ưu điểm nhằm mưu cầu hạnh phúc cho nhân loại"},{"key":"D","text":"Các học thuyết này không phù hợp trong điều kiện Việt Nam hiện đại"}]},{"n":91,"sec":"2. Cơ sở lý luận","stem":"Theo Hồ Chí Minh, điều gì là \"vũ khí không gì thay thế được\" giúp cách mạng Việt Nam giành thắng lợi?","answer":"B","options":[{"key":"A","text":"Sự đoàn kết dân tộc và lòng yêu nước nồng nàn của nhân dân Việt Nam"},{"key":"B","text":"Chủ nghĩa Mác - Lênin"},{"key":"C","text":"Sự hỗ trợ về quân sự và kinh tế từ các nước xã hội chủ nghĩa trên thế giới"},{"key":"D","text":"Chiến lược quân sự linh hoạt và khả năng vận động quần chúng rộng rãi"}]},{"n":92,"sec":"2. Cơ sở lý luận","stem":"Mục đích chính của Hồ Chí Minh muốn ra nước ngoài là?","answer":"B","options":[{"key":"A","text":"Tìm kiếm cơ hội kinh doanh và làm giàu cho bản thân và gia đình"},{"key":"B","text":"Học hỏi, tìm đường cứu nước, vận động cách mạng giải phóng dân tộc khỏi ách đô hộ"},{"key":"C","text":"Du lịch, khám phá các nền văn hóa mới và trải nghiệm cuộc sống ở nước ngoài"},{"key":"D","text":"Tham gia các tổ chức quốc tế để xây dựng sự nghiệp chính trị cá nhân"}]},{"n":93,"sec":"2. Cơ sở lý luận","stem":"Trong quá lãnh đạo cách mạng Việt Nam, Hồ Chí Minh đã có những đóng góp gì?","answer":"C","options":[{"key":"A","text":"Ứng dụng triệt để mô hình cách mạng vô sản kiểu Nga tại Việt Nam"},{"key":"B","text":"Thực hiện học thuyết kinh tế chính trị của Mác trong cải cách ruộng đất"},{"key":"C","text":"Vận dụng sáng tạo, bổ sung, phát triển chủ nghĩa Mác – Lênin trong thực tiễn"},{"key":"D","text":"Áp dụng lý luận đấu tranh giai cấp triệt để, không điều chỉnh theo hoàn cảnh"}]},{"n":94,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Lý tưởng sống cao cả của Hồ Chí Minh từ khi còn trẻ là gì?","answer":"C","options":[{"key":"A","text":"Làm giàu để giúp dân bằng phát triển kinh tế tư bản bản địa"},{"key":"B","text":"Phấn đấu trở thành quan chức để cải cách hành chính thuộc địa"},{"key":"C","text":"Cứu dân, cứu nước khỏi cảnh lầm than, cơ cực để theo kịp các nước tiên tiến trên thế giới"},{"key":"D","text":"Xây dựng mô hình đại học khai sáng để nâng cao dân trí Việt Nam"}]},{"n":95,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Hồ Chí Minh đã thể hiện ý chí và nghị lực to lớn như thế nào trong hành trình tìm đường cứu nước?","answer":"C","options":[{"key":"A","text":"Rời quê hương cùng gia đình sang Pháp để tìm hiểu chế độ thuộc địa"},{"key":"B","text":"Theo học tại các học viện chính trị lớn ở châu Âu từ khi còn thiếu niên"},{"key":"C","text":"Một mình ra đi tìm đường cứu nước chỉ với hai bàn tay trắng, làm đủ nghề để sống và hoạt động"},{"key":"D","text":"Tự tham gia vào hệ thống hành chính Pháp để cải cách từ bên trong"}]},{"n":96,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Tư duy lý luận của Hồ Chí Minh được đặc trưng bởi yếu tố nào nổi bật nhất?","answer":"B","options":[{"key":"A","text":"Sao chép nguyên mẫu học thuyết Marx – Lênin áp dụng cho Việt Nam"},{"key":"B","text":"Tư duy độc lập, tự chủ, sáng tạo, giàu tính phê phán, đổi mới và cách mạng"},{"key":"C","text":"Dựa trên các mô hình phong kiến và chế độ nho giáo cải cách"},{"key":"D","text":"Trung thành tuyệt đối với một mô hình lý thuyết cố định"}]},{"n":97,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Hồ Chí Minh có khả năng nổi bật nào giúp Người định hướng chiến lược cách mạng Việt Nam?","answer":"C","options":[{"key":"A","text":"Khả năng tổ chức công nghiệp hóa dựa trên mô hình Xô viết"},{"key":"B","text":"Khả năng vận hành các chính sách kinh tế thị trường định hướng XHCN"},{"key":"C","text":"Khả năng dự báo, tổng kết thực tiễn, và dẫn dắt cách mạng qua từng giai đoạn"},{"key":"D","text":"Khả năng đàm phán với các đế quốc bằng vũ lực và ngoại giao bí mật"}]},{"n":98,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Phẩm chất đạo đức nổi bật nào sau đây của Hồ Chí Minh được đánh giá là nhất quán suốt đời?","answer":"B","options":[{"key":"A","text":"Lấy bản thân làm trung tâm để làm giàu cho dân tộc"},{"key":"B","text":"Suốt đời tận trung với nước, tận hiếu với dân, Là người suốt đời đấu tranh cho sự nghiệp cách mạng của Đảng cộng sản Việt Nam và của cách mạng thế giới"},{"key":"C","text":"Chỉ tập trung vào công cuộc phát triển trí thức tinh hoa"},{"key":"D","text":"Đặt lý tưởng quốc tế vô sản lên trên lợi ích dân tộc"}]},{"n":99,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Trước khi trở thành Chủ tịch nước, Hồ Chí Minh đã sống, học tập, công tác ở khoảng bao nhiêu quốc gia?","answer":"C","options":[{"key":"A","text":"Khoảng 15 nước trên ba châu lục"},{"key":"B","text":"Khoảng 20 nước chủ yếu ở châu Á và châu Âu"},{"key":"C","text":"Khoảng 30 nước trên nhiều châu lục khác nhau"},{"key":"D","text":"Khoảng 10 nước thuộc hệ thống thuộc địa cũ"}]},{"n":100,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Hồ Chí Minh đã hiểu biết sâu sắc chủ nghĩa đế quốc, thực dân chủ yếu thông qua?","answer":"A","options":[{"key":"A","text":"Qua tìm hiểu trên các loại tài liệu, sách, báo, radio mà còn hiểu biết sâu sắc về chúng qua cuộc sống và hoạt động thực tiễn tại các cường quốc đế quốc"},{"key":"B","text":"Kinh nghiệm công tác tại các nước xã hội chủ nghĩa Đông Âu"},{"key":"C","text":"Hoạt động thực tiễn, trực tiếp sống tại các nước đế quốc và thuộc địa"},{"key":"D","text":"Tư vấn và trao đổi học thuật với các nhà cách mạng quốc tế"}]},{"n":101,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Hồ Chí Minh không chỉ nghiên cứu phong trào cách mạng mà còn trực tiếp tham gia vào tổ chức nào sau đây?","answer":"C","options":[{"key":"A","text":"Quốc tế Lao động và Hội nghị Versailles"},{"key":"B","text":"Đảng Dân chủ Xã hội Đức và phong trào Công đoàn Pháp"},{"key":"C","text":"Sáng lập Đảng Cộng sản Pháp, qua hoạt động trong Đảng Cộng sản Trung Quốc, qua tham gia phong trào cộng sản quốc tế ở nhiều nước, qua nghiên cứu đời sống xã hội ở Liên Xô"},{"key":"D","text":"Tổ chức Thanh niên Á - Phi và Liên minh Phản đế quốc"}]},{"n":102,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Hồ Chí Minh tham gia chuẩn bị những yếu tố nào cho sự ra đời của Đảng Cộng sản Việt Nam?","answer":"C","options":[{"key":"A","text":"Tài chính, vũ khí và lực lượng quân sự trung thành"},{"key":"B","text":"Cơ sở vật chất, truyền thông báo chí và quân đội"},{"key":"C","text":"Chính trị, tư tưởng, tổ chức"},{"key":"D","text":"Kết nối với Quốc dân đảng Trung Quốc và khởi nghĩa vũ trang"}]},{"n":103,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Sự kết hợp giữa phẩm chất cá nhân cùng những hoạt động thực tiễn phong phú của Hồ Chí Minh đã dẫn đến kết quả gì?","answer":"C","options":[{"key":"A","text":"Hình thành mô hình lý luận tập trung hóa cao độ giống Trung Quốc"},{"key":"B","text":"Tạo ra đường lối giáo dục lý luận độc lập với các học thuyết phương Tây"},{"key":"C","text":"Là nhân tố chủ quan hình thành nên tư tưởng Hồ Chí Minh"},{"key":"D","text":"Khẳng định tư tưởng Hồ Chí Minh là tách rời hoàn toàn khỏi chủ nghĩa Mác – Lênin"}]},{"n":104,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Nguyễn Tất Thành đã tham dự cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên Huế vào thời gian nào?","answer":"B","options":[{"key":"A","text":"Tháng 5/1905"},{"key":"B","text":"Tháng 5/1908"},{"key":"C","text":"Tháng 5/1906"},{"key":"D","text":"Tháng 6/1908"}]},{"n":105,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Chọn đáp án trả lời đúng nhất: Hồ Chí Minh đã từng dạy học ở ngôi trường nào?","answer":"D","options":[{"key":"A","text":"Trường tiểu học Pháp – Việt ở Vinh"},{"key":"B","text":"Trường tiểu học Đông Ba ở Huế"},{"key":"C","text":"Trường Quốc học Huế"},{"key":"D","text":"Trường Dục Thanh ở Phan Thiết"}]},{"n":106,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Nguyễn Ái Quốc viết 1 bức thư gửi cho 1 cán bộ của Quốc tế Cộng sản có đoạn viết “đồng chí có thể hình dung nơi tôi đang sống trong một tình trạng tinh thần và vật chất như thế nào không: biết là có nhiều công việc nhưng không thể làm gì được, ăn không ng ồi rồi, không có tiến, sống ngày nào hay ngày ấy mà không được phép hoạt động, vv..” bức thư đó Nguyễn Ái Quốc viết khi nào?","answer":"B","options":[{"key":"A","text":"4-1925"},{"key":"B","text":"4-1928"},{"key":"C","text":"4-1930"},{"key":"D","text":"4-1937"}]},{"n":107,"sec":"3. Nhân tố chủ quan Hồ Chí Minh","stem":"Nguyễn Tất Thành dạy học ở trường Dục Thanh vào thời gian nào?","answer":"C","options":[{"key":"A","text":"Tháng 9/1908 đến tháng 9/1909"},{"key":"B","text":"Tháng 9/1910 đến tháng 4/1911"},{"key":"C","text":"Tháng 9/1910 đến tháng 2/1911"},{"key":"D","text":"Tháng 1/1910 đến 5/1911"}]},{"n":108,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Tư tưởng Hồ Chí Minh được hình thành và phát triển qua mấy giai đoạn?","answer":"C","options":[{"key":"A","text":"3 giai đoạn"},{"key":"B","text":"4 giai đoạn"},{"key":"C","text":"5 giai đoạn"},{"key":"D","text":"6 giai đoạn"}]},{"n":109,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Thời kỳ nào sau đây đã đặt nền móng hình thành tư tưởng yêu nước và chí hướng tìm con đường cứu nước mới ở Hồ Chí Minh?","answer":"A","options":[{"key":"A","text":"Thời kỳ trước năm 1911"},{"key":"B","text":"Thời kỳ 1911-1920"},{"key":"C","text":"Thời kỳ 1920-1930"},{"key":"D","text":"Thời kỳ 1930-1941"}]},{"n":110,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Yếu tố nào sau đây góp phần sớm hình thành tư tưởng yêu nước của Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Sự phát triển kinh tế - văn hóa mạnh mẽ của nước Pháp đầu thế kỷ XX"},{"key":"B","text":"Truyền thống yêu nước, nhân nghĩa của quê hương, gia đình và dân tộc"},{"key":"C","text":"Ảnh hưởng của phong trào Thiên chúa giáo canh tân thời Pháp thuộc"},{"key":"D","text":"Tư tưởng cải cách đất nước theo hướng quân chủ lập hiến"}]},{"n":111,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Câu nói nổi tiếng “Quan trường là nô lệ trong những người nô lệ” là của ai?","answer":"C","options":[{"key":"A","text":"Phan Châu Trinh"},{"key":"B","text":"Cụ Hoàng Thị Loan"},{"key":"C","text":"Cụ Nguyễn Sinh Sắc"},{"key":"D","text":"Phan Bội Châu"}]},{"n":112,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Ảnh hưởng lớn nhất từ người mẹ – cụ Hoàng Thị Loan đến Hồ Chí Minh là gì?","answer":"B","options":[{"key":"A","text":"Tư duy pháp luật và hành chính, đào tạo chính trị từ trong gia đình"},{"key":"B","text":"Tấm lòng nhân hậu, cần mẫn, yêu thương con người và sống đạo đức"},{"key":"C","text":"Tài năng sư phạm và kỹ năng hùng biện khi còn nhỏ"},{"key":"D","text":"Ảnh hưởng tư tưởng cải cách theo mô hình Nhật Bản"}]},{"n":113,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Hồ Chí Minh đã tham gia phong trào chống thuế ở Trung Kỳ vào năm nào?","answer":"B","options":[{"key":"A","text":"1905"},{"key":"B","text":"1908"},{"key":"C","text":"1910"},{"key":"D","text":"1911"}]},{"n":114,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Điểm đặc biệt trong suy nghĩ tuổi trẻ của Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phản đối mọi hình thức đấu tranh yêu nước đương thời"},{"key":"B","text":"Tán thành hoàn toàn tư tưởng của Phan Bội Châu và Hoàng Hoa Thám"},{"key":"C","text":"Suy ngẫm sâu sắc về Tổ quốc và thời cuộc. Tuy rất khâm phục tinh thần yêu nước của các vị tiền bối nhưng Người sáng suốt phê phán, không tán thành, không đi theo các phương pháp, khuynh hướng cứu nước của các vị đó"},{"key":"D","text":"Muốn khôi phục lại chế độ phong kiến độc lập theo mô hình Minh Trị"}]},{"n":115,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Thời điểm nào Nguyễn Tất Thành đi ra nước ngoài tìm con đường cứu nước, cứu dân?","answer":"A","options":[{"key":"A","text":"Ngày 5/6/1911"},{"key":"B","text":"Ngày 5/6/1913"},{"key":"C","text":"Ngày 5/6/1915"},{"key":"D","text":"Ngày 5/6/1919"}]},{"n":116,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Nguyễn Tất Thành lên con tàu Amiran LatusơTơrovin để ra đi tìm đường cứu nước tại đâu? Vào thời gian nào?","answer":"C","options":[{"key":"A","text":"Ngày 4/6/1911 tại bến Nhà Rồng"},{"key":"B","text":"Ngày 5/6/1913 tại bến cảng Nhà Rồng"},{"key":"C","text":"Ngày 5/6/1911 tại bến cảng Nhà Rồng"},{"key":"D","text":"Ngày 5/6/1919 tại Hà Nội"}]},{"n":117,"sec":"1. Thời kỳ từ ngày 5-6-1911 trở về trước: Hình thành tư tưởng yêu nước và","stem":"Nguyễn Tất Thành ra đi tìm đường cứu nước lúc bao nhiêu tuổi?","answer":"C","options":[{"key":"A","text":"19 tuổi"},{"key":"B","text":"20 tuổi"},{"key":"C","text":"21 tuổi"},{"key":"D","text":"24 tuổi"}]},{"n":118,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Trong thời gian ở nước ngoài, Nguyễn Tất Thành làm những công việc gì?","answer":"D","options":[{"key":"A","text":"Phụ bếp, cào tuyết"},{"key":"B","text":"Thợ ảnh, làm bánh"},{"key":"C","text":"Đốt lò, bán báo"},{"key":"D","text":"Cả A, B và C"}]},{"n":119,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Hồ Chí Minh lấy tên Nguyễn Ái Quốc vào thời gian nào?","answer":"C","options":[{"key":"A","text":"Khi Bác lên tàu từ bến Nhà Rồng 1911"},{"key":"B","text":"Khi Bác tham gia sáng lâp Đảng Cộng Sản Pháp tại Đại Hội Tua tháng 12/1920."},{"key":"C","text":"Tại Hội Nghị Vécxay (Pháp) ngày 18/6/1919"},{"key":"D","text":"Khi Bác sang Liên Xô làm việc ở Ban Phương Đông của Quốc tế Cộng sản tháng 6/1923"}]},{"n":120,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Thời kỳ hình thành tư tưởng cứu nước, giải phóng dân tộc Việt Nam theo con đường cách mạng vô sản là thời kỳ nào?","answer":"B","options":[{"key":"A","text":"Thời kỳ trước năm 1911"},{"key":"B","text":"Thời kỳ 1911-1920"},{"key":"C","text":"Thời kỳ 1920-1930"},{"key":"D","text":"Thời kỳ 1930-1941"}]},{"n":121,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Trong giai đoạn 1911 - 1917, Hồ Chí Minh đã hình thành nhận thức nào sau đây?","answer":"C","options":[{"key":"A","text":"Tư sản và vô sản là đồng minh cách mạng"},{"key":"B","text":"Chủ nghĩa thực dân có thể cải cách nếu đấu tranh ôn hòa"},{"key":"C","text":"Nhân dân lao động các nước đều có thể là bạn; đế quốc ở đâu cũng là kẻ thù"},{"key":"D","text":"Cách mạng giải phóng dân tộc chỉ cần dựa vào trí thức"}]},{"n":122,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Khi trở lại Pháp năm 1917, Hồ Chí Minh đã tham gia phong trào nào?","answer":"B","options":[{"key":"A","text":"Phong trào bảo vệ quyền lợi người nhập cư"},{"key":"B","text":"Phong trào công nhân Pháp đấu tranh chống chủ nghĩa thực dân"},{"key":"C","text":"Phong trào bảo vệ hòa bình thế giới"},{"key":"D","text":"Phong trào cải cách xã hội và nhân đạo"}]},{"n":123,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Hồ Chí Minh gia nhập Đảng Xã hội Pháp vào năm nào?","answer":"B","options":[{"key":"A","text":"1917"},{"key":"B","text":"1919"},{"key":"C","text":"1920"},{"key":"D","text":"1923"}]},{"n":124,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Theo Hồ Chí Minh, lý tưởng cao quý của Đại Cách mạng Pháp là gì?","answer":"C","options":[{"key":"A","text":"Tự do, dân chủ, hạnh phúc"},{"key":"B","text":"Công bằng, đoàn kết, văn minh"},{"key":"C","text":"Tự do, bình đẳng, bác ái"},{"key":"D","text":"Hòa bình, hữu nghị, hợp tác"}]},{"n":125,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Nguyễn Ái Quốc gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Vécxây vào thời gian nào?","answer":"B","options":[{"key":"A","text":"1-5-1919"},{"key":"B","text":"18-6-1919"},{"key":"C","text":"2-9-1920"},{"key":"D","text":"30-12-1920"}]},{"n":126,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Bản yêu sách gửi Hội nghị Vécxây yêu cầu điều gì?","answer":"C","options":[{"key":"A","text":"Quyền độc lập dân tộc và thống nhất đất nước"},{"key":"B","text":"Quyền sở hữu đất đai cho nông dân"},{"key":"C","text":"Quyền tự do, dân chủ cho nhân dân Việt Nam"},{"key":"D","text":"Quyền bình đẳng kinh tế giữa các tầng lớp nhân dân"}]},{"n":127,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Thay mặt Hội những người Việt Nam yêu nước tại Pháp, Nguyễn Ái Quốc gửi bản “Yêu sách của nhân dân Việt Nam” tới Hội Nghị Vécxay. Bản Yêu sách gồm mấy điểm?","answer":"B","options":[{"key":"A","text":"6 điểm"},{"key":"B","text":"8 điểm"},{"key":"C","text":"9 điểm"},{"key":"D","text":"12 điểm"}]},{"n":128,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Văn kiện của Lênin đã giúp Hồ Chí Minh tìm thấy con đường cách mạng vô sản là gì?","answer":"C","options":[{"key":"A","text":"Bản Tuyên ngôn của Quốc tế Cộng sản"},{"key":"B","text":"Những nguyên lý chủ nghĩa Mác"},{"key":"C","text":"Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa"},{"key":"D","text":"Chủ nghĩa xã hội khoa học và dân tộc học"}]},{"n":129,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"“Luận cương của V.I. Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao. Tôi vui mừng đến phát khóc lên. Ngồi một minh trong buồng tối mà tôi nói to lên nhhư đang nói trước quần chúng đông đảo: hỡi đồng bào bị đọa đày đau khổ? Đây là cái cần thiết cho chung ta, đây là con đường giải phóng của chúng ta”. Câu nói này của Nguyễn Ái Quốc được trích từ tác phẩm nào?","answer":"B","options":[{"key":"A","text":"Cuộc đời hoạt động của Hồ Chủ tịch"},{"key":"B","text":"Con đường dẫn tôi đến với chủ nghĩa Mác - Lênin"},{"key":"C","text":"Lênin vĩ đại"},{"key":"D","text":"Cách mạng Tháng Mười và con đường vĩ đại"}]},{"n":130,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Hồ Chí Minh đọc được Luận cương của Lênin vào thời điểm nào?","answer":"B","options":[{"key":"A","text":"Tháng 6-1918"},{"key":"B","text":"Tháng 7-1920"},{"key":"C","text":"Tháng 5-1923"},{"key":"D","text":"Tháng 10-1921"}]},{"n":131,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Hồ Chí Minh bỏ phiếu tán thành Quốc tế Cộng sản tại Đại hội nào?","answer":"C","options":[{"key":"A","text":"Đại hội Paris 1919"},{"key":"B","text":"Đại hội Marseille 1921"},{"key":"C","text":"Đại hội Tua 1920"},{"key":"D","text":"Đại hội Lyon 1923"}]},{"n":132,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Hồ Chí Minh trở thành người cộng sản Việt Nam đầu tiên vào thời điểm nào?","answer":"C","options":[{"key":"A","text":"Đại hội Paris 1919"},{"key":"B","text":"Đại hội Marseille 1921"},{"key":"C","text":"Đại hội Tua 1920"},{"key":"D","text":"Đại hội Lyon 1923"}]},{"n":133,"sec":"2. Thời kỳ từ ngày 6-6-1911 đến ngày 30-12-1920: Hình thành tư tưởng cứu","stem":"Sự kiện nào đánh dấu bước ngoặt trong cuộc đời Hồ Chí Minh, kết hợp chủ nghĩa yêu nước với cách mạng vô sản?","answer":"C","options":[{"key":"A","text":"Gửi Yêu sách tới Hội nghị Vécxây"},{"key":"B","text":"Gia nhập Đảng Xã hội Pháp"},{"key":"C","text":"Tham gia Đại hội Tua, sáng lập Đảng Cộng sản Pháp"},{"key":"D","text":"Gặp gỡ phong trào công nhân ở Mỹ"}]},{"n":134,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Thời kỳ hình thành những nội dung cơ bản tư tưởng về cách mạng Việt Nam là thời kỳ nào?","answer":"C","options":[{"key":"A","text":"Thời kỳ trước năm 1911"},{"key":"B","text":"Thời kỳ 1911-1920"},{"key":"C","text":"Thời kỳ 1920-1930"},{"key":"D","text":"Thời kỳ 1930-1941"}]},{"n":135,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Hồ Chí Minh đã sử dụng báo chí Pháp để thực hiện điều gì?","answer":"C","options":[{"key":"A","text":"Phê phán chế độ phong kiến An Nam lạc hậu"},{"key":"B","text":"Quảng bá văn hóa Đông Dương ra quốc tế"},{"key":"C","text":"Lên án chủ nghĩa thực dân Pháp và thức tỉnh nhân dân thuộc địa"},{"key":"D","text":"Bảo vệ vai trò của giới trí thức bản xứ trong chính quyền Pháp"}]},{"n":136,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Báo Le Paria do Hồ Chí Minh sáng lập có vai trò gì?","answer":"D","options":[{"key":"A","text":"Diễn đàn văn hóa nghệ thuật của người Pháp yêu nước"},{"key":"B","text":"Cơ quan ngôn luận của phong trào nông dân ở Pháp"},{"key":"C","text":"Công cụ tuyên truyền về quyền lợi của công nhân Pháp"},{"key":"D","text":"Phương tiện để thức tỉnh tinh thần giải phóng dân tộc của nhân dân thuộc địa"}]},{"n":137,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Năm 1921, Hồ Chí Minh tham gia sáng lập tổ chức nào?","answer":"B","options":[{"key":"A","text":"Hội Pháp - Đông Dương hữu nghị"},{"key":"B","text":"Hội liên hiệp thuộc địa"},{"key":"C","text":"Hội truyền bá tư tưởng Mác"},{"key":"D","text":"Hội quốc tế công nhân"}]},{"n":138,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Hồ Chí Minh được bầu làm Trưởng Tiểu ban Nghiên cứu vấn đề dân tộc thuộc địa của tổ chức nào?","answer":"C","options":[{"key":"A","text":"Quốc tế Cộng sản"},{"key":"B","text":"Quốc hội Pháp"},{"key":"C","text":"Đảng Cộng sản Pháp"},{"key":"D","text":"Hội Liên hiệp quốc tế"}]},{"n":139,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Tác phẩm nào của Hồ Chí Minh xuất bản năm 1925 tại Paris?","answer":"D","options":[{"key":"A","text":"Đường cách mệnh"},{"key":"B","text":"Những mẩu chuyện về đời hoạt động của Lênin"},{"key":"C","text":"Thư gửi thanh niên Việt Nam"},{"key":"D","text":"Bản án chế độ thực dân Pháp"}]},{"n":140,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Tác phẩm “Bản án chế độ thực dân Pháp” được viết bằng ngôn ngữ nào?","answer":"D","options":[{"key":"A","text":"Tiếng Việt"},{"key":"B","text":"Tiếng Nga"},{"key":"C","text":"Tiếng Trung"},{"key":"D","text":"Tiếng Pháp"}]},{"n":141,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Tổ chức tiền thân của Đảng Cộng sản Việt Nam là?","answer":"C","options":[{"key":"A","text":"Đảng Lao động Việt Nam"},{"key":"B","text":"Đông Dương Cộng sản Đảng"},{"key":"C","text":"Hội Việt Nam Cách mạng Thanh niên"},{"key":"D","text":"Việt Nam Độc lập Đồng minh Hội"}]},{"n":142,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Hồ Chí Minh sáng lập tổ chức tiền thân của Đảng Cộng sản Việt Nam vào năm nào?","answer":"A","options":[{"key":"A","text":"Tháng 6/1925"},{"key":"B","text":"Tháng 7/1920"},{"key":"C","text":"Tháng 8/1928"},{"key":"D","text":"Tháng 2/1930"}]},{"n":143,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Báo \"Thanh niên\" do Hồ Chí Minh sáng lập được viết bằng ngôn ngữ nào?","answer":"A","options":[{"key":"A","text":"Tiếng Việt"},{"key":"B","text":"Tiếng Nga"},{"key":"C","text":"Tiếng Trung"},{"key":"D","text":"Tiếng Pháp"}]},{"n":144,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Tác phẩm “Đường cách mệnh” được xuất bản năm nào? Ở đâu?","answer":"C","options":[{"key":"A","text":"Năm 1925, ở Paris, Pháp"},{"key":"B","text":"Năm 1926, ở Hà Nội, Việt Nam"},{"key":"C","text":"Năm 1927, ở Quảng Châu, Trung Quốc"},{"key":"D","text":"Năm 1928, ở Moskva, Liên Xô"}]},{"n":145,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Tác phẩm “Đường cách mệnh” của Hồ Chí Minh thể hiện vai trò gì?","answer":"D","options":[{"key":"A","text":"Phác thảo mô hình nhà nước dân chủ mới"},{"key":"B","text":"Đề ra chiến lược phát triển kinh tế - xã hội"},{"key":"C","text":"Kêu gọi hợp tác với chính quyền Pháp để cải cách xã hội"},{"key":"D","text":"Chuẩn bị về chính trị, tư tưởng, tổ chức cho sự ra đời Đảng Cộng sản Việt Nam"}]},{"n":146,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam do ai khởi thảo?","answer":"C","options":[{"key":"A","text":"Trần Phú"},{"key":"B","text":"Nguyễn Văn Cừ"},{"key":"C","text":"Hồ Chí Minh"},{"key":"D","text":"Lê Hồng Phong"}]},{"n":147,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Mục tiêu cách mạng được Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam xác định là gì?","answer":"B","options":[{"key":"A","text":"Thực hiện cải cách kinh tế theo mô hình phương Tây"},{"key":"B","text":"Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản"},{"key":"C","text":"Xây dựng nhà nước quân chủ lập hiến và công nghiệp hóa đất nước"},{"key":"D","text":"Thúc đẩy thương mại tự do với các nước tư bản phát triển"}]},{"n":148,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Theo Cương lĩnh chính trị đầu tiên, lực lượng nòng cốt của cách mạng Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Giai cấp trí thức và tư sản dân tộc"},{"key":"B","text":"Quân đội và địa chủ tiến bộ"},{"key":"C","text":"Liên minh công nông"},{"key":"D","text":"Đội ngũ cán bộ hành chính và tiểu tư sản"}]},{"n":149,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Cương lĩnh chính trị đầu tiên xác định vai trò lãnh đạo của tổ chức nào?","answer":"C","options":[{"key":"A","text":"Quốc tế Cộng sản"},{"key":"B","text":"Hội Việt Nam Cách mạng Thanh niên"},{"key":"C","text":"Đảng Cộng sản Việt Nam"},{"key":"D","text":"Đảng Cộng sản Pháp"}]},{"n":150,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Cương lĩnh 1930 khẳng định cách mạng Việt Nam là bộ phận của phong trào nào?","answer":"C","options":[{"key":"A","text":"Phong trào độc lập dân tộc ở châu Á"},{"key":"B","text":"Cách mạng châu Á và phong trào giải phóng dân tộc"},{"key":"C","text":"Cách mạng thế giới"},{"key":"D","text":"Phong trào xã hội chủ nghĩa tại châu Âu"}]},{"n":151,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Cương lĩnh chính trị đầu tiên đã vận dụng sáng tạo chủ nghĩa Mác - Lênin vào việc giải quyết mối quan hệ nào?","answer":"D","options":[{"key":"A","text":"Quan hệ giữa đế quốc và thuộc địa"},{"key":"B","text":"Quan hệ giữa nhà nước và tôn giáo"},{"key":"C","text":"Quan hệ giữa công nhân và chủ đất"},{"key":"D","text":"Mối quan hệ giai cấp - dân tộc - quốc tế"}]},{"n":152,"sec":"3. Thời kỳ từ ngày 31 -12-1920 đến ngày 3 -2-1930: Hình thành những nội","stem":"Việc thành lập Đảng Cộng sản Việt Nam và ban hành Cương lĩnh chính trị đầu tiên đã chấm dứt điều gì?","answer":"C","options":[{"key":"A","text":"Sự lệ thuộc vào đế quốc Pháp"},{"key":"B","text":"Sự chia rẽ giữa các phong trào dân tộc"},{"key":"C","text":"Cuộc khủng hoảng về đường lối và tổ chức lãnh đạo cách mạng Việt Nam"},{"key":"D","text":"Sự thiếu thống nhất trong nền kinh tế thuộc địa"}]},{"n":153,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Thời kỳ vượt qua thử thách, giữ vững đường lối, phương pháp cách mạng Việt Nam đúng đắn, sáng tạo là thời kỳ nào?","answer":"D","options":[{"key":"A","text":"Thời kỳ trước năm 1911"},{"key":"B","text":"Thời kỳ 1911-1920"},{"key":"C","text":"Thời kỳ 1920-1930"},{"key":"D","text":"Thời kỳ 1930-1941"}]},{"n":154,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Tư tưởng Hồ Chí Minh trong Cương lĩnh chính trị đầu tiên bị một số người trong Quốc tế Cộng sản phê phán như thế nào?","answer":"B","options":[{"key":"A","text":"Cho rằng đó là tư tưởng phản cách mạng"},{"key":"B","text":"Bị coi là “hữu khuynh”, “dân tộc chủ nghĩa”"},{"key":"C","text":"Bị phê phán là quá thiên về quân sự"},{"key":"D","text":"Cho là không phù hợp với chủ nghĩa Mao"}]},{"n":155,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Hội nghị Trung ương Đảng tháng 10-1930 đã có quan điểm sai lầm gì về Hội nghị thành lập Đảng do Nguyễn Ái Quốc chủ trì?","answer":"B","options":[{"key":"A","text":"Cho rằng Hội nghị thiếu tính quốc tế"},{"key":"B","text":"Cho rằng Hội nghị “chỉ lo phản đế mà quên đấu tranh giai cấp”"},{"key":"C","text":"Cho rằng Hội nghị chưa hợp thức hóa tổ chức chính trị"},{"key":"D","text":"Cho rằng Hội nghị tập trung quá nhiều vào trí thức"}]},{"n":156,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Theo nghị quyết tháng 10-1930, tên Đảng Cộng sản Việt Nam được thay bằng tên nào?","answer":"A","options":[{"key":"A","text":"Đảng Cộng sản Đông Dương"},{"key":"B","text":"Đảng Lao động Việt Nam"},{"key":"C","text":"Đông Dương Cộng sản Đoàn"},{"key":"D","text":"Liên minh Cộng sản Việt – Lào – Miên"}]},{"n":157,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Hồ Chí Minh rời Liên Xô vào thời điểm nào để bắt đầu hành trình trở về Việt Nam?","answer":"A","options":[{"key":"A","text":"Tháng 10 năm 1938"},{"key":"B","text":"Tháng 10 năm 1939"},{"key":"C","text":"Tháng 12 năm 1937"},{"key":"D","text":"Tháng 1 năm 1940"}]},{"n":158,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Tư tưởng Hồ Chí Minh trở thành yếu tố chỉ đạo cách mạng Việt Nam từ Hội nghị Trung ương Đảng vào thời điểm nào?","answer":"C","options":[{"key":"A","text":"Tháng 11-1939"},{"key":"B","text":"Tháng 3-1940"},{"key":"C","text":"Tháng 5-1941"},{"key":"D","text":"Tháng 7-1942"}]},{"n":159,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Hội nghị Trung ương tháng 5-1941 do Hồ Chí Minh chủ trì được tổ chức ở đâu?","answer":"C","options":[{"key":"A","text":"Tân Trào, Tuyên Quang"},{"key":"B","text":"Thái Nguyên"},{"key":"C","text":"Pác Bó, Cao Bằng"},{"key":"D","text":"Đồng Văn, Hà Giang"}]},{"n":160,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Hội nghị Trung ương tháng 5-1941 đã đặt nhiệm vụ nào lên hàng đầu?","answer":"B","options":[{"key":"A","text":"Giải phóng giai cấp"},{"key":"B","text":"Giải phóng dân tộc"},{"key":"C","text":"Giải phóng con người"},{"key":"D","text":"Giải phóng xã hội"}]},{"n":161,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Tại Hội nghị Trung ương 5 -1941, khẩu hiệu cách mạng điền địa được xử lý như thế nào?","answer":"C","options":[{"key":"A","text":"Đẩy mạnh hơn trong kháng chiến"},{"key":"B","text":"Tiếp tục thực hiện song song"},{"key":"C","text":"Tạm thời gác lại"},{"key":"D","text":"Phủ định hoàn toàn"}]},{"n":162,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Hội nghị Trung ương Đảng tháng 5 -1941 đã hoàn chỉnh bước chuyển hướng nào?","answer":"D","options":[{"key":"A","text":"Chuyển hướng ưu tiên đấu tranh giai cấp tại nông thôn"},{"key":"B","text":"Chuyển hướng từ đấu tranh hòa bình sang bạo lực vũ trang"},{"key":"C","text":"Chuyển hướng chiến lược cách mạng dân tộc dân chủ sang cách mạng xã hội chủ nghĩa"},{"key":"D","text":"Chuyển hướng chiến lược và sách lược của cách mạng Việt Nam được vạch ra từ Hội nghị Trung ương Đảng tháng 11 năm 1939"}]},{"n":163,"sec":"4. Thời kỳ từ ngày 4-2-1930 đến ngày 28-1-1941: Vượt qua thử thách, giữ","stem":"Năm 1941, Nguyễn Ái Quốc viết một tác phẩm có câu mở đầu: “Dân ta phải biết sử ta; Cho tường gốc tích nước nhà Việt Nam”. Đó là tác phẩm… ?","answer":"B","options":[{"key":"A","text":"“Đường cách mệnh”"},{"key":"B","text":"“Lịch sử nước ta”"},{"key":"C","text":"“Bài ca du kích”"},{"key":"D","text":"“Di chúc”"}]},{"n":164,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Thời kỳ tư tưởng Hồ Chí Minh tiếp tục phát triển, soi đường cho sự nghiệp cách mạng của Đảng và nhân dân ta là thời kỳ nào?","answer":"D","options":[{"key":"A","text":"Thời kỳ 1911-1920"},{"key":"B","text":"Thời kỳ 1920-1930"},{"key":"C","text":"Thời kỳ 1930-1941"},{"key":"D","text":"Thời kỳ 1941 – 1969"}]},{"n":165,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Ngày 19/5/1941 Hồ Chí Minh sáng lập tổ chức nào?","answer":"A","options":[{"key":"A","text":"Mặt trận Việt Minh"},{"key":"B","text":"Đội Việt Nam tuyên truyền giải phóng quân"},{"key":"C","text":"Hội Nông dân cứu quốc Việt Nam"},{"key":"D","text":"Quốc dân Đại hội tại Tân Trào"}]},{"n":166,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Tổ chức nào do Hồ Chí Minh sáng lập vào ngày 22-12-1944, là tiền thân của Quân đội Nhân dân Việt Nam?","answer":"B","options":[{"key":"A","text":"Đội du kích Bắc Sơn, lực lượng vũ trang đầu tiên của dân tộc"},{"key":"B","text":"Đội Việt Nam tuyên truyền giải phóng quân"},{"key":"C","text":"Mặt trận Giải phóng quân, đội quân chính trị và quân sự song song"},{"key":"D","text":"Đội cứu quốc quân Việt Nam, do Hội Cứu quốc tổ chức"}]},{"n":167,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Hồ Chí Minh ra Lời kêu gọi Tổng khởi nghĩa giành chính quyền vào thời gian nào?","answer":"B","options":[{"key":"A","text":"Ngày 23-8-1945"},{"key":"B","text":"Ngày 18-8-1945"},{"key":"C","text":"Ngày 15-8-1945"},{"key":"D","text":"Ngày 19-8-1945"}]},{"n":168,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Thắng lợi của Cách mạng Tháng Tám 1945 có ý nghĩa như thế nào đối với cdân tộc Việt Nam?","answer":"C","options":[{"key":"A","text":"Thiết lập chính quyền quân sự lâm thời để quản lý đất nước"},{"key":"B","text":"Mở đầu quá trình đàm phán hòa bình với thực dân Pháp"},{"key":"C","text":"Lật đổ chế độ phong kiến hơn ngàn năm, l ật đổ ách thống trị của thực dân Pháp hơn 80 năm và giành lại độc lập dân tộc trực tiếp từ tay phát xít Nhật"},{"key":"D","text":"Thống nhất đất nước dưới sự lãnh đạo của nhà Nguyễn"}]},{"n":169,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Đâu được coi là thắng lợi to lớn đầu tiên của chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh ở Việt Nam?","answer":"C","options":[{"key":"A","text":"Phong trào Xô viết Nghệ Tĩnh năm 1930–1931"},{"key":"B","text":"Chiến thắng Điện Biên Phủ năm 1954"},{"key":"C","text":"Cách mạng Tháng Tám thành công năm 1945"},{"key":"D","text":"Chiến thắng “Điện Biên Phủ trên không” năm 1972"}]},{"n":170,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Sự kiện nào mở ra một thời đại mới trong lịch sử dân tộc Việt Nam, thời đại độc lập dân tộc gắn liền với chủ nghĩa xã hội?","answer":"C","options":[{"key":"A","text":"Hồ Chí Minh kêu gọi toàn quốc kháng chiến năm 1946"},{"key":"B","text":"Đảng Cộng sản Đông Dương đổi tên thành Đảng Lao động Việt Nam"},{"key":"C","text":"Hồ Chí Minh đọc Tuyên ngôn Độc lập vào ngày 2-9-1945"},{"key":"D","text":"Hội nghị Chính trị đặc biệt tháng 3-1964 về chiến lược miền Nam"}]},{"n":171,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Ngày 2-9-1945 ở Việt Nam đã diễn ra sự kiện lịch sử trọng đại nào?","answer":"C","options":[{"key":"A","text":"Hồ Chí Minh kêu gọi toàn quốc kháng chiến năm 1946"},{"key":"B","text":"Đảng Cộng sản Đông Dương đổi tên thành Đảng Lao động Việt Nam"},{"key":"C","text":"Hồ Chí Minh đọc Tuyên ngôn Độc lập vào ngày 2-9-1945"},{"key":"D","text":"Hội nghị Chính trị đặc biệt tháng 3-1964 về chiến lược miền Nam"}]},{"n":172,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Phương châm hành động nào của Hồ Chí Minh trong giai đoạn 1945–1946 thể hiện sách lược ngoại giao mềm dẻo và nguyên tắc?","answer":"B","options":[{"key":"A","text":"Lấy đoàn kết dân tộc làm cơ sở cho đàm phán hòa bình lâu dài"},{"key":"B","text":"Dĩ bất biến ứng vạn biến, giữ vững độc lập dân tộc bằng sách lược linh hoạt"},{"key":"C","text":"Cách mạng là sự nghiệp của toàn dân, cần tranh thủ thời gian hòa hoãn"},{"key":"D","text":"Lấy đấu tranh vũ trang làm phương tiện duy nhất để giữ độc lập"}]},{"n":173,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Trong kháng chiến chống thực dân Pháp, Đảng ta và Chủ tịch Hồ Chí Minh đã xác định đường lối kháng chiến như thế nào?","answer":"C","options":[{"key":"A","text":"Toàn diện, toàn dân, lâu dài và dựa vào viện trợ quốc tế là chủ yếu"},{"key":"B","text":"Dựa trên cơ sở ngoại giao mềm dẻo và chính trị đa phương"},{"key":"C","text":"Lâu dài, toàn dân, toàn diện, tự lực cánh sinh"},{"key":"D","text":"Tập trung xây dựng lực lượng chủ lực để đánh nhanh thắng nhanh"}]},{"n":174,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến vào thời gian nào?","answer":"B","options":[{"key":"A","text":"2/9/1945"},{"key":"B","text":"19/12/1946"},{"key":"C","text":"19/5/1950"},{"key":"D","text":"21/7/1954"}]},{"n":175,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Lời kêu gọi toàn quốc kháng chiến ngày 19-12-1946 thể hiện điều gì?","answer":"D","options":[{"key":"A","text":"Tinh thần cải cách hành chính để tăng cường năng lực chiến tranh"},{"key":"B","text":"Chủ trương đàm phán hòa bình lâu dài với thực dân Pháp"},{"key":"C","text":"Khuyến khích toàn dân học tập kinh nghiệm cách mạng Trung Quốc"},{"key":"D","text":"Ý chí không nhân nhượng, quyết tâm bảo vệ độc lập dân tộc đến cùng"}]},{"n":176,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Giai đoạn từ 1954–1969, cách mạng Việt Nam có đặc điểm nổi bật gì?","answer":"C","options":[{"key":"A","text":"Tập trung xây dựng nền kinh tế thị trường theo định hướng dân chủ"},{"key":"B","text":"Đấu tranh thống nhất đất nước bằng con đường ngoại giao hòa bình"},{"key":"C","text":"Đồng thời thực hiện hai nhiệm vụ chiến lược ở hai miền Bắc - Nam"},{"key":"D","text":"Xây dựng hệ thống quân sự hóa toàn dân để chống lại chiến tranh lạnh"}]},{"n":177,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Hồ Chí Minh ra Lời kêu gọi đồng bào và chiến sĩ cả nước vào thời gian nào?","answer":"A","options":[{"key":"A","text":"17-7-1966"},{"key":"B","text":"18-7-1966"},{"key":"C","text":"30-7-1966"},{"key":"D","text":"1-8-1967"}]},{"n":178,"sec":"5. Thời kỳ từ ngày 29-1-1941 đến ngày 2-9-1969: Tư tưởng Hồ Chí Minh tiếp","stem":"Điền từ còn thiếu vào (_____)? “Toàn Đảng, toàn dân ta đoàn kết phấn đấu, xây dựng một nước Việt Nam (_____), (_____), (_____), (_____), và góp phần xứng đáng vào sự nghiệp cách mạng thế giới\" (Hồ Chí Minh: Toàn tập, Sđd, t.15, tr. 624)","answer":"B","options":[{"key":"A","text":"Độc lập, dân chủ, hòa bình, thịnh vượng"},{"key":"B","text":"Hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"C","text":"Hòa bình, dân tộc, công bằng, văn minh và phát triển"},{"key":"D","text":"Thống nhất, toàn vẹn, dân chủ, công bằng và đoàn kết"}]},{"n":179,"sec":"1. Đối với cách mạng Việt Nam","stem":"Tư tưởng Hồ Chí Minh có vai trò như thế nào đối với cách mạng giải phóng dân tộc Việt Nam?","answer":"C","options":[{"key":"A","text":"Chỉ đóng vai trò bổ trợ cho phong trào giải phóng dân tộc ở khu vực Đông Nam Á"},{"key":"B","text":"Là một hình thức biểu hiện tinh thần dân tộc thuần túy, không mang tính lý luận"},{"key":"C","text":"Đưa cách mạng giải phóng dân tộc Việt Nam đến thắng lợi và bắt đầu xây dựng một xã hội mới trên đất nước ta"},{"key":"D","text":"Đóng vai trò giáo dục đạo đức là chính, ít ảnh hưởng đến phương hướng cách mạng"}]},{"n":180,"sec":"1. Đối với cách mạng Việt Nam","stem":"Thành tựu nào được xem là minh chứng rõ nhất cho tính đúng đắn và sáng tạo của tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Sự phát triển kinh tế thị trường theo mô hình của các nước phát triển"},{"key":"B","text":"Sự thống nhất giữa chủ nghĩa xã hội và chủ nghĩa tư bản trong thể chế nhà nước"},{"key":"C","text":"Những thắng lợi liên tiếp của cách mạng Việt Nam qua từng thời kỳ lịch sử"},{"key":"D","text":"Việc áp dụng linh hoạt mô hình chính trị của các nước Xã hội chủ nghĩa Đông Âu"}]},{"n":181,"sec":"1. Đối với cách mạng Việt Nam","stem":"Tư tưởng Hồ Chí Minh là hệ thống những quan điểm lý luận về?","answer":"B","options":[{"key":"A","text":"Quản lý nhà nước, phát triển công nghiệp hóa – hiện đại hóa theo mô hình thị trường"},{"key":"B","text":"Chiến lược cách mạng dân tộc dân chủ nhân dân và cách mạng xã hội chủ nghĩa ở Việt Nam"},{"key":"C","text":"Cách thức vận hành thể chế nhà nước tam quyền phân lập theo kiểu phương Tây"},{"key":"D","text":"Sự kết hợp giữa dân chủ tự do và mô hình quân chủ lập hiến ở Việt Nam"}]},{"n":182,"sec":"1. Đối với cách mạng Việt Nam","stem":"Tư tưởng Hồ Chí Minh lần đầu tiên mang lại điều gì cho lịch sử tư tưởng Việt Nam?","answer":"B","options":[{"key":"A","text":"Một hệ thống tư tưởng thuần triết học phương Đông cổ điển"},{"key":"B","text":"Tư tưởng định hướng, soi đường, chỉ đạo sự phát triển của cách mạng Việt Nam và dân tộc Việt Nam là của chính người Việt Nam"},{"key":"C","text":"Sự du nhập trọn vẹn của tư tưởng Marx - Lenin từ phương Tây"},{"key":"D","text":"Một học thuyết kết hợp Nho giáo với hệ thống đạo đức truyền thống"}]},{"n":183,"sec":"1. Đối với cách mạng Việt Nam","stem":"Tư tưởng Hồ Chí Minh giúp Đảng ta và nhân dân ta làm gì trong bối cảnh thế giới hiện nay?","answer":"B","options":[{"key":"A","text":"Chủ động hội nhập toàn diện vào hệ thống kinh tế tư bản toàn cầu"},{"key":"B","text":"Nhận thức đúng những vấn đề lớn có liên quan đến việc bảo vệ nền độc lập dân tộc, phát triển kinh tế-xã hội, bảo đảm tự do và hạnh phúc của con người, tiến tới xã hội xã hội chủ nghĩa"},{"key":"C","text":"Ưu tiên đầu tư phát triển khoa học kỹ thuật theo định hướng thị trường"},{"key":"D","text":"Kết hợp chặt chẽ giữa chính trị quốc tế và ngoại giao đa phương hóa"}]},{"n":184,"sec":"1. Đối với cách mạng Việt Nam","stem":"Tư tưởng Hồ Chí Minh có vai trò gì trong việc xây dựng đường lối cách mạng của Đảng?","answer":"B","options":[{"key":"A","text":"Là tài liệu giáo khoa để học tập, không ảnh hưởng đến đường lối thực tiễn"},{"key":"B","text":"Là nền tảng và chỗ dựa tư tưởng vững chắc để xác định đường lối đúng đắn"},{"key":"C","text":"Là một phần trong hệ tư tưởng khu vực Đông Nam Á mang tính tham khảo"},{"key":"D","text":"Là tư tưởng cần được điều chỉnh để phù hợp với chính trị đương đại"}]},{"n":185,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hồ Chí Minh được thế giới tôn vinh là ai trong thời đại ngày nay?","answer":"C","options":[{"key":"A","text":"Một lãnh tụ đại diện cho khối các nước công nghiệp mới nổi"},{"key":"B","text":"Người sáng lập phong trào xã hội dân chủ kiểu mới"},{"key":"C","text":"Anh hùng giải phóng dân tộc và danh nhân văn hóa thế giới"},{"key":"D","text":"Người đặt nền móng cho chủ nghĩa tự do trong phong trào độc lập dân tộc"}]},{"n":186,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Theo tư tưởng Hồ Chí Minh, cách mạng giải phóng dân tộc muốn thắng lợi phải theo con đường nào?","answer":"C","options":[{"key":"A","text":"Con đường dân chủ tư sản kiểu phương Tây, do tầng lớp trí thức lãnh đạo"},{"key":"B","text":"Con đường bạo lực thuần túy, không cần tổ chức chính trị dẫn dắt"},{"key":"C","text":"Con đường cách mạng vô sản, dưới sự lãnh đạo của Đảng cộng sản"},{"key":"D","text":"Con đường vận động ngoại giao hòa bình, phi chính trị hóa quần chúng"}]},{"n":187,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hồ Chí Minh là người đầu tiên đề xuất điều gì trong lý luận giải phóng dân tộc?","answer":"B","options":[{"key":"A","text":"Giải phóng dân tộc là nhiệm vụ của tầng lớp trung lưu đô thị"},{"key":"B","text":"Cách mạng giải phóng dân tộc có thể thắng lợi trước cách mạng vô sản ở chính quốc"},{"key":"C","text":"Cách mạng chỉ có thể thành công nếu được viện trợ từ các nước lớn"},{"key":"D","text":"Phong trào giải phóng dân tộc phải đi sau công nghiệp hóa"}]},{"n":188,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Điểm đặc sắc trong tư tưởng Hồ Chí Minh về cách mạng giải phóng dân tộc là gì?","answer":"C","options":[{"key":"A","text":"Tập trung vào đấu tranh giai cấp trong nội bộ xã hội thuộc địa"},{"key":"B","text":"Phân tích các mô hình tự trị và liên bang kiểu mới ở châu Á"},{"key":"C","text":"Gắn giải phóng dân tộc với giải phóng giai cấp và con người"},{"key":"D","text":"Đề cao việc phát triển thị trường tự do trước khi giải phóng dân tộc"}]},{"n":189,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Trong tư tưởng Hồ Chí Minh, cách mạng giải phóng dân tộc cần tiến hành như thế nào?","answer":"C","options":[{"key":"A","text":"Dựa vào can thiệp quốc tế để tránh đổ máu và bất ổn"},{"key":"B","text":"Ưu tiên hòa bình, tránh bạo lực dù phải nhân nhượng về chủ quyền"},{"key":"C","text":"Cần được tiến hành chủ động, sáng tạo, có thể thắng lợi trước cách mạng vô sản ở chính quốc, bằng con đường bạo lực: Kết hợp đấu tranh chính trị của quần chúng với đấu tranh vũ trang"},{"key":"D","text":"Đề cao việc phát triển thị trường tự do trước khi giải phóng dân tộc"}]},{"n":190,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hồ Chí Minh là người Việt Nam đầu tiên khẳng định điều gì là xu thế tất yếu của thời đại?","answer":"C","options":[{"key":"A","text":"Toàn cầu hóa thị trường, tự do hóa thương mại và tư bản hóa kinh tế"},{"key":"B","text":"Hội nhập văn hóa khu vực Đông Á theo mô hình đa nguyên chính trị"},{"key":"C","text":"Hợp tác quốc tế là xu thế tất yếu của thời đại, phá bỏ sự biệt lập, mở đường cho sự phát triển, liên kết các dân tộc trong cuộc đấu tranh vì độc lập, tự do, hòa bình, dân chủ và tiến bộ xã hội"},{"key":"D","text":"Phát triển tư duy tự cường và không cần liên minh quốc tế"}]},{"n":191,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Nội dung nào sau đây phản ánh đúng tư tưởng Hồ Chí Minh về hợp tác quốc tế?","answer":"B","options":[{"key":"A","text":"Hợp tác quốc tế là phương tiện ngắn hạn để chống lại ảnh hưởng từ các nước lớn"},{"key":"B","text":"Hợp tác quốc tế trên cơ sở giữ vững độc lập, chủ quyền, bình đẳng và cùng có lợi"},{"key":"C","text":"Hợp tác chỉ cần thiết khi đất nước gặp khó khăn về kinh tế - xã hội"},{"key":"D","text":"Hợp tác quốc tế chủ yếu phục vụ các mục tiêu chiến lược của các quốc gia lớn"}]},{"n":192,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hồ Chí Minh từng khẳng định nội dung lớn nào sau đây về chính sách đối ngoại?","answer":"C","options":[{"key":"A","text":"Làm bạn với các quốc gia có cùng thể chế và lợi ích chiến lược"},{"key":"B","text":"Chỉ hợp tác với các nước xã hội chủ nghĩa và các lực lượng cách mạng"},{"key":"C","text":"Làm bạn với tất cả các nước dân chủ và không gây thù oán với một ai"},{"key":"D","text":"Ưu tiên quan hệ quốc tế kinh tế trước chính trị và văn hóa"}]},{"n":193,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hồ Chí Minh đã gắn cách mạng Việt Nam với các phong trào nào?","answer":"B","options":[{"key":"A","text":"Phong trào tư bản hóa và dân chủ hóa của các nước phát triển"},{"key":"B","text":"Phong trào giải phóng dân tộc, phong trào đấu tranh của giai cấp công nhân trong các nước tư bản và phong trào cộng sản quốc tế"},{"key":"C","text":"Phong trào học thuật phương Đông và trào lưu cải cách hành chính"},{"key":"D","text":"Phong trào kỹ trị và xã hội dân sự trong các nước phương Tây"}]},{"n":194,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Tư tưởng Hồ Chí Minh về hợp tác quốc tế không chỉ nhằm giành độc lập dân tộc, mà còn hướng đến mục tiêu nào?","answer":"B","options":[{"key":"A","text":"Thiết lập trật tự thế giới đơn cực để đảm bảo lợi ích quốc gia"},{"key":"B","text":"Xóa bỏ nghèo nàn, lạc hậu, tiến kịp các nước tiên tiến và sâu xa là đặt chiến lược phát triển đất nước gắn với những chuyển biến của thời đại …"},{"key":"C","text":"Phát triển thị trường tự do và thương mại hóa nền kinh tế dân tộc"},{"key":"D","text":"Mở rộng ảnh hưởng văn hóa và mô hình chính trị xã hội chủ nghĩa ra toàn cầu"}]},{"n":195,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Hợp tác quốc tế theo tư tưởng Hồ Chí Minh cần gắn kết điều gì?","answer":"B","options":[{"key":"A","text":"Phát triển nền kinh tế mở và đa phương hóa mọi lĩnh vực xã hội"},{"key":"B","text":"Phát huy sức mạnh nội lực của dân tộc kết hợp sức mạnh thời đại, đồng thời không quên nghĩa vụ quốc tế"},{"key":"C","text":"ứng dụng mô hình đối tác công - tư và các hiệp định tự do thương mại"},{"key":"D","text":"Tập trung hoàn toàn vào mục tiêu xuất khẩu và thu hút đầu tư ngoại tệ"}]},{"n":196,"sec":"2. Đối với sự phát triển tiến bộ của nhân loại","stem":"Theo Đại hội XII của Đảng, tư tưởng Hồ Chí Minh được khẳng định là gì?","answer":"C","options":[{"key":"A","text":"Một học thuyết hiện đại hóa kinh tế có giá trị quốc tế lâu dài"},{"key":"B","text":"Một hệ thống triết lý giáo dục và khoa học toàn diện"},{"key":"C","text":"Nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng và cách mạng Việt Nam, là tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta, mãi mãi soi đường cho sự nghiệp cách mạng của Đảng và nhân dân ta"}]}]},{"id":"III","title":"TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐỘC LẬP DÂN TỘC VÀ CHỦ NGHĨA XÃ HỘI","questions":[{"n":1,"sec":"","stem":"Theo tư tưởng Hồ Chí Minh, quyền thiêng liêng và bất khả xâm phạm của tất cả các dân tộc là gì?","answer":"C","options":[{"key":"A","text":"Quyền phát triển văn hóa, giáo dục và khoa học công nghệ"},{"key":"B","text":"Quyền bình đẳng giới, bình đẳng tôn giáo và tự do đi lại"},{"key":"C","text":"Quyền độc lập, tự do"},{"key":"D","text":"Quyền được hỗ trợ tài chính và viện trợ quốc tế"}]},{"n":2,"sec":"","stem":"Lần đầu tiên tư tưởng Hồ Chí Minh về quyền của các dân tộc thuộc địa được thể hiện qua sự kiện nào?","answer":"D","options":[{"key":"A","text":"Hồ Chí Minh gửi bản yêu sách đến Hội nghị Giơnevơ đòi quyền cho người Việt"},{"key":"B","text":"Hồ Chí Minh tham gia Hội nghị Pari để đàm phán về chủ quyền dân tộc"},{"key":"C","text":"Hồ Chí Minh đọc bản Tuyên ngôn Độc lập tại Quảng trường Ba Đình năm 1945"},{"key":"D","text":"Hồ Chí Minh gửi bản Yêu sách của nhân dân An Nam đến Hội nghị Vécxây năm 1919"}]},{"n":3,"sec":"","stem":"Bản Yêu sách của nhân dân An Nam do Hồ Chí Minh gửi năm 1919 có nội dung chính là gì?","answer":"A","options":[{"key":"A","text":"Đòi quyền bình đẳng về mặt pháp lý và đòi các quyền tự do, dân chủ của người dân Đông Dương"},{"key":"B","text":"Đề nghị được độc lập hoàn toàn về chính trị và kinh tế"},{"key":"C","text":"Phản đối sự đàn áp văn hóa truyền thống của người Việt"},{"key":"D","text":"Tuyên bố thành lập chính phủ tự trị tại các vùng bị chiếm đóng"}]},{"n":4,"sec":"","stem":"Điền từ còn thiếu vào (_____)? “Cái mà tôi cần nhất trên đời là đồng bào tôi được (_____), Tổ quốc tôi được (_____)”","answer":"B","options":[{"key":"A","text":"Độc lập - tự do"},{"key":"B","text":"Tự do - độc lập"},{"key":"C","text":"Dân chủ - hạnh phúc"},{"key":"D","text":"Hạnh phúc - tự do"}]},{"n":5,"sec":"","stem":"Phát biểu nào sau đây KHÔNG phù hợp với tư tưởng Hồ Chí Minh về quyền dân tộc?","answer":"C","options":[{"key":"A","text":"Mỗi dân tộc có quyền sống, quyền sung sướng và quyền tự do"},{"key":"B","text":"Tất cả các dân tộc sinh ra đều bình đẳng, không ai có quyền xâm phạm"},{"key":"C","text":"Quyền độc lập dân tộc có thể linh hoạt tùy vào điều kiện lịch sử"},{"key":"D","text":"Độc lập dân tộc là điều kiện tiên quyết để có tự do cho nhân dân"}]},{"n":6,"sec":"","stem":"Tuyên bố “Tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do…Đó là những lẽ phải không ai chối cãi được” của Hồ Chí Minh được viết trong văn kiện nào?","answer":"B","options":[{"key":"A","text":"Bản Tuyên ngôn Nhân quyền của Liên Hợp Quốc"},{"key":"B","text":"Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa năm 1945"},{"key":"C","text":"Cương lĩnh của Đảng Lao động Việt Nam lần thứ nhất"},{"key":"D","text":"Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa"}]},{"n":7,"sec":"","stem":"Trong tư tưởng Hồ Chí Minh, giá trị nào là thiêng liêng và bất biến nhất?","answer":"D","options":[{"key":"A","text":"Chủ quyền kinh tế và quyền khai thác tài nguyên thiên nhiên"},{"key":"B","text":"Quyền có chính phủ riêng và lực lượng quân sự tự vệ"},{"key":"C","text":"Khả năng đàm phán ngoại giao và liên kết quốc tế bền vững"},{"key":"D","text":"Độc lập dân tộc và tự do của nhân dân là giá trị thiêng liêng nhất"}]},{"n":8,"sec":"","stem":"Trong Tuyên ngôn Độc lập năm 1945, Hồ Chí Minh tuyên bố điều gì về quyền tự do và độc lập của dân tộc Việt Nam?","answer":"C","options":[{"key":"A","text":"Tự do và độc lập là mục tiêu tương lai của dân tộc Việt Nam"},{"key":"B","text":"Việt Nam sẽ đấu tranh để từng bước giành lại tự do và độc lập"},{"key":"C","text":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do và độc lập"},{"key":"D","text":"Chính phủ Việt Nam cam kết thúc đẩy quyền tự do và dân chủ toàn diện"}]},{"n":9,"sec":"","stem":"Hồ Chí Minh khẳng định điều gì trong thư gửi Liên Hợp Quốc năm 1946?","answer":"B","options":[{"key":"A","text":"Nhân dân Việt Nam chấp nhận nhượng bộ để giữ gìn hòa bình và ổn định"},{"key":"B","text":"Nhân dân Việt Nam thành thật mong muốn hoà bình, nhưng cũng kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất"},{"key":"C","text":"Chính phủ Việt Nam cam kết duy trì quan hệ quốc tế hoà bình và ổn định"},{"key":"D","text":"Việt Nam sẵn sàng thương lượng để chấm dứt chiến tranh theo nguyên tắc song phương"}]},{"n":10,"sec":"","stem":"Trong Lời kêu gọi toàn quốc kháng chiến ngày 19-12-1946, Hồ Chí Minh tuyên bố điều gì, thể hiện quyết tâm sắt đá, bảo vệ cho bằng được nền độc lập dân tộc?","answer":"C","options":[{"key":"A","text":"Dân tộc Việt Nam sẵn sàng hoà giải để gìn giữ nền hoà bình quốc gia"},{"key":"B","text":"Chúng ta sẵn sàng thỏa hiệp nếu có cơ hội duy trì chủ quyền dân tộc"},{"key":"C","text":"Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ"},{"key":"D","text":"Hòa bình là mục tiêu cuối cùng, chiến tranh chỉ là biện pháp tạm thời để đạt được mục tiêu đó"}]},{"n":11,"sec":"","stem":"Câu nói “Không có gì quý hơn độc lập, tự do” của Hồ Chí Minh được nêu ra trong hoàn cảnh nào?","answer":"A","options":[{"key":"A","text":"Đế quốc Mỹ tăng cường mở rộng chiến tranh ở Việt Nam: ồ ạt đưa quân viễn chinh Mỹ, chư hầu vào miền Nam tiến hành chiến lược “Chiến tranh cục bộ” và gây chiến tranh phá hoại miền Bắc"},{"key":"B","text":"Trong buổi lễ kỷ niệm Quốc khánh lần thứ 10 năm 1955"},{"key":"C","text":"Sau khi ký kết Hiệp định Genève về Đông Dương năm 1954"},{"key":"D","text":"Trong quá trình chuẩn bị tổng tuyển cử thống nhất đất nước năm 1956"}]},{"n":12,"sec":"","stem":"Theo Hồ Chí Minh độc lập dân tộc phải gắn liền với?","answer":"C","options":[{"key":"A","text":"Sự phát triển khoa học – công nghệ và hội nhập quốc tế"},{"key":"B","text":"Quyền làm giàu chính đáng và bình đẳng giới trong xã hội"},{"key":"C","text":"Tự do, hạnh phúc của nhân dân"},{"key":"D","text":"Sự lãnh đạo tuyệt đối của Đảng và chính quyền các cấp"}]},{"n":13,"sec":"","stem":"Hồ Chí Minh đánh giá cao học thuyết nào của Tôn Trung Sơn liên quan đến độc lập và tự do?","answer":"B","options":[{"key":"A","text":"Học thuyết Cộng sản hóa toàn dân"},{"key":"B","text":"Học thuyết Tam dân: dân tộc độc lập, dân quyền tự do, dân sinh hạnh phúc"},{"key":"C","text":"Học thuyết Tam cương - Ngũ thường của Nho giáo"},{"key":"D","text":"Học thuyết Khai sáng toàn diện về dân quyền tư sản"}]},{"n":14,"sec":"","stem":"Trong Tuyên ngôn Độc lập năm 1945, Hồ Chí Minh đã viện dẫn bản Tuyên ngôn nào để khẳng định quyền tự do, bình đẳng của dân tộc Việt Nam?","answer":"C","options":[{"key":"A","text":"Tuyên ngôn Độc lập Hoa Kỳ năm 1776"},{"key":"B","text":"Tuyên ngôn về quyền con người của Liên Hợp Quốc năm 1948"},{"key":"C","text":"Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp năm 1791"},{"key":"D","text":"Tuyên ngôn Độc lập của Anh quốc năm 1689"}]},{"n":15,"sec":"","stem":"Hồ Chí Minh khẳng định dân tộc Việt Nam “đương nhiên cũng phải được tự do và bình đẳng về quyền lợi” vì lý do nào?","answer":"C","options":[{"key":"A","text":"Vì đây là nguyên tắc trong Hiến pháp của nhà nước pháp quyền"},{"key":"B","text":"Vì quyền con người là một đặc quyền do quốc tế công nhận"},{"key":"C","text":"Vì đó là lẽ phải không ai có thể chối cãi được"},{"key":"D","text":"Vì dân tộc Việt Nam có lịch sử văn hiến lâu đời"}]},{"n":16,"sec":"","stem":"Trong Chánh cương vắn tắt năm 1930, Hồ Chí Minh xác định mục tiêu nào gắn với tự do, hạnh phúc của nhân dân?","answer":"D","options":[{"key":"A","text":"Củng cố quyền lực chính trị và mở rộng ảnh hưởng của chính quyền"},{"key":"B","text":"Xây dựng nền dân chủ tư sản kiểu mới trên cơ sở pháp quyền"},{"key":"C","text":"Đẩy mạnh công nghiệp hóa để tăng trưởng kinh tế và cải thiện đời sống"},{"key":"D","text":"Làm cho nước Nam được hoàn toàn độc lập, dân chúng được tự do, thâu ruộng đất chia cho dân cày nghèo, bỏ sưu thuế, thi hành ngày làm 8 giờ"}]},{"n":17,"sec":"","stem":"Câu nói “Nước độc lập mà dân không hưởng hạnh phúc tự do, thì độc lập cũng chẳng có nghĩa lý gì” thể hiện quan điểm gì?","answer":"B","options":[{"key":"A","text":"Độc lập dân tộc chỉ là một mục tiêu tạm thời để phát triển kinh tế"},{"key":"B","text":"Độc lập dân tộc phải đi kèm với tự do và hạnh phúc của nhân dân"},{"key":"C","text":"Tự do, hạnh phúc là mục tiêu cuối cùng, độc lập chỉ là phương tiện"},{"key":"D","text":"Muốn giữ được độc lập thì phải hy sinh hạnh phúc cá nhân"}]},{"n":18,"sec":"","stem":"Sau cách mạng Tháng Tám năm 1945, Hồ Chí Minh đã đưa ra yêu cầu cấp thiết nào trong bối cảnh dân đói nghèo, mù chữ?","answer":"A","options":[{"key":"A","text":"Làm cho dân có ăn, có mặc, có chỗ ở và có học hành"},{"key":"B","text":"Phải phát triển công nghiệp nặng và hiện đại hóa quân đội"},{"key":"C","text":"Phải ban hành luật chống tham nhũng và củng cố bộ máy nhà nước"},{"key":"D","text":"Tập trung phát triển khu vực thành thị để làm đầu tàu phát triển"}]},{"n":19,"sec":"","stem":"Theo Hồ Chí Minh, tại sao độc lập dân tộc không thể tách rời khỏi tự do và hạnh phúc của nhân dân?","answer":"B","options":[{"key":"A","text":"Vì đó là điều kiện để thu hút sự ủng hộ quốc tế"},{"key":"B","text":"Vì độc lập mà dân không hạnh phúc, tự do thì độc lập vô nghĩa"},{"key":"C","text":"Vì chính quyền phải có nghĩa vụ với cộng đồng dân cư"},{"key":"D","text":"Vì đó là cách duy nhất để giữ gìn văn hóa truyền thống"}]},{"n":20,"sec":"","stem":"Điền từ còn thiếu vào (_____)? “Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn (_____), dân ta được hoàn toàn (_____), đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.4, tr.187)","answer":"A","options":[{"key":"A","text":"Độc lập - tự do"},{"key":"B","text":"Tự do - độc lập"},{"key":"C","text":"Dân chủ - hạnh phúc"},{"key":"D","text":"Hạnh phúc - tự do"}]},{"n":21,"sec":"","stem":"Theo Hồ Chí Minh, nền độc lập dân tộc chỉ có ý nghĩa khi nào?","answer":"B","options":[{"key":"A","text":"Khi đất nước có tốc độ tăng trưởng GDP cao trong khu vực"},{"key":"B","text":"Khi người dân có quyền tự quyết về ngoại giao, quân đội, tài chính"},{"key":"C","text":"Khi các chính phủ bù nhìn cũng có danh nghĩa “quốc gia độc lập”"},{"key":"D","text":"Khi được các nước phương Tây công nhận trên truyền thông quốc tế"}]},{"n":22,"sec":"","stem":"Hồ Chí Minh quan niệm thế nào về “độc lập giả hiệu” mà thực dân tuyên truyền?","answer":"C","options":[{"key":"A","text":"Là sự chuyển giao quyền lực tạm thời trước khi trao trả độc lập"},{"key":"B","text":"Là chiến lược mềm dẻo để ổn định thuộc địa thông qua cải cách"},{"key":"C","text":"Là cái vỏ bên ngoài để che đậy bản chất ăn cướp và giết người của chúng"},{"key":"D","text":"Là phương thức hợp pháp hóa sự hiện diện quân sự ở thuộc địa"}]},{"n":23,"sec":"","stem":"Theo Hồ Chí Minh, một quốc gia chưa có quân đội, ngoại giao và tài chính riêng thì:","answer":"C","options":[{"key":"A","text":"Là quốc gia đang trong giai đoạn chuyển giao quyền lực"},{"key":"B","text":"Là quốc gia tự trị với mức độ độc lập hạn chế"},{"key":"C","text":"Không thể gọi là một quốc gia thực sự độc lập"},{"key":"D","text":"Là quốc gia liên bang trong một hệ thống thuộc địa hiện đại"}]},{"n":24,"sec":"","stem":"Hồ Chí Minh nhấn mạnh nền độc lập phải như thế nào?","answer":"C","options":[{"key":"A","text":"Phù hợp với điều kiện từng giai đoạn lịch sử và sự công nhận quốc tế"},{"key":"B","text":"Phải mang tính hình thức để đảm bảo ngoại giao linh hoạt"},{"key":"C","text":"Phải thật sự, hoàn toàn và triệt để, không chỉ trên danh nghĩa"},{"key":"D","text":"Phải dựa trên cơ sở chuyển giao từ các cường quốc thực dân"}]},{"n":25,"sec":"","stem":"Theo Hồ Chí Minh, vì sao độc lập dân tộc phải gắn liền với thống nhất và toàn vẹn lãnh thổ?","answer":"D","options":[{"key":"A","text":"Vì chỉ có thống nhất mới giúp phát triển kinh tế thị trường định hướng xã hội chủ nghĩa"},{"key":"B","text":"Vì đó là điều kiện để Việt Nam gia nhập các tổ chức quốc tế"},{"key":"C","text":"Vì sự chia cắt lãnh thổ giúp chính quyền dễ quản lý theo vùng"},{"key":"D","text":"Vì đất nước bị chia cắt là tạo điều kiện cho kẻ thù thực hiện âm mưu thống trị lâu dài"}]},{"n":26,"sec":"","stem":"Câu nói “Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi” thể hiện điều gì?","answer":"A","options":[{"key":"A","text":"Quyết tâm sắt đá trong bảo vệ sự thống nhất quốc gia"},{"key":"B","text":"Tư tưởng nhân đạo với đồng bào ở vùng khó khăn, xa xôi"},{"key":"C","text":"Khẳng định nguyên tắc dân chủ trong toàn quốc"},{"key":"D","text":"Tuyên bố chính trị mang tính đối ngoại để ổn định tình hình"}]},{"n":27,"sec":"","stem":"Trong Di chúc, Hồ Chí Minh khẳng định điều gì về tương lai đất nước?","answer":"C","options":[{"key":"A","text":"Cuộc chiến tranh sẽ kéo dài nhiều năm nhưng thắng lợi sẽ thuộc về phe chính nghĩa"},{"key":"B","text":"Cuộc kháng chiến chống Mỹ là cần thiết để giữ vững nền độc lập đã có"},{"key":"C","text":"Tổ quốc ta nhất định sẽ thống nhất, đồng bào Nam Bắc nhất định sẽ sum họp một nhà"},{"key":"D","text":"Nhân dân miền Nam sẽ được xây dựng chế độ dân chủ xã hội chủ nghĩa trong hòa bình"}]},{"n":28,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, cách mạng giải p hóng dân tộc muốn thắng lợi thì phải đi theo con đường cách mạng nào?","answer":"C","options":[{"key":"A","text":"Dựa vào sự giúp đỡ của các nước lớn có nền dân chủ lâu đời"},{"key":"B","text":"Thực hiện cách mạng dân chủ tư sản kiểu mới"},{"key":"C","text":"Con đường cách mạng vô sản"},{"key":"D","text":"Đấu tranh bằng phương pháp hòa bình và cải lương"}]},{"n":29,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Điền từ còn thiếu vào (_____)? “Cách mệnh Pháp cũng như cách mệnh Mỹ, nghĩa là cách mệnh (_____), cách mệnh không đến nơi, tiếng là cộng hoà và dân chủ, kỳ thực trong thì nó tước lục (_____), ngoài thì nó áp bức (_____). Cách mệnh đã 4 lần rồi, mà nay công nông Pháp hẵng còn phải mưu cách mệnh lần nữa mới hòng thoát khỏi vòng áp bức”","answer":"B","options":[{"key":"A","text":"Tư sản - địa chủ - nhân dân"},{"key":"B","text":"Tư sản - công nông - thuộc địa"},{"key":"C","text":"Vô sản - trí thức - nông dân"},{"key":"D","text":"Dân quyền - giai cấp - công nhân"}]},{"n":30,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Yếu tố nào có ảnh hưởng sâu sắc đến Hồ Chí Minh trong việc lựa chọn con đường cứu nước, giải phóng dân tộc?","answer":"C","options":[{"key":"A","text":"Cuộc chiến tranh thế giới lần thứ nhất bùng nổ"},{"key":"B","text":"Sự suy yếu của các đế quốc thực dân"},{"key":"C","text":"Cách mạng Tháng Mười Nga năm 1917 thành công"},{"key":"D","text":"Chính sách khai thác thuộc địa lần thứ hai của Pháp"}]},{"n":31,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Năm 1920, sau khi đọc bản Sơ thảo lần thứ nhất những luận cương của Lênin về vấn đề dân tộc và vấn đề thuộc địa, Hồ Chí Minh đã?","answer":"D","options":[{"key":"A","text":"Quyết định theo con đường cải cách của Nhật Bản"},{"key":"B","text":"Tin tưởng vào con đường đấu tranh vũ trang như ở Trung Quốc"},{"key":"C","text":"Tán thành tư tưởng dân quyền trong cách mạng Mỹ"},{"key":"D","text":"Khẳng định phải theo con đường cách mạng vô sản"}]},{"n":32,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Điền từ còn thiếu vào (_____)? “Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “ Hỡi đồng bào bị đọa đày đau khổ! Đây là cái (_____) cho chúng ta, đây là con đường (_____) chúng ta”","answer":"D","options":[{"key":"A","text":"Cần thiết – cứu rỗi"},{"key":"B","text":"Đúng đắn – giải phóng"},{"key":"C","text":"Quý giá – hạnh phúc"},{"key":"D","text":"Cần thiết – giải phóng"}]},{"n":33,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, trật tự các bước giải phóng ở các nước thuộc địa như Việt Nam là?","answer":"D","options":[{"key":"A","text":"Giải phóng xã hội → giải phóng dân tộc → giải phóng con người"},{"key":"B","text":"Giải phóng giai cấp → giải phóng xã hội → giải phóng dân tộc"},{"key":"C","text":"Giải phóng con người → giải phóng dân tộc → giải phóng giai cấp"},{"key":"D","text":"Giải phóng dân tộc → giải phóng xã hội → giải phóng giai cấp → giải phóng con người"}]},{"n":34,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, điều kiện đầu tiên và tiên quyết để cách mạng thành công là phải có?","answer":"D","options":[{"key":"A","text":"Sự hỗ trợ của quốc tế"},{"key":"B","text":"Giai cấp công nhân đông đảo"},{"key":"C","text":"Lực lượng vũ trang mạnh"},{"key":"D","text":"Một đảng cách mệnh vững vàng"}]},{"n":35,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong tác phẩm Đường cách mệnh (1927), Hồ Chí Minh nhấn mạnh: “Trước hết phải có cái gì?”","answer":"A","options":[{"key":"A","text":"Phải có đảng cách mệnh"},{"key":"B","text":"Phải có lực lượng vũ trang nhân dân"},{"key":"C","text":"Phải có căn cứ địa cách mạng"},{"key":"D","text":"Phải có phong trào công – nông rộng khắp"}]},{"n":36,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, một đảng cách mạng muố n làm tròn sứ mệnh lịch sử phải?","answer":"B","options":[{"key":"A","text":"Dựa vào tầng lớp trí thức để xây dựng đường lối cách mạng"},{"key":"B","text":"Tập hợp đông đảo quần chúng, giác ngộ, tổ chức và đưa họ ra đấu tranh"},{"key":"C","text":"Có liên minh với các đảng phái dân chủ trong và ngoài nước"},{"key":"D","text":"Kết hợp đấu tranh vũ trang với hoạt động nghị trường"}]},{"n":37,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh khẳng định Đảng Cộng sản Việt Nam là đảng của?","answer":"C","options":[{"key":"A","text":"Chỉ giai cấp công nhân"},{"key":"B","text":"Chủ yếu của nông dân và công nhân"},{"key":"C","text":"Cả giai cấp công nhân, nhân dân lao động và dân tộc Việt Nam"},{"key":"D","text":"Tầng lớp tiên tiến, trí thức xã hội chủ nghĩa"}]},{"n":38,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong Báo cáo chính trị tại Đại hội II của Đảng (1951), Hồ Chí Minh nhấn mạnh vai trò của Đảng Lao động Việt Nam là?","answer":"C","options":[{"key":"A","text":"Lãnh đạo lực lượng vũ trang nhân dân đấu tranh giành chính quyền"},{"key":"B","text":"Đảng đại diện cho trí thức và tư sản dân tộc"},{"key":"C","text":"Đảng của giai cấp công nhân và nhân dân lao động, đồng thời là Đảng của dân tộc Việt Nam"},{"key":"D","text":"Đảng của công – nông liên minh dưới sự lãnh đạo của quốc tế cộng sản"}]},{"n":39,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Các nhà lý luận kinh điển của chủ nghĩa Mác - Lênin khẳng định rằng: cách mạng là sự nghiệp của ai?","answer":"D","options":[{"key":"A","text":"Những người có lý tưởng và nhận thức cách mạng tiên tiến"},{"key":"B","text":"Đảng Cộng sản và các tổ chức chính trị xã hội"},{"key":"C","text":"Giai cấp công nhân với vai trò lãnh đạo tiên phong"},{"key":"D","text":"Quần chúng nhân dân – chủ thể sáng tạo ra lịch sử"}]},{"n":40,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, cách mạng là sự nghiệp của ai?","answer":"C","options":[{"key":"A","text":"Của những nhà lãnh đạo tài ba và trí thức ưu tú"},{"key":"B","text":"Của Đảng và các tổ chức chính trị – xã hội"},{"key":"C","text":"Của toàn dân tộc"},{"key":"D","text":"Của giai cấp công nhân và bộ phận trí thức tiên tiến"}]},{"n":41,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Phát biểu nào sau đây là của Hồ Chí Minh thể hiện rõ quan điểm về vai trò của nhân dân trong cách mạng?","answer":"C","options":[{"key":"A","text":"Không gì quý hơn độc lập, tự do"},{"key":"B","text":"Đoàn kết, đoàn kết, đại đoàn kết"},{"key":"C","text":"Được lòng dân thì được tất cả, mất lòng dân thì mất tất cả"},{"key":"D","text":"Chúng ta thà hy sinh tất cả chứ nhất định không chịu mất nước"}]},{"n":42,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong tác phẩm Đường cách mệnh, Hồ Chí Minh cho rằng giai cấp nào là “gốc cách mệnh”?","answer":"B","options":[{"key":"A","text":"Trí thức và tư sản dân tộc"},{"key":"B","text":"Nông dân và công nhân"},{"key":"C","text":"Tiểu tư sản và trung nông"},{"key":"D","text":"Công chức và học sinh yêu nước"}]},{"n":43,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Lý do Hồ Chí Minh coi công - nông là lực lượng cách mạng chủ yếu là vì?","answer":"D","options":[{"key":"A","text":"Họ có học thức và tinh thần yêu nước cao"},{"key":"B","text":"Họ chiếm số lượng ít nhưng tinh thần đấu tranh mạnh"},{"key":"C","text":"Họ là lực lượng vũ trang chính trong các cuộc khởi nghĩa"},{"key":"D","text":"Họ bị áp bức nặng nề nên có ý chí đấu tranh kiên cường và bền bỉ"}]},{"n":44,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Điền từ còn thiếu vào (_____)? Trong Lời kêu gọi toàn quốc kháng chiến (12-1946), Người viết: “Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh (_____) để cứu (_____)”?","answer":"C","options":[{"key":"A","text":"Nhật – đồng bào"},{"key":"B","text":"Mĩ – hòa bình"},{"key":"C","text":"Thực dân Pháp – Tổ quốc"},{"key":"D","text":"Phát xít – đất nước"}]},{"n":45,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh cho rằng cách mạng thuộc địa có thể giành thắng lợi trước cách mạng vô sản ở chính quốc vì?","answer":"C","options":[{"key":"A","text":"Thuộc địa có điều kiện kinh tế xã hội phát triển tương đồng với chính quốc"},{"key":"B","text":"Thuộc địa nhận được sự hỗ trợ tuyệt đối từ cách mạng vô sản chính quốc"},{"key":"C","text":"Thuộc địa có vị trí , vai trò, tầm quan trọng đặc biệt đối với chủ nghĩa đế quốc, là nơi duy trì sự tồn tại, phát triển, là món mồi “béo bở” cho chủ nghĩa đế quốc"},{"key":"D","text":"Thuộc địa là nơi có nhiều đảng phái, tần g lớp trung lưu ủng hộ cách mạn"}]},{"n":46,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, chủ nghĩa tư bản giống như con gì để minh họa cho mối quan hệ giữa chính quốc và thuộc địa?","answer":"D","options":[{"key":"A","text":"Một con bạch tuộc với nhiều vòi bóp nghẹt các dân tộc yếu"},{"key":"B","text":"Một con rắn độc sống nhờ nọc tại các nước giàu"},{"key":"C","text":"Một con thú hoang bị thương nhưng chưa chết"},{"key":"D","text":"Một con đỉa hút máu cả ở chính quốc và thuộc địa"}]},{"n":47,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong tác phẩm Bản án chế độ thực dân Pháp, Hồ Chí Minh ví chủ nghĩa tư bản như một con đỉa, có bao nhiêu vòi và hút máu ở đâu?","answer":"B","options":[{"key":"A","text":"Một vòi - hút máu giai cấp tư sản"},{"key":"B","text":"Hai vòi - hút máu giai cấp vô sản ở chính quốc và thuộc địa"},{"key":"C","text":"Ba vòi - hút máu địa chủ, công nhân và nông dân"},{"key":"D","text":"Một vòi - hút máu nông dân nghèo ở thuộc địa"}]},{"n":48,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh từng phát biểu tại Đại hội V Quốc tế Cộng sản (1924) về “nọc độc và sức sống của con rắn độc tư bản chủ nghĩa” đang tập trung ở đâu?","answer":"D","options":[{"key":"A","text":"Ở các nước công nghiệp phát triển"},{"key":"B","text":"Ở các trung tâm tài chính và công nghiệp lớn"},{"key":"C","text":"Ở các thuộc địa châu Á, châu Phi"},{"key":"D","text":"Ở các thuộc địa hơn là chính quốc"}]},{"n":49,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, muốn tiêu diệt hoàn toàn chủ nghĩa tư bản thì phải?","answer":"C","options":[{"key":"A","text":"Đẩy mạnh sản xuất trong chính quốc để làm suy yếu kinh tế tư bản"},{"key":"B","text":"Cắt đứt một trong hai nguồn tài chính của nó từ thuộc địa"},{"key":"C","text":"Đồng thời tiêu diệt cả hai “vòi” hút máu ở chính quốc và thuộc địa"},{"key":"D","text":"Xây dựng mô hình hợp tác xã kiểu mới thay thế mô hình bóc lột"}]},{"n":50,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Câu nói nào của Hồ Chí Minh khẳng định khả năng chủ động giải phóng của các dân tộc thuộc địa?","answer":"B","options":[{"key":"A","text":"“Độc lập dân tộc không thể tách rời khỏi giải phóng giai cấp”"},{"key":"B","text":"“Công cuộc giải phóng anh em chỉ có thể thực hiện được bằng sự nỗ lực của bản thân anh em”"},{"key":"C","text":"“Không có cách mạng nào là dễ dàng, nhưng nhân dân sẽ vượt qua tất cả”"},{"key":"D","text":"“Sự đoàn kết giữa vô sản và nông dân là yếu tố quyết định thắng lợi cách mạng”"}]},{"n":51,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Luận điểm cho rằng “cách mạng thuộc địa có thể giành thắng lợi trước cách mạng vô sản ở chính quốc” là một đóng góp:","answer":"D","options":[{"key":"A","text":"Thể hiện sự tách biệt giữa cách mạng ở chính quốc và thuộc địa"},{"key":"B","text":"Sao chép lý luận cũ của Quốc tế Cộng sản"},{"key":"C","text":"Phản bác hoàn toàn tư tưởng Mác – Lênin về cách mạng"},{"key":"D","text":"Sáng tạo, phát triển lý luận cách mạng vô sản phù hợp với thực tiễn thuộc địa"}]},{"n":52,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo C.Mác, bạo lực là gì trong quá trình chuyển từ xã hội cũ sang xã hội mới?","answer":"D","options":[{"key":"A","text":"Công cụ của giai cấp vô sản trong việc giáo dục nhân dân"},{"key":"B","text":"Hệ quả tất yếu của tiến bộ xã hội"},{"key":"C","text":"Một hình thức bóc lột nhằm thiết lập chế độ mới"},{"key":"D","text":"Bà đỡ của một chế độ xã hội cũ đang thai nghén một chế độ mới"}]},{"n":53,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh cho rằng, trong cuộc đấu tranh chống kẻ thù dân tộc, phải:","answer":"B","options":[{"key":"A","text":"Tìm cách thuyết phục kẻ thù quay đầu là bờ"},{"key":"B","text":"Dùng bạo lực cách mạng chống lại bạo lực phản cách mạng"},{"key":"C","text":"Ưu tiên con đường hòa bình trước mọi tình huống"},{"key":"D","text":"Nhờ các nước lớn phân xử công bằng"}]},{"n":54,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Theo Hồ Chí Minh, phương pháp bạo lực cách mạng gồm mấy lực lượng chính và hình thức đấu tranh nào?","answer":"B","options":[{"key":"A","text":"Một lực lượng chính trị, một hình thức tuyên truyền"},{"key":"B","text":"Hai lực lượng chính trị và quân sự, hai hình thức đấu tranh: đấu tranh chính trị và đấu tranh vũ trang"},{"key":"C","text":"Một lực lượng vũ trang, một hình thức đấu tranh văn hóa"},{"key":"D","text":"Lực lượng quốc tế và hình thức đấu tranh kinh tế"}]},{"n":55,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh quan niệm thế nào về chế độ thực dân?","answer":"C","options":[{"key":"A","text":"Là sản phẩm lỗi thời của thời đại, không cần đối đầu"},{"key":"B","text":"Là hệ thống chính trị hợp pháp ở các nước chậm tiến"},{"key":"C","text":"Là một hành động bạo lực của kẻ mạnh đối với kẻ yếu"},{"key":"D","text":"Là mô hình quản trị phù hợp giai đoạn phát triển thuộc địa"}]},{"n":56,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong cách mạng Việt Nam, đấu tranh vũ trang có vai trò gì theo tư tưởng Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Là phương tiện tuyên truyền hiệu quả trong kháng chiến"},{"key":"B","text":"Có ý nghĩa quyết định trong việc tiêu diệt lực lượng quân sự của địch"},{"key":"C","text":"Là công cụ phụ trợ cho hoạt động chính trị"},{"key":"D","text":"Là hình thức tự phát không cần tổ chức rõ ràng"}]},{"n":57,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Hồ Chí Minh nhấn mạnh cần xác định hình thức đấu tranh cách mạng như thế nào?","answer":"C","options":[{"key":"A","text":"Áp dụng duy nhất hình thức vũ trang để giành thắng lợi"},{"key":"B","text":"Ưu tiên đấu tranh kinh tế, văn hóa trong thời bình"},{"key":"C","text":"Tùy tình hình cụ thể để áp dụng hình thức đấu tranh phù hợp"},{"key":"D","text":"Kết hợp nhiều phong trào nhưng lấy hòa bình làm nền tảng"}]},{"n":58,"sec":"2. Về cách mạng giải phóng dân tộc","stem":"Trong Cách mạng Tháng Tám 1945, phương pháp bạo lực cách mạng được thể hiện qua:","answer":"D","options":[{"key":"A","text":"Khởi nghĩa công nông nổ ra lẻ tẻ ở từng địa phương"},{"key":"B","text":"Biểu tình ôn hòa kết hợp đàm phán với thực dân"},{"key":"C","text":"Tấn công vũ trang đơn độc của lực lượng quân sự cách mạng"},{"key":"D","text":"Tổng khởi nghĩa của quần chúng nhân dân trong cả nước, chủ yếu dựa vào lực lượng chính trị, kết hợp với lực lượng vũ trang"}]},{"n":59,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Hồ Chí Minh tiếp cận khái niệm chủ nghĩa xã hội bằng cách:","answer":"C","options":[{"key":"A","text":"Đưa ra định nghĩa học thuật, mang tính lý luận sâu sắc"},{"key":"B","text":"Trình bày theo lập luận duy tâm, mang tính cảm tính"},{"key":"C","text":"Tiếp cận ở nhiều góc độ khác nhau với cách diễn đạt dung dị, dễ hiểu"},{"key":"D","text":"Dựa trên mô hình của Liên Xô và áp dụng nguyên xi vào Việt Nam"}]},{"n":60,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, mục tiêu cơ bản của chủ nghĩa xã hội là?","answer":"B","options":[{"key":"A","text":"Xây dựng quân đội hùng mạnh và phát triển công nghiệp nặng"},{"key":"B","text":"Làm cho dân giàu, nước mạnh, mọi người được ấm no, hạnh phúc"},{"key":"C","text":"Tập trung hóa toàn bộ tư liệu sản xuất và phân phối theo chế độ tem phiếu"},{"key":"D","text":"Thay thế hoàn toàn kinh tế tư nhân bằng kinh tế nhà nước"}]},{"n":61,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? “Nói một cách tóm tắt, mộc mạc, chủ nghĩa xã hội trước hết nhằm làm cho nhân dân lao động thoát nạn (_____), làm cho mọi người có công ăn việc làm, được ấm no và sống một đời hạnh phúc”.","answer":"A","options":[{"key":"A","text":"Bần cùng"},{"key":"B","text":"Nghèo khổ"},{"key":"C","text":"Nghèo đói"},{"key":"D","text":"Lầm than"}]},{"n":62,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Trong xã hội chủ nghĩa, theo Hồ Chí Min h, lợi ích cá nhân được hiểu là?","answer":"C","options":[{"key":"A","text":"Tách biệt hoàn toàn với lợi ích tập thể"},{"key":"B","text":"Bị hy sinh hoàn toàn cho lợi ích của nhà nước"},{"key":"C","text":"Nằm trong lợi ích tập thể và là một bộ phận của lợi ích tập thể"},{"key":"D","text":"Là động lực chính để phát triển chủ nghĩa xã hội"}]},{"n":63,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, chủ nghĩa xã hội khác với các chế độ xã hội có giai cấp bóc lột ở điểm nào?","answer":"C","options":[{"key":"A","text":"Không có chính quyền tập trung"},{"key":"B","text":"Có thể tồn tại song song với chế độ cũ"},{"key":"C","text":"Là chế độ do nhân dân lao động làm chủ, không còn áp bức, bóc lột"},{"key":"D","text":"Chỉ tồn tại trong lý thuyết"}]},{"n":64,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, chủ nghĩa xã hội là?","answer":"B","options":[{"key":"A","text":"Giai đoạn cao nhất của chủ nghĩa cộng sản"},{"key":"B","text":"Giai đoạn đầu của chủ nghĩa cộng sản"},{"key":"C","text":"Một hình thức chính phủ dân chủ tư sản"},{"key":"D","text":"Giai đoạn chuyển tiếp giữa phong kiến và tư bản"}]},{"n":65,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, trong chế độ xã hội chủ nghĩa, “mỗi người là một bộ phận của (_____), giữ một vị trí nhất định và đóng góp một phần công lao trong xã hội”.","answer":"A","options":[{"key":"A","text":"Tập thể"},{"key":"B","text":"Xã hội"},{"key":"C","text":"Nhà nước"},{"key":"D","text":"Giai cấp"}]},{"n":66,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh viết: “Chủ nghĩa cộng sản có hai giai đoạn. Giai đoạn thấp, tức là (_____), giai đoạn cao, tức là (_____)”.","answer":"C","options":[{"key":"A","text":"Tư bản chủ nghĩa – cộng sản nguyên thủy"},{"key":"B","text":"Giai cấp – xã hội chủ nghĩa"},{"key":"C","text":"Chủ nghĩa xã hội – chủ nghĩa cộng sản"},{"key":"D","text":"Giai cấp – xã hội chủ nghĩa"}]},{"n":67,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo tư tưởng Hồ Chí Minh, quá trình phát triển của xã hội loài người là?","answer":"D","options":[{"key":"A","text":"Do ngẫu nhiên và ý chí cá nhân quyết định"},{"key":"B","text":"Một chuỗi những biến động không có quy luật"},{"key":"C","text":"Do các tôn giáo và triết học điều khiển"},{"key":"D","text":"Một quá trình lịch sử - tự nhiên, tuân theo quy luật khách quan"}]},{"n":68,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, những quốc gia như Việt Nam, Trung Quốc, Đông Âu có thể tiến lên chủ nghĩa xã hội bằng cách?","answer":"D","options":[{"key":"A","text":"Phát triển đầy đủ chủ nghĩa tư bản trước"},{"key":"B","text":"Kết hợp giữa phong kiến và tư bản"},{"key":"C","text":"Trực tiếp đi lên chủ nghĩa cộng sản không qua trung gian"},{"key":"D","text":"Bỏ qua giai đoạn phát triển tư bản chủ nghĩa"}]},{"n":69,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, “chế độ dân chủ mới” là?","answer":"A","options":[{"key":"A","text":"Chế độ dưới sự lãnh đạo của Đảng và giai cấp công nhân, nhân dân đã đánh đổ đế quốc và phong kiến; trên nền tảng công nông liên minh, nhân dân lao động làm chủ…"},{"key":"B","text":"Một giai đoạn trung gian giữa chủ nghĩa phong kiến và chủ nghĩa tư bản"},{"key":"C","text":"Một hình thức mới của chế độ phong kiến"},{"key":"D","text":"Một dạng tư bản chủ nghĩa thân Đảng"}]},{"n":70,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Hồ Chí Minh nhận định, lịch sử loài người phát triển qua các hình thái kinh tế - xã hội nào sau đây?","answer":"B","options":[{"key":"A","text":"Nô lệ - Phong kiến - Tư bản chủ nghĩa - Hậu hiện đại"},{"key":"B","text":"Công xã nguyên thủy - Chiếm hữu nô lệ - Phong kiến - Tư bản chủ nghĩa - Xã hội chủ nghĩa, Cộng sản chủ nghĩa"},{"key":"C","text":"Cộng sản chủ nghĩa – Phong kiến – Tư bản chủ nghĩa"},{"key":"D","text":"Ngẫu nhiên, không theo trật tự"}]},{"n":71,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Với Việt Nam, theo Hồ Chí Minh, chủ nghĩa xã hội là?","answer":"C","options":[{"key":"A","text":"Một học thuyết khó áp dụng"},{"key":"B","text":"Một sự lựa chọn tình thế"},{"key":"C","text":"Nguồn gốc của sự tự do, bình đẳng, bác ái, xóa bỏ những bức tường dài ngăn cản con người đoàn kết, yêu thương nhau"},{"key":"D","text":"Một giai đoạn tạm thời trước khi trở lại chế độ phong kiến"}]},{"n":72,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh viết: “Chế độ xã hội cũng phát triển từ cộng sản nguyên thủy đến chế độ nô lệ, đến chế độ phong kiến, đến chế độ tư bản chủ nghĩa và ngày nay gần một nửa loài người đang tiến lên chế độ (_____) và chế độ (_____)”.","answer":"B","options":[{"key":"A","text":"Dân chủ - xã hội chủ nghĩa"},{"key":"B","text":"Xã hội chủ nghĩa - cộng sản chủ nghĩa"},{"key":"C","text":"Tư bản chủ nghĩa - xã hội chủ nghĩa"},{"key":"D","text":"Cộng sản nguyên thủy - nô lệ"}]},{"n":73,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh cho rằng, tiến lên chủ nghĩa xã hội là một quá trình (_____), tuân theo những quy luật (_____), trước hết là những quy luật trong sản xuất vật chất.","answer":"B","options":[{"key":"A","text":"Tự phát – chủ quan"},{"key":"B","text":"Tất yếu – khách quan"},{"key":"C","text":"Ngắn hạn – duy ý chí"},{"key":"D","text":"Tạm thời – kinh tế"}]},{"n":74,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, chế độ dân chủ mới là chế độ dưới sự lãnh đạo của (_____) và (_____), nhân dân đã đánh đổ đế quốc và phong kiến.","answer":"C","options":[{"key":"A","text":"Giai cấp nông dân - Quốc hội"},{"key":"B","text":"Nhân dân - Chính phủ"},{"key":"C","text":"Đảng - giai cấp công nhân"},{"key":"D","text":"Mặt trận Tổ quốc - Nhà nước"}]},{"n":75,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, đặc trưng chính trị nổi bật của xã hội xã hội chủ nghĩa là?","answer":"D","options":[{"key":"A","text":"Nhà nước do giới trí thức điều hành"},{"key":"B","text":"Đảng quyết định toàn bộ quyền lực nhân dân"},{"key":"C","text":"Xã hội không cần đến nhà nước"},{"key":"D","text":"Xã hội do nhân dân làm chủ, nhân dân là chủ, dưới sự lãnh đạo của Đảng cộng sản trên nền tảng liên minh công - nông"}]},{"n":76,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, trong xã hội xã hội chủ nghĩa, địa vị cao nhất thuộc về?","answer":"D","options":[{"key":"A","text":"Đảng Cộng sản"},{"key":"B","text":"Quốc hội"},{"key":"C","text":"Nhà nước"},{"key":"D","text":"Nhân dân"}]},{"n":77,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Một đặc trưng kinh tế cơ bản của xã hội xã hội chủ nghĩa là?","answer":"B","options":[{"key":"A","text":"Nền kinh tế thị trường tự do hoàn toàn"},{"key":"B","text":"Nền kinh tế dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về tư liệu sản xuất chủ yếu"},{"key":"C","text":"Kinh tế phân phối lại do tư nhân làm chủ"},{"key":"D","text":"Tập trung sở hữu tư liệu sản xuất vào tay một nhóm người"}]},{"n":78,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Quan hệ sản xuất trong xã hội xã hội chủ nghĩa được Hồ Chí Minh diễn đạt là?","answer":"A","options":[{"key":"A","text":"Lấy nhà máy, xe lửa, ngân hàng, v.v. làm của chung; là tư liệu sản xuất thuộc về nhân dân"},{"key":"B","text":"Người cày có ruộng, người lao động làm chủ tư liệu sản xuất"},{"key":"C","text":"Mọi người đều bình đẳng, không còn áp bức, bóc lột"},{"key":"D","text":"Cả A, B, C"}]},{"n":79,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, về văn hóa và đạo đức, xã hội xã hội chủ nghĩa là xã hội?","answer":"C","options":[{"key":"A","text":"Tự do tuyệt đối không có kỷ luật"},{"key":"B","text":"Không cần pháp luật vì mọi người đều tốt"},{"key":"C","text":"Không còn hiện tượng người bóc lột người; con người được tôn trọng, được bảo đảm đối xử công bằng, bình đẳng và các dân tộc đoàn kết, gắn bó với nhau"},{"key":"D","text":"Ai cũng bình đẳng vì đều là đảng viên"}]},{"n":80,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Về quan hệ xã hội, xã hội xã hội chủ nghĩa theo tư tưởng Hồ Chí Minh thể hiện?","answer":"C","options":[{"key":"A","text":"Phân biệt giai cấp theo năng suất lao động"},{"key":"B","text":"Ai làm việc mới được hưởng quyền sống"},{"key":"C","text":"Bình đẳng, công bằng trong quyền lợi và nghĩa vụ"},{"key":"D","text":"Ưu tiên cán bộ, trí thức hơn người lao động phổ thông"}]},{"n":81,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Chủ nghĩa xã hội là công trình tập thể của nhân dân dưới sự lãnh đạo của?","answer":"C","options":[{"key":"A","text":"Giai cấp tư sản dân tộc"},{"key":"B","text":"Quốc hội do dân bầu"},{"key":"C","text":"Đảng Cộng sản"},{"key":"D","text":"Các nhà kinh tế"}]},{"n":82,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, ai là chủ thể quyết định sự thành công của công cuộc xây dựng chủ nghĩa xã hội?","answer":"B","options":[{"key":"A","text":"Giai cấp tư sản dân tộc"},{"key":"B","text":"Nhân dân lao động"},{"key":"C","text":"Bộ máy chính quyền"},{"key":"D","text":"Lực lượng vũ trang"}]},{"n":83,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, trong xã hội xã hội chủ nghĩa, nhà nước là của (_____), do (_____) và vì (_____).","answer":"A","options":[{"key":"A","text":"Nhân dân - nhân dân - nhân dân"},{"key":"B","text":"Nhà nước – nhân dân – Tổ quốc"},{"key":"C","text":"Đảng – nhân dân – giai cấp công nhân"},{"key":"D","text":"Giai cấp công nhân – Đảng Cộng sản – Chủ nghĩa xã hội"}]},{"n":84,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Xã hội xã hội chủ nghĩa bảo đảm quyền (_____) trước pháp luật cho mọi công dân.","answer":"B","options":[{"key":"A","text":"Tự do"},{"key":"B","text":"Bình đẳng"},{"key":"C","text":"Công bằng"},{"key":"D","text":"Lao động"}]},{"n":85,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Trong xã hội xã hội chủ nghĩa, “làm nhiều thì hưởng (), làm ít thì hưởng (), không làm thì (_____)”.","answer":"A","options":[{"key":"A","text":"Nhiều - ít - không hưởng"},{"key":"B","text":"Lương - thưởng - mất việc"},{"key":"C","text":"Công - phúc - bị phạt"},{"key":"D","text":"Ít - nhiều - vẫn có phần"}]},{"n":86,"sec":"1. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh khẳng định: “Chỉ có sự lãnh đạo của một đảng biết vận dụng một cách sáng tạo (_____) vào điều kiện cụ thể của nước mình thì mới có thể đưa cách mạng đến thành công”.","answer":"B","options":[{"key":"A","text":"Chủ nghĩa tư bản"},{"key":"B","text":"Chủ nghĩa Mác - Lênin"},{"key":"C","text":"Chủ nghĩa dân tộc"},{"key":"D","text":"Chủ nghĩa xã hội"}]},{"n":87,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, chế độ chính trị trong chủ nghĩa xã hội ở Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Chế độ chuyên chính vô sản với quyền lực tập trung vào Đảng"},{"key":"B","text":"Chế độ pháp quyền xã hội chủ nghĩa lấy pháp luật làm công cụ tối cao"},{"key":"C","text":"Chế độ dân chủ, trong đó nhân dân là người làm chủ"},{"key":"D","text":"Chế độ cộng hòa xã hội chủ nghĩa với Nhà nước kiểm soát toàn diện"}]},{"n":88,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Hồ Chí Minh khẳng định vị trí của nhân dân trong chế độ dân chủ như thế nào?","answer":"D","options":[{"key":"A","text":"Nhân dân là đối tượng phục vụ chính của bộ máy Nhà nước và các tổ chức xã hội"},{"key":"B","text":"Nhân dân là lực lượng lao động chính trong công cuộc phát triển kinh tế"},{"key":"C","text":"Nhân dân là thành phần hỗ trợ cho sự lãnh đạo của Nhà nước và các cơ quan đoàn thể"},{"key":"D","text":"Nhân dân là chủ, có quyền hạn và trách nhiệm trong sự nghiệp xây dựng đất nước"}]},{"n":89,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, tất cả quyền hạn và lực lượng trong chế độ ta đều thuộc về ai?","answer":"D","options":[{"key":"A","text":"Đảng Cộng sản Việt Nam và các tổ chức chính trị xã hội"},{"key":"B","text":"Nhà nước và các cơ quan lập pháp, hành pháp"},{"key":"C","text":"Các lực lượng cách mạng nòng cốt của giai cấp công nhân"},{"key":"D","text":"Nhân dân, vì nhân dân là chủ và làm chủ đất nước"}]},{"n":90,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Hồ Chí Minh nhấn mạnh điều gì trong mối quan hệ giữa chính trị và kinh tế trong chủ nghĩa xã hội?","answer":"C","options":[{"key":"A","text":"Chính trị quyết định kinh tế, nên cần tập trung toàn lực vào chính trị"},{"key":"B","text":"Kinh tế và chính trị là hai lĩnh vực độc lập nhưng cùng phục vụ mục tiêu xã hội chủ nghĩa"},{"key":"C","text":"Mục tiêu kinh tế phải gắn bó chặt chẽ với mục tiêu chính trị trong quá trình xây dựng chủ nghĩa xã hội"},{"key":"D","text":"Kinh tế là công cụ để phục vụ chính trị, nên cần phát triển kinh tế thị trường định hướng xã hội chủ nghĩa"}]},{"n":91,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, nền kinh tế trong chủ nghĩa xã hội ở Việt Nam phải như thế nào?","answer":"D","options":[{"key":"A","text":"Dựa trên kinh tế thị trường có sự điều tiết mạnh mẽ của Nhà nước"},{"key":"B","text":"Kết hợp giữa sở hữu tư nhân và sở hữu nhà nước trên nền tảng pháp lý vững chắc"},{"key":"C","text":"Chấp nhận đa dạng sở hữu, miễn là đảm bảo an sinh và phát triển bền vững"},{"key":"D","text":"Là nền kinh tế thuần nhất, dựa trên sở hữu toàn dân và sở hữu tập thể"}]},{"n":92,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, chế độ dân chủ trong chủ nghĩa xã hội ở Việt Nam được hiểu là gì?","answer":"C","options":[{"key":"A","text":"Là chế độ chính trị do Nhà nước kiểm soát toàn bộ đời sống xã hội"},{"key":"B","text":"Là chế độ tập trung quyền lực vào bộ máy hành chính trung ương"},{"key":"C","text":"Là chế độ mà nhân dân làm chủ, dân là chủ và dân làm chủ"},{"key":"D","text":"Là chế độ có sự giám sát của Đảng đối với mọi tổ chức đoàn thể"}]},{"n":93,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, địa vị cao nhất trong chế độ dân chủ là?","answer":"D","options":[{"key":"A","text":"Đảng Cộng sản Việt Nam"},{"key":"B","text":"Bộ máy nhà nước trung ương"},{"key":"C","text":"Lực lượng công nhân và nông dân"},{"key":"D","text":"Nhân dân, vì dân là chủ"}]},{"n":94,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, công cuộc đổi mới đất nước là trách nhiệm của ai?","answer":"D","options":[{"key":"A","text":"Nhà nước và các tổ chức chính trị"},{"key":"B","text":"Đảng và bộ máy hành chính"},{"key":"C","text":"Cả hệ thống chính trị trung ương"},{"key":"D","text":"Nhân dân – vì dân là người chủ và người làm chủ"}]},{"n":95,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, tổ chức đoàn thể trong xã hội xã hội chủ nghĩa được hình thành bởi ai?","answer":"A","options":[{"key":"A","text":"Nhân dân – do dân tổ chức nên"},{"key":"B","text":"Nhà nước chỉ đạo tổ chức thực hiện"},{"key":"C","text":"Chính phủ ban hành và giám sát"},{"key":"D","text":"Đảng Cộng sản thiết lập và điều hành"}]},{"n":96,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Khái quát về mục tiêu kinh tế trong chủ nghĩa xã hội theo Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phát triển công nghiệp nhẹ và nông nghiệp theo hướng truyền thống"},{"key":"B","text":"Ưu tiên xây dựng kinh tế nhiều thành phần linh hoạt"},{"key":"C","text":"Nền kinh tế phát triển cao với công nghiệp, nông nghiệp hiện đại, KHKT tiên tiến"},{"key":"D","text":"Tập trung vào xuất khẩu để hội nhập kinh tế quốc tế"}]},{"n":97,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, cơ sở sở hữu của nền kinh tế xã hội chủ nghĩa gồm những hình thức nào?","answer":"D","options":[{"key":"A","text":"Sở hữu cá nhân và sở hữu hỗn hợp"},{"key":"B","text":"Sở hữu toàn dân và sở hữu tư nhân đặc biệt"},{"key":"C","text":"Sở hữu của Nhà nước và sở hữu của doanh nghiệp nước ngoài"},{"key":"D","text":"Sở hữu toàn dân và sở hữu tập thể"}]},{"n":98,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Tư tưởng Hồ Chí Minh nhấn mạnh vai trò của thành phần kinh tế nào trong nền kinh tế quốc dân?","answer":"A","options":[{"key":"A","text":"Kinh tế quốc doanh và hợp tác xã"},{"key":"B","text":"Kinh tế tư nhân và doanh nghiệp nước ngoài"},{"key":"C","text":"Kinh tế hợp tác xã và kinh tế tập thể nhỏ"},{"key":"D","text":"Kinh tế nhà nước và kinh tế đầu tư nước ngoài"}]},{"n":99,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, mục tiêu về chính trị trong xây dựng chủ nghĩa xã hội là gì?","answer":"B","options":[{"key":"A","text":"Tập trung hóa quyền lực vào trung ương để điều hành hiệu quả"},{"key":"B","text":"Xây dựng chế độ dân chủ, nơi nhân dân làm chủ thực sự"},{"key":"C","text":"Thiết lập hệ thống tổ chức kiểm soát toàn diện các lĩnh vực"},{"key":"D","text":"Tạo ra bộ máy hành chính hiệu quả phục vụ cho sự lãnh đạo của Đảng"}]},{"n":100,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, mục tiêu của nền văn hóa Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Xây dựng một nền văn hóa hiện đại, tự do và hội nhập với thế giới"},{"key":"B","text":"Xây dựng nền văn hóa mang tính dân tộc, hiện đại và phổ cập cho mọi tầng lớp"},{"key":"C","text":"Xây dựng nền văn hóa mang tính dân tộc, khoa học, đại chúng và tiếp thu tinh hoa văn hóa nhân loại"},{"key":"D","text":"Xây dựng nền văn hóa mang tính khu vực, khoa học, và phục vụ công cuộc đổi mới đất nước"}]},{"n":101,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Hồ Chí Minh đánh giá mối quan hệ giữa văn hóa với chính trị và kinh tế như thế nào?","answer":"D","options":[{"key":"A","text":"Chính trị và kinh tế giữ vai trò phụ trợ cho sự phát triển văn hóa lâu dài"},{"key":"B","text":"Văn hóa và chính trị là cốt lõi, còn kinh tế là công cụ thực hiện các mục tiêu đó"},{"key":"C","text":"Chính trị và văn hóa là nền tảng, kinh tế đóng vai trò hỗ trợ sự phát triển của hai lĩnh vực này"},{"key":"D","text":"Đó là mối quan hệ biện chứng, trong đó chính trị – kinh tế quyết định văn hóa, còn văn hóa góp phần thực hiện mục tiêu chính trị và kinh tế"}]},{"n":102,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Phát biểu nào sau đây phản ánh đúng quan điểm của Hồ Chí Minh về vị trí của kinh tế và văn hóa?","answer":"C","options":[{"key":"A","text":"Phát triển văn hóa là nền tảng để tạo điều kiện phát triển kinh tế vững chắc"},{"key":"B","text":"Phải phát triển cả văn hóa và kinh tế song hành vì văn hóa là yếu tố then chốt của cách mạng"},{"key":"C","text":"Phải phát triển kinh tế trước vì “có thực mới vực được đạo”, rồi mới phát triển văn hóa"},{"key":"D","text":"Phát triển văn hóa trước để xây dựng hệ giá trị phù hợp, sau đó kinh tế sẽ theo sau"}]},{"n":103,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Phát biểu “Xã hội thế nào, văn nghệ thế ấy” của Hồ Chí Minh phản ánh điều gì?","answer":"C","options":[{"key":"A","text":"Mối liên hệ đơn chiều giữa xã hội và nghệ thuật, trong đó xã hội quyết định toàn bộ nghệ thuật"},{"key":"B","text":"Văn nghệ là sản phẩm ngẫu nhiên của xã hội, không phản ánh rõ ràng đời sống xã hội"},{"key":"C","text":"Văn nghệ chịu sự tác động của xã hội, phản ánh tính chất, trình độ và định hướng phát triển xã hội"},{"key":"D","text":"Văn nghệ phát triển độc lập với xã hội nhưng vẫn ảnh hưởng đến tư duy của quần chúng"}]},{"n":104,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, văn hóa góp phần vào mục tiêu nào của đất nước?","answer":"C","options":[{"key":"A","text":"Xây dựng một xã hội phát triển, cởi mở, đa chiều và hướng đến toàn cầu hóa"},{"key":"B","text":"Phát triển nền văn hóa giải trí để phục vụ đời sống tinh thần của nhân dân"},{"key":"C","text":"Xây dựng nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"D","text":"Thúc đẩy giáo dục đại học, hội nhập văn hóa phương Tây và phát triển nền công nghiệp sáng tạo"}]},{"n":105,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, mục tiêu của quan hệ xã hội trong chủ nghĩa xã hội là gì?","answer":"C","options":[{"key":"A","text":"Bảo đảm dân chủ, công bằng, hiện đại hóa và phát triển thị trường"},{"key":"B","text":"Phát triển xã hội ổn định, hiện đại và hướng tới sự hội nhập toàn cầu"},{"key":"C","text":"Bảo đảm dân chủ, công bằng, văn minh"},{"key":"D","text":"Tăng trưởng kinh tế làm trung tâm, bảo đảm trật tự an ninh là cốt lõi"}]},{"n":106,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Chế độ xã hội chủ nghĩa theo tư tưởng Hồ Chí Minh là chế độ như thế nào?","answer":"B","options":[{"key":"A","text":"Chế độ dân làm chủ, nhà nước định hướng phát triển xã hội theo mô hình hỗn hợp"},{"key":"B","text":"Chế độ dân làm chủ, dân là chủ, mọi người đều có trách nhiệm xây dựng xã hội"},{"key":"C","text":"Chế độ do nhà nước toàn quyền quản lý, dân có quyền tham gia qua đại biểu"},{"key":"D","text":"Chế độ xã hội công bằng, bình đẳng nhưng quyền dân chủ được thực hiện có điều kiện"}]},{"n":107,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo tư tưởng Hồ Chí Minh, công dân trong chế độ xã hội chủ nghĩa có quyền gì?","answer":"C","options":[{"key":"A","text":"Quyền tự do kinh doanh, quyền tiếp cận vốn, quyền bảo vệ tài sản, quyền định cư"},{"key":"B","text":"Quyền bình đẳng giới, quyền nhập cư, quyền phát triển doanh nghiệp, quyền sở hữu trí tuệ"},{"key":"C","text":"Quyền làm việc, nghỉ ngơi, học tập, tự do thân thể, ngôn luận, báo chí, hội họp, lập hội, biểu tình; tín ngưỡng, bầu cử và ứng cử"},{"key":"D","text":"Quyền cư trú, quyền di chuyển quốc tế, quyền sở hữu cá nhân, quyền khiếu kiện quốc tế"}]},{"n":108,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Quan điểm của Hồ Chí Minh về việc thực hiện các quyền tự do dân chủ như thế nào?","answer":"C","options":[{"key":"A","text":"Các quyền tự do dân chủ phải đi kèm với cam kết trung thành tuyệt đối với Nhà nước"},{"key":"B","text":"Các quyền tự do dân chủ được đảm bảo hoàn toàn, không có bất kỳ giới hạn nào trong thực hiện"},{"key":"C","text":"Nhà nước đảm bảo quyền tự do dân chủ nhưng nghiêm c ấm lợi dụng các quyền đó để xâm phạm lợi ích Nhà nước và nhân dân"},{"key":"D","text":"Các quyền tự do dân chủ chỉ thực hiện khi được cơ quan có thẩm quyền cho phép cụ thể từng trường hợp"}]},{"n":109,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, mọi công dân trong chế độ xã hội chủ nghĩa phải được?","answer":"C","options":[{"key":"A","text":"Hưởng quyền lợi theo mức độ cống hiến và mức thu nhập cá nhân"},{"key":"B","text":"Hưởng các quyền cơ bản nếu thực hiện đúng nghĩa vụ đối với Nhà nước"},{"key":"C","text":"Bảo đảm quyền và nghĩa vụ bình đẳng về mọi mặt, đặc biệt là trong pháp luật"},{"key":"D","text":"Ưu tiên tiếp cận các chính sách phát triển cá nhân khi có đóng góp cho xã hội"}]},{"n":110,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, làm thế nào để phát huy được tính cách và sở trường của mỗi người?","answer":"D","options":[{"key":"A","text":"Bằng cách tổ chức các phong trào cá nhân xuất sắc trong sản xuất và lao động"},{"key":"B","text":"Bằng việc khuyến khích cạnh tranh lành mạnh giữa các cá nhân trong xã hội"},{"key":"C","text":"Bằng chính sách ưu đãi và phân loại nhân lực theo ngành nghề đặc thù"},{"key":"D","text":"Bằng cách bảo đảm lợi ích cá nhân đúng đắn được thỏa mãn trong sự hài hòa với lợi ích chung"}]},{"n":111,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Nội dung nào sau đây KHÔNG phản ánh đúng quan điểm của Hồ Chí Minh về chế độ dân chủ?","answer":"C","options":[{"key":"A","text":"Dân chủ là để người dân thực sự làm chủ đất nước"},{"key":"B","text":"Dân chủ là mục tiêu và cũng là động lực của sự phát triển xã hội chủ nghĩa"},{"key":"C","text":"Dân chủ chỉ nên áp dụng trong lĩnh vực chính trị, không mở rộng sang kinh tế"},{"key":"D","text":"Dân chủ đi đôi với kỷ cương và pháp luật, không được lợi dụng để chống phá"}]},{"n":112,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, để thúc đẩy tiến trình cách mạng xã hội chủ nghĩa, động lực giữ vai trò quyết định là gì?","answer":"A","options":[{"key":"A","text":"Nội lực dân tộc, là nhân dân"},{"key":"B","text":"Sự hỗ trợ của các nước xã hội chủ nghĩa anh em"},{"key":"C","text":"Tập trung phát triển công nghiệp nặng, hiện đại hóa quốc phòng"},{"key":"D","text":"Việc thực hiện cải cách hành chính và xây dựng bộ máy nhà nước tinh gọn"}]},{"n":113,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Trong tư tưởng Hồ Chí Minh, động lực cách mạng xã hội chủ nghĩa KHÔNG chỉ bao gồm nội lực mà còn có gì?","answer":"B","options":[{"key":"A","text":"Hệ thống tuyên truyền hiện đại và mạng lưới thông tin rộng khắp"},{"key":"B","text":"Cả nội lực và ngoại lực, vật chất và tinh thần, quá khứ, hiện tại và tương lai"},{"key":"C","text":"Chính sách bảo hộ mậu dịch và tự chủ kinh tế quốc gia"},{"key":"D","text":"Việc áp dụng công nghệ cao và chuyển đổi số trong quản lý xã hội"}]},{"n":114,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Hồ Chí Minh cho rằng trong xã hội xã hội chủ nghĩa, mỗi người có điều kiện gì?","answer":"B","options":[{"key":"A","text":"Đóng góp cho nền văn hóa dân tộc thông qua hoạt động sáng tạo cá nhân"},{"key":"B","text":"Phát huy sở trường cá nhân, cải thiện đời sống và sống hạnh phúc"},{"key":"C","text":"Tự do lựa chọn nghề nghiệp phù hợp theo nhu cầu thị trường lao động"},{"key":"D","text":"Thực hiện quyền tự do kinh doanh trong mọi lĩnh vực của nền kinh tế"}]},{"n":115,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, dân chủ là gì đối với nhân dân?","answer":"D","options":[{"key":"A","text":"Là phương tiện để thực hiện chính sách phân bổ nguồn lực quốc gia"},{"key":"B","text":"Là công cụ kiểm soát và giám sát bộ máy nhà nước"},{"key":"C","text":"Là nền tảng để tăng trưởng kinh tế bền vững và hội nhập quốc tế"},{"key":"D","text":"Là của quý báu nhất, vì dân là chủ"}]},{"n":116,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Vì sao Hồ Chí Minh quan tâm đến lợi ích của cả cộng đồng người và lợi ích của những con người cụ thể?","answer":"B","options":[{"key":"A","text":"Vì mỗi người đều có quyền tham gia vào hoạt động xã hội và chính trị"},{"key":"B","text":"Vì Người cho rằng đây là một trong những điểm khác nhau cơ bản giữa chủ nghĩa xã hội với những chế độ xã hội trước nó"},{"key":"C","text":"Vì điều đó giúp tăng năng suất lao động và phát triển kinh tế đất nước"},{"key":"D","text":"Vì nó là phương tiện để Nhà nước dễ dàng quản lý xã hội và tổ chức sản xuất"}]},{"n":117,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Trong tư tưởng Hồ Chí Minh, Đảng Cộng sản được ví như điều gì?","answer":"C","options":[{"key":"A","text":"Là bàn tay của nhân dân, nắm giữ sức mạnh tập thể"},{"key":"B","text":"Là mái nhà chung của mọi tầng lớp nhân dân"},{"key":"C","text":"Là người cầm lái, giữ vai trò quyết định trong hành trình cách mạng"},{"key":"D","text":"Là tiếng nói chính thức của giai cấp công nhân và nông dân"}]},{"n":118,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo tư tưởng Hồ Chí Minh, yếu tố nào giữ vai trò quyết định trong hoạt động của các cộng đồng người nhằm phát huy động lực của chủ nghĩa xã hội?","answer":"C","options":[{"key":"A","text":"Sự ủng hộ từ cộng đồng quốc tế và các tổ chức nhân đạo"},{"key":"B","text":"Trình độ học vấn và nhận thức của các tổ chức quần chúng"},{"key":"C","text":"Sự lãnh đạo của Đảng Cộng sản"},{"key":"D","text":"Sự quản lý chặt chẽ của các cơ quan hành chính nhà nước"}]},{"n":119,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh khẳng định: “Muốn xây dựng chủ nghĩa xã hội, trước hết cần có những (_____)” (Hồ Chí Minh: Toàn tập, Sđd, t. 13, tr. 66)","answer":"C","options":[{"key":"A","text":"Người lao động có tay nghề cao"},{"key":"B","text":"Cán bộ quản lý am hiểu chuyên môn"},{"key":"C","text":"Con người xã hội chủ nghĩa"},{"key":"D","text":"Tổ chức chính trị vững mạnh"}]},{"n":120,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, con người xã hội chủ nghĩa cần có tư tưởng nào dưới đây?","answer":"B","options":[{"key":"A","text":"Đặt lợi ích cá nhân lên trên lợi ích tập thể"},{"key":"B","text":"“Mình vì mọi người, mọi người vì mình”"},{"key":"C","text":"Làm việc theo nguyên tắc “trách nhiệm cá nhân cao hơn trách nhiệm tập thể”"},{"key":"D","text":"Phấn đấu để có cuộc sống tiện nghi và địa vị cao trong xã hội"}]},{"n":121,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Câu nào sau đây là biểu hiện của tư tưởng và tác phong xã hội chủ nghĩa theo Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Ưu tiên lợi nhuận và hiệu suất trong tất cả các hoạt động kinh tế"},{"key":"B","text":"Tôn trọng quy trình, thủ tục hành chính trong mọi tình huống"},{"key":"C","text":"Có tinh thần tập thể xã hội chủ nghĩa, ý thức làm chủ, cần kiệm và tiến bộ"},{"key":"D","text":"Đặt mục tiêu phát triển cá nhân song song với sự ổn định chính trị"}]},{"n":122,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Hồ Chí Minh cho rằng, các tổ chức chính trị - xã hội hoạt động nhằm mục đích gì?","answer":"C","options":[{"key":"A","text":"Tăng cường tính cạnh tranh giữa các nhóm lợi ích"},{"key":"B","text":"Hỗ trợ thực hiện các chương trình kinh tế của nhà nước"},{"key":"C","text":"Vì lợi ích của thành viên trong sự thống nhất với lợi ích dân tộc"},{"key":"D","text":"Bảo vệ quyền tự do ngôn luận và phản biện chính sách"}]},{"n":123,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, Nhà nước giữ vai trò gì dưới sự lãnh đạo của Đảng?","answer":"B","options":[{"key":"A","text":"Là cơ quan điều hành và kiểm soát tất cả các lĩnh vực xã hội"},{"key":"B","text":"Là tổ chức đại diện cho ý chí và quyền lực của nhân dân, thực hiện chức năng quản lý xã hội"},{"key":"C","text":"Là bộ máy hành chính phục vụ các quyết định chiến lược về kinh tế"},{"key":"D","text":"Là tổ chức kiểm tra và giám sát hoạt động của các tổ chức đảng và đoàn thể"}]},{"n":124,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Chủ nghĩa cá nhân trong tư tưởng Hồ Chí Minh được xem là?","answer":"C","options":[{"key":"A","text":"Biểu hiện tự nhiên của con người trong quá trình phát triển cá nhân"},{"key":"B","text":"Một trở ngại nhỏ, có thể điều chỉnh bằng giáo dục đạo đức"},{"key":"C","text":"Một kẻ địch bên trong cần kiên quyết loại bỏ"},{"key":"D","text":"Một đặc điểm phù hợp với nền kinh tế thị trường hiện đại"}]},{"n":125,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Trong hệ thống động lực của chủ nghĩa xã hội, ba yếu tố nào gắn bó hữu cơ với nhau trong tư tưởng Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Kinh tế – văn hóa – giáo dục"},{"key":"B","text":"Lợi ích của dân – dân chủ của dân – đoàn kết toàn dân"},{"key":"C","text":"Tự do cá nhân – cạnh tranh thị trường – phát triển công nghệ"},{"key":"D","text":"Đạo đức – kỷ luật – sự lãnh đạo của các cấp chính quyền"}]},{"n":126,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Theo Hồ Chí Minh, để các động lực của chủ nghĩa xã hội phát huy hiệu quả, cần phải?","answer":"C","options":[{"key":"A","text":"Có sự tài trợ quốc tế và viện trợ phát triển"},{"key":"B","text":"Đảm bảo sự phối hợp giữa các bộ, ngành và địa phương"},{"key":"C","text":"Thông qua hoạt động của những cộng đồng người và những con người cụ thể"},{"key":"D","text":"Có kế hoạch dài hạn và chính sách ưu tiên theo vùng miền"}]},{"n":127,"sec":"2. Tư tưởng Hồ Chí Minh về xây dựng chủ nghĩa xã hội ở Việt Nam","stem":"Chống lại kẻ địch bên ngoài trong tư tưởng Hồ Chí Minh đồng thời phải kết hợp với?","answer":"C","options":[{"key":"A","text":"Mở rộng quan hệ quốc tế và viện trợ phát triển"},{"key":"B","text":"Thắt chặt kỷ cương và kiểm soát nội bộ"},{"key":"C","text":"Cảnh giác và chống lại kẻ địch bên trong là chủ nghĩa cá nhân"},{"key":"D","text":"Nâng cao năng lực quản lý và điều hành của cán bộ"}]},{"n":128,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là thời kỳ như thế nào?","answer":"D","options":[{"key":"A","text":"Thời kỳ ổn định chính trị và phát triển kinh tế thị trường định hướng XHCN"},{"key":"B","text":"Thời kỳ thực hiện cải cách hành chính toàn diện trên mọi lĩnh vực"},{"key":"C","text":"Thời kỳ chuyển đổi cơ cấu dân số từ nông thôn sang đô thị một cách nhanh chóng"},{"key":"D","text":"Thời kỳ cải biến sâu sắc, lâu dài, phức tạp, khó khăn và gian khổ"}]},{"n":129,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, nhiệm vụ lớn nhất của thời kỳ quá độ ở Việt Nam là gì?","answer":"B","options":[{"key":"A","text":"Tăng trưởng kinh tế dựa vào công nghiệp nặng"},{"key":"B","text":"Cải biến xã hội cũ thành xã hội mới – xã hội chủ nghĩa"},{"key":"C","text":"Xây dựng các đặc khu kinh tế, mở rộng thị trường xuất khẩu"},{"key":"D","text":"Tăng tốc hiện đại hóa quân đội và củng cố an ninh quốc phòng"}]},{"n":130,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Điều gì khiến thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam trở nên đặc biệt khó khăn, theo Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Do sự can thiệp của các thế lực thù địch và các cuộc chiến tranh cục bộ"},{"key":"B","text":"Do thiếu hụt nguồn tài chính và phụ thuộc vào viện trợ nước ngoài"},{"key":"C","text":"Vì phải thay đổi triệt để nếp sống, tư tưởng, thói quen có gốc rễ hàng ngàn năm"},{"key":"D","text":"Vì sự phân hóa giàu nghèo ngày càng gia tăng và đô thị hóa thiếu kiểm soát"}]},{"n":131,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Hồ Chí Minh khẳng định: “Tiến lên chủ nghĩa xã hội không thể một sớm một chiều\" vì lý do nào?","answer":"C","options":[{"key":"A","text":"Phải chờ đợi sự phát triển toàn diện về khoa học công nghệ"},{"key":"B","text":"Cần có thời gian để thu hút đầu tư nước ngoài và hội nhập kinh tế quốc tế"},{"key":"C","text":"Công cuộc này là biến đổi sâu sắc, phức tạp hơn cả việc đánh giặc"},{"key":"D","text":"Do xã hội cần thời gian để hoàn thiện hệ thống luật pháp và thể chế"}]},{"n":132,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Đặc điểm lớn nhất của thời kỳ quá độ ở Việt Nam, theo Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phát triển công nghiệp nặng trước nông nghiệp và dịch vụ"},{"key":"B","text":"Tiến hành cải cách thể chế chính trị trước cải cách kinh tế"},{"key":"C","text":"Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không qua giai đoạn tư bản chủ nghĩa"},{"key":"D","text":"Thực hiện song song công nghiệp hóa và hiện đại hóa với tăng trưởng xanh"}]},{"n":133,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Một trong những khó khăn đặc trưng của thời kỳ quá độ là gì?","answer":"A","options":[{"key":"A","text":"Xã hội tồn tại đan xen yếu tố cũ và mới, trong đó yếu tố cũ có khi còn thắng yếu tố mới"},{"key":"B","text":"Cơ sở hạ tầng yếu kém, thiếu vốn đầu tư và nhân lực chất lượng cao"},{"key":"C","text":"Kinh tế vĩ mô chưa ổn định và thị trường tài chính chưa phát triển"},{"key":"D","text":"Thiếu sự phối hợp giữa các cơ quan trung ương và địa phương trong thực thi chính sách"}]},{"n":134,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, vì sao thời kỳ quá độ ở Việt Nam không thể làm mau được?","answer":"B","options":[{"key":"A","text":"Vì cần có thời gian để thiết lập hệ thống hành chính thống nhất"},{"key":"B","text":"Vì nước ta mới thoát khỏi ách thực dân, phong kiến, xuất phát điểm thấp"},{"key":"C","text":"Vì các mô hình phát triển hiện đại chưa được cập nhật đầy đủ"},{"key":"D","text":"Vì chưa đạt được đồng thuận toàn xã hội về định hướng phát triển"}]},{"n":135,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Việt Nam bước vào thời kỳ quá độ lên chủ nghĩa xã hội trong điều kiện?","answer":"C","options":[{"key":"A","text":"Là một nước công nghiệp mới nổi, có nền sản xuất phát triển cao"},{"key":"B","text":"Là một nước vừa trải qua cải cách ruộng đất và công nghiệp hóa cơ bản"},{"key":"C","text":"Là một nước nông nghiệp lạc hậu, mới thoát khỏi ách thực dân, phong kiến"},{"key":"D","text":"Là một nước đã hoàn thành quá trình tích lũy tư bản chủ nghĩa ban đầu"}]},{"n":136,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Trong thời kỳ quá độ, theo Hồ Chí Minh, xã hội Việt Nam tồn tại đồng thời điều gì?","answer":"B","options":[{"key":"A","text":"Nhiều hình thức sở hữu và phân phối thu nhập chưa đồng đều"},{"key":"B","text":"Yếu tố của xã hội cũ và yếu tố của xã hội mới cùng tồn tại, đan xen nhau"},{"key":"C","text":"Các hình thức giáo dục truyền thống và hiện đại song song phát triển"},{"key":"D","text":"Cơ cấu dân cư và lao động chuyển dịch mạnh từ nông thôn ra thành thị"}]},{"n":137,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, nhiệm vụ quan trọng nhất trong lĩnh vực kinh tế trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Cải tổ nền kinh tế thị trường định hướng xã hội chủ nghĩa dựa trên các mô hình của phương Tây"},{"key":"B","text":"Tập trung xóa bỏ hoàn toàn tư hữu và kinh tế cá thể để xây dựng kinh tế quốc doanh"},{"key":"C","text":"Cải tạo nền kinh tế cũ, xây dựng nền kinh tế mới có công nghiệp và nông nghiệp hiện đại"},{"key":"D","text":"Đẩy mạnh phát triển kinh tế thị trường tư bản chủ nghĩa để thu hút đầu tư ngoại quốc"}]},{"n":138,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Về mặt chính trị, Hồ Chí Minh nhấn mạnh phải xây dựng chế độ nào trong thời kỳ quá độ?","answer":"C","options":[{"key":"A","text":"Chế độ pháp quyền tư sản dựa trên mô hình dân chủ phương Tây"},{"key":"B","text":"Chế độ tập quyền trung ương với sự lãnh đạo toàn diện của nhà nước"},{"key":"C","text":"Chế độ dân chủ vì đây là bản chất của chủ nghĩa xã hội"},{"key":"D","text":"Chế độ quân chủ chuyên chế có cải tiến theo hướng hiện đại hóa"}]},{"n":139,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, việc xây dựng chế độ dân chủ trong thời kỳ quá độ phải bắt đầu từ đâu?","answer":"B","options":[{"key":"A","text":"Phát triển mạnh mẽ các tổ chức xã hội để giám sát bộ máy hành chính"},{"key":"B","text":"Chống chủ nghĩa cá nhân trong Đảng và bộ máy chính quyền, bồi dưỡng nhân dân có tri thức làm chủ"},{"key":"C","text":"Tập trung quyền lực vào trung ương để đảm bảo sự lãnh đạo tập trung, thống nhất"},{"key":"D","text":"Tăng cường kiểm soát của nhà nước đối với toàn bộ đời sống xã hội"}]},{"n":140,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Hồ Chí Minh cho rằng giữa nhiệm vụ “cải tạo” và “xây dựng” trong phát triển kinh tế thì đâu là nhiệm vụ chủ chốt và lâu dài?","answer":"A","options":[{"key":"A","text":"Xây dựng là nhiệm vụ chủ chốt và lâu dài, gắn với thực hiện quyền làm chủ của nhân dân"},{"key":"B","text":"Cải tạo là nhiệm vụ quan trọng vì cần xóa bỏ ngay tàn dư của chế độ cũ"},{"key":"C","text":"Cả hai nhiệm vụ đều tách biệt và không phụ thuộc lẫn nhau"},{"key":"D","text":"Phải tập trung cải cách hệ thống ngân hàng trước khi tiến hành xây dựng nền kinh tế mới"}]},{"n":141,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, trong lĩnh vực văn hóa, cần thực hiện nhiệm vụ nào sau đây để xây dựng nền văn hóa xã hội chủ nghĩa?","answer":"C","options":[{"key":"A","text":"Tập trung hiện đại hóa giáo dục và loại bỏ toàn bộ di sản văn hóa truyền thống"},{"key":"B","text":"Phát triển văn hóa mang tính khu vực, nhấn mạnh đặc thù vùng miền hơn là tính dân tộc"},{"key":"C","text":"Tẩy trừ di tích thuộc địa, ảnh hưởng văn hóa đế quốc, phát huy truyền thống dân tộc và tiếp thu văn hóa tiến bộ thế giới"},{"key":"D","text":"Du nhập tối đa văn hóa phương Tây để theo kịp trình độ văn minh hiện đại của nhân loại"}]},{"n":142,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Một trong những đặc điểm của nền văn hóa mới mà Hồ Chí Minh hướng tới là gì?","answer":"D","options":[{"key":"A","text":"Có tính chất hiện đại hóa tuyệt đối, phù hợp với xu hướng văn hóa toàn cầu"},{"key":"B","text":"Mang tính phổ quát, phi dân tộc và đề cao cá nhân chủ nghĩa"},{"key":"C","text":"Đề cao yếu tố giải trí, thương mại hóa các giá trị văn hóa truyền thống"},{"key":"D","text":"Là nền văn hóa có tính dân tộc, khoa học và đại chúng"}]},{"n":143,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Trong quan điểm của Hồ Chí Minh, việc thay đổi các quan hệ xã hội cũ cần nhằm mục tiêu gì?","answer":"A","options":[{"key":"A","text":"Xây dựng xã hội dân chủ, công bằng, văn minh, tôn trọng con người và hài hòa lợi ích cá nhân với tập thể"},{"key":"B","text":"Duy trì những truyền thống xã hội cũ để đảm bảo tính ổn định trong thời kỳ chuyển tiếp"},{"key":"C","text":"Đề cao tuyệt đối lợi ích tập thể, triệt tiêu hoàn toàn quyền lợi cá nhân"},{"key":"D","text":"Tách biệt hoàn toàn các lợi ích cá nhân với đời sống tập thể để tránh xung đột xã hội"}]},{"n":144,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, việc bảo đảm lợi ích cá nhân trong thời kỳ quá độ nhằm mục đích gì?","answer":"C","options":[{"key":"A","text":"Tạo ra sự cạnh tranh quyết liệt để thúc đẩy năng suất lao động."},{"key":"B","text":"Khuyến khích tư hữu trong mọi lĩnh vực để phát triển kinh tế thị trường tự do"},{"key":"C","text":"Giúp mỗi người cải thiện đời sống riêng, phát huy sở trường trong sự hài hòa với lợi ích tập thể"},{"key":"D","text":"Là phương tiện để củng cố địa vị của các tầng lớp xã hội truyền thống"}]},{"n":145,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Để phát triển một nền văn hóa mới trong thời kỳ quá độ, Hồ Chí Minh đặc biệt nhấn mạnh việc tiếp thu như thế nào đối với văn hóa thế giới?","answer":"B","options":[{"key":"A","text":"Chỉ tiếp thu các yếu tố hiện đại thuộc văn hóa phương Tây"},{"key":"B","text":"Tiếp thu có chọn lọc các yếu tố tiến bộ của văn hóa thế giới, phù hợp với văn hóa dân tộc"},{"key":"C","text":"Đồng hóa toàn bộ văn hóa thế giới để nâng cao trình độ dân trí"},{"key":"D","text":"Hòa nhập toàn diện vào các mô hình văn hóa toàn cầu, không cần giữ bản sắc"}]},{"n":146,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Có mấy nguyên tắc xây dựng chủ nghĩa xã hội trong thời kỳ quá độ?","answer":"C","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]},{"n":147,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, nguyên tắc hàng đầu trong quá trình xây dựng chủ nghĩa xã hội là gì?","answer":"B","options":[{"key":"A","text":"Đặt trọng tâm vào việc mở rộng quan hệ quốc tế, học hỏi mô hình của các nước tư bản phát triển"},{"key":"B","text":"Mọi tư tưởng, hành động phải được thực hiện trên nền tảng chủ nghĩa Mác – Lênin"},{"key":"C","text":"Thực hiện nhanh chóng công nghiệp hóa và hiện đại hóa theo hướng tự phát"},{"key":"D","text":"Xây dựng một hệ thống pháp luật riêng biệt, không cần phụ thuộc lý luận cách mạng"}]},{"n":148,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Trong tư tưởng Hồ Chí Minh, tại sao độc lập dân tộc là nguyên tắc không thể thiếu khi xây dựng chủ nghĩa xã hội?","answer":"A","options":[{"key":"A","text":"Vì độc lập dân tộc là điều kiện tiên quyết để thực hiện chủ nghĩa xã hội, và chủ nghĩa xã hội bảo đảm cho độc lập dân tộc vững chắc"},{"key":"B","text":"Vì chỉ có các nước đã độc lập mới có quyền tự do lựa chọn mô hình phát triển kinh tế"},{"key":"C","text":"Vì chủ nghĩa xã hội chỉ có thể tồn tại trong điều kiện không bị ảnh hưởng bởi các nước lớn"},{"key":"D","text":"Vì độc lập dân tộc là mục tiêu chính trị ngắn hạn trong khi chủ nghĩa xã hội là mục tiêu dài hạn"}]},{"n":149,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, việc “cụ thể hóa chủ nghĩa Mác – Lênin” có ý nghĩa gì trong thực tiễn cách mạng Việt Nam?","answer":"C","options":[{"key":"A","text":"Lựa chọn những điểm có lợi nhất trong học thuyết để áp dụng vào từng giai đoạn phát triển kinh tế - xã hội"},{"key":"B","text":"Tùy ý điều chỉnh lý luận để phù hợp với thực tiễn mà không cần giữ nguyên lập trường tư tưởng"},{"key":"C","text":"Vận dụng lập trường, quan điểm, phương pháp Mác – Lênin phù hợp với điều kiện, hoàn cảnh cụ thể của Việt Nam"},{"key":"D","text":"Đưa học thuyết vào giáo dục như một môn học bắt buộc để nâng cao nhận thức chính trị cho sinh viên"}]},{"n":150,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, vì sao cách mạng Việt Nam cần đoàn kết và học tập kinh nghiệm của các nước anh em?","answer":"B","options":[{"key":"A","text":"Vì Việt Nam chưa đủ điều kiện để phát triển độc lập nên cần dựa hoàn toàn vào các mô hình có sẵn"},{"key":"B","text":"Vì cách mạng Việt Nam là một bộ phận của lực lượng hòa bình, dân chủ, xã hội chủ nghĩa trên thế giới"},{"key":"C","text":"Vì cần phụ thuộc vào sự viện trợ của các nước xã hội chủ nghĩa để tồn tại trong thời kỳ quá độ"},{"key":"D","text":"Vì học tập kinh nghiệm sẽ giúp Việt Nam đồng hóa nhanh chóng với các nước tiên tiến"}]},{"n":151,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Hồ Chí Minh khẳng định rằng khi học tập kinh nghiệm quốc tế, Việt Nam cần?","answer":"B","options":[{"key":"A","text":"Áp dụng toàn bộ mô hình xây dựng chủ nghĩa xã hội của Liên Xô một cách triệt để"},{"key":"B","text":"Vận dụng sáng tạo kinh nghiệm các nước anh em, tránh sao chép máy móc"},{"key":"C","text":"Tập trung sao chép mô hình kinh tế kế hoạch hóa tập trung như các nước bạn"},{"key":"D","text":"Chuyển giao toàn bộ cơ chế tổ chức của Đảng từ mô hình của các nước xã hội chủ nghĩa lớn"}]},{"n":152,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Nguyên tắc “xây phải đi đôi với chống” trong tư tưởng Hồ Chí Minh nhằm nhấn mạnh điều gì?","answer":"C","options":[{"key":"A","text":"Chỉ cần xây dựng kinh tế, không cần quan tâm đến tàn dư tư tưởng xã hội cũ"},{"key":"B","text":"Ưu tiên chống chủ nghĩa cá nhân trước khi bắt đầu quá trình xây dựng"},{"key":"C","text":"Cùng với xây dựng xã hội mới, phải kiên quyết đấu tranh với những thế lực cản trở sự phát triển của cách mạng"},{"key":"D","text":"Chỉ tập trung vào bảo vệ an ninh quốc gia mà chưa cần phát triển các lĩnh vực khác"}]},{"n":153,"sec":"3. Tư tưởng Hồ Chí Minh về thời kỳ quá độ lên chủ nghĩa xã hội ở Việt","stem":"Theo Hồ Chí Minh, ai là “kẻ địch bên trong” mà mỗi người cần phải đánh bại trong quá trình xây dựng CNXH?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa cá nhân với các biểu hiện như tham lam, háo danh, vô tổ chức, vô kỷ luật"},{"key":"B","text":"Lực lượng phản động lưu vong ở nước ngoài"},{"key":"C","text":"Những tàn dư của văn hóa thực dân, đế quốc"},{"key":"D","text":"Các phần tử cơ hội trong xã hội và kinh tế tư nhân"}]},{"n":154,"sec":"1. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, độc lập dân tộc có vai trò như thế nào trong tiến trình cách mạng xã hội chủ nghĩa?","answer":"B","options":[{"key":"A","text":"Là mục tiêu tối hậu của cách mạng Việt Nam, không cần thiết tiến xa hơn"},{"key":"B","text":"Là cơ sở, tiền đề cho cách mạng xã hội chủ nghĩa và chủ nghĩa cộng sản"},{"key":"C","text":"Là giai đoạn song song với cách mạng xã hội chủ nghĩa, không liên quan trực tiếp"},{"key":"D","text":"Là kết quả của chính sách cải cách kinh tế triệt để trong thời kỳ quá độ"}]},{"n":155,"sec":"1. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội","stem":"Hồ Chí Minh khẳng định nội dung của độc lập dân tộc bao gồm những yếu tố nào?","answer":"B","options":[{"key":"A","text":"Chỉ bao gồm toàn vẹn lãnh thổ và quyền tự trị quốc gia"},{"key":"B","text":"Bao gồm cả nội dung dân tộc và dân chủ, độc lập dân tộc phải gắn liền với thống nhất, chủ quyền và toàn vẹn lãnh thổ"},{"key":"C","text":"Bao gồm chủ quyền chính trị, nhưng không gắn với đời sống nhân dân"},{"key":"D","text":"Tập trung vào tự do báo chí, ngôn luận, mà không bao gồm chủ quyền lãnh thổ"}]},{"n":156,"sec":"1. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, cách mạng dân tộc dân chủ nhân dân càng triệt để sẽ mang lại điều gì cho cách mạng xã hội chủ nghĩa?","answer":"D","options":[{"key":"A","text":"Tạo ra áp lực buộc nhà nước phải thực hiện công nghiệp hóa một cách cấp tốc"},{"key":"B","text":"Đặt nền móng cho sự chuyển hóa nhanh chóng sang mô hình chủ nghĩa tư bản nhà nước"},{"key":"C","text":"Làm suy yếu ảnh hưởng của các tôn giáo truyền thống trong xã hội"},{"key":"D","text":"Tạo ra tiền đề thuận lợi và sức mạnh to lớn cho cách mạng xã hội chủ nghĩa"}]},{"n":157,"sec":"1. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội","stem":"Điều nào sau đây thể hiện tính đúng đắn và sáng tạo trong tư tưởng Hồ Chí Minh về mối quan hệ giữa độc lập dân tộc và chủ nghĩa xã hội?","answer":"A","options":[{"key":"A","text":"Kết hợp mục tiêu giải phóng dân tộc với định hướng xây dựng chủ nghĩa xã hội ngay từ đầu"},{"key":"B","text":"Chỉ tập trung vào đấu tranh giai cấp, không chú trọng vấn đề dân tộc"},{"key":"C","text":"Áp dụng hoàn toàn mô hình cách mạng của các nước tư bản phương Tây"},{"key":"D","text":"Ưu tiên chủ nghĩa xã hội trước, độc lập dân tộc sẽ đến sau khi kinh tế phát triển"}]},{"n":158,"sec":"2. Chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","stem":"Điền từ còn thiếu vào (_____)? Chủ nghĩa xã hội là xu thế (_____) của thời đại và phù hợp với lợi ích của nhân dân Việt Nam. Vì vậy, cách mạng giải phóng dân tộc ở Việt Nam phải mang tính (_____) thì mới giành được thắng lợi hoàn toàn và triệt để.","answer":"C","options":[{"key":"A","text":"Ngẫu nhiên - độc lập"},{"key":"B","text":"Kinh tế – cách mạng"},{"key":"C","text":"Tất yếu – định hướng xã hội chủ nghĩa"},{"key":"D","text":"Phụ thuộc – bảo thủ"}]},{"n":159,"sec":"2. Chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","stem":"Theo Hồ Chí Minh, đặc trưng dân chủ của chủ nghĩa xã hội thể hiện ở điều gì?","answer":"A","options":[{"key":"A","text":"Là chế độ do nhân dân làm chủ, thể hiện trong mọi mặt đời sống và được thể chế hóa bằng pháp luật"},{"key":"B","text":"Là một nhà nước chuyên chính vô sản, tập trung quyền lực tối cao vào quân đội và công an"},{"key":"C","text":"Là hệ thống cai trị do Đảng điều hành tuyệt đối, không cần tham khảo ý kiến quần chúng"},{"key":"D","text":"Là mô hình chính trị kết hợp giữa chế độ phong kiến và hình thức nghị viện kiểu tư sản"}]},{"n":160,"sec":"2. Chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","stem":"Trong tư tưởng Hồ Chí Minh, chủ nghĩa xã hội bảo đảm phúc lợi xã hội cho những đối tượng nào?","answer":"C","options":[{"key":"A","text":"Chỉ áp dụng cho những người làm việc trong khu vực nhà nước"},{"key":"B","text":"Chủ yếu tập trung cho cán bộ nhà nước và lực lượng vũ trang ưu tú"},{"key":"C","text":"Cho người già, trẻ em và những người gặp khó khăn trong cuộc sống"},{"key":"D","text":"Dành riêng cho giai cấp công nhân để thực hiện chuyên chính vô sản"}]},{"n":161,"sec":"2. Chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","stem":"Hồ Chí Minh cho rằng chủ nghĩa xã hội hiện thực ở Việt Nam sẽ có tác dụng gì đối với quốc tế?","answer":"D","options":[{"key":"A","text":"Làm thay đổi hệ thống chính trị toàn cầu theo hướng tập quyền tuyệt đối"},{"key":"B","text":"Trở thành căn cứ địa quân sự chủ chốt cho phong trào cộng sản thế giới"},{"key":"C","text":"Làm tăng vị thế Việt Nam trong khối các nước phát triển tư bản."},{"key":"D","text":"Làm gương cho các nước mới giành độc lập đang định hướng xã hội chủ nghĩa"}]},{"n":162,"sec":"3. Điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, có mấy điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội?","answer":"B","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]},{"n":163,"sec":"3. Điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, điều kiện nào là cần thiết để bảo đảm nền độc lập dân tộc gắn liền với chủ nghĩa xã hội?","answer":"A","options":[{"key":"A","text":"Bảo đảm vai trò lãnh đạo tuyệt đối của Đảng Cộng sản trong suốt tiến trình cách mạng"},{"key":"B","text":"Tăng cường quyền lực cho các tổ chức kinh tế tư nhân để thúc đẩy phát triển đất nước"},{"key":"C","text":"Tập trung phát triển kinh tế theo hướng đa ngành, đa lĩnh vực, không phụ thuộc vào sự lãnh đạo của Đảng"},{"key":"D","text":"Giảm thiểu vai trò của khối đại đoàn kết dân tộc để ưu tiên phát triển khu vực tư nhân"}]},{"n":164,"sec":"3. Điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội","stem":"Theo Hồ Chí Minh, vì sao phải củng cố và tăng cường khối đại đoàn kết dân tộc?","answer":"B","options":[{"key":"A","text":"Vì đại đoàn kết dân tộc giúp tập trung vốn đầu tư nước ngoài"},{"key":"B","text":"Vì đại đoàn kết dân tộc là vấn đề chiến lược quyết định sự thành công của cách mạng"},{"key":"C","text":"Vì đại đoàn kết dân tộc giúp giảm thiểu sự tham nhũng trong bộ máy nhà nước"},{"key":"D","text":"Vì đại đoàn kết dân tộc là phương tiện để phát triển kinh tế thị trường"}]},{"n":165,"sec":"3. Điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội","stem":"Hồ Chí Minh nhấn mạnh vai trò của sự đoàn kết quốc tế vì?","answer":"A","options":[{"key":"A","text":"Đoàn kết quốc tế tạo sức mạnh to lớn cho cách mạng và góp phần bảo vệ hòa bình, độc lập và chủ nghĩa xã hội trên thế giới"},{"key":"B","text":"Đoàn kết quốc tế giúp Việt Nam áp dụng mô hình chủ nghĩa tư bản phát triển nhanh"},{"key":"C","text":"Đoàn kết quốc tế chủ yếu phục vụ lợi ích kinh tế của các nước phương Tây"},{"key":"D","text":"Đoàn kết quốc tế nhằm tăng cường ảnh hưởng của các tập đoàn đa quốc gia tại Việt Nam"}]},{"n":166,"sec":"3. Điều kiện để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội","stem":"Nếu không có vai trò lãnh đạo của Đảng Cộng sản, theo Hồ Chí Minh, điều gì sẽ xảy ra?","answer":"B","options":[{"key":"A","text":"Cách mạng sẽ phát triển theo hướng dân chủ đa nguyên và đa đảng"},{"key":"B","text":"Cách mạng sẽ không đi theo con đường cách mạng vô sản và độc lập dân tộc sẽ không giành được"},{"key":"C","text":"Cách mạng sẽ trở thành cuộc đấu tranh tư bản chủ nghĩa."},{"key":"D","text":"Cách mạng sẽ được thúc đẩy bởi các tổ chức phi chính phủ"}]},{"n":167,"sec":"1. Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã xác định","stem":"Theo Hồ Chí Minh, mục tiêu tiến tới chủ nghĩa xã hội và chủ nghĩa cộng sản là?","answer":"A","options":[{"key":"A","text":"Quá trình hợp quy luật, phù hợp với khát vọng của nhân dân Việt Nam"},{"key":"B","text":"Quá trình tự phát và không cần sự lãnh đạo của Đảng"},{"key":"C","text":"Sự lựa chọn của các lực lượng tư sản và phong kiến"},{"key":"D","text":"Một con đường ngắn hạn và không có tính lâu dài"}]},{"n":168,"sec":"1. Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã xác định","stem":"Đại hội đại biểu toàn quốc lần thứ VII của Đảng đã ban hành văn bản gì liên quan đến thời kỳ quá độ lên chủ nghĩa xã hội?","answer":"A","options":[{"key":"A","text":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội"},{"key":"B","text":"Văn kiện tuyên truyền cho chủ nghĩa tư bản"},{"key":"C","text":"Chính sách giảm thiểu vai trò của nhà nước trong kinh tế"},{"key":"D","text":"Kế hoạch phát triển kinh tế đa ngành, đa chủng loại"}]},{"n":169,"sec":"1. Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã xác định","stem":"Đại hội nào của Đảng đã ban hành Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội?","answer":"A","options":[{"key":"A","text":"Đại hội VII của Đảng Cộng sản Việt Nam"},{"key":"B","text":"Đại hội VIII của Đảng Cộng sản Việt Nam"},{"key":"C","text":"Đại hội IX với định hướng phát triển kinh tế thị trường định hướng tư bản"},{"key":"D","text":"Đại hội VI của Đảng, lần đầu thực hiện chính sách Đổi mới"}]},{"n":170,"sec":"1. Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã xác định","stem":"Theo Hồ Chí Minh, xây dựng chủ nghĩa xã hội sẽ?","answer":"A","options":[{"key":"A","text":"Tạo nền tảng vững chắc để bảo vệ nền độc lập dân tộc và làm đất nước phát triển mạnh mẽ"},{"key":"B","text":"Làm giảm quyền làm chủ của nhân dân và tăng áp bức"},{"key":"C","text":"Là con đường ngắn hạn không cần sự tham gia của quần chúng"},{"key":"D","text":"Là hình thức duy nhất của chủ nghĩa tư bản trên thế giới"}]},{"n":171,"sec":"1. Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã xác định","stem":"Theo Cương lĩnh xây dựng đất nước, bài học lớn đầu tiên được Đảng ta rút ra là gì?","answer":"C","options":[{"key":"A","text":"Kết hợp hài hoà giữa văn hoá truyền thống và hiện đại trong công cuộc đổi mới"},{"key":"B","text":"Đặt lợi ích cá nhân làm động lực phát triển xã hộ"},{"key":"C","text":"Nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội do Chủ tịch Hồ Chí Minh trao lại"},{"key":"D","text":"Phát triển xã hội dựa trên nền tảng quyền lực của các tập đoàn kinh tế"}]},{"n":172,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Phát huy sức mạnh dân chủ xã hội chủ nghĩa là gì?","answer":"A","options":[{"key":"A","text":"Là phát huy sức mạnh bản chất ưu việt của chế độ xã hội chủ nghĩa; bảo đảm tất cả quyền lực nhà nước thuộc về nhân dân, thực hiện dân chủ đầy đủ trên tất cả các lĩnh vực của đời sống"},{"key":"B","text":"Là thực hiện dân chủ theo phương châm “dân biết, dân bàn, dân làm, dân kiểm tra” nhưng không cần bảo đảm quyền lực nhà nước thuộc về nhân dân"},{"key":"C","text":"Là phát huy quyền lực nhà nước và hạn chế sự tham gia của nhân dân trong các quyết định quan trọng"},{"key":"D","text":"Là chỉ thực hiện dân chủ trong một số lĩnh vực của đời sống xã hội, không phải tất cả"}]},{"n":173,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Phát huy sức mạnh dân chủ xã hội chủ nghĩa không thể tách rời với việc nào dưới đây?","answer":"A","options":[{"key":"A","text":"Hoàn thiện hệ thống pháp luật, tôn trọng và bảo vệ quyền con người, quyền và nghĩa vụ công dân theo tinh thần của Hiến pháp hiện hành"},{"key":"B","text":"Tăng cường quyền lực của nhà nước mà không cần quan tâm đến quyền của công dân"},{"key":"C","text":"Hạn chế quyền làm chủ của nhân dân để đảm bảo ổn định chính trị"},{"key":"D","text":"Thực hiện dân chủ cực đoan và không cần xử lý các hành vi vi phạm quyền dân"}]},{"n":174,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Theo quan điểm của tư tưởng Hồ Chí Minh, phát huy sức mạnh dân chủ xã hội chủ nghĩa cần đi đôi với điều gì?","answer":"B","options":[{"key":"A","text":"Tăng quyền lực cho chính quyền mà không cần trách nhiệm của công dân"},{"key":"B","text":"Tăng cường pháp chế, đề cao trách nhiệm công dân và phê phán dân chủ cực đoan, dân chủ hình thức"},{"key":"C","text":"Để nhân dân tự quyết mà không cần quy định pháp luật cụ thể"},{"key":"D","text":"Thường xuyên thay đổi pháp luật theo ý muốn của nhà cầm quyền"}]},{"n":175,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Phương châm “dân biết, dân bàn, dân làm, dân kiểm tra” trong phát huy dân chủ xã hội chủ nghĩa có ý nghĩa gì?","answer":"C","options":[{"key":"A","text":"Là để chính quyền tự quyết định mọi việc mà không cần tham khảo ý kiến nhân dân"},{"key":"B","text":"Là chỉ để nhân dân biết nhưng không cần tham gia hoặc kiểm tra các quyết định"},{"key":"C","text":"Là để nhân dân biết, tham gia và kiểm soát tất cả các quyết định liên quan đến cuộc sống và lợi ích của họ"},{"key":"D","text":"Là phương châm dành cho các tổ chức quốc tế, không áp dụng cho nhân dân trong nước"}]},{"n":176,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Trong tư tưởng Hồ Chí Minh, dân chủ xã hội chủ nghĩa phải được thực hiện như thế nào?","answer":"A","options":[{"key":"A","text":"Đầy đủ, nghiêm túc trên tất cả các lĩnh vực của đời sống xã hội"},{"key":"B","text":"Hạn chế ở một vài lĩnh vực, tập trung vào các lĩnh vực kinh tế."},{"key":"C","text":"Chủ yếu thực hiện ở cấp trung ương, không quan tâm đến cấp địa phương"},{"key":"D","text":"Thực hiện một cách hình thức, không cần nhân dân tham gia thực chất"}]},{"n":177,"sec":"2. Phát huy sức mạnh dân chủ xã hội chủ nghĩa","stem":"Phát huy dân chủ xã hội chủ nghĩa là phát huy sức mạnh nào của chế độ xã hội chủ nghĩa?","answer":"D","options":[{"key":"A","text":"Quyền lực tập trung tuyệt đối của nhà nước"},{"key":"B","text":"Sự phân quyền rộng rãi cho các tổ chức nước ngoài"},{"key":"C","text":"Sức mạnh của các tập đoàn kinh tế tư nhân"},{"key":"D","text":"Bản chất ưu việt của chế độ xã hội chủ nghĩa"}]},{"n":178,"sec":"3. Củng cố, kiện toàn, phát huy sức mạnh và hiệu quả hoạt động của toàn","stem":"Đặc điểm cơ bản của hệ thống chính trị ở Việt Nam là gì?","answer":"C","options":[{"key":"A","text":"Đa nguyên chính trị, đa đảng đối lập nhằm đảm bảo quyền lực phân tán"},{"key":"B","text":"Tập trung vào yếu tố dân sự, phi nhà nước trong điều hành xã hội"},{"key":"C","text":"Tính nhất nguyên và thống nhất dưới sự lãnh đạo của Đảng Cộng sản Việt Nam"},{"key":"D","text":"Tính độc lập tuyệt đối giữa các cơ quan trong bộ máy chính trị – hành pháp – tư pháp"}]},{"n":179,"sec":"3. Củng cố, kiện toàn, phát huy sức mạnh và hiệu quả hoạt động của toàn","stem":"Mục tiêu cuối cùng của việc củng cố, kiện toàn và phát huy hiệu quả hệ thống chính trị là gì?","answer":"C","options":[{"key":"A","text":"Xây dựng chính quyền trung ương vững mạnh, không phụ thuộc vào địa phương"},{"key":"B","text":"Phát triển các cơ chế kiểm soát quyền lực theo mô hình tư bản chủ nghĩa"},{"key":"C","text":"Thực hiện đầy đủ dân chủ xã hội chủ nghĩa và phát huy quyền làm chủ của nhân dân"},{"key":"D","text":"Hoàn tất quá trình chuyển đổi cơ cấu tổ chức nhà nước theo mô hình phương Tây"}]},{"n":180,"sec":"3. Củng cố, kiện toàn, phát huy sức mạnh và hiệu quả hoạt động của toàn","stem":"Tính “nhất nguyên” trong hệ thống chính trị Việt Nam được hiểu là?","answer":"B","options":[{"key":"A","text":"Mọi quyền lực tập trung vào một cá nhân lãnh đạo tối cao trong Đảng"},{"key":"B","text":"Chỉ có một đảng duy nhất lãnh đạo, thống nhất về chính trị, tư tưởng, tổ chức"},{"key":"C","text":"Các tổ chức tự quản địa phương được tự do quyết định chính sách độc lập"},{"key":"D","text":"Mọi hoạt động của chính quyền đều dựa trên luật tục cổ truyền"}]},{"n":181,"sec":"4. Đấu tranh chống những biểu hiện suy thoái về tư tưởng chính trị, đạo","stem":"Theo nội dung tư tưởng Hồ Chí Minh và Nghị quyết của Đảng, việc đấu tranh chống suy thoái tư tưởng chính trị, đạo đức, lối sống hiện nay có ý nghĩa gì?","answer":"C","options":[{"key":"A","text":"Là biện pháp tạm thời nhằm ổn định nội bộ trong điều kiện khủng hoảng kinh tế"},{"key":"B","text":"Là điều kiện cần để nâng cao hiệu quả cải cách hành chính công"},{"key":"C","text":"Là nhiệm vụ cấp thiết, gắn liền với xây dựng Đảng, giữ vững chế độ xã hội chủ nghĩa"},{"key":"D","text":"Là chiến lược truyền thông để củng cố hình ảnh chính trị đối ngoại của Đảng"}]},{"n":182,"sec":"4. Đấu tranh chống những biểu hiện suy thoái về tư tưởng chính trị, đạo","stem":"Hồ Chí Minh không sử dụng trực tiếp các khái niệm “suy thoái”, “tự diễn biến”, “tự chuyển hóa”, nhưng Người đã?","answer":"D","options":[{"key":"A","text":"Đề xuất những giải pháp kỹ thuật nhằm cải thiện cơ chế kiểm tra nội bộ"},{"key":"B","text":"Xây dựng các công cụ xử lý vi phạm dựa trên luật pháp quốc tế hiện đại"},{"key":"C","text":"Phê phán việc thực hiện dân chủ quá mức trong tổ chức Đảng và chính quyền"},{"key":"D","text":"Đề cập đến nhiều “căn bệnh” là biểu hiện của những hiện tượng đó và cảnh báo tác hại nghiêm trọng"}]},{"n":183,"sec":"4. Đấu tranh chống những biểu hiện suy thoái về tư tưởng chính trị, đạo","stem":"Tại sao việc “tự diễn biến”, “tự chuyển hóa” lại đặc biệt nguy hiểm trong nội bộ Đảng?","answer":"C","options":[{"key":"A","text":"Vì có thể dẫn đến cạnh tranh không lành mạnh giữa các tổ chức đoàn thể"},{"key":"B","text":"Vì làm mất khả năng hợp tác quốc tế trong lĩnh vực quốc phòng – an ninh"},{"key":"C","text":"Vì phá hoại từ bên trong, làm suy yếu niềm tin của nhân dân và vai trò lãnh đạo của Đảng"},{"key":"D","text":"Vì ảnh hưởng trực tiếp đến chính sách hỗ trợ các doanh nghiệp trong nước"}]}]},{"id":"IV","title":"TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẢNG CỘNG SẢN VIỆT NAM VÀ NHÀ NƯỚC CỦA NHÂN DÂN, DO NHÂN DÂN, VÌ NHÂN DÂN","questions":[{"n":1,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Trong tác phẩm Đường cách mệnh (năm 1927), Hồ Chí Minh khẳng định: Cách mạng trước hết phải có “(_____), để trong thì vận động và tổ chức dân chúng, ngoài thì liên lạc với dân tộc bị áp bức và vô sản giai cấp ở mọi nơi. Đảng có vững, cách mệnh mới (_____), cũng như người cầm lái có vững thuyền mới chạy” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.2, tr.289)","answer":"C","options":[{"key":"A","text":"Giai cấp lãnh đạo / thắng lợi"},{"key":"B","text":"Lực lượng vũ trang / phát triển"},{"key":"C","text":"Đảng cách mệnh / thành công"},{"key":"D","text":"Chủ nghĩa xã hội / toàn thắng"}]},{"n":2,"sec":"","stem":"Khẳng định đảng cộng sản “như người cầm lái” cho con thuyền cách mạng là quan điểm nhất quán của Hồ Chí Minh về?","answer":"A","options":[{"key":"A","text":"Vai trò lãnh đạo của Đảng Cộng sản Việt Nam"},{"key":"B","text":"Vai trò của quân đội trong cách mạng"},{"key":"C","text":"Vai trò của giai cấp nông dân trong cách mạng"},{"key":"D","text":"Tầm quan trọng của việc xây dựng kinh tế sau cách mạng"}]},{"n":3,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, “Đảng muốn vững thì phải có chủ nghĩa (_____), trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy”","answer":"B","options":[{"key":"A","text":"Làm căn cứ"},{"key":"B","text":"Làm cốt"},{"key":"C","text":"Làm kim chỉ nam"},{"key":"D","text":"Làm nền tảng tư tưởng"}]},{"n":4,"sec":"","stem":"Theo Hồ Chí Minh, yếu tố nào là điều kiện tiên quyết để cách mạng thành công?","answer":"C","options":[{"key":"A","text":"Có sự ủng hộ của quần chúng nhân dân"},{"key":"B","text":"Có đường lối đấu tranh phù hợp với hoàn cảnh đất nước"},{"key":"C","text":"Có một đảng cách mạng vững mạnh lãnh đạo"},{"key":"D","text":"Có sự trợ giúp từ các nước xã hội chủ nghĩa"}]},{"n":5,"sec":"","stem":"Hình ảnh “người cầm lái” được Hồ Chí Minh dùng để ví với điều gì?","answer":"C","options":[{"key":"A","text":"Quần chúng nhân dân trong cách mạng"},{"key":"B","text":"Lãnh tụ cách mạng của dân tộc"},{"key":"C","text":"Đảng Cộng sản Việt Nam trong vai trò lãnh đạo"},{"key":"D","text":"Các chiến sĩ tiên phong trong đấu tranh"}]},{"n":6,"sec":"","stem":"Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam có vai trò như thế nào trong sự nghiệp cách mạng?","answer":"D","options":[{"key":"A","text":"Là một lực lượng hỗ trợ phong trào yêu nước"},{"key":"B","text":"Là tổ chức kết nối giữa các phong trào dân tộc"},{"key":"C","text":"Là một bộ phận trong hệ thống chính trị"},{"key":"D","text":"Là nhân tố quyết định sự thành công của cách mạng"}]},{"n":7,"sec":"","stem":"Học thuyết Mác - Lênin cho rằng, sự ra đời của Đảng cộng sản là sản phẩm của sự kết hợp giữa?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa xã hội khoa học với phong trào công nhân"},{"key":"B","text":"Phong trào công nhân và các tổ chức nông dân trong các nước thuộc địa"},{"key":"C","text":"Lực lượng dân tộc và các tổ chức công đoàn lao động"},{"key":"D","text":"Chủ nghĩa dân tộc và các phong trào cách mạng tư sản"}]},{"n":8,"sec":"","stem":"Đối với Việt Nam, Hồ Chí Minh nhận định sự ra đời của Đảng Cộng sản Việt Nam là kết quả của sự kết hợp giữa?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa xã hội khoa học và cách mạng vô sản"},{"key":"B","text":"Chủ nghĩa Mác – Lênin với phong trào công nhân và phong trào yêu nước"},{"key":"C","text":"Tư tưởng Lênin và phong trào dân chủ tư sản"},{"key":"D","text":"Phong trào yêu nước và lý luận chủ nghĩa dân tộc"}]},{"n":9,"sec":"","stem":"Yếu tố nào được Hồ Chí Minh bổ sung vào lý luận của Mác – Lênin khi nói về sự ra đời của Đảng Cộng sản Việt Nam?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa yêu nước của trí thức tiểu tư sản"},{"key":"B","text":"Vai trò lãnh đạo của cá nhân xuất sắc"},{"key":"C","text":"Phong trào yêu nước của dân tộc Việt Nam"},{"key":"D","text":"Chủ nghĩa dân tộc của các tầng lớp nhân dân"}]},{"n":10,"sec":"","stem":"So với học thuyết Mác – Lênin, Hồ Chí Minh đưa thêm yếu tố nào vào tổ hợp các yếu tố cho sự ra đời của Đảng Cộng sản Việt Nam?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa yêu nước của trí thức tiểu tư sản"},{"key":"B","text":"Vai trò lãnh đạo của cá nhân xuất sắc"},{"key":"C","text":"Phong trào yêu nước của dân tộc Việt Nam"},{"key":"D","text":"Chủ nghĩa dân tộc của các tầng lớp nhân dân"}]},{"n":11,"sec":"","stem":"Đảng Cộng sản Việt Nam do Hồ Chí Minh sáng lập và rèn luyện là một đảng chính trị tồn tại và phát triển theo những quan điểm của?","answer":"A","options":[{"key":"A","text":"V.I.Lênin về đảng kiểu mới của giai cấp vô sản"},{"key":"B","text":"Chủ nghĩa xã hội khoa học và kinh nghiệm cách mạng Nga"},{"key":"C","text":"Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh"},{"key":"D","text":"Tư tưởng Hồ Chí Minh và đường lối đổi mới"}]},{"n":12,"sec":"","stem":"Quan điểm “Đảng có vững, cách mệnh mới thành công” được Hồ Chí Minh viết trong tác phẩm nào?","answer":"B","options":[{"key":"A","text":"Bản án chế độ thực dân Pháp"},{"key":"B","text":"Đường cách mệnh"},{"key":"C","text":"Nhật ký trong tù"},{"key":"D","text":"Chính cương vắn tắt"}]},{"n":13,"sec":"","stem":"“Đảng có vững cách mệnh mới thành công, cũng như người cầm lái có vững thuyền mới chạy”. Câu nói trên được trích từ tác phẩm nào của Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Bản án chế độ thực dân Pháp"},{"key":"B","text":"Đường cách mệnh"},{"key":"C","text":"Nhật ký trong tù"},{"key":"D","text":"Chính cương vắn tắt"}]},{"n":14,"sec":"","stem":"Hồ Chí Minh khẳng định vai trò lãnh đạo của Đảng là một?","answer":"D","options":[{"key":"A","text":"Định hướng lý tưởng của thế hệ trẻ"},{"key":"B","text":"Điều kiện cần nhưng không đủ"},{"key":"C","text":"Sự lựa chọn của lịch sử"},{"key":"D","text":"Tất yếu khách quan của cách mạng"}]},{"n":15,"sec":"","stem":"Ai là người sáng lập và rèn luyện Đảng Cộng sản Việt Nam?","answer":"A","options":[{"key":"A","text":"Hồ Chí Minh"},{"key":"B","text":"V.I. Lênin"},{"key":"C","text":"Trần Phú"},{"key":"D","text":"Trường Chinh"}]},{"n":16,"sec":"","stem":"Điểm khác biệt trong quan điểm của Hồ Chí Minh về sự ra đời của Đảng so với Lênin là gì?","answer":"C","options":[{"key":"A","text":"Nhấn mạnh sự trợ giúp quốc tế"},{"key":"B","text":"Bỏ qua yếu tố phong trào công nhân"},{"key":"C","text":"Thêm yếu tố phong trào yêu nước vào lý luận"},{"key":"D","text":"Đề cao vai trò của giai cấp tư sản dân tộc"}]},{"n":17,"sec":"","stem":"Đảng Cộng sản Việt Nam ra đời vào thời gian nào?","answer":"B","options":[{"key":"A","text":"05/6/1911"},{"key":"B","text":"03/2/1930"},{"key":"C","text":"19/5/1941"},{"key":"D","text":"21/7/1954"}]},{"n":18,"sec":"","stem":"Theo tư tưởng Hồ Chí Minh, luận điểm: Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước là?","answer":"C","options":[{"key":"A","text":"Xác định nhiệm vụ của Đảng"},{"key":"B","text":"Xác định bản chất của Đảng"},{"key":"C","text":"Xác định nguồn gốc ra đời của Đảng"},{"key":"D","text":"Xác định năng lực của Đảng"}]},{"n":19,"sec":"","stem":"Theo tư tưởng Hồ Chí Minh, luận điểm: Đảng Cộng sản Việt Nam là nhân tố quyết định hàng đầu để đưa cách mạng Việt Nam đi đến thắng lợi là?","answer":"B","options":[{"key":"A","text":"Xác định vị thế cầm quyền của Đảng"},{"key":"B","text":"Xác định vai trò lãnh đạo của Đảng"},{"key":"C","text":"Xác định bản chất của Đảng"},{"key":"D","text":"Xác định năng lực của Đảng"}]},{"n":20,"sec":"","stem":"Theo Hồ Chí Minh, Đảng cộng sản Việt Nam là Đảng của giai cấp nào?","answer":"C","options":[{"key":"A","text":"Giai cấp công nhân"},{"key":"B","text":"Nhân dân lao động"},{"key":"C","text":"Giai cấp công nhân, nhân dân lao động và của dân tộc Việt Nam"},{"key":"D","text":"Đội ngũ trí thức"}]},{"n":21,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Trong bài nói tại Lễ Kỷ niệm 30 năm Ngày thành lập Đảng (năm 1960), Hồ Chí Minh cho rằng: “Đảng ta là (_____), là (_____)”","answer":"B","options":[{"key":"A","text":"Chính nghĩa, dân chủ"},{"key":"B","text":"Đạo đức, văn minh"},{"key":"C","text":"Trung thành, gương mẫu"},{"key":"D","text":"Kiên cường, cách mạng"}]},{"n":22,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, mục đích hoạt động của Đảng là gì?","answer":"C","options":[{"key":"A","text":"Xây dựng nhà nước pháp quyền xã hội chủ nghĩa hiện đại"},{"key":"B","text":"Mở rộng ảnh hưởng của Đảng trong khu vực và quốc tế"},{"key":"C","text":"Lãnh đạo đấu tranh giải phóng dân tộc, giải phóng xã hội, giải phóng giai cấp, giải phóng con người"},{"key":"D","text":"Quản lý toàn diện đời sống chính trị, kinh tế, xã hội của đất nước"}]},{"n":23,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh nhấn mạnh phẩm chất nào sau đây là bắt buộc đối với cán bộ, đảng viên?","answer":"B","options":[{"key":"A","text":"Có lý luận chính trị vững chắc và kinh nghiệm công tác lâu năm"},{"key":"B","text":"Trung với Đảng, trung với nước, hiếu với dân"},{"key":"C","text":"Có trình độ chuyên môn cao và kỹ năng lãnh đạo"},{"key":"D","text":"Tự do sáng tạo trong công tác và sinh hoạt cá nhân"}]},{"n":24,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Đạo đức cách mạng được Hồ Chí Minh ví như gì?","answer":"C","options":[{"key":"A","text":"Truyền thống dân tộc lâu đời"},{"key":"B","text":"Kim chỉ nam trong học tập và làm việc"},{"key":"C","text":"Là gốc, là nền tảng của người cách mạng"},{"key":"D","text":"Biểu hiện của chủ nghĩa nhân đạo cộng sản"}]},{"n":25,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Một trong những biểu hiện của đạo đức cách mạng là gì?","answer":"D","options":[{"key":"A","text":"Hoàn thành chỉ tiêu công tác do cấp trên giao"},{"key":"B","text":"Trung thành tuyệt đối với lãnh đạo trực tiếp"},{"key":"C","text":"Nắm vững nghị quyết và vận dụng linh hoạt"},{"key":"D","text":"Cần, Kiệm, Liêm, Chính và luôn chí công vô tư"}]},{"n":26,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, Đảng văn minh phải là tổ chức như thế nào?","answer":"C","options":[{"key":"A","text":"Là trung tâm đoàn kết của toàn dân tộc"},{"key":"B","text":"Có quy mô tổ chức mạnh, bao phủ toàn xã hội"},{"key":"C","text":"Tiêu biểu cho lương tâm, trí tuệ và danh dự của dân tộc"},{"key":"D","text":"Có quyền kiểm soát toàn bộ đời sống chính trị đất nước"}]},{"n":27,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, đội ngũ đảng viên cần phải có?","answer":"B","options":[{"key":"A","text":"Ý thức tự giác chấp hành luật pháp và điều lệ Đảng"},{"key":"B","text":"Lòng nhân ái, tình đồng chí thương yêu lẫn nhau"},{"key":"C","text":"Tinh thần đấu tranh chính trị mạnh mẽ và tri thức chuyên môn sâu"},{"key":"D","text":"Năng lực lãnh đạo và quản lý trong mọi lĩnh vực"}]},{"n":28,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh ví người đảng viên phải có phẩm chất nào sau đây?","answer":"A","options":[{"key":"A","text":"Giàu sang không quyến rũ, nghèo khó không lay chuyển"},{"key":"B","text":"Kiên định, khéo léo, bản lĩnh"},{"key":"C","text":"Quyết đoán, trung thành, năng động"},{"key":"D","text":"Trí tuệ, sáng tạo, nhiệt tình"}]},{"n":29,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, nếu Đảng không giữ đạo đức, không văn minh thì hậu quả là gì?","answer":"C","options":[{"key":"A","text":"Suy giảm lòng tin của cán bộ, đảng viên"},{"key":"B","text":"Khó hoàn thành nhiệm vụ chính trị"},{"key":"C","text":"Mất vai trò lãnh đạo cách mạng"},{"key":"D","text":"Giảm uy tín đối với các tổ chức quốc tế"}]},{"n":30,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Một đặc điểm của Đảng văn minh trong tư tưởng Hồ Chí Minh là?","answer":"D","options":[{"key":"A","text":"Hoạt động như một lực lượng quân sự - chính trị nòng cốt"},{"key":"B","text":"Thực hiện quyền lãnh đạo tuyệt đối với mọi tổ chức xã hội"},{"key":"C","text":"Đại diện cho tầng lớp ưu tú, có học vấn và tư tưởng tiến bộ"},{"key":"D","text":"Đảng ra đời là một tất yếu, phù hợp với quy luật phát triển văn minh tiến bộ của dân tộc và của nhân loại"}]},{"n":31,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Câu nói: “Đảng ta là đạo đức, là văn minh” được Hồ Chí Minh phát biểu khi nào?","answer":"C","options":[{"key":"A","text":"Lễ kỷ niệm thành lập nước Việt Nam Dân chủ Cộng hòa"},{"key":"B","text":"Đại hội lần thứ II của Đảng"},{"key":"C","text":"Lễ kỷ niệm 30 năm ngày thành lập Đảng (1960)"},{"key":"D","text":"Hội nghị chính trị toàn quốc của Đảng năm 1951"}]},{"n":32,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong thời kỳ Đảng cầm quyền, Hồ Chí Minh đặc biệt quan tâm đến vấn đề gì?","answer":"B","options":[{"key":"A","text":"Thực hiện đường lối đổi mới kinh tế"},{"key":"B","text":"Phòng và chống các tiêu cực trong Đảng"},{"key":"C","text":"Xây dựng nền quốc phòng toàn dân"},{"key":"D","text":"Phát triển quan hệ đối ngoại"}]},{"n":33,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Đảng văn minh trong tư tưởng Hồ Chí Minh là Đảng hoạt động như thế nào?","answer":"C","options":[{"key":"A","text":"Có sự giám sát của Quốc hội và nhân dân"},{"key":"B","text":"Với sự tham gia của toàn bộ trí thức tinh hoa"},{"key":"C","text":"Trong khuôn khổ Hiến pháp và pháp luật"},{"key":"D","text":"Độc lập với hệ thống hành pháp và tư pháp"}]},{"n":34,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, đảng viên phải là?","answer":"A","options":[{"key":"A","text":"Là những chiến sĩ tiên phong, gương mẫu trong công tác và cuộc sống hằng ngày"},{"key":"B","text":"Người có năng lực công tác và có ảnh hưởng xã hội lớn"},{"key":"C","text":"Người trung thực, thẳng thắn và có tư duy cải cách"},{"key":"D","text":"Người có trình độ chuyên môn và kinh nghiệm thực tiễn cao"}]},{"n":35,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Một trong những nội dung Hồ Chí Minh đặc biệt nhấn mạnh khi xây dựng Đảng là?","answer":"B","options":[{"key":"A","text":"Tăng cường vai trò kiểm tra của các tổ chức Đảng"},{"key":"B","text":"Làm trong sạch đội ngũ, xây dựng Đảng trong sạch, vững mạnh"},{"key":"C","text":"Mở rộng ảnh hưởng của Đảng ra khu vực"},{"key":"D","text":"Đào tạo đội ngũ kế cận có trình độ chuyên môn cao"}]},{"n":36,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh nhấn mạnh: “Mỗi đảng viên và cán bộ phải thật sự thấm nhuần (_____), thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là (_____), là (_____) thật trung thành của nhân dân” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.15, tr.611-612)","answer":"B","options":[{"key":"A","text":"Tư tưởng chính trị; người đại diện; chiến sĩ"},{"key":"B","text":"Đạo đức cách mạng; người lãnh đạo; người đầy tớ"},{"key":"C","text":"Tư duy cách mạng; người phụng sự; người cộng sản"},{"key":"D","text":"Phẩm chất đạo đức; công bộc; cán bộ"}]},{"n":37,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? “Một dân tộc, một đảng và mỗi con người, ngày hôm qua là vĩ đại, có sức hấp dẫn lớn, không nhất định hôm nay và ngày mai vẫn được mọi người yêu mến và ca ngợi, nếu lòng dạ không trong sáng nữa, nếu sa vào (_____)”","answer":"C","options":[{"key":"A","text":"Chủ nghĩa hình thức"},{"key":"B","text":"Chủ nghĩa kinh nghiệm"},{"key":"C","text":"Chủ nghĩa cá nhân"},{"key":"D","text":"Chủ nghĩa xét lại"}]},{"n":38,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng là?","answer":"D","options":[{"key":"A","text":"Tư tưởng Hồ Chí Minh"},{"key":"B","text":"Chủ nghĩa xã hội hiện đại"},{"key":"C","text":"Tư tưởng dân tộc và cách mạng"},{"key":"D","text":"Chủ nghĩa Mác – Lênin"}]},{"n":39,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong tác phẩm Đường cách mệnh (1927), Hồ Chí Minh nhấn mạnh vai trò của chủ nghĩa nào đối với sự vững mạnh của Đảng?","answer":"D","options":[{"key":"A","text":"Chủ nghĩa dân chủ xã hội phương Tây"},{"key":"B","text":"Chủ nghĩa dân tộc yêu nước"},{"key":"C","text":"Chủ nghĩa xã hội khoa học"},{"key":"D","text":"Chủ nghĩa Lênin"}]},{"n":40,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Trong tác phẩm Đường cách mệnh (năm 1927), Hồ Chí Minh khẳng định: “Đảng muốn vững thì phải có chủ nghĩa làm cốt, trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy. Đảng mà không có chủ nghĩa cũng như người không có trí khôn, tàu không có bàn chỉ nam. Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mệnh nhất là (_____)” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.2, tr.289)","answer":"D","options":[{"key":"A","text":"Chủ nghĩa dân chủ xã hội phương Tây"},{"key":"B","text":"Chủ nghĩa dân tộc yêu nước"},{"key":"C","text":"Chủ nghĩa xã hội khoa học"},{"key":"D","text":"Chủ nghĩa Lênin"}]},{"n":41,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? “Đảng mà không có chủ nghĩa cũng như người không có (_____), tàu không có (_____)”?","answer":"B","options":[{"key":"A","text":"Lương tâm và trí tuệ"},{"key":"B","text":"Trí khôn, bàn chỉ nam"},{"key":"C","text":"Hướng đi và hành động"},{"key":"D","text":"Mục tiêu và phương pháp"}]},{"n":42,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, việc học và vận dụng chủ nghĩa Mác – Lênin phải được thực hiện như thế nào?","answer":"C","options":[{"key":"A","text":"Phải trung thành tuyệt đối và không thay đổi dù hoàn cảnh nào"},{"key":"B","text":"Luôn tiếp thu nguyên vẹn các quan điểm, tránh làm sai lệch"},{"key":"C","text":"Trung thành nhưng sáng tạo, phù hợp với điều kiện từng nơi, từng lúc, không được phép giáo điều"},{"key":"D","text":"Gắn liền với chủ nghĩa yêu nước truyền thống mà không cần sáng tạo"}]},{"n":43,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, một trong những nguyên tắc tổ chức và sinh hoạt Đảng cơ bản là gì?","answer":"D","options":[{"key":"A","text":"Thiểu số phục tùng đa số"},{"key":"B","text":"Biểu quyết hoặc bỏ phiếu kín"},{"key":"C","text":"Cấp dưới phục tùng cấp trên"},{"key":"D","text":"Tập trung dân chủ"}]},{"n":44,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Đâu KHÔNG PHẢI là một trong những nguyên tắc tổ chức và sinh hoạt Đảng?","answer":"D","options":[{"key":"A","text":"Tập trung dân chủ"},{"key":"B","text":"Tự phê bình và phê bình"},{"key":"C","text":"Đảng phải thường xuyên đổi mới"},{"key":"D","text":"Phê phán đa nguyên chính trị"}]},{"n":45,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Luận đề “tập trung trên nền tảng dân chủ, dân chủ phải đi đến tập trung” phản ánh nguyên tắc nào của Đảng?","answer":"A","options":[{"key":"A","text":"Tập trung dân chủ"},{"key":"B","text":"Tập trung lãnh đạo"},{"key":"C","text":"Dân chủ hóa nội bộ"},{"key":"D","text":"Lãnh đạo tập trung"}]},{"n":46,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, hàm lượng dân chủ càn g cao thì điều gì càng đúng đắn?","answer":"C","options":[{"key":"A","text":"Sự phát triển tư tưởng trong Đảng"},{"key":"B","text":"Vai trò của quần chúng nhân dân"},{"key":"C","text":"Sự tập trung trong Đảng"},{"key":"D","text":"Quyền lãnh đạo cá nhân"}]},{"n":47,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh cho rằng quyền tự do của đảng viên trở thành gì sau khi đã thảo luận dân chủ?","answer":"B","options":[{"key":"A","text":"Quyền đồng thuận tập thể"},{"key":"B","text":"Quyền phục tùng chân lý"},{"key":"C","text":"Quyền chỉ đạo lãnh đạo"},{"key":"D","text":"Quyền tự do hành động cá nhân"}]},{"n":48,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điều kiện tiên quyết để thực hiện nguyên tắc tập trung dân chủ là?","answer":"A","options":[{"key":"A","text":"Tổ chức Đảng phải trong sạch, vững mạnh"},{"key":"B","text":"Ban lãnh đạo có quyền lực mạnh"},{"key":"C","text":"Cơ chế phản biện được mở rộng"},{"key":"D","text":"Tôn trọng các ý kiến bên ngoài"}]},{"n":49,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh coi “tập thể lãnh đạo” là biểu hiện của điều gì?","answer":"C","options":[{"key":"A","text":"Sự phối hợp chặt chẽ giữa các cơ quan"},{"key":"B","text":"Quyết định cuối cùng thuộc về đa số"},{"key":"C","text":"Tính dân chủ trong lãnh đạo"},{"key":"D","text":"Quyền lực được phân chia đều"}]},{"n":50,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong tư tưởng Hồ Chí Minh, “cá nhân phụ trách” là biểu hiện của?","answer":"B","options":[{"key":"A","text":"Quyền lực của cấp trên"},{"key":"B","text":"Tính tập trung trong lãnh đạo"},{"key":"C","text":"Trách nhiệm của người đứng đầu"},{"key":"D","text":"Sự tuân thủ nguyên tắc dân chủ"}]},{"n":51,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hai điều Hồ Chí Minh yêu cầu tránh trong hoạt động Đảng là?","answer":"A","options":[{"key":"A","text":"Độc đoán, chuyên quyền, coi thường tập thể; Dựa d ẫm tập thể, không dám quyết đoán"},{"key":"B","text":"Thiếu trách nhiệm và vô kỷ luật"},{"key":"C","text":"Giáo điều và thiếu sáng tạo"},{"key":"D","text":"Tham nhũng và bè phái"}]},{"n":52,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Cặp phạm trù “tập thể lãnh đạo, cá nhân phụ trách” theo Hồ Chí Minh có mối quan hệ như thế nào?","answer":"D","options":[{"key":"A","text":"Song song nhưng không phụ thuộc"},{"key":"B","text":"Cá nhân quyết định thay tập thể"},{"key":"C","text":"Tập thể hỗ trợ, cá nhân quyết định"},{"key":"D","text":"Luôn đi đôi, hỗ trợ lẫn nhau"}]},{"n":53,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, tự phê bình và phê bình trong Đảng cần được thực hiện như thế nào?","answer":"C","options":[{"key":"A","text":"Thỉnh thoảng, khi cần thiết và có chỉ đạo từ cấp trên"},{"key":"B","text":"Theo định kỳ 6 tháng hoặc 1 năm một lần, theo quy định của tổ chức"},{"key":"C","text":"Thường xuyên và nghiêm chỉnh như “mỗi ngày phải rửa mặt”"},{"key":"D","text":"Chỉ khi có mâu thuẫn nội bộ mới tiến hành để giải quyết dứt điểm"}]},{"n":54,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh ví tự phê bình và phê bình như “thang thu ốc” nhằm mục đích gì?","answer":"B","options":[{"key":"A","text":"Loại bỏ toàn bộ cái xấu trong con người và tổ chức một cách tuyệt đối"},{"key":"B","text":"Làm cho phần tốt trong mỗi tổ chức và mỗi con người nẩy nở như hoa mùa xuân và phần xấu bị mất dần đi"},{"key":"C","text":"Để xử lý kỷ luật những cán bộ, đảng viên sai phạm"},{"key":"D","text":"Giúp các cá nhân hoàn toàn thay đổi tư duy trong thời gian ngắn"}]},{"n":55,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong Di chúc, Hồ Chí Minh nhấn mạnh tự phê bình và phê bình là?","answer":"C","options":[{"key":"A","text":"Một công cụ để giám sát nội bộ và thi hành kỷ luật hiệu quả"},{"key":"B","text":"Hình thức trao đổi nội bộ giữa các cán bộ cấp cao"},{"key":"C","text":"Cách tốt nhất để củng cố sự đoàn kết và thống nhất trong Đảng"},{"key":"D","text":"Cách thức để biểu hiện lòng trung thành với Đảng"}]},{"n":56,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Tự phê bình và phê bình, theo Hồ Chí Minh, cần gắn với tinh thần gì trong Đảng?","answer":"D","options":[{"key":"A","text":"Phê bình phải gay gắt, không nhân nhượng với sai lầm"},{"key":"B","text":"Trung thực và mạnh dạn chỉ ra mọi điểm yếu của đồng chí"},{"key":"C","text":"Cần giữ bí mật, không công khai gây mất đoàn kết"},{"key":"D","text":"Phải có tình đồng chí thương yêu lẫn nhau"}]},{"n":57,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, khi tiến hành phê bình, cần phải đảm bảo yếu tố nào sau đây?","answer":"A","options":[{"key":"A","text":"Trung thực, kiên quyết, đúng người, đúng việc, có văn hóa"},{"key":"B","text":"Dựa trên quy trình kiểm điểm định kỳ đã được ban hành"},{"key":"C","text":"Có sự giám sát của cấp ủy cấp trên để đảm bảo tính khách quan"},{"key":"D","text":"Luôn đưa ra nhận xét chung, không nên đi sâu vào chi tiết cá nhân"}]},{"n":58,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh cho rằng tự phê bình và phê bình là \"thang thuốc\" tốt nhất vì?","answer":"C","options":[{"key":"A","text":"Nó giúp mỗi cán bộ nâng cao trình độ chuyên môn, nghiệp vụ"},{"key":"B","text":"Giúp cán bộ tự soi rọi để thay đổi tư duy trong mọi lĩnh vực"},{"key":"C","text":"Làm cho phần tốt trong mỗi tổ chức và con người nảy nở như hoa mùa xuân"},{"key":"D","text":"Là giải pháp thay thế cho các quy định về xử lý kỷ luật trong Đảng"}]},{"n":59,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Tại sao Hồ Chí Minh cho rằng tự phê bình và phê bình là cần thiết?","answer":"B","options":[{"key":"A","text":"Vì đó là phương pháp giáo dục chính trị sâu sắc và hiệu quả"},{"key":"B","text":"Vì đó là cách tốt nhất để làm cho phần tốt phát triển và phần xấu bị mất dần đi"},{"key":"C","text":"Vì đó là phương pháp giám sát nội bộ hiệu quả và tiết kiệm chi phí"},{"key":"D","text":"Vì đó là cách để cấp trên hiểu được cấp dưới có sai phạm hay không"}]},{"n":60,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh khẳng định điều gì là cơ sở tạo nên sức mạnh của Đảng Cộng sản?","answer":"C","options":[{"key":"A","text":"Cán bộ cấp cao có quyền lực và quyết đoán trong hành động"},{"key":"B","text":"Bộ máy tổ chức gọn nhẹ, linh hoạt trong chỉ đạo thực tiễn"},{"key":"C","text":"Kỷ luật nghiêm minh, muôn người như một, cùng một ý chí và hành động"},{"key":"D","text":"Sự giám sát chặt chẽ từ quần chúng nhân dân đối với Đảng"}]},{"n":61,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, kỷ luật của Đảng phải như thế nào?","answer":"D","options":[{"key":"A","text":"Cần mềm dẻo và linh hoạt để phù hợp với từng địa phương"},{"key":"B","text":"Do các tổ chức cấp trên ban hành và điều chỉnh theo tình huống"},{"key":"C","text":"Dựa trên các điều lệ và nội quy hành chính của Nhà nước"},{"key":"D","text":"Phải rất nghiêm từ trên xuống dưới, tư tưởng và hành động đều phải nhất trí"}]},{"n":62,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Câu nói “Không có kỷ luật sắt, không có Đảng” của Hồ Chí Minh thể hiện điều gì?","answer":"A","options":[{"key":"A","text":"Kỷ luật là yếu tố sống còn đối với sự tồn tại và phát triển của Đảng"},{"key":"B","text":"Kỷ luật chỉ cần thiết trong điều kiện cách mạng vũ trang khốc liệt"},{"key":"C","text":"Kỷ luật của Đảng chủ yếu phục vụ việc giữ gìn hình ảnh chính trị"},{"key":"D","text":"Kỷ luật trong Đảng không nhất thiết phải cứng nhắc và bắt buộc"}]},{"n":63,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, điều gì làm cho kỷ luật của Đảng trở nên bền lâu?","answer":"C","options":[{"key":"A","text":"Các hình thức kiểm tra, giám sát chặt chẽ từ cấp trê"},{"key":"B","text":"Quy định rõ ràng các mức xử lý trong từng loại sai phạm"},{"key":"C","text":"Lòng tự giác của đảng viên về nhiệm vụ của họ đối với Đảng"},{"key":"D","text":"Sự răn đe từ các vụ việc điển hình bị xử lý kỷ luật nghiêm khắc"}]},{"n":64,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh cho rằng đảng viên khi đã vào Đảng thì phải?","answer":"D","options":[{"key":"A","text":"Tự do thể hiện chính kiến nhưng vẫn tuân thủ pháp luật"},{"key":"B","text":"Làm theo điều lệ Đảng nhưng có thể góp ý trái chiều nếu cần"},{"key":"C","text":"Được quyền chọn lọc các chỉ thị phù hợp với điều kiện thực tiễn để thực hiện"},{"key":"D","text":"Theo tư tưởng của Đảng và thực hiện nghiêm nghị quyết, chỉ thị của Đảng"}]},{"n":65,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, một trong những biểu hiện cụ thể của kỷ luật Đảng là?","answer":"B","options":[{"key":"A","text":"Tôn trọng đa dạng tư tưởng để tạo nên sức mạnh tổng hợp"},{"key":"B","text":"Tư tưởng phải nhất trí, hành động phải nhất trí"},{"key":"C","text":"Mỗi người có thể linh hoạt áp dụng nghị quyết theo cách riêng"},{"key":"D","text":"Cấp dưới có thể phản biện nếu thấy cấp trên chưa hợp lý"}]},{"n":66,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Khi nói “Không làm thì đu ổi ra khỏi Đảng”, Hồ Chí Minh muốn nhấn mạnh điều gì?","answer":"D","options":[{"key":"A","text":"Tính dân chủ trong Đảng cho phép kỷ luật nghiêm minh hơn các tổ chức khác"},{"key":"B","text":"Mọi đảng viên đều có quyền từ chối nhiệm vụ nếu thấy không phù hợp"},{"key":"C","text":"Đảng viên cần được đào tạo kỹ lưỡng trước khi giao nhiệm vụ quan trọng"},{"key":"D","text":"Đảng viên phải chấp hành tuyệt đối nghị quyết, nếu không thì bị khai trừ"}]},{"n":67,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, điều kiện để được kết nạp vào Đảng là?","answer":"A","options":[{"key":"A","text":"Là những phần tử hăng hái nhất, cách mạng nhất"},{"key":"B","text":"Có thời gian sinh hoạt tại địa phương ít nhất 5 năm"},{"key":"C","text":"Có bằng cấp, kinh nghiệm làm việc và đóng góp xã hội"},{"key":"D","text":"Là cán bộ Nhà nước hoặc công chức trong hệ thống chính trị"}]},{"n":68,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, vì sao Đảng Cộng sản Việt Nam cần phải thường xuyên tự chỉnh đốn?","answer":"C","options":[{"key":"A","text":"Vì Đảng là một tổ chức lãnh đạo nên có quyền lực tuyệt đối trong xã hội"},{"key":"B","text":"Vì Đảng là công cụ để các đảng viên nâng cao địa vị xã hội"},{"key":"C","text":"Vì quyền lực của Đảng là do giai cấp công nhân, nhân dân lao động và toàn dân tộc giao phó do nhân dân trao, Đảng không có mục đích tự thân, Đảng không phải là tổ chức để làm quan phát tài"},{"key":"D","text":"Vì Đảng có quyền ra quyết định cuối cùng nên không cần bị giám sát"}]},{"n":69,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, sau khi cuộc kháng chiến chống Mỹ kết thúc thắng lợi, việc cần làm trước tiên là gì?","answer":"B","options":[{"key":"A","text":"Tổ chức lễ kỷ niệm chiến thắng trên toàn quốc"},{"key":"B","text":"Chỉnh đốn lại Đảng, làm cho mỗi đảng viên, mỗi đoàn viên, mỗi chi bộ đều ra sức làm tròn nhiệm vụ đảng giao phó cho mình"},{"key":"C","text":"Tổ chức lại bộ máy nhà nước theo mô hình kinh tế thị trường"},{"key":"D","text":"Chuẩn bị kế hoạch hội nhập quốc tế và ký kết hiệp ước thương mại"}]},{"n":70,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Nội dung Điều số 9 trong 12 điều Hồ Chí Minh nêu ra trong Sửa đổi lối làm việc là?","answer":"B","options":[{"key":"A","text":"Đảng phải thường xuyên đổi mới phương thức lãnh đạo để tránh lỗi thời"},{"key":"B","text":"Đảng phải chọn lựa những người rất trung thành và rất hăng hái, đoàn kết họ thành nhóm trung kiên lãnh đạo"},{"key":"C","text":"Đảng phải giữ vững lập trường để đấu tranh chống các thế lực thù địch"},{"key":"D","text":"Đảng cần kết nạp tất cả những ai có lòng yêu nước dù không theo chủ nghĩa Mác – Lênin"}]},{"n":71,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Nội dung Điều số 10 trong 12 điều Hồ Chí Minh nêu ra trong Sửa đổi lối làm việc là?","answer":"C","options":[{"key":"A","text":"Giữ lại để giáo dục nội bộ, tránh gây mất đoàn kết"},{"key":"B","text":"Đảng phải chọn lựa những người rất trung thành và rất hăng hái, đoàn kết họ thành nhóm trung kiên lãnh đạo"},{"key":"C","text":"Đảng phải luôn luôn tẩy bỏ những phần tử hủ hóa ra ngoài"},{"key":"D","text":"Đưa sang làm công tác khác để tự kiểm điểm"}]},{"n":72,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Thường xuyên tự chỉnh đốn trở thành một nhiệm vụ cực kỳ (_____) trong xây dựng Đảng.","answer":"A","options":[{"key":"A","text":"Quan trọng"},{"key":"B","text":"Phổ biến"},{"key":"C","text":"Đơn giản"},{"key":"D","text":"Cấp bách"}]},{"n":73,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh nhấn mạnh rằng nếu Đảng làm tốt việc chỉnh đốn và xây dựng Đảng thì điều gì sẽ đạt được?","answer":"C","options":[{"key":"A","text":"Đảng có thể đứng vững trước mọi thế lực bên ngoài"},{"key":"B","text":"Nhân dân sẽ tuyệt đối phục tùng mệnh lệnh của Đảng"},{"key":"C","text":"Mọi công việc dù to lớn, khó khăn mấy cũng nhất định thắng lợi"},{"key":"D","text":"Đảng sẽ không cần đến các hình thức kiểm tra, giám sát nữa"}]},{"n":74,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong Sửa đổi lối làm việc, Hồ Chí Minh yêu cầu lựa chọn cán bộ theo tiêu chí nào?","answer":"D","options":[{"key":"A","text":"Những người có trình độ học vấn cao và ngoại ngữ tốt"},{"key":"B","text":"Những người có kinh nghiệm chiến đấu lâu năm"},{"key":"C","text":"Những người có quan hệ rộng và được nhiều người biết đến"},{"key":"D","text":"Những người rất trung thành và rất hăng hái"}]},{"n":75,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, yếu tố nào quyết định sự vững mạnh của Đảng về số lượng và chất lượng?","answer":"A","options":[{"key":"A","text":"Tuyển chọn cán bộ trung thành, tẩy bỏ phần tử hủ hóa"},{"key":"B","text":"Tăng cường hoạt động tuyên truyền, quảng bá hình ảnh Đảng"},{"key":"C","text":"Thường xuyên tổ chức hội nghị, tổng kết hoạt động"},{"key":"D","text":"Phối hợp với các tổ chức xã hội dân sự trong quản lý đảng viên"}]},{"n":76,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, đoàn kết trong Đảng phải được xây dựng trên cơ sở nào?","answer":"C","options":[{"key":"A","text":"Truyền thống lịch sử lâu dài và tinh thần yêu nước của dân tộc"},{"key":"B","text":"Mối quan hệ mật thiết giữa các tổ chức cơ sở Đảng và chính quyền địa phương"},{"key":"C","text":"Chủ nghĩa Mác - Lênin, cương lĩnh, đường lối, quan điểm, nghị quyết của Đảng"},{"key":"D","text":"Lòng trung thành của đảng viên với tổ chức và cấp trên trong mọi hoàn cảnh"}]},{"n":77,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Trong Di chúc, Hồ Chí Minh ví việc giữ gìn sự đoàn kết nhất trí của Đảng như điều gì?","answer":"D","options":[{"key":"A","text":"Giữ gìn vàng ngọc quý báu nhất trong kho tàng của dân tộc"},{"key":"B","text":"Giữ gìn danh dự thiêng liêng của người đảng viên"},{"key":"C","text":"Giữ gìn lòng trung thành với lý tưởng cách mạng"},{"key":"D","text":"Giữ gìn con ngươi của mắt mình"}]},{"n":78,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, muốn xây dựng được khối đại đoàn kết toàn dân tộc thì trước hết cần thực hiện điều gì?","answer":"B","options":[{"key":"A","text":"Đổi mới nội dung tuyên truyền trong nhân dân"},{"key":"B","text":"Đoàn kết, thống nhất trong Đảng trước hết là trong cấp ủy, trong những cán bộ lãnh đạo chủ chốt"},{"key":"C","text":"Giữ gìn lòng trung thành với lý tưởng cách mạng"},{"key":"D","text":"Giữ gìn con ngươi của mắt mình"}]},{"n":79,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Vì sao theo Hồ Chí Minh, đoàn kết trong Đảng lại có ảnh hưởng quyết định đến khối đại đoàn kết toàn dân tộc?","answer":"A","options":[{"key":"A","text":"Vì Đảng là đội tiên phong dẫn dắt và lãnh đạo toàn dân tộc"},{"key":"B","text":"Vì Đảng là lực lượng đại diện duy nhất của giai cấp công nhân"},{"key":"C","text":"Vì Đảng là đội tiên phong dẫn dắt và lãnh đạo toàn dân tộc"},{"key":"D","text":"Vì Đảng có vai trò điều phối các tổ chức quần chúng nhân dân"}]},{"n":80,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, yếu tố nào sau đây là biểu hiện rõ nét nhất của sự đoàn kết trong Đảng?","answer":"C","options":[{"key":"A","text":"Tất cả đảng viên có chung sở thích, lối sống và thói quen"},{"key":"B","text":"Các cấp ủy Đảng đưa ra nghị quyết phải đạt 100% phiếu thuận"},{"key":"C","text":"Các đảng viên thực hiện đúng cương lĩnh, đường lối, nghị quyết của Đảng"},{"key":"D","text":"Đảng viên không phát biểu trái quan điểm cấp trên trong cuộc họp"}]},{"n":81,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Trong Di chúc, Hồ Chí Minh nhấn mạnh: “(_____) là một truyền thống cực kỳ quý báu của Đảng và của dân tộc ta. Các đồng chí từ Trung ương đến các chi bộ cần phải giữ gìn sự đoàn kết nhất trí của Đảng như giữ gìn con ngươi của mắt mình” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.15, tr.611)","answer":"A","options":[{"key":"A","text":"Đoàn kết"},{"key":"B","text":"Trung thực"},{"key":"C","text":"Kỷ luật"},{"key":"D","text":"Tự phê bình"}]},{"n":82,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam có quan hệ như thế nào với giai cấp công nhân và nhân dân lao động?","answer":"B","options":[{"key":"A","text":"Độc lập hoàn toàn để giữ vững tính cách mạng"},{"key":"B","text":"Là mối quan hệ khăng khít, máu thịt"},{"key":"C","text":"Là một tổ chức trung gian giữa nhà nước và nhân dân"},{"key":"D","text":"Là người lãnh đạo tối cao, không cần chịu trách nhiệm với dân"}]},{"n":83,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, câu nào sau đây KHÔNG phản ánh đúng vai trò của Đảng?","answer":"C","options":[{"key":"A","text":"Đảng là đội tiên phong của giai cấp công nhân và dân tộc"},{"key":"B","text":"Đảng phải học dân, làm dân tin, phục vụ dân"},{"key":"C","text":"Đảng chỉ phục vụ lợi ích của giai cấp công nhân, không cần quan tâm đến nhân dân"},{"key":"D","text":"Đảng là hiện thân của văn hóa dân tộc"}]},{"n":84,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, Đảng phải giữ chữ gì để dân tin và yêu mến Đảng?","answer":"D","options":[{"key":"A","text":"Chữ Đạo"},{"key":"B","text":"Chữ Lễ"},{"key":"C","text":"Chữ Quyền"},{"key":"D","text":"Chữ Tín"}]},{"n":85,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, biểu hiện của cán bộ, đảng viên xa rời quần chúng là gì?","answer":"C","options":[{"key":"A","text":"Hành động cứng nhắc theo nghị quyết"},{"key":"B","text":"Không lắng nghe ý kiến đóng góp từ Đảng"},{"key":"C","text":"“Vác mặt quan cách mạng”, xâm phạm quyền làm chủ của nhân dân"},{"key":"D","text":"Không tham gia sinh hoạt chính trị đầy đủ"}]},{"n":86,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Đảng Cộng sản Việt Nam \"không phải (_____) sa xuống. Nó ở trong (_____) mà ra\"","answer":"C","options":[{"key":"A","text":"Ngẫu nhiên – dân tộc"},{"key":"B","text":"Bỗng dưng – thực tế"},{"key":"C","text":"Trên trời – xã hội"},{"key":"D","text":"Đột ngột – đất nước"}]},{"n":87,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Trong một bài nói chuyện ngày 10-5-1950, Hồ Chí Minh nói: “Đảng không phải làm (_____), sai khiến quần chúng, mà phải làm (_____) cho quần chúng và phải làm cho ra trò, nếu không, quần chúng sẽ đá đít” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.6, tr.367)","answer":"B","options":[{"key":"A","text":"Người chỉ huy - người gánh vác"},{"key":"B","text":"Quan - đầy tớ"},{"key":"C","text":"Lãnh đạo - người thay thế"},{"key":"D","text":"Thầy - học trò"}]},{"n":88,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Đảng viên không được cứ ăn cỗ đi trước, lội nước đi sau; không phải cứ dán lên trán hai chữ (_____) là dân tin, dân yêu, dân kính, dân phục, mà phải trong công tác hằng ngày cố gắng học dân, làm cho dân tin.","answer":"D","options":[{"key":"A","text":"Trung thành"},{"key":"B","text":"Tiên phong"},{"key":"C","text":"Cách mạng"},{"key":"D","text":"Cộng sản"}]},{"n":89,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, đoàn kết quốc tế của Đảng Cộng sản Việt Nam cần thực hiện trên nền tảng nào?","answer":"C","options":[{"key":"A","text":"Chủ nghĩa dân tộc chân chính và tinh thần khai phóng"},{"key":"B","text":"Học thuyết tam dân và tinh thần nhân đạo"},{"key":"C","text":"Chủ nghĩa Mác - Lênin và chủ nghĩa quốc tế vô sản, có lý có tình"},{"key":"D","text":"Đường lối ngoại giao mềm dẻo và hòa hiếu giữa các dân tộc"}]},{"n":90,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, cách mạng Việt Nam có quan hệ như thế nào với cách mạng thế giới?","answer":"A","options":[{"key":"A","text":"Là một bộ phận khăng khít của cách mạng thế giới"},{"key":"B","text":"Là trung tâm chỉ đạo tư tưởng cho phong trào cách mạng toàn cầu"},{"key":"C","text":"Là hình mẫu duy nhất cho các nước thuộc địa học tập"},{"key":"D","text":"Là lực lượng độc lập, không liên quan đến các nước khác"}]},{"n":91,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Trong Di chúc, Người mong Đảng “sẽ ra sức hoạt động, góp phần đắc lực vào việc khôi phục lại khối đoàn kết giữa các đảng anh em trên nền tảng (_____) và chủ nghĩa (_____), có lý có tình” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.15, tr.613)","answer":"A","options":[{"key":"A","text":"Chủ nghĩa Mác – Lênin; quốc tế vô sản"},{"key":"B","text":"Chủ nghĩa tư bản; quốc tế cộng sản"},{"key":"C","text":"Chủ nghĩa dân tộc; quốc tế lao động"},{"key":"D","text":"Chủ nghĩa xã hội; quốc tế xã hội"}]},{"n":92,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, cán bộ, đảng viên phải tuyệt đối trung thành với ai?","answer":"B","options":[{"key":"A","text":"Tổ chức Đảng và các tổ chức quốc tế"},{"key":"B","text":"Với Đảng, suốt đời phấn đấu cho lợi ích của cách mạng, vì mục tiêu lý tưởng của Đảng"},{"key":"C","text":"Chính quyền địa phương và nhân dân"},{"key":"D","text":"Bản thân và gia đình mình"}]},{"n":93,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Yêu cầu nào sau đây KHÔNG thuộc phẩm chất cán bộ, đảng viên theo Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Tuân thủ cương lĩnh, nghị quyết của Đảng"},{"key":"B","text":"Luôn luôn học tập nâng cao trình độ"},{"key":"C","text":"Chỉ tập trung vào công việc của mình, không cần liên hệ dân"},{"key":"D","text":"Phải có mối liên hệ mật thiết với nhân dân"}]},{"n":94,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, cán bộ, đảng viên phải luôn luôn làm gì để giữ gìn đạo đức cách mạng?","answer":"B","options":[{"key":"A","text":"Chỉ làm việc khi được giao nhiệm vụ"},{"key":"B","text":"Tu dưỡng, rèn luyện và trau dồi đạo đức cách mạng"},{"key":"C","text":"Tập trung tranh thủ lợi ích cá nhân"},{"key":"D","text":"Học tập theo kiểu qua loa, hình thức"}]},{"n":95,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh coi các tiêu cực như tham ô, quan liêu, lãng phí là gì?","answer":"B","options":[{"key":"A","text":"Vấn đề cá nhân, không ảnh hưởng tới Đảng"},{"key":"B","text":"Giặc nội xâm, là những kẻ địch bên trong"},{"key":"C","text":"Chuyện bình thường trong công tác cán bộ"},{"key":"D","text":"Vấn đề của xã hội không liên quan đến cán bộ"}]},{"n":96,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, cán bộ, đảng viên cần có thái độ nào khi mắc sai lầm?","answer":"C","options":[{"key":"A","text":"Phủ nhận và che giấu"},{"key":"B","text":"Vui vẻ khoan dung với lỗi của mình"},{"key":"C","text":"Ra sức sửa chữa và không ngừng tiến bộ"},{"key":"D","text":"Đổ lỗi cho người khác hoặc hoàn cảnh"}]},{"n":97,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh khẳng định cán bộ, đảng viên phải là người như thế nào?","answer":"B","options":[{"key":"A","text":"Ăn cỗ đi trước, lội nước đi sau"},{"key":"B","text":"Học dân, làm cho dân tin và gương mẫu đi đầu"},{"key":"C","text":"Tập trung quyền lực, không cần nghe ý dân"},{"key":"D","text":"Chỉ làm việc khi có lệnh cấp trên"}]},{"n":98,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, công tác cán bộ phải?","answer":"A","options":[{"key":"A","text":"Đánh giá đúng, đề bạt đúng và huấn luyện có hiệu quả"},{"key":"B","text":"Ưu tiên cán bộ trẻ, bỏ qua cán bộ cũ"},{"key":"C","text":"Chỉ tuyển dụng cán bộ địa phương"},{"key":"D","text":"Để cán bộ tự học, không cần kiểm tra"}]},{"n":99,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh nói: “Đảng không che giấu những khuyết điểm của mình, không sợ phê bình”. Ý nghĩa của câu này là gì?","answer":"B","options":[{"key":"A","text":"Đảng nên che giấu để bảo vệ thanh danh"},{"key":"B","text":"Đảng phải thừa nhận sai lầm, tự sửa chữa để tiến bộ"},{"key":"C","text":"Đảng nên tránh các cuộc tranh luận nội bộ"},{"key":"D","text":"Đảng chỉ cần phê bình những người ngoài Đảng"}]},{"n":100,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, cán bộ, đảng viên phải có tinh thần như thế nào?","answer":"B","options":[{"key":"A","text":"Thụ động, chờ lệnh cấp trên"},{"key":"B","text":"Năng động, sáng tạo, dám chịu trách nhiệm"},{"key":"C","text":"Hạn chế phát biểu ý kiến"},{"key":"D","text":"Chủ yếu dựa vào kinh nghiệm cá nhân"}]},{"n":101,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Hồ Chí Minh đặc biệt coi trọng công tác nào?","answer":"C","options":[{"key":"A","text":"Công tác tài chính của Đảng"},{"key":"B","text":"Công tác đối ngoại nhân dân"},{"key":"C","text":"Công tác cán bộ"},{"key":"D","text":"Công tác tuyên truyền cổ động"}]},{"n":102,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh cho rằng : “cán bộ là (_____) của mọi công việc”","answer":"A","options":[{"key":"A","text":"Gốc"},{"key":"B","text":"Nền tảng"},{"key":"C","text":"Trung tâm"},{"key":"D","text":"Rường cột"}]},{"n":103,"sec":"2. Đảng phải trong sạch, vững mạnh","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh cho rằng: “muôn việc (_____) hoặc (_____) đều do cán bộ tốt hoặc kém”","answer":"C","options":[{"key":"A","text":"Đúng đắn; sai lầm"},{"key":"B","text":"Thắng lợi; thất bại"},{"key":"C","text":"Thành công; thất bại"},{"key":"D","text":"Tiến bộ; trì trệ"}]},{"n":104,"sec":"1. Nhà nước dân chủ","stem":"Theo quan điểm của Hồ Chí Minh, Nhà nước Việt Nam mới – Nhà nước Việt Nam Dân chủ Cộng hòa là một nhà nước mang bản chất của giai cấp nào?","answer":"D","options":[{"key":"A","text":"Giai cấp tư sản"},{"key":"B","text":"Giai cấp địa chủ"},{"key":"C","text":"Giai cấp tiểu tư sản"},{"key":"D","text":"Giai cấp công nhân"}]},{"n":105,"sec":"1. Nhà nước dân chủ","stem":"Bản chất giai cấp công nhân của Nhà nước Việt Nam thể hiện trên mấy phương diện?","answer":"B","options":[{"key":"A","text":"2 phương diện"},{"key":"B","text":"3 phương diện"},{"key":"C","text":"4 phương diện"},{"key":"D","text":"5 phương diện"}]},{"n":106,"sec":"1. Nhà nước dân chủ","stem":"Nội dung nào dưới đây thể hiện rõ bản chất giai cấp công nhân của Nhà nước Việt Nam?","answer":"D","options":[{"key":"A","text":"Nhà nước tách biệt hoàn toàn với các giai cấp trong xã hội"},{"key":"B","text":"Nhà nước phi giai cấp, chỉ bảo vệ lợi ích cá nhân"},{"key":"C","text":"Nhà nước toàn dân theo nghĩa không có giai cấp"},{"key":"D","text":"Đảng Cộng sản Việt Nam giữ vị trí và vai trò cầm quyền"}]},{"n":107,"sec":"1. Nhà nước dân chủ","stem":"Bản chất giai cấp công nhân của Nhà nước thể hiện ở nguyên tắc tổ chức và hoạt động của nó là nguyên tắc nào?","answer":"C","options":[{"key":"A","text":"Tự do cá nhân tuyệt đối"},{"key":"B","text":"Phân quyền cứng nhắc"},{"key":"C","text":"Tập trung dân chủ"},{"key":"D","text":"Độc quyền pháp luật"}]},{"n":108,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, Đảng cầm quyền bằng các phương thức nào sau đây?","answer":"D","options":[{"key":"A","text":"Bằng kiểm soát hoàn toàn nền kinh tế"},{"key":"B","text":"Bằng các chỉ đạo hành chính từ trung ương"},{"key":"C","text":"Bằng sự độc quyền tuyệt đối trong Quốc hội"},{"key":"D","text":"Bằng đường lối, quan điểm, chủ trương để Nhà nước thể chế hóa thành pháp luật, chính sách, kế hoạch"}]},{"n":109,"sec":"1. Nhà nước dân chủ","stem":"Đảng cầm quyền bằng các phương thức nào sau đây?","answer":"D","options":[{"key":"A","text":"Bằng đường lối, quan điểm, chủ trương để Nhà nước thể chế hóa thành pháp luật, chính sách, kế hoạch"},{"key":"B","text":"Bằng hoạt động của các tổ chức đảng và đảng viên của mình trong bộ máy, cơ quan nhà nước"},{"key":"C","text":"Bằng công tác kiểm tra"},{"key":"D","text":"Cả A, B và C"}]},{"n":110,"sec":"1. Nhà nước dân chủ","stem":"Trong tư tưởng của Hồ Chí Minh về Nhà nước mới ở Việt Nam, bản chất giai cấp công nhân của Nhà nước thống nhất với tính nhân dân và tính dân tộc, thể hiện ở những phương diện nào?","answer":"D","options":[{"key":"A","text":"Nhà nước Việt Nam ra đời là kết quả của cuộc đấu tranh lâu dài, gian khổ của rất nhiều thế hệ người Việt Nam, của toàn thể dân tộc"},{"key":"B","text":"Nhà nước Việt Nam ngay từ khi ra đời đã xác định rõ và luôn kiên trì, nhất quán mục tiêu vì quyền lợi của nhân dân, lấy quyền lợi của dân tộc làm nền tảng"},{"key":"C","text":"Nhà nước mới ở Việt Nam đã đảm đương nhiệm vụ mà toàn thể dân tộc giao phó là tổ chức nhân dân tiến hành các cuộc kháng chiến để bảo vệ nền độc lập, tự do của Tổ quốc, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"D","text":"Cả A, B và C"}]},{"n":111,"sec":"1. Nhà nước dân chủ","stem":"Theo tư tưởng Hồ Chí Minh, Nhà nước mới ở Việt Nam ra đời là kết quả của?","answer":"C","options":[{"key":"A","text":"Ý chí chính trị của tầng lớp trí thức tiến bộ"},{"key":"B","text":"Nỗ lực đấu tranh của giai cấp công nhân và nông dân trong thời kỳ hiện đại hóa"},{"key":"C","text":"Cuộc đấu tranh lâu dài, gian khổ của nhiều thế hệ người Việt Nam, của toàn thể dân tộc"},{"key":"D","text":"Những cải cách hành chính và chính trị của thời kỳ thuộc địa Pháp"}]},{"n":112,"sec":"1. Nhà nước dân chủ","stem":"Hồ Chí Minh khẳng định quyền lợi cơ bản của giai cấp công nhân thống nhất với?","answer":"C","options":[{"key":"A","text":"Lợi ích lâu dài của các tầng lớp trung lưu và trí thức trong xã hội"},{"key":"B","text":"Quyền lợi kinh tế của giai cấp tư sản và địa chủ tiến bộ"},{"key":"C","text":"Lợi ích của nhân dân lao động và của toàn dân tộc"},{"key":"D","text":"Chủ trương cải cách hành chính và phát triển nền kinh tế thị trường"}]},{"n":113,"sec":"1. Nhà nước dân chủ","stem":"Theo tư tưởng Hồ Chí Minh, Nhà nước Việt Nam mới đại diện và bảo vệ lợi ích của?","answer":"A","options":[{"key":"A","text":"Giai cấp công nhân, nhân dân lao động và toàn thể dân tộc Việt Nam"},{"key":"B","text":"Giai cấp công nhân, giai cấp tư sản dân tộc và tầng lớp tiểu tư sản"},{"key":"C","text":"Giai cấp công nhân và những người yêu nước tiến bộ trong xã hội"},{"key":"D","text":"Nhân dân lao động, các tầng lớp tiểu tư sản và địa chủ yêu nước"}]},{"n":114,"sec":"1. Nhà nước dân chủ","stem":"Trong thực tế, Nhà nước mới ở Việt Nam đã đảm đương nhiệm vụ mà toàn thể dân tộc giao phó là?","answer":"B","options":[{"key":"A","text":"Bảo đảm phát triển kinh tế tư nhân trong thời kỳ quá độ lên chủ nghĩa xã hội"},{"key":"B","text":"Tổ chức nhân dân tiến hành các cuộc kháng chiến để bảo vệ nền độc lập, tự do của Tổ quốc, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh"},{"key":"C","text":"Điều hành xã hội theo pháp luật và kiểm soát toàn diện mọi lĩnh vực"},{"key":"D","text":"Lãnh đạo toàn diện hệ thống chính trị và quản lý các thành phần kinh tế"}]},{"n":115,"sec":"1. Nhà nước dân chủ","stem":"Nhà nước Việt Nam mới không phải của riêng giai cấp, tầng lớp nào, mà là thuộc về?","answer":"B","options":[{"key":"A","text":"Thuộc quyền quản lý của Đảng Cộng sản Việt Nam trên cơ sở pháp luật"},{"key":"B","text":"Thuộc về nhân dân"},{"key":"C","text":"Thuộc về liên minh giữa giai cấp công nhân và giai cấp nông dân"},{"key":"D","text":"Thuộc quyền sở hữu của tập thể nhân dân lao động"}]},{"n":116,"sec":"1. Nhà nước dân chủ","stem":"Bản chất giai cấp công nhân của Nhà nước Việt Nam được Hồ Chí Minh nhìn nhận là?","answer":"D","options":[{"key":"A","text":"Đặc điểm phân biệt rõ ràng giữa Nhà nước Việt Nam và các nhà nước phong kiến"},{"key":"B","text":"Một đặc trưng của giai đoạn đầu khi giai cấp công nhân nắm chính quyền"},{"key":"C","text":"Kết quả từ sự phát triển của lực lượng sản xuất trong thời kỳ hiện đại"},{"key":"D","text":"Thống nhất với tính nhân dân và tính dân tộc trong bản chất của Nhà nước"}]},{"n":117,"sec":"1. Nhà nước dân chủ","stem":"Theo quan điểm của Hồ Chí Minh, nhà nước của nhân dân là nhà nước như thế nào?","answer":"A","options":[{"key":"A","text":"Là nhà nước mà tất cả mọi quyền lực trong nhà nước và trong xã hội đều thuộc về nhân dân"},{"key":"B","text":"Là nhà nước trong đó mọi công dân đều có quyền sở hữu tài sản công cộng"},{"key":"C","text":"Nhà nước đại diện cho đa số tầng lớp trung lưu trong xã hội hiện đại"},{"key":"D","text":"Nhà nước quản lý xã hội bằng pháp luật và do Đảng trực tiếp điều hành mọi hoạt động"}]},{"n":118,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? “Trong Nhà nước Việt Nam Dân chủ Cộng hoà của chúng ta, tất cả mọi quyền lực đều là (_____)” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.8, tr.262).","answer":"C","options":[{"key":"A","text":"Của Đảng lãnh đạo và Nhà nước thực thi"},{"key":"B","text":"Của Quốc hội và các cơ quan hành pháp"},{"key":"C","text":"Của nhân dân"},{"key":"D","text":"Của giai cấp công nhân tiên phong"}]},{"n":119,"sec":"1. Nhà nước dân chủ","stem":"Nhà nước của dân tức là?","answer":"D","options":[{"key":"A","text":"Dân sở hữu tài sản công"},{"key":"B","text":"Dân phục tùng pháp luật"},{"key":"C","text":"Dân làm kinh tế"},{"key":"D","text":"Dân là chủ"}]},{"n":120,"sec":"1. Nhà nước dân chủ","stem":"Nguyên lý “dân là chủ” khẳng định địa vị chủ thể tối cao của mọi quyền lực là?","answer":"C","options":[{"key":"A","text":"Đảng Cộng sản"},{"key":"B","text":"Nhà nước"},{"key":"C","text":"Nhân dân"},{"key":"D","text":"Chính phủ"}]},{"n":121,"sec":"1. Nhà nước dân chủ","stem":"Trong Nhà nước dân chủ, nhân dân thực thi quyền lực thông qua mấy hình thức?","answer":"A","options":[{"key":"A","text":"2 hình thức"},{"key":"B","text":"3 hình thức"},{"key":"C","text":"4 hình thức"},{"key":"D","text":"5 hình thức"}]},{"n":122,"sec":"1. Nhà nước dân chủ","stem":"Trong Nhà nước dân chủ, nhân dân thực thi quyền lực thông qua hai hình thức dân chủ là?","answer":"C","options":[{"key":"A","text":"Tập trung và phân quyền"},{"key":"B","text":"Đại nghị và quân chủ"},{"key":"C","text":"Trực tiếp và gián tiếp"},{"key":"D","text":"Cố định và linh hoạt"}]},{"n":123,"sec":"1. Nhà nước dân chủ","stem":"Hình thức dân chủ nào được Hồ Chí Minh đánh giá là hoàn bị nhất?","answer":"B","options":[{"key":"A","text":"Dân chủ gián tiếp"},{"key":"B","text":"Dân chủ trực tiếp"},{"key":"C","text":"Dân chủ theo mô hình đại nghị phương Tây"},{"key":"D","text":"Dân chủ xã hội"}]},{"n":124,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, dân chủ trực tiếp là hình thức dân chủ như thế nào?","answer":"B","options":[{"key":"A","text":"Nhân dân bầu ra đại biểu để thay mặt quyết định các vấn đề"},{"key":"B","text":"Nhân dân trực tiếp quyết định mọi vấn đề liên quan đến vận mệnh của quốc gia, dân tộc và quyền lợi của dân chúng"},{"key":"C","text":"Nhân dân góp ý kiến thông qua các tổ chức đoàn thể trung gian"},{"key":"D","text":"Nhân dân được thông báo về chính sách do Nhà nước ban hành"}]},{"n":125,"sec":"1. Nhà nước dân chủ","stem":"Hồ Chí Minh quan niệm thế nào về hình thức dân chủ trực tiếp?","answer":"A","options":[{"key":"A","text":"Là hình thức dân chủ mà nhân dân trực tiếp quyết định các vấn đề quan trọng của đất nước"},{"key":"B","text":"Là hình thức nhân dân góp ý cho đại biểu để đưa ra quyết sách đúng đắn"},{"key":"C","text":"Là hình thức nhân dân thông qua đại biểu để thực hiện quyền lực của mình"},{"key":"D","text":"Là hình thức nhân dân giám sát hoạt động của các cơ quan công quyền"}]},{"n":126,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, dân chủ gián tiếp là hình thức dân chủ như thế nào?","answer":"B","options":[{"key":"A","text":"Nhân dân tham gia các hội nghị để nêu ý kiến đóng góp cho chính sách"},{"key":"B","text":"Nhân dân thực thi quyền lực của mình thông qua các đại diện mà họ lựa chọn, bầu ra và những thiết chế quyền lực mà họ lập nên"},{"key":"C","text":"Nhân dân giám sát hoạt động của Nhà nước thông qua các phương tiện truyền thông đại chúng"},{"key":"D","text":"Nhân dân góp ý xây dựng chính quyền thông qua các hội nghị lấy ý kiến nhân dân"}]},{"n":127,"sec":"1. Nhà nước dân chủ","stem":"Theo quan điểm của Hồ Chí Minh, trong hình thức dân chủ gián tiếp, quyền lực nhà nước là?","answer":"D","options":[{"key":"A","text":"Là đặc quyền hợp pháp của tổ chức nắm chính quyền"},{"key":"B","text":"Là kết quả của cuộc cách mạng do giai cấp công nhân lãnh đạo"},{"key":"C","text":"Là quyền lực tập trung và không thể chia sẻ cho các tổ chức xã hội"},{"key":"D","text":"“Thừa ủy quyền” của nhân dân. Tự bản thân nhà nước không có quyền lực. Quyền lực của nhà nước là do nhân dân ủy thác"}]},{"n":128,"sec":"1. Nhà nước dân chủ","stem":"Hồ Chí Minh gọi các cán bộ, công chức trong nhà nước là gì?","answer":"B","options":[{"key":"A","text":"Người lãnh đạo dân chúng thực hiện nhiệm vụ cách mạng"},{"key":"B","text":"Công bộc của dân, là người gánh vác việc chung cho dân"},{"key":"C","text":"Những người có trách nhiệm ban hành và thực thi pháp luật"},{"key":"D","text":"Những người có quyền đại diện cho dân trong quản lý xã hội"}]},{"n":129,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Các cơ quan quyền lực nhà nước cùng với đội ngũ cán bộ đều là “(_____)” của nhân dân, nghĩa là “gánh vác việc chung cho dân, chứ không phải để đè đầu dân” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.4, tr.64-65)","answer":"C","options":[{"key":"A","text":"Lãnh đạo"},{"key":"B","text":"Đại biểu"},{"key":"C","text":"Công bộc"},{"key":"D","text":"Cán bộ"}]},{"n":130,"sec":"1. Nhà nước dân chủ","stem":"Quan điểm Hồ Chí Minh về cán bộ nhà nước là?","answer":"B","options":[{"key":"A","text":"Lực lượng nòng cốt trong công cuộc phát triển kinh tế - xã hội"},{"key":"B","text":"Công bộc của dân, không phải “quan cách mạng”"},{"key":"C","text":"Người được Đảng phân công lãnh đạo và chỉ đạo nhân dân"},{"key":"D","text":"Đối tượng đại diện cho lợi ích giai cấp công nhân trong bộ máy nhà nước"}]},{"n":131,"sec":"1. Nhà nước dân chủ","stem":"Theo tư tưởng Hồ Chí Minh, nhân dân có quyền gì đối với những đại biểu do mình bầu ra?","answer":"C","options":[{"key":"A","text":"Được quyền yêu cầu đại biểu đó từ chức nếu vi phạm đạo đức"},{"key":"B","text":"Có quyền yêu cầu tổ chức lại bầu cử nếu đại biểu không hoàn thành nhiệm vụ"},{"key":"C","text":"Có quyền bãi miễn nếu đại biểu tỏ ra không xứng đáng với sự tín nhiệm của nhân dân"},{"key":"D","text":"Chỉ được góp ý nếu đại biểu có sai phạm nhỏ"}]},{"n":132,"sec":"1. Nhà nước dân chủ","stem":"Trong tư tưởng Hồ Chí Minh, nếu Chính phủ làm hại dân thì dân có quyền gì?","answer":"C","options":[{"key":"A","text":"Được yêu cầu Chính phủ giải trình trước Quốc hội"},{"key":"B","text":"Có quyền kiến nghị lên các tổ chức quốc tế"},{"key":"C","text":"Có quyền đuổi Chính phủ nếu làm hại đến nhân dân"},{"key":"D","text":"Được quyền yêu cầu bầu cử lại trong kỳ tiếp theo"}]},{"n":133,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Nhân dân có quyền (_____), (_____) nhà nước, có quyền (_____) những đại biểu mà họ đã lựa chọn, bầu ra và có quyền (____ _) những thiết chế quyền lực mà họ đã lập nên.","answer":"A","options":[{"key":"A","text":"Kiểm soát, phê bình, bãi miễn, giải tán"},{"key":"B","text":"Kiểm tra, phản đối, bãi miễn, xóa bỏ"},{"key":"C","text":"Góp ý, kiến nghị, thay thế, đình chỉ"},{"key":"D","text":"Theo dõi, can thiệp, loại bỏ, giải thể"}]},{"n":134,"sec":"1. Nhà nước dân chủ","stem":"Tư tưởng Hồ Chí Minh về nhà nước thể hiện rõ nguyên tắc nào dưới đây?","answer":"D","options":[{"key":"A","text":"Chính phủ chỉ cần chịu trách nhiệm trước Quốc hội"},{"key":"B","text":"Nhà nước là nơi đại diện cho trí thức và giới tinh hoa"},{"key":"C","text":"Mọi thiết chế quyền lực được hình thành từ quyết định của nhà nước"},{"key":"D","text":"Quyền lực nhà nước phải nằm trong tay dân chúng"}]},{"n":135,"sec":"1. Nhà nước dân chủ","stem":"Theo tư tưởng Hồ Chí Minh, nhân dân có quyền giải tán thiết chế nào dưới đây nếu không còn phục vụ lợi ích của dân?","answer":"C","options":[{"key":"A","text":"Các tổ chức phi chính phủ"},{"key":"B","text":"Các tổ chức tôn giáo"},{"key":"C","text":"Những thiết chế quyền lực do dân lập nên"},{"key":"D","text":"Các doanh nghiệp nhà nước"}]},{"n":136,"sec":"1. Nhà nước dân chủ","stem":"Luật pháp trong Nhà nước Việt Nam mới theo Hồ Chí Minh có điểm gì khác biệt so với luật pháp của chế độ cũ?","answer":"B","options":[{"key":"A","text":"Là công cụ kiểm soát xã hội trong tay chính quyền"},{"key":"B","text":"Phản ánh ý nguyện và bảo vệ quyền lợi của nhân dân"},{"key":"C","text":"Là công cụ để duy trì trật tự cho lợi ích của nhà nước"},{"key":"D","text":"Là phương tiện để củng cố vai trò lãnh đạo của Đảng"}]},{"n":137,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, Nhà nước do nhân dân trước hết là?","answer":"C","options":[{"key":"A","text":"Nhà nước được hình thành từ giới tinh hoa trí thức"},{"key":"B","text":"Nhà nước do Đảng Cộng sản tổ chức và điều hành hoàn toàn"},{"key":"C","text":"Nhà nước do nhân dân lập nên sau thắng lợi của sự nghiệp cách mạng của toàn dân tộc dưới sự lãnh đạo của Đảng Cộng sản Việt Nam"},{"key":"D","text":"Nhà nước do các tổ chức chính trị – xã hội đại diện nhân dân tạo ra"}]},{"n":138,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, nhà nước do nhân dân còn có nghĩa là?","answer":"A","options":[{"key":"A","text":"Dân làm chủ"},{"key":"B","text":"Dân có quyền được nghe báo cáo từ chính phủ"},{"key":"C","text":"Dân có quyền góp ý cho Đảng"},{"key":"D","text":"Người dân có quyền kiến nghị về chính sách"}]},{"n":139,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, nhân dân “cử ra”, “tổ chức nên” nhà nước trên cơ sở nào?","answer":"C","options":[{"key":"A","text":"Truyền thống văn hóa và tín ngưỡng lâu đời của dân tộc"},{"key":"B","text":"Kinh nghiệm thực tiễn cách mạng và vai trò của các đoàn thể"},{"key":"C","text":"Nền tảng pháp lý của một chế độ dân chủ và các trình tự dân chủ"},{"key":"D","text":"Quyết định chung của Quốc hội và Chính phủ"}]},{"n":140,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, “Nước ta là nước dân chủ, nghĩa là...”?","answer":"D","options":[{"key":"A","text":"Chính phủ được bầu cử dân chủ"},{"key":"B","text":"Các tầng lớp nhân dân đều được bảo vệ quyền lợi"},{"key":"C","text":"Nhân dân có quyền quyết định mọi chính sách"},{"key":"D","text":"Nước nhà do nhân dân làm chủ"}]},{"n":141,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Theo quan điểm của Hồ Chí Minh, “nhân dân có (_____) làm chủ, thì phải có (_____) làm tròn bổn phận công dân, giữ đúng đạo đức công dân” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.9, tr.258).","answer":"A","options":[{"key":"A","text":"Quyền lợi - nghĩa vụ"},{"key":"B","text":"Quyền - trách nhiệm"},{"key":"C","text":"Điều kiện - cam kết"},{"key":"D","text":"Năng lực - đạo đức"}]},{"n":142,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Nếu “dân là chủ” xác định (_____) của nhân dân đối với quyền lực nhà nước, thì “dân làm chủ” nhấn mạnh (_____) và (_____) của nhân dân với tư cách là người chủ.","answer":"B","options":[{"key":"A","text":"Vai trò – trách nhiệm pháp lý"},{"key":"B","text":"Vị thế – quyền lợi và nghĩa vụ"},{"key":"C","text":"Chức năng – quyền lực"},{"key":"D","text":"Phẩm chất – trách nhiệm công dân"}]},{"n":143,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, người dân làm chủ thì phải?","answer":"B","options":[{"key":"A","text":"Trung thành với nhà nước, không chất vấn chính quyền"},{"key":"B","text":"Có trách nhiệm tuân thủ pháp luật, đạo đức và nghĩa vụ công dân"},{"key":"C","text":"Sẵn sàng lên tiếng nếu thấy lãnh đạo không làm tròn bổn phận"},{"key":"D","text":"Chỉ cần tham gia bầu cử là đủ"}]},{"n":144,"sec":"1. Nhà nước dân chủ","stem":"Một trong những nghĩa vụ công dân được Hồ Chí Minh nêu ra là gì?","answer":"C","options":[{"key":"A","text":"Góp phần xây dựng luật mới"},{"key":"B","text":"Tham gia đầy đủ các kỳ họp tổ dân phố"},{"key":"C","text":"Nộp thuế đúng kỳ, đúng số"},{"key":"D","text":"Gửi kiến nghị đến Quốc hội"}]},{"n":145,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, Trong nhà nước do nhân dân làm chủ, nhà nước phải tạo điều kiện gì cho nhân dân?","answer":"D","options":[{"key":"A","text":"Có nhiều thời gian để làm việc riêng"},{"key":"B","text":"Tránh can thiệp vào cuộc sống cá nhân của nhân dân"},{"key":"C","text":"Được tự do kinh doanh trong mọi lĩnh vực"},{"key":"D","text":"Thực hiện quyền và nghĩa vụ công dân theo đúng Hiến pháp, pháp luật"}]},{"n":146,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh nói: “Chúng ta là những người lao động làm chủ nước nhà. Muốn làm chủ được tốt, phải có (_____) làm chủ” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.12, tr.527).","answer":"D","options":[{"key":"A","text":"Vai trò"},{"key":"B","text":"Vị thế"},{"key":"C","text":"Chức năng"},{"key":"D","text":"Năng lực"}]},{"n":147,"sec":"1. Nhà nước dân chủ","stem":"Điểm nào sau đây KHÔNG phù hợp với tư tưởng Hồ Chí Minh về Nhà nước do nhân dân?","answer":"A","options":[{"key":"A","text":"Nhà nước có thể thay mặt nhân dân quyết định mọi vấn đề"},{"key":"B","text":"Nhân dân có quyền bầu ra và phúc quyết với các cơ quan quyền lực"},{"key":"C","text":"Nhân dân vừa có quyền, vừa có nghĩa vụ làm chủ đất nước"},{"key":"D","text":"Cần chuẩn bị năng lực để nhân dân thực hiện tốt vai trò làm chủ"}]},{"n":148,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, Nhà nước vì nhân dân là Nhà nước như thế nào?","answer":"D","options":[{"key":"A","text":"Nhà nước đại diện giai cấp công nhân, xây dựng xã hội chủ nghĩa hiện đại"},{"key":"B","text":"Nhà nước được tổ chức chặt chẽ, có hệ thống điều hành hành chính hiệu quả"},{"key":"C","text":"Nhà nước xây dựng từ dưới lên, phát huy dân chủ trực tiếp toàn diện"},{"key":"D","text":"Nhà nước phục vụ lợi ích và nguyện vọng của nhân dân, không có đặc quyền đặc lợi"}]},{"n":149,"sec":"1. Nhà nước dân chủ","stem":"Hồ Chí Minh cho rằng thước đo một Nhà nước vì dân là gì?","answer":"B","options":[{"key":"A","text":"Là việc Nhà nước có hiệu suất làm việc cao, minh bạch và tiết kiệm chi tiêu"},{"key":"B","text":"Là phải được lòng dân, dân tin, dân mến, dân yêu"},{"key":"C","text":"Là sự hiện diện của pháp luật nghiêm minh và trật tự xã hội ổn định"},{"key":"D","text":"Là Nhà nước do dân bầu ra, được giám sát chặt chẽ qua các kênh pháp lý"}]},{"n":150,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? \"Các công việc của Chính phủ làm phải nhằm vào một mục đích duy nhất là mưu tự do hạnh phúc cho mọi người. Cho nên Chính phủ nhân dân bao giờ cũng phải đặt (_____) dân lên trên hết thảy. Việc gì có (_____) cho dân thì làm. Việc gì có (_____) cho dân thì phải tránh”","answer":"C","options":[{"key":"A","text":"Quyền lợi - lợi ích - tác hại"},{"key":"B","text":"Nguyện vọng - hạnh phúc - khó khăn"},{"key":"C","text":"Quyền lợi - lợi - hại"},{"key":"D","text":"lợi ích - lợi ích - bất lợi"}]},{"n":151,"sec":"1. Nhà nước dân chủ","stem":"Theo Hồ Chí Minh, thước đo một Nhà nước vì dân là phải?","answer":"D","options":[{"key":"A","text":"Tổ chức bộ máy chặt chẽ, cán bộ có trình độ chuyên môn vững vàng"},{"key":"B","text":"Có hiệu quả quản lý cao, tuân thủ pháp luật và không có tham nhũng"},{"key":"C","text":"Có đủ nguồn lực tài chính và nhân lực để phục vụ phát triển đất nước"},{"key":"D","text":"Được lòng dân"}]},{"n":152,"sec":"1. Nhà nước dân chủ","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh đặt vấn đề với cán bộ Nhà nước phải “làm sao cho được (_____), dân tin, dân mến, dân yêu”, đồng thời chỉ rõ: “muốn được dân yêu, muốn được lòng dân, trước hết phải (_____), phải đặt (_____) của dân trên hết thảy, phải có một tinh thần chí công vô tư” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.4, tr.52)","answer":"A","options":[{"key":"A","text":"Lòng dân – yêu dân – quyền lợi"},{"key":"B","text":"Sự tín nhiệm – tận tụy – nhu cầu"},{"key":"C","text":"Lòng dân – tận trung – nguyện vọng"},{"key":"D","text":"Sự đồng thuận – chăm lo – lợi ích"}]},{"n":153,"sec":"1. Nhà nước dân chủ","stem":"Hồ Chí Minh cho rằng việc gì có lợi cho dân thì phải làm, còn việc gì có hại cho dân thì?","answer":"C","options":[{"key":"A","text":"Phải sửa chữa nếu như đã gây ảnh hưởng đến uy tín của chính quyền"},{"key":"B","text":"Phải thảo luận kỹ trong Đảng rồi mới quyết định"},{"key":"C","text":"Phải tránh, không được làm vì sẽ ảnh hưởng đến lòng dân"},{"key":"D","text":"Phải báo cáo lên cấp trên để xin ý kiến chỉ đạo"}]},{"n":154,"sec":"1. Nhà nước dân chủ","stem":"Trong Nhà nước vì dân, cán bộ vừa là đày tớ, nhưng đồng thời phải vừa là?","answer":"C","options":[{"key":"A","text":"Người phụ trách kỹ thuật trong hệ thống hành chính"},{"key":"B","text":"Cán bộ chuyên môn có quyền quyết định cuối cùng"},{"key":"C","text":"Người lãnh đạo nhân dân"},{"key":"D","text":"Người trung gian giữa Đảng và quần chúng nhân dân"}]},{"n":155,"sec":"1. Nhà nước dân chủ","stem":"Trong Nhà nước vì dân, cán bộ là đày tớ thì phải như thế nào?","answer":"B","options":[{"key":"A","text":"Phải phục tùng tuyệt đối mọi mệnh lệnh cấp trên đưa ra trong mọi hoàn cảnh"},{"key":"B","text":"Phải trung thành, tận tụy, cần kiệm liêm chính, chí công vô tư, lo trước thiên hạ, vui sau thiên hạ"},{"key":"C","text":"Phải thường xuyên đổi mới tư duy lãnh đạo, tăng cường tiếp cận công nghệ hiện đại"},{"key":"D","text":"Phải giữ gìn sự ổn định chính trị, phát triển kinh tế bền vững và thực hiện mục tiêu dân giàu nước mạnh"}]},{"n":156,"sec":"1. Nhà nước dân chủ","stem":"Trong Nhà nước vì dân, cán bộ là người lãnh đạo thì phải như thế nào?","answer":"D","options":[{"key":"A","text":"Phải có tinh thần học hỏi, sẵn sàng tuân thủ các mệnh lệnh cấp trên một cách nghiêm túc"},{"key":"B","text":"Phải thường xuyên kiểm tra giám sát, xử lý nghiêm các sai phạm trong nội bộ nhân dân"},{"key":"C","text":"Phải nâng cao hiệu quả quản lý bằng cách sử dụng công nghệ và cải cách hành chính mạnh mẽ"},{"key":"D","text":"Phải có trí tuệ hơn người, minh mẫn, sáng suốt, nhìn xa trông rộng, gần gũi nhân dân, trọng dụng hiền tài"}]},{"n":157,"sec":"2. Nhà nước pháp quyền","stem":"Trong bản “Yêu sách của nhân dân An Nam” năm 1919, Hồ Chí Minh yêu cầu cải cách nền pháp lý ở Đông Dương theo hướng nào?","answer":"C","options":[{"key":"A","text":"Tăng cường vai trò kiểm tra, giám sát của các cơ quan hành pháp"},{"key":"B","text":"Ban hành sắc lệnh để xử lý nhanh các vụ việc đặc biệt"},{"key":"C","text":"Cải cách nền pháp lý ở Đông Dương bằng cách làm cho người bản xứ cũng được quyền hưởng những bảo đảm về mặt pháp luật như người Âu châu"},{"key":"D","text":"Áp dụng mô hình pháp lý của Nhật Bản để xây dựng luật pháp bản địa"}]},{"n":158,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh đề nghị điều gì ngay trong phiên họp đầu tiên của Chính phủ lâm thời ngày 3/9/1945?","answer":"C","options":[{"key":"A","text":"Thảo luận về các sắc lệnh khẩn cấp để giải quyết hậu quả chiến tranh"},{"key":"B","text":"Thành lập Hội đồng cố vấn pháp luật để chuẩn bị cho việc lập hiến"},{"key":"C","text":"Đề nghị Chính phủ tổ chức càng sớm càng hay cuộc tổng tuyển cử với chế độ phổ thông đầu phiếu"},{"key":"D","text":"Soạn thảo luật hình sự đầu tiên của nước Việt Nam mới"}]},{"n":159,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh đề nghị tổ chức Tổng tuyển cử vào thời điểm nào?","answer":"B","options":[{"key":"A","text":"Trong phiên họp Quốc hội đầu tiên"},{"key":"B","text":"Một ngày sau khi đọc Tuyên ngôn Độc lập"},{"key":"C","text":"Sau khi thành lập Chính phủ lâm thời"},{"key":"D","text":"Trước khi đàm phán với quân Đồng Minh"}]},{"n":160,"sec":"2. Nhà nước pháp quyền","stem":"Mục đích Hồ Chí Minh đề xuất tổ chức Tổng tuyển cử sớm là gì?","answer":"B","options":[{"key":"A","text":"Khuyến khích tinh thần dân chủ trong nhân dân"},{"key":"B","text":"Hợp thức hoá chính quyền và xây dựng cơ sở pháp lý vững chắc"},{"key":"C","text":"Thể hiện thiện chí hoà bình với các lực lượng quốc tế"},{"key":"D","text":"Thiết lập quyền tự trị của các địa phương trên cả nước"}]},{"n":161,"sec":"2. Nhà nước pháp quyền","stem":"Cuộc Tổng tuyển cử đầu tiên của nước Việt Nam Dân chủ Cộng hòa được tổ chức vào thời gian nào?","answer":"C","options":[{"key":"A","text":"2-9-1945"},{"key":"B","text":"3-9-1945"},{"key":"C","text":"6-1-1946"},{"key":"D","text":"2-3-1946"}]},{"n":162,"sec":"2. Nhà nước pháp quyền","stem":"Cuộc Tổng tuyển cử năm 1946 được tiến hành theo hình thức nào sau đây?","answer":"C","options":[{"key":"A","text":"Bầu cử gián tiếp qua đại biểu trung gian"},{"key":"B","text":"Bầu cử công khai tại nơi làm việc"},{"key":"C","text":"Phổ thông đầu phiếu, trực tiếp và bỏ phiếu kín"},{"key":"D","text":"Chỉ áp dụng cho nam giới có địa vị xã hội cao"}]},{"n":163,"sec":"2. Nhà nước pháp quyền","stem":"Lần đầu tiên trong lịch sử hàng nghìn năm của dân tộc Việt Nam cũng như lần đầu tiên ở Đông Nam Á, mọi công dân từ bao nhiêu tuổi trở lên đều có quyền bỏ phiếu bầu những đại biểu của mình tham gia Quốc hội?","answer":"A","options":[{"key":"A","text":"18 tuổi trở lên"},{"key":"B","text":"20 tuổi trở lên"},{"key":"C","text":"21 tuổi trở lên"},{"key":"D","text":"22 tuổi trở lên"}]},{"n":164,"sec":"2. Nhà nước pháp quyền","stem":"Quốc hội khoá I nước Việt Nam Dân chủ Cộng hoà đã họp phiên đầu tiên vào thời gian nào?","answer":"C","options":[{"key":"A","text":"6-1-1946"},{"key":"B","text":"15-2-1946"},{"key":"C","text":"2-3-1946"},{"key":"D","text":"30-4-1946"}]},{"n":165,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh được bầu vào vị trí nào trong Chính phủ liên hiệp đầu tiên?","answer":"B","options":[{"key":"A","text":"Tổng bí thư Đảng Cộng sản"},{"key":"B","text":"Chủ tịch Chính phủ liên hiệp"},{"key":"C","text":"Bộ trưởng Bộ Quốc phòng"},{"key":"D","text":"Chủ tịch Quốc hội"}]},{"n":166,"sec":"2. Nhà nước pháp quyền","stem":"Trong tư tưởng Hồ Chí Minh, Nhà nước quản lý bằng bộ máy và bằng nhiều biện pháp khác nhau, nhưng quan trọng nhất là quản lý bằng?","answer":"A","options":[{"key":"A","text":"Hiến pháp và pháp luật"},{"key":"B","text":"Bộ máy hành chính linh hoạt và gọn nhẹ"},{"key":"C","text":"Các phương tiện truyền thông và tuyên truyền"},{"key":"D","text":"Quyết định của tập thể lãnh đạo cấp cao"}]},{"n":167,"sec":"2. Nhà nước pháp quyền","stem":"Ở cương vị Chủ tịch nước, Hồ Chí Minh đã mấy lần tham gia vào quá trình lãnh đạo soạn thảo Hiến pháp?","answer":"B","options":[{"key":"A","text":"Một lần"},{"key":"B","text":"Hai lần"},{"key":"C","text":"Ba lần"},{"key":"D","text":"Bốn lần"}]},{"n":168,"sec":"2. Nhà nước pháp quyền","stem":"Ở cương vị Chủ tịch nước, Hồ Chí Minh đã hai lần tham gia vào quá trình lãnh đạo soạn thảo Hiến pháp. Đó là Hiến pháp năm nào?","answer":"B","options":[{"key":"A","text":"Hiến pháp năm 1945 và Hiến pháp năm 1954"},{"key":"B","text":"Hiến pháp năm 1946 và Hiến pháp năm 1959"},{"key":"C","text":"Hiến pháp năm 1947 và Hiến pháp năm 1960"},{"key":"D","text":"Hiến pháp năm 1950 và Hiến pháp năm 1965"}]},{"n":169,"sec":"2. Nhà nước pháp quyền","stem":"Trong thời kỳ làm Chủ tịch nước, Hồ Chí Minh đã ký công bố bao nhiêu sắc lệnh?","answer":"D","options":[{"key":"A","text":"316 sắc lệnh, chủ yếu về tổ chức hành chính"},{"key":"B","text":"421 sắc lệnh, trong đó có nhiều sắc lệnh về giáo dục"},{"key":"C","text":"512 sắc lệnh, bao gồm các sắc lệnh về kinh tế và quốc phòng"},{"key":"D","text":"613 sắc lệnh trong đó có 243 sắc lệnh quy định về tổ chức Nhà nước và pháp luật, và nhiều văn bản dưới luật khác"}]},{"n":170,"sec":"2. Nhà nước pháp quyền","stem":"Để pháp luật thực sự đi vào cuộc sống, Hồ Chí Minh nhấn mạnh cần làm gì?","answer":"C","options":[{"key":"A","text":"Tổ chức đối thoại giữa cán bộ và nhân dân về các văn bản pháp luật"},{"key":"B","text":"Thiết lập lực lượng chuyên trách giám sát tuân thủ pháp luật"},{"key":"C","text":"Bảo đảm thi hành và có cơ chế giám sát việc thi hành pháp luật"},{"key":"D","text":"Giao quyền lập pháp cho các đoàn thể nhân dân đại diện"}]},{"n":171,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh đặc biệt coi trọng việc nâng cao điều gì trong nhân dân để xây dựng Nhà nước pháp quyền?","answer":"D","options":[{"key":"A","text":"Tư duy phản biện và ý thức đoàn kết"},{"key":"B","text":"Trình độ chuyên môn và năng lực sản xuất"},{"key":"C","text":"Tư tưởng tự quản và khả năng tự chủ kinh tế"},{"key":"D","text":"Trình độ hiểu biết và năng lực sử dụng pháp luật"}]},{"n":172,"sec":"2. Nhà nước pháp quyền","stem":"Theo Hồ Chí Minh, vì sao cần phải giáo dục pháp luật cho nhân dân?","answer":"C","options":[{"key":"A","text":"Để nhân dân thực hiện đúng quy trình khiếu nại, tố cáo"},{"key":"B","text":"Để pháp luật trở thành công cụ của các tổ chức chính trị"},{"key":"C","text":"Để nhân dân biết hưởng và sử dụng quyền dân chủ của mình"},{"key":"D","text":"Để nhân dân tập trung vào công việc sản xuất hơn là chính trị"}]},{"n":173,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh nhấn mạnh vai trò của thế hệ nào trong việc học tập và thực thi pháp luật?","answer":"B","options":[{"key":"A","text":"Cán bộ lão thành cách mạng"},{"key":"B","text":"Thế hệ trẻ - những người chủ tương lai của đất nước"},{"key":"C","text":"Những người có chức vụ trong bộ máy nhà nước"},{"key":"D","text":"Giới tri thức – lực lượng tinh hoa trong xã hội"}]},{"n":174,"sec":"2. Nhà nước pháp quyền","stem":"Theo Hồ Chí Minh, việc thực thi pháp luật gắn liền chặt chẽ với?","answer":"C","options":[{"key":"A","text":"Khả năng điều phối của chính quyền địa phương"},{"key":"B","text":"Sự phát triển kinh tế của từng vùng miền"},{"key":"C","text":"Trình độ dân trí và ý thức chính trị của nhân dân"},{"key":"D","text":"Việc kiểm tra tài chính các cấp chính quyền"}]},{"n":175,"sec":"2. Nhà nước pháp quyền","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh luôn nêu cao tính (_____) của pháp luật.","answer":"A","options":[{"key":"A","text":"Nghiêm minh"},{"key":"B","text":"Linh hoạt"},{"key":"C","text":"Khoan dung"},{"key":"D","text":"Mềm dẻo"}]},{"n":176,"sec":"2. Nhà nước pháp quyền","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh tuyên bố: “Pháp luật Việt Nam tuy (_____) với những người biết cải tà quy chính, nhưng sẽ thẳng tay (_____) những tên Việt gian đầu sỏ đã bán nước buôn dân” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.6, tr.49.)","answer":"B","options":[{"key":"A","text":"Nhân đạo – xử phạt"},{"key":"B","text":"Khoan hồng – trừng trị"},{"key":"C","text":"Cảm thông – giáo hóa"},{"key":"D","text":"Bao dung – xử lý nghiêm"}]},{"n":177,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh nêu rõ tính chất nào của pháp luật trong xử lý sai phạm?","answer":"D","options":[{"key":"A","text":"Khoan dung và linh hoạt trong từng trường hợp"},{"key":"B","text":"Cứng rắn với người dân, nhẹ nhàng với cán bộ"},{"key":"C","text":"Nghiêm minh nhưng có tình, có lý"},{"key":"D","text":"Khoan hồng với người hối cải, nghiêm trị kẻ phản bội"}]},{"n":178,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh phê phán điều gì thể hiện sự thiếu nghiêm minh trong pháp luật?","answer":"B","options":[{"key":"A","text":"Coi thường kỷ luật trong bộ máy hành chính"},{"key":"B","text":"Lẫn lộn giữa công và tội, thưởng phạt không nghiêm"},{"key":"C","text":"Cấp dưới không tôn trọng ý kiến cấp trên"},{"key":"D","text":"Lạm dụng quyền lực trong việc tổ chức pháp luật"}]},{"n":179,"sec":"2. Nhà nước pháp quyền","stem":"Người thực thi pháp luật, theo Hồ Chí Minh, cần có phẩm chất gì?","answer":"A","options":[{"key":"A","text":"Công tâm, nghiêm minh, không thiên vị"},{"key":"B","text":"Biết vận dụng luật mềm dẻo tùy tình hình"},{"key":"C","text":"Thấu tình đạt lý và ưu tiên ổn định xã hội"},{"key":"D","text":"Linh hoạt, sáng tạo và có mối quan hệ rộng"}]},{"n":180,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh cho rằng, việc đưa pháp luật vào cuộc sống đòi hỏi điều gì ở cán bộ tư pháp?","answer":"B","options":[{"key":"A","text":"Phải trung thành với tổ chức Đảng và nhân dân"},{"key":"B","text":"Phải phụng công, thủ pháp, chí công vô tư"},{"key":"C","text":"Phải kết hợp giữa lý thuyết và thực tế"},{"key":"D","text":"Phải kết hợp giữa lý thuyết và thực tế"}]},{"n":181,"sec":"2. Nhà nước pháp quyền","stem":"Theo Hồ Chí Minh, pháp luật là công cụ của ai?","answer":"C","options":[{"key":"A","text":"Của Nhà nước dùng để kiểm soát xã hội"},{"key":"B","text":"Của các tổ chức chính trị để điều hành đất nước"},{"key":"C","text":"Của nhân dân để bảo vệ quyền và nghĩa vụ của mình"},{"key":"D","text":"Của chính quyền địa phương để phát triển cộng đồng"}]},{"n":182,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh nhấn mạnh vai trò của cán bộ trong việc tuân thủ pháp luật, đặc biệt là?","answer":"C","options":[{"key":"A","text":"Cán bộ quân đội và lực lượng an ninh"},{"key":"B","text":"Cán bộ cấp huyện và cấp tỉnh"},{"key":"C","text":"Cán bộ ngành hành pháp và tư pháp"},{"key":"D","text":"Cán bộ lãnh đạo doanh nghiệp nhà nước"}]},{"n":183,"sec":"2. Nhà nước pháp quyền","stem":"Điền từ còn thiếu vào (_____)? Trong thư gửi Hội nghị tư pháp toàn quốc, Người viết: “Các bạn là những người phụ trách thi hành pháp luật. Lẽ tất nhiên các bạn cần phải nêu cao cái gương “(_____), (_____), (_____), (_____) ” cho nhân dân noi theo” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.5, tr.473 )","answer":"A","options":[{"key":"A","text":"Phụng công, thủ pháp, chí công, vô tư"},{"key":"B","text":"Cần, kiệm, liêm ,chính"},{"key":"C","text":"Liêm khiết, cần, kiệm, chí công vô tư"},{"key":"D","text":"Trong sáng, liêm khiết, chí công vô tư"}]},{"n":184,"sec":"2. Nhà nước pháp quyền","stem":"Quan niệm “Pháp quyền nhân nghĩa” của Hồ Chí Minh nhấn mạnh điều gì trước hết?","answer":"C","options":[{"key":"A","text":"Nhà nước phải đặt lợi ích quốc gia lên hàng đầu"},{"key":"B","text":"Nhà nước cần kiểm soát toàn bộ quyền lực xã hội"},{"key":"C","text":"Nhà nước phải tôn trọng và bảo đảm thực hiện đầy đủ các quyền con người, chăm lo đến lợi ích của mọi người"},{"key":"D","text":"Nhà nước phải ưu tiên phát triển công nghiệp nặng"}]},{"n":185,"sec":"2. Nhà nước pháp quyền","stem":"Theo tư tưởng Hồ Chí Minh, quyền con người bao gồm?","answer":"C","options":[{"key":"A","text":"Chỉ các quyền chính trị – dân sự"},{"key":"B","text":"Chỉ các quyền tự nhiên cơ bản như quyền sống"},{"key":"C","text":"Các quyền chính trị – dân sự, quyền kinh tế, văn hóa, xã hội và quyền sống"},{"key":"D","text":"Chỉ các quyền kinh tế trong điều kiện đặc biệt"}]},{"n":186,"sec":"2. Nhà nước pháp quyền","stem":"Hồ Chí Minh đề cập đến các quyền tự nhiên của con người, trong đó quyền cao nhất là?","answer":"A","options":[{"key":"A","text":"Quyền sống"},{"key":"B","text":"Quyền tự do tín ngưỡng và tôn giáo"},{"key":"C","text":"Quyền được học tập và phát triển toàn diện"},{"key":"D","text":"Quyền tham gia vào các tổ chức chính trị – xã hội"}]},{"n":187,"sec":"2. Nhà nước pháp quyền","stem":"Tính nhân văn của pháp luật theo tư tưởng Hồ Chí Minh thể hiện ở?","answer":"D","options":[{"key":"A","text":"Xử phạt nghiêm khắc để răn đe toàn xã hội"},{"key":"B","text":"Coi trọng kỷ luật sắt và chế tài mạnh tay"},{"key":"C","text":"Giảm án tù cho mọi hành vi vi phạm nhỏ"},{"key":"D","text":"Bảo vệ quyền con người, nghiêm minh nhưng khách quan, công bằng và khuyến thiện"}]},{"n":188,"sec":"2. Nhà nước pháp quyền","stem":"Ngay khi thành lập, Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa đã?","answer":"A","options":[{"key":"A","text":"Lập tức tuyên bố xoá bỏ mọi luật pháp hà khắc của chính quyền thực dân phản động"},{"key":"B","text":"Tuyên bố duy trì một số luật cũ để ổn định xã hội"},{"key":"C","text":"Trưng cầu dân ý về cải cách luật pháp"},{"key":"D","text":"Giữ nguyên hệ thống pháp luật để đảm bảo tính kế thừa"}]},{"n":189,"sec":"2. Nhà nước pháp quyền","stem":"Trong tư tưởng Hồ Chí Minh, việc thi hành pháp luật cần phải?","answer":"B","options":[{"key":"A","text":"Dựa vào luật quốc tế hơn là luật trong nước"},{"key":"B","text":"Dựa trên nền tảng đạo đức xã hội, coi trọng giáo dục và cảm hóa con người"},{"key":"C","text":"Cứng rắn và không cần thỏa hiệp với sai trái"},{"key":"D","text":"Tuân thủ mô hình pháp quyền xã hội chủ nghĩa kiểu Trung Quốc"}]},{"n":190,"sec":"2. Nhà nước pháp quyền","stem":"Pháp luật trong Nhà nước pháp quyền nhân nghĩa phải là?","answer":"C","options":[{"key":"A","text":"Hệ thống kiểm soát hành vi hiệu quả trong xã hội"},{"key":"B","text":"Công cụ duy trì trật tự và ổn định chính trị"},{"key":"C","text":"Pháp luật vì con người, gắn với đạo đức và nhân văn"},{"key":"D","text":"Quy định cứng rắn để nâng cao hiệu lực nhà nước"}]},{"n":191,"sec":"2. Nhà nước pháp quyền","stem":"Trong tư tưởng “pháp quyền nhân nghĩa” của Hồ Chí Minh, pháp luật có đặc điểm gì nổi bật?","answer":"D","options":[{"key":"A","text":"Mang tính cưỡng chế cao để đảm bảo trật tự xã hội"},{"key":"B","text":"Đặt mục tiêu kiểm soát hành vi con người làm trung tâm"},{"key":"C","text":"Nhấn mạnh vai trò trừng phạt để răn đe và ngăn ngừa vi phạm"},{"key":"D","text":"Có tính nhân văn, khuyến thiện, bảo vệ cái đúng và cảm hóa con người"}]},{"n":192,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Để giữ vững bản chất của Nhà nước, bảo đảm cho Nhà nước hoạt động có hiệu quả, phòng chống thoái hóa, biến chất trong đội ngũ cán bộ Nhà nước, Hồ Chí Minh rất chú trọng vấn đề nào?","answer":"C","options":[{"key":"A","text":"Nâng cao trình độ chuyên môn và kỹ năng hành chính cho cán bộ"},{"key":"B","text":"Xây dựng đội ngũ cán bộ trung thành tuyệt đối với tổ chức Đảng"},{"key":"C","text":"Kiểm soát quyền lực nhà nước một cách chặt chẽ và có hệ thống"},{"key":"D","text":"Tăng cường áp dụng kỷ luật nghiêm khắc đối với cán bộ sai phạm"}]},{"n":193,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, vì sao cần kiểm soát quyền lực nhà nước?","answer":"D","options":[{"key":"A","text":"Vì cán bộ dễ bị tác động bởi yếu tố nước ngoài"},{"key":"B","text":"Vì quyền lực cần được tập trung về trung ương"},{"key":"C","text":"Vì quyền lực nhà nước thuộc về Đảng nên cần giữ bí mật nội bộ"},{"key":"D","text":"Vì quyền lực là do nhân dân ủy thác, dễ bị lạm dụng nếu không được kiểm soát"}]},{"n":194,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh cho rằng, các cán bộ nhà nước dễ lạm dụng quyền lực vì?","answer":"D","options":[{"key":"A","text":"Có nhiều đặc quyền trong xã hội phong kiến để lại"},{"key":"B","text":"Chịu ảnh hưởng của chủ nghĩa cá nhân tư sản"},{"key":"C","text":"Được ưu tiên đào tạo từ các trường chính trị nên dễ chủ quan"},{"key":"D","text":"Không hiểu nhiệm vụ, chính sách và dễ ngông nghênh, cậy thế, cậy quyền"}]},{"n":195,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Tổ chức nào có quyền và trách nhiệm kiểm soát quyền lực nhà nước theo tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Chủ tịch nước và Bộ Chính trị"},{"key":"B","text":"Quốc hội và Viện kiểm sát nhân dân"},{"key":"C","text":"Đảng Cộng sản Việt Nam, với vai trò lãnh đạo toàn diện xã hội"},{"key":"D","text":"Mặt trận Tổ quốc và các tổ chức quần chúng"}]},{"n":196,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, muốn kiểm soát quyền lực nhà nước có kết quả tốt cần điều kiện gì?","answer":"B","options":[{"key":"A","text":"Được thực hiện bởi các cơ quan tư pháp độc lập"},{"key":"B","text":"Phải có hệ thống và người đi kiểm soát phải là những người rất có uy tín"},{"key":"C","text":"Có ngân sách rõ ràng và quy trình kỹ thuật minh bạch"},{"key":"D","text":"Phải có sự hỗ trợ của các tổ chức quốc tế"}]},{"n":197,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hai cách kiểm soát quyền lực được Hồ Chí Minh đề cập là?","answer":"B","options":[{"key":"A","text":"Trực tiếp và gián tiếp"},{"key":"B","text":"Từ trên xuống và từ dưới lên"},{"key":"C","text":"Nội bộ và bên ngoài"},{"key":"D","text":"Dân sự và quân sự"}]},{"n":198,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, chủ thể tối cao của quyền lực nhà nước là?","answer":"D","options":[{"key":"A","text":"Đảng Cộng sản Việt Nam"},{"key":"B","text":"Quốc hội"},{"key":"C","text":"Chính phủ"},{"key":"D","text":"Nhân dân"}]},{"n":199,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Nhân dân là chủ thể tối cao của quyền lực Nhà nước, vì thế, nhân dân có quyền gì?","answer":"B","options":[{"key":"A","text":"Chỉ tham gia các hoạt động bầu cử và giám sát định kỳ 5 năm"},{"key":"B","text":"Kiểm soát quyền lực Nhà nước"},{"key":"C","text":"Yêu cầu cán bộ nhà nước thực hiện nghị quyết của Đảng"},{"key":"D","text":"Chuyển giao toàn bộ quyền lực cho cơ quan lập pháp và hành pháp"}]},{"n":200,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, “giặc nội xâm” nguy hiểm hơn “giặc ngoại xâm” bao gồm các hiện tượng nào sau đây?","answer":"C","options":[{"key":"A","text":"Bệnh thành tích, thiếu minh bạch và vi phạm đạo đức công vụ"},{"key":"B","text":"Tham nhũng chính sách, lợi ích nhóm và bè phái"},{"key":"C","text":"Tham ô, lãng phí và bệnh quan liêu"},{"key":"D","text":"Cửa quyền, lạm dụng quyền lực và che giấu sai phạm"}]},{"n":201,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, đâu là nguyên nhân chủ quan sâu xa nhất dẫn đến các hiện tượng tiêu cực trong Nhà nước?","answer":"B","options":[{"key":"A","text":"Tác động của các thế lực thù địch chống phá Nhà nước"},{"key":"B","text":"Căn “bệnh mẹ” là chủ nghĩa cá nhân"},{"key":"C","text":"Cơ chế vận hành thiếu minh bạch và chưa khoa học"},{"key":"D","text":"Chính sách tuyển dụng chưa phù hợp và không công khai"}]},{"n":202,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh nhận định, muốn chống tham ô, lãng phí thì trước hết phải làm gì?","answer":"C","options":[{"key":"A","text":"Kiểm tra, xử lý nghiêm các sai phạm rõ ràng, minh bạch"},{"key":"B","text":"Xây dựng hệ thống pháp luật nghiêm minh và đồng bộ"},{"key":"C","text":"Tẩy sạch bệnh quan liêu – gốc sinh ra hai căn bệnh kia"},{"key":"D","text":"Đào tạo cán bộ chuyên môn vững, phẩm chất tốt"}]},{"n":203,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh ví những người lạm dụng chức quyền, làm lợi cho bản thân là gì?","answer":"A","options":[{"key":"A","text":"Là những người sa vào chủ nghĩa cá nhân"},{"key":"B","text":"Là những người thiếu hiểu biết chính trị sâu sắc"},{"key":"C","text":"Là thành phần cơ hội, không đủ tư cách cách mạng"},{"key":"D","text":"Là cán bộ thoái hóa, biến chất cần bị loại bỏ"}]},{"n":204,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Biện pháp căn bản và có ý nghĩa lâu dài nhất để chống tiêu cực theo Hồ Chí Minh là gì?","answer":"B","options":[{"key":"A","text":"Nâng cao năng lực lãnh đạo và phẩm chất cán bộ"},{"key":"B","text":"Nâng cao dân chủ xã hội, phát huy quyền làm chủ nhân dân"},{"key":"C","text":"Thường xuyên đổi mới cơ chế kiểm tra, giám sát nội bộ"},{"key":"D","text":"Tăng cường xử lý vi phạm, xử phạt nghiêm minh"}]},{"n":205,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Một trong những biện pháp được Hồ Chí Minh nhấn mạnh trong giáo dục cán bộ là gì?","answer":"C","options":[{"key":"A","text":"Tập trung vào đào tạo lý luận chính trị và chuyên môn sâu"},{"key":"B","text":"Coi trọng thi đua khen thưởng và xử phạt hành chính"},{"key":"C","text":"Lấy giáo dục đạo đức, cảm hóa làm chủ yếu"},{"key":"D","text":"Ưu tiên tuyển dụng cán bộ trẻ, năng động và sáng tạo"}]},{"n":206,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Cán bộ, nhất là người đứng đầu, cần có thái độ như thế nào để chống tiêu cực hiệu quả?","answer":"D","options":[{"key":"A","text":"Phải làm gương trong tuân thủ quy định và pháp luật"},{"key":"B","text":"Phải biết tổ chức, điều hành đơn vị một cách khoa học"},{"key":"C","text":"Phải tránh rơi vào cám dỗ quyền lực, giữ gìn hình ảnh"},{"key":"D","text":"Phải nêu gương, tu dưỡng đạo đức cách mạng"}]},{"n":207,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, yếu tố quyết định sự thành công của công cuộc xây dựng Nhà nước là gì?","answer":"C","options":[{"key":"A","text":"Năng lực hành chính của cán bộ trong hệ thống công quyền"},{"key":"B","text":"Sự tham gia rộng rãi của quần chúng nhân dân vào quản lý nhà nước"},{"key":"C","text":"Sự trong sạch, vững mạnh của Đảng cầm quyền"},{"key":"D","text":"Việc cải cách hành chính và số hóa hệ thống quản lý công"}]},{"n":208,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, những căn bệnh như “đặc quyền, đặc lợi” biểu hiện của điều gì?","answer":"C","options":[{"key":"A","text":"Sự vận hành thiếu hiệu quả của thể chế chính trị"},{"key":"B","text":"Tác động từ nền kinh tế thị trường chưa kiểm soát"},{"key":"C","text":"Sự lạm dụng quyền lực để thu lợi cá nhân, sa vào chủ nghĩa cá nhân"},{"key":"D","text":"Ảnh hưởng tiêu cực từ phong tục tập quán cũ"}]},{"n":209,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh ví ba căn bệnh tham ô, lãng phí, quan liêu là gì?","answer":"A","options":[{"key":"A","text":"Giặc nội xâm, nguy hiểm hơn cả giặc ngoại xâm"},{"key":"B","text":"Ba căn bệnh kinh niên của nền hành chính cũ"},{"key":"C","text":"Những hiện tượng tạm thời của quá trình chuyển tiếp"},{"key":"D","text":"Các yếu tố phát sinh từ quá trình đô thị hóa"}]},{"n":210,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh nhấn mạnh pháp luật của Nhà nước phải như thế nào?","answer":"C","options":[{"key":"A","text":"Có tính mềm dẻo để phù hợp thực tiễn"},{"key":"B","text":"Được tuyên truyền sâu rộng trong nhân dân"},{"key":"C","text":"Nghiêm minh, không có vùng cấm, bất kể người vi phạm là ai"},{"key":"D","text":"Luôn ưu tiên khoan hồng cho cán bộ"}]},{"n":211,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, bệnh quan liêu là?","answer":"D","options":[{"key":"A","text":"Hệ quả tất yếu trong giai đoạn chuyển tiếp của cách mạng"},{"key":"B","text":"Hệ quả của công tác tổ chức chưa tốt"},{"key":"C","text":"Bệnh không nguy hiểm nếu được giám sát đúng mức"},{"key":"D","text":"Bệnh gốc sinh ra tham ô và lãng phí"}]},{"n":212,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, công tác kiểm tra cán bộ phải được thực hiện như thế nào?","answer":"C","options":[{"key":"A","text":"Định kỳ mỗi quý do cấp trên chỉ đạo"},{"key":"B","text":"Chỉ khi có dấu hiệu vi phạm rõ ràng"},{"key":"C","text":"Thường xuyên, kết hợp tự giác và bắt buộc"},{"key":"D","text":"Phối hợp giữa kiểm tra nội bộ và dân lập"}]},{"n":213,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh lên án hành vi kéo bè, kéo cánh vì hậu quả gì?","answer":"C","options":[{"key":"A","text":"Gây lãng phí nhân lực trong bộ máy nhà nước"},{"key":"B","text":"Làm suy yếu nền kinh tế quốc dân"},{"key":"C","text":"Làm tổn hại uy tín của Đảng trong cộng đồng quốc tế"},{"key":"D","text":"Gây mất đoàn kết, rối loạn trong công tác chính quyền"}]},{"n":214,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh coi cán bộ giữ chức vụ càng cao thì càng phải?","answer":"D","options":[{"key":"A","text":"Biết bảo vệ uy tín bản thân và tập thể"},{"key":"B","text":"Chịu sự giám sát khắt khe hơn từ cơ quan chức năng"},{"key":"C","text":"Tự chủ động đề xuất cải cách hành chính"},{"key":"D","text":"Có trách nhiệm nêu gương về đạo đức và hành động"}]},{"n":215,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Những nguyên nhân khách quan dẫn đến tiêu cực được Hồ Chí Minh nêu gồm?","answer":"C","options":[{"key":"A","text":"Sự phát triển mạnh của kinh tế tư nhân"},{"key":"B","text":"Tác động từ toàn cầu hóa và thương mại hóa"},{"key":"C","text":"Tàn dư phong kiến, kẻ thù phá hoại và hệ thống tổ chức chưa tốt"},{"key":"D","text":"Thiếu vốn đầu tư và lạm phát kéo dài"}]},{"n":216,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Hồ Chí Minh ví những người cán bộ “có quyền mà thiếu lương tâm” là?","answer":"C","options":[{"key":"A","text":"Những người cần được nhắc nhở, cảm hóa nhẹ nhàng"},{"key":"B","text":"Những kẻ đáng bị truy cứu hình sự không khoan nhượng"},{"key":"C","text":"Có cơ hội để đục khoét, “dĩ công vi tư” nếu không được rèn luyện"},{"key":"D","text":"Những cá nhân không đủ năng lực, cần được đào tạo lại"}]},{"n":217,"sec":"3. Nhà nước trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, lòng yêu nước có vai trò gì trong chống tiêu cực?","answer":"B","options":[{"key":"A","text":"Là tinh thần nền tảng để thực hiện cải cách chính trị"},{"key":"B","text":"Là nguồn sức mạnh nội tại chống lại cái xấu, cái ác trong xã hội"},{"key":"C","text":"Là một yếu tố phụ trợ trong quá trình hành pháp"},{"key":"D","text":"Là một khía cạnh cần được cân nhắc trong xây dựng pháp luật"}]},{"n":218,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, muốn xây dựng Đảng trong sạch, vững mạnh thì điều đầu tiên cần phải làm là gì?","answer":"C","options":[{"key":"A","text":"Tăng cường số lượng đảng viên để nâng cao sức mạnh tổ chức"},{"key":"B","text":"Xây dựng cơ sở vật chất đầy đủ cho các cơ quan đảng"},{"key":"C","text":"Đề ra đường lối, chủ trương đúng đắn phù hợp với hoàn cảnh đất nước"},{"key":"D","text":"Thay đổi cơ cấu tổ chức các cơ quan trong hệ thống chính trị"}]},{"n":219,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Chủ trương, đường lối của Đảng cần được xây dựng trên nền tảng lý luận nào?","answer":"D","options":[{"key":"A","text":"Chủ nghĩa xã hội dân chủ Bắc Âu và tư tưởng dân tộc"},{"key":"B","text":"Chủ nghĩa duy tâm biện chứng và triết lý phương Đông"},{"key":"C","text":"Chủ nghĩa thực dụng và lý thuyết cải cách toàn cầu"},{"key":"D","text":"Chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh"}]},{"n":220,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Đội ngũ nào có vai trò đặc biệt quan trọng trong việc tổ chức thực hiện chủ trương, đường lối của Đảng?","answer":"C","options":[{"key":"A","text":"Cán bộ tuyên giáo cấp cơ sở và đoàn thanh niên"},{"key":"B","text":"Công chức hành chính và nhân viên truyền thông"},{"key":"C","text":"Cán bộ, đảng viên, nhất là cán bộ chiến lược và người đứng đầu"},{"key":"D","text":"Lực lượng vũ trang và tình nguyện viên địa phương"}]},{"n":221,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Vì sao Hồ Chí Minh nhấn mạnh việc “thống nhất giữa nói và làm” trong Đảng?","answer":"C","options":[{"key":"A","text":"Vì đây là biểu hiện rõ ràng nhất của năng lực quản lý hành chính trong tổ chức Đảng"},{"key":"B","text":"Vì nó giúp xây dựng hình ảnh Đảng hiện đại, hội nhập quốc tế sâu rộng"},{"key":"C","text":"Vì sự thiếu nhất quán giữa nói và làm làm mất lòng tin của nhân dân với Đảng"},{"key":"D","text":"Vì điều này liên quan trực tiếp đến năng suất lao động trong các cơ quan Đảng"}]},{"n":222,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, Đảng phải luôn xứng đáng là gì?","answer":"D","options":[{"key":"A","text":"Người hướng dẫn học tập cho quần chúng nhân dân"},{"key":"B","text":"Tổ chức đại diện cho tinh thần dân tộc trong thời đại mới"},{"key":"C","text":"Tổ chức trung gian giữa chính quyền và nhân dân"},{"key":"D","text":"Người cầm quyền và người đày tớ thật trung thành của nhân dân"}]},{"n":223,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Theo Hồ Chí Minh, để đường lối, chủ trương của Đảng phát huy hiệu quả, điều quan trọng là gì?","answer":"C","options":[{"key":"A","text":"Ban hành các chính sách phù hợp theo từng quý"},{"key":"B","text":"Tập trung vào phát triển cơ sở vật chất và kỹ thuật hiện đại"},{"key":"C","text":"Biến đường lối thành hành động tích cực trong toàn bộ hệ thống chính trị"},{"key":"D","text":"Đào tạo nhân sự mới thay thế toàn bộ bộ máy hiện tại"}]},{"n":224,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Hồ Chí Minh yêu cầu người đứng đầu Đảng và chính quyền cần làm gì?","answer":"B","options":[{"key":"A","text":"Thể hiện tinh thần trách nhiệm qua báo cáo định kỳ"},{"key":"B","text":"Nêu cao trách nhiệm nêu gương để quần chúng noi theo"},{"key":"C","text":"Tổ chức hội nghị, tọa đàm để tuyên truyền chủ trương"},{"key":"D","text":"Thường xuyên thay đổi phương pháp điều hành, chỉ đạo"}]},{"n":225,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Theo nội dung tư tưởng Hồ Chí Minh, hình ảnh Đảng được lý tưởng hóa như thế nào?","answer":"C","options":[{"key":"A","text":"Đảng là hiện thân của trí tuệ tập thể và quyền lực nhân dân"},{"key":"B","text":"Đảng là tấm gương cho các tổ chức quốc tế học hỏi"},{"key":"C","text":"Đảng là đạo đức, là văn minh"},{"key":"D","text":"Đảng là tổ chức chính trị duy nhất mang tính cách mạng"}]},{"n":226,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Những sinh viên đang là đảng viên của Đảng cần chú trọng điều gì?","answer":"A","options":[{"key":"A","text":"Thực hiện thật tốt đường lối, quan điểm, chủ trương, điều lệ Đảng, phải là công dân gương mẫu và là sinh viên tốt"},{"key":"B","text":"Phấn đấu trở thành cán bộ lãnh đạo trong tổ chức Đảng và Nhà nước"},{"key":"C","text":"Tích cực hoạt động phong trào và tham gia các hội nhóm sinh viên"},{"key":"D","text":"Thường xuyên tổ chức tuyên truyền về chủ nghĩa xã hội trong sinh viên"}]},{"n":227,"sec":"1. Xây dựng Đảng thật sự trong sạch, vững mạnh","stem":"Theo tư tưởng Hồ Chí Minh, sinh viên chưa là đảng viên cần làm gì?","answer":"C","options":[{"key":"A","text":"Tham gia đầy đủ các hoạt động phong trào và các câu lạc bộ học thuật"},{"key":"B","text":"Tập trung học ngoại ngữ và kỹ năng mềm để hội nhập quốc tế"},{"key":"C","text":"Nghiên cứu, học tập tốt tư tưởng Hồ Chí Minh, phấn đấu trở thành đảng viên hoặc người tích cực ủng hộ Đảng"},{"key":"D","text":"Học tập để trở thành chuyên gia kỹ thuật phục vụ công nghiệp hóa"}]},{"n":228,"sec":"2. Xây dựng Nhà nước","stem":"Hồ Chí Minh cho rằng để kiểm soát tốt quyền lực nhà nước, cần thực hiện điều gì?","answer":"B","options":[{"key":"A","text":"Giới hạn nhiệm kỳ các cơ quan lập pháp và hành pháp"},{"key":"B","text":"Thiết lập rõ cơ chế phối hợp giữa các cơ quan nhà nước"},{"key":"C","text":"Tách biệt hoàn toàn các cơ quan lập pháp và tư pháp"},{"key":"D","text":"Tăng cường ngân sách cho công tác thanh tra, kiểm toán"}]},{"n":229,"sec":"2. Xây dựng Nhà nước","stem":"Theo tư tưởng Hồ Chí Minh, mục tiêu cuối cùng của xây dựng Nhà nước là gì?","answer":"C","options":[{"key":"A","text":"Đưa đất nước phát triển nhanh hơn các quốc gia láng giềng"},{"key":"B","text":"Bảo đảm an ninh quốc phòng trong mọi hoàn cảnh lịch sử"},{"key":"C","text":"Làm cho đất nước hùng cường, nhân dân ấm no, tự do, hạnh phúc"},{"key":"D","text":"Duy trì thể chế chính trị ổn định qua mọi thời kỳ"}]},{"n":230,"sec":"2. Xây dựng Nhà nước","stem":"Theo tư tưởng Hồ Chí Minh, pháp luật có vai trò như thế nào trong quản lý xã hội và thực hiện quyền làm chủ của nhân dân?","answer":"D","options":[{"key":"A","text":"Pháp luật là công cụ hành chính chủ yếu của hệ thống chính trị để trấn áp sai phạm"},{"key":"B","text":"Pháp luật chỉ nhằm phục vụ các quyết sách của cơ quan lập pháp"},{"key":"C","text":"Pháp luật giúp củng cố vai trò của các tổ chức đảng trong Nhà nước"},{"key":"D","text":"Pháp luật là công cụ để Nhà nước quản lý xã hội và để nhân dân làm chủ, kiểm tra, giám sát quyền lực nhà nước"}]},{"n":231,"sec":"2. Xây dựng Nhà nước","stem":"Tư tưởng Hồ Chí Minh yêu cầu phải hoàn thiện hệ thống pháp luật theo hướng nào?","answer":"B","options":[{"key":"A","text":"Ưu tiên tính linh hoạt của luật hơn là sự ổn định lâu dài"},{"key":"B","text":"Tôn trọng, bảo đảm và bảo vệ quyền con người, quyền và nghĩa vụ công dân"},{"key":"C","text":"Chuyển hóa hệ thống pháp luật theo xu hướng pháp luật quốc tế hiện đại"},{"key":"D","text":"Tập trung điều chỉnh hoạt động nội bộ của các cơ quan nhà nước"}]},{"n":232,"sec":"2. Xây dựng Nhà nước","stem":"Theo tư tưởng Hồ Chí Minh, việc phân công, phối hợp thực thi quyền lực nhà nước cần dựa trên nguyên tắc nào?","answer":"A","options":[{"key":"A","text":"Quyền lực nhà nước là thống nhất, có cơ chế kiểm soát giữa các cơ quan lập pháp, hành pháp, tư pháp"},{"key":"B","text":"Tăng cường sự phân quyền triệt để giữa ba nhánh quyền lực để hạn chế lạm quyền"},{"key":"C","text":"Tách biệt hoàn toàn giữa Trung ương và địa phương nhằm nâng cao tự trị địa phương"},{"key":"D","text":"Phân quyền cho các tổ chức xã hội dân sự tham gia quản lý các lĩnh vực trọng yếu"}]},{"n":233,"sec":"2. Xây dựng Nhà nước","stem":"Để xây dựng Nhà nước vững mạnh, cần chú trọng xây dựng đội ngũ cán bộ, công chức có những phẩm chất nào?","answer":"C","options":[{"key":"A","text":"Có tinh thần cầu tiến, biết thích nghi với môi trường làm việc toàn cầu hóa"},{"key":"B","text":"Có quan hệ tốt trong bộ máy, biết tạo ảnh hưởng và gây dựng uy tín chính trị"},{"key":"C","text":"Có bản lĩnh chính trị vững vàng, phẩm chất đạo đức trong sáng, năng lực chuyên môn phù hợp"},{"key":"D","text":"Có trình độ ngoại ngữ và tin học cao để phục vụ cải cách hành chính số"}]},{"n":234,"sec":"2. Xây dựng Nhà nước","stem":"Tư tưởng Hồ Chí Minh đề cao biện pháp nào trong công tác tuyển chọn cán bộ?","answer":"B","options":[{"key":"A","text":"Đề xuất của cấp trên và tín nhiệm của tập thể lãnh đạo"},{"key":"B","text":"Thực hiện dân chủ hóa, mở rộng thi tuyển, dân trực tiếp bầu một số chức danh ở cơ sở và cấp huyện"},{"key":"C","text":"Bổ nhiệm dựa trên số năm công tác và thành tích trong cơ quan"},{"key":"D","text":"Lựa chọn qua kỳ kiểm tra hành chính, do các tổ chức trung ương tiến hành"}]},{"n":235,"sec":"2. Xây dựng Nhà nước","stem":"Theo tư tưởng Hồ Chí Minh, tiêu chí đánh giá, bổ nhiệm cán bộ cần dựa trên yếu tố nào?","answer":"B","options":[{"key":"A","text":"Tính sáng tạo trong công việc và khả năng tổ chức nhân sự"},{"key":"B","text":"Bản lĩnh chính trị, phẩm chất đạo đức, năng lực và hiệu quả thực thi nhiệm vụ"},{"key":"C","text":"Khả năng huy động tài chính và xây dựng mạng lưới đối ngoại"},{"key":"D","text":"Mức độ hoàn thành các chương trình đào tạo và bồi dưỡng nghiệp vụ"}]},{"n":236,"sec":"2. Xây dựng Nhà nước","stem":"Để nâng cao hiệu lực, hiệu quả của Nhà nước, theo tư tưởng Hồ Chí Minh, Đảng cần chú trọng điều gì?","answer":"D","options":[{"key":"A","text":"Hợp tác với các tổ chức quốc tế nhằm tăng năng lực thể chế"},{"key":"B","text":"Giảm vai trò can thiệp vào hoạt động của các bộ, ngành cụ thể"},{"key":"C","text":"Phân cấp hoàn toàn cho địa phương tự quyết các vấn đề về tổ chức bộ máy"},{"key":"D","text":"Đổi mới phương thức lãnh đạo, nâng cao chất lượng lập pháp, cải cách hành chính và tư pháp"}]},{"n":237,"sec":"2. Xây dựng Nhà nước","stem":"Theo tư tưởng Hồ Chí Minh, sự trong sạch, vững mạnh của Đảng có vai trò gì đối với Nhà nước?","answer":"A","options":[{"key":"A","text":"Là yếu tố quyết định cho sự thành công của việc xây dựng Nhà nước"},{"key":"B","text":"Là điều kiện cần nhưng chưa đủ cho hoạt động của các cơ quan công quyền"},{"key":"C","text":"Là một tiêu chí phụ trong tiêu chuẩn đạo đức cán bộ công chức"},{"key":"D","text":"Là cơ sở để thiết lập mối quan hệ giữa nhà nước và các tổ chức quốc tế"}]}]},{"id":"V","title":"TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN DÂN TỘC VÀ ĐOÀN KẾT QUỐC TẾ","questions":[{"n":1,"sec":"","stem":"Tư tưởng đại đoàn kết dân tộc của Hồ Chí Minh hình thành trên cơ sở nào?","answer":"D","options":[{"key":"A","text":"Từ truyền thống yêu nước, nhân ái, tinh thần cố kết cộng đồng dân tộc Việt Nam"},{"key":"B","text":"Từ quan điểm của Chủ nghĩa Mác - Lênin về cách mạng giải phóng dân tộc, về vai trò của quần chúng nhân dân trong cách mạng"},{"key":"C","text":"Từ tổng kết kinh nghiệm thành công và thất bại của các phong trào yêu nước, phong trào cách mạng Việt Nam và thế giới"},{"key":"D","text":"Cả A, B, C"}]},{"n":2,"sec":"","stem":"Theo tư tưởng Hồ Chí Minh, đại đoàn kết toàn dân tộc có vai trò như thế nào đối với cách mạng Việt Nam?","answer":"D","options":[{"key":"A","text":"Là một chiến lược ngắn hạn để giải quyết khó khăn tạm thời trong từng giai đoạn"},{"key":"B","text":"Là một sách lược linh hoạt, có thể thay đổi tùy hoàn cảnh chính trị"},{"key":"C","text":"Là một thủ đoạn chính trị để đạt được sự ủng hộ của quần chúng"},{"key":"D","text":"Là vấn đề có ý nghĩa chiến lược, quyết định thành công của cách mạng"}]},{"n":3,"sec":"","stem":"Trong tư tưởng Hồ Chí Minh, đại đoàn kết toàn dân tộc không phải là sách lược hay thủ đoạn chính trị mà là?","answer":"A","options":[{"key":"A","text":"Là chiến lược lâu dài, nhất quán của cách mạng Việt Nam"},{"key":"B","text":"Một hình thức tuyên truyền nhằm tạo đồng thuận xã hội"},{"key":"C","text":"Một chiến lược lâu dài, nhất quán của cách mạng Việt Nam"},{"key":"D","text":"Một biện pháp vận động chính trị linh hoạt theo từng thời kỳ"}]},{"n":4,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh nói rõ: “Sử dạy cho ta bài học này: Lúc nào dân ta (_____) muôn người như một thì nước ta độc lập, tự do. Trái lại lúc nào dân ta (_____) thì bị nước ngoài xâm lấn” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.3, tr.256).","answer":"D","options":[{"key":"A","text":"Đoàn kết – chia rẽ"},{"key":"B","text":"Yêu nước – không yêu nước"},{"key":"C","text":"Quyết tâm – thiếu niềm tin"},{"key":"D","text":"Đoàn kết – không đoàn kết"}]},{"n":5,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh đã nêu: “Bây giờ còn một điểm rất quan trọng, cũng là (_____). Điểm này mà thực hiện tốt thì đẻ ra con cháu đều tốt: Đó là (_____)”","answer":"B","options":[{"key":"A","text":"Điểm then chốt – Khởi nghĩa"},{"key":"B","text":"Điểm mẹ – Đoàn kết"},{"key":"C","text":"Điểm nền tảng – Dân tộc"},{"key":"D","text":"Điểm trung tâm – Cách mạng"}]},{"n":6,"sec":"","stem":"Trong từng giai đoạn cách mạng, Hồ Chí Minh cho rằng việc điều chỉnh chính sách đoàn kết là?","answer":"A","options":[{"key":"A","text":"Cần thiết, nhưng không được thay đổi chủ trương đại đoàn kết toàn dân tộc"},{"key":"B","text":"Phụ thuộc vào việc phân tầng xã hội và sự phát triển kinh tế"},{"key":"C","text":"Do Trung ương Đảng quyết định theo các chương trình hành động cụ thể"},{"key":"D","text":"Chỉ cần thiết trong thời kỳ chuyển tiếp lên chủ nghĩa xã hội"}]},{"n":7,"sec":"","stem":"Hồ Chí Minh khẳng định điều gì về vai trò của đoàn kết?","answer":"C","options":[{"key":"A","text":"Là yếu tố hỗ trợ trong công tác vận động quần chúng"},{"key":"B","text":"Là một trong những điều kiện để cải cách hành chính thành công"},{"key":"C","text":"Là sức mạnh, là then chốt của thành công, là lực lượng vô địch để giành thắng lợi"},{"key":"D","text":"Là biện pháp chủ yếu để phát triển lực lượng quân sự của đất nước"}]},{"n":8,"sec":"","stem":"Luận điểm nổi tiếng thể hiện tinh thần đoàn kết trong tư tưởng Hồ Chí Minh là?","answer":"D","options":[{"key":"A","text":"“Dân tộc mạnh là dân tộc biết học hỏi lẫn nhau”"},{"key":"B","text":"“Đoàn kết là phẩm chất của người cách mạng hiện đại”"},{"key":"C","text":"“Đoàn kết là sức mạnh trong thời bình, đấu tranh là vũ khí trong thời chiến”"},{"key":"D","text":"“Đoàn kết, đoàn kết, đại đoàn kết – Thành công, thành công, đại thành công”"}]},{"n":9,"sec":"","stem":"Đối với Hồ Chí Minh, đại đoàn kết không chỉ là khẩu hiệu chiến lược mà còn là?","answer":"A","options":[{"key":"A","text":"Là mục tiêu lâu dài của cách mạng"},{"key":"B","text":"Một khẩu hiệu chính trị linh hoạt tùy thời điểm lịch sử"},{"key":"C","text":"Một giải pháp tranh thủ lòng dân trong thời kỳ chuyển đổi thể chế"},{"key":"D","text":"Một giải pháp tranh thủ lòng dân trong thời kỳ chuyển đổi thể chế"}]},{"n":10,"sec":"","stem":"Đại đoàn kết toàn dân tộc được Hồ Chí Minh xác định là nhiệm vụ hàng đầu của lực lượng nào?","answer":"B","options":[{"key":"A","text":"Mặt trận Tổ quốc và các tổ chức đoàn thể chính trị - xã hội"},{"key":"B","text":"Đảng – lực lượng lãnh đạo cách mạng Việt Nam"},{"key":"C","text":"Chính phủ và các cơ quan hành chính nhà nước"},{"key":"D","text":"Các tổ chức phi chính phủ hoạt động trong lĩnh vực dân tộc – tôn giáo"}]},{"n":11,"sec":"","stem":"Trong lời kết thúc buổi ra mắt Đảng Lao động Việt Nam ngày 3-3- 1951, Hồ Chí Minh tuyên bố mục đích của Đảng Lao động Việt Nam bằng cụm từ nào?","answer":"C","options":[{"key":"A","text":"“Giành độc lập, giữ chủ quyền, phát triển đất nước”"},{"key":"B","text":"“Xây dựng đất nước giàu mạnh, văn minh, hạnh phúc”"},{"key":"C","text":"“Đoàn kết toàn dân, phụng sự Tổ quốc”"},{"key":"D","text":"“Độc lập – Tự do – Hòa bình – Hợp tác”"}]},{"n":12,"sec":"","stem":"Theo Hồ Chí Minh, cách mạng là sự nghiệp của ai?","answer":"C","options":[{"key":"A","text":"Của Đảng tiên phong và những cá nhân xuất sắc trong xã hội"},{"key":"B","text":"Của các nhà tư tưởng, lãnh tụ và nhà hoạt động chính trị"},{"key":"C","text":"Của quần chúng, do quần chúng và vì quần chúng"},{"key":"D","text":"Của Nhà nước, với sự chỉ đạo toàn diện từ các cấp chính quyền"}]},{"n":13,"sec":"","stem":"Đại đoàn kết là yêu cầu khách quan của sự nghiệp cách mạng, là đòi hỏi khách quan của quần chúng nhân dân trong cuộc đấu tranh tự giải phóng bởi?","answer":"A","options":[{"key":"A","text":"Bởi nếu không đoàn kết thì chính họ sẽ thất bại trong cuộc đấu tranh vì lợi ích của chính mình"},{"key":"B","text":"Bởi nếu không đoàn kết, các nhóm xã hội sẽ bị phân hóa thành lực lượng đối lập"},{"key":"C","text":"Bởi các thế lực phản động dễ lợi dụng sự chia rẽ trong nội bộ dân tộc"},{"key":"D","text":"Bởi đại đoàn kết là điều kiện để tạo uy tín đối ngoại của đất nước"}]},{"n":14,"sec":"","stem":"Vai trò của Đảng trong việc tổ chức khối đại đoàn kết toàn dân tộc theo tư tưởng Hồ Chí Minh là gì?","answer":"D","options":[{"key":"A","text":"Chuyển hóa phong trào chính trị thành đường lối cứng rắn mang tính pháp lý"},{"key":"B","text":"Hạn chế sự chia rẽ bằng các biện pháp kiểm soát tư tưởng trong dân chúng"},{"key":"C","text":"Lãnh đạo lực lượng vũ trang kiểm soát tình hình, đảm bảo trật tự ổn định xã hội"},{"key":"D","text":"Thức tỉnh, tập hợp, hướng dẫn quần chúng và chuyển yêu cầu tự phát thành hành động tự giác có tổ chức"}]},{"n":15,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, chủ thể của khối đại đoàn kết toàn dân tộc là?","answer":"B","options":[{"key":"A","text":"Chỉ gồm công nhân, nông dân và trí thức yêu nước"},{"key":"B","text":"Toàn thể nhân dân Việt Nam yêu nước, ở các giai cấp, các tầng lớp trong xã hội, các ngành, các giới, các lứa tuổi, các dân tộc, đồng bào các tôn giáo, các đảng phái…"},{"key":"C","text":"Những người đã được kết nạp vào các tổ chức chính trị - xã hội có uy tín"},{"key":"D","text":"Người dân yêu nước đang sống và làm việc trong nước dưới sự lãnh đạo của Đảng"}]},{"n":16,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Trong tư tưởng Hồ Chí Minh, từ “nhân dân” được hiểu là?","answer":"D","options":[{"key":"A","text":"Lực lượng chính trị nòng cốt trong các phong trào cách mạng"},{"key":"B","text":"Những công dân có quyền bầu cử, ứng cử theo Hiến pháp"},{"key":"C","text":"Người lao động sống chủ yếu bằng sức lao động chân tay hoặc trí óc"},{"key":"D","text":"Vừa là con người Việt cụ thể, vừa là tập hợp đông đảo quần chúng nhân dân"}]},{"n":17,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Hồ Chí Minh còn chỉ rõ, trong quá trình xây dựng khối đại đoàn kết toàn dân tộc, phải đứng vững trên lập trường của giai cấp nào?","answer":"B","options":[{"key":"A","text":"Lập trường dân tộc gắn với lợi ích cộng đồng"},{"key":"B","text":"Lập trường giai cấp công nhân, giải quyết hài hòa mối quan hệ giữa giai cấp và dân tộc"},{"key":"C","text":"Lập trường chính trị – xã hội dựa trên nguyên tắc đại diện nhân dân"},{"key":"D","text":"Lập trường độc lập tự chủ về tư tưởng, không phụ thuộc vào giai cấp"}]},{"n":18,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Điền từ còn thiếu vào (_____)? Đại đoàn kết toàn dân tộc tức là phải tập hợp, đoàn kết được tất cả mọi người dân vào một khối thống nhất, không phân biệt (_____), (_____), (_____), (_____), (_____), lứa tuổi, giới tính, nghề nghiệp, ở trong nước hay ở ngoài nước cùng hướng vào mục tiêu chung, “ai có tài, có đức, có sức, có lòng phụng sự Tổ quốc và phục vụ nhân dân thì ta đoàn kết với họ”","answer":"A","options":[{"key":"A","text":"Dân tộc, giai cấp, tầng lớp, đảng phái, tôn giáo"},{"key":"B","text":"Nghề nghiệp, dân tộc, tôn giáo, đảng phái, sở thích"},{"key":"C","text":"Quốc tịch, dân tộc, độ tuổi, chính kiến, thành phần kinh tế"},{"key":"D","text":"Đảng phái, giới tính, vùng miền, học vấn, dân cư"}]},{"n":19,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Theo quan điểm của Hồ Chí Minh, đâu là lực lượng làm nền tảng cho khối đại đoàn kết toàn dân tộc?","answer":"C","options":[{"key":"A","text":"Cán bộ, đảng viên và các tổ chức chính trị – xã hội"},{"key":"B","text":"Quân đội, công an và lực lượng dân quân tự vệ"},{"key":"C","text":"Công nhân, nông dân và trí thức"},{"key":"D","text":"Doanh nhân, nhà khoa học và chuyên gia kỹ thuật"}]},{"n":20,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh chỉ rõ: “Đại đoàn kết tức là trước hết phải đoàn kết đại đa số nhân dân, mà đại đa số nhân dân là (_____), (_____) và (_____) khác. Đó là nền, gốc của đại đoàn kết. Nó cũng như cái nền của nhà, gốc của cây. Nhưng đã có nền vững, gốc tốt, còn phải đoàn kết các tầng lớp nhân dân khác”","answer":"C","options":[{"key":"A","text":"Nông dân, bộ đội, trí thức"},{"key":"B","text":"Công nhân, viên chức, nhà khoa học"},{"key":"C","text":"Công nhân, nông dân và các tầng lớp nhân dân lao động khác"},{"key":"D","text":"Quần chúng, thanh niên, tiểu thương"}]},{"n":21,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Trong khối đại đoàn kết toàn dân tộc, yếu tố “hạt nhân” được Hồ Chí Minh xác định là?","answer":"A","options":[{"key":"A","text":"Sự đoàn kết và thống nhất trong Đảng"},{"key":"B","text":"Tầng lớp thanh niên và sinh viên đi đầu trong các phong trào"},{"key":"C","text":"Sự đồng thuận của các tầng lớp xã hội trong thời bình"},{"key":"D","text":"Tính đồng thuận giữa các tôn giáo và dân tộc thiểu số"}]},{"n":22,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, sự đoàn kết của Đảng có vai trò như thế nào đối với khối đại đoàn kết toàn dân tộc?","answer":"B","options":[{"key":"A","text":"Là yếu tố phụ trợ, hỗ trợ cho các tổ chức xã hội thực hiện nhiệm vụ tuyên truyền"},{"key":"B","text":"Là điều kiện để tăng cường đoàn kết toàn dân tộc và gắn bó giữa Đảng với nhân dân"},{"key":"C","text":"Là cơ sở để chính quyền thực hiện cải cách pháp luật hiệu quả hơn"},{"key":"D","text":"Là mục tiêu cuối cùng của quá trình xây dựng xã hội dân chủ"}]},{"n":23,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Vì sao cần đặc biệt chú trọng sự đoàn kết trong Đảng khi xây dựng khối đại đoàn kết toàn dân tộc?","answer":"B","options":[{"key":"A","text":"Vì Đảng là cơ quan duy nhất quản lý hành chính và tư pháp"},{"key":"B","text":"Vì sự đoàn kết trong Đảng là điều kiện để tạo ra sự đoàn kết trong toàn xã hội"},{"key":"C","text":"Vì Đảng giữ vai trò trung lập, giúp điều phối các luồng tư tưởng khác nhau"},{"key":"D","text":"Vì Đảng đại diện cho lực lượng sản xuất tiên tiến và khoa học công nghệ"}]},{"n":24,"sec":"2. Lực lượng của khối đại đoàn kết toàn dân tộc","stem":"Theo tư tưởng Hồ Chí Minh, sức mạnh bên trong của cách mạng Việt Nam để vượt qua khó khăn, thử thách bắt nguồn từ đâu?","answer":"A","options":[{"key":"A","text":"Sự gắn bó máu thịt giữa Đảng với nhân dân"},{"key":"B","text":"Sự viện trợ quốc tế và liên minh với các phong trào tiến bộ trên thế giới"},{"key":"C","text":"Năng lực quản trị và cải cách thể chế hành chính"},{"key":"D","text":"Sự lãnh đạo của Đảng trong phát triển công nghiệp hóa, hiện đại hóa"}]},{"n":25,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Để xây dựng khối đại đoàn kết toàn dân tộc, quy tụ, đoàn kết được mọi giai cấp, tầng lớp cần phải bảo đảm mấy điều kiện?","answer":"C","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]},{"n":26,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc?","answer":"D","options":[{"key":"A","text":"Phải lấy lợi ích chung làm điểm quy tụ, đồng thời tôn trọng các lợi ích khác biệt chính đáng"},{"key":"B","text":"Phải kế thừa truyền thống yêu nước, nhân nghĩa, đoàn kết của dân tộc"},{"key":"C","text":"Phải có lòng khoan dung, độ lượng với con người; phải có niềm tin vào nhân dân"},{"key":"D","text":"Cả A, B và C"}]},{"n":27,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Đâu KHÔNG PHẢI là điều kiện để xây dựng khối đại đoàn kết toàn dân tộc?","answer":"D","options":[{"key":"A","text":"Phải lấy lợi ích chung làm điểm quy tụ, đồng thời tôn trọng các lợi ích khác biệt chính đáng"},{"key":"B","text":"Phải kế thừa truyền thống yêu nước, nhân nghĩa, đoàn kết của dân tộc"},{"key":"C","text":"Phải có lòng khoan dung, độ lượng với con người; phải có niềm tin vào nhân dân"},{"key":"D","text":"Phải xây dựng xã hội dân chủ kiểu mới theo mô hình chủ nghĩa xã hội khoa học của Liên Xô"}]},{"n":28,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, điều kiện tiên quyết để quy tụ lực lượng toàn dân vào khối đại đoàn kết là gì?","answer":"B","options":[{"key":"A","text":"Phải dựa vào truyền thống yêu nước của người dân Việt Nam và giáo dục lòng yêu nước qua thế hệ trẻ"},{"key":"B","text":"Phải lấy lợi ích chung làm điểm quy tụ, đồng thời tôn trọng các lợi ích khác biệt chính đáng"},{"key":"C","text":"Phải tổ chức phong trào yêu nước rộng khắp và không ngừng kêu gọi đấu tranh giai cấp"},{"key":"D","text":"Phải dựa trên nguyên tắc thống nhất quan điểm tư tưởng giữa các tầng lớp nhân dân"}]},{"n":29,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Theo tư tưởng Hồ Chí Minh, cội nguồn sức mạnh để cả dân tộc chiến đấu và chiến thắng thiên tai, địch họa là gì?","answer":"C","options":[{"key":"A","text":"Sự chỉ đạo đúng đắn của Đảng và tinh thần cách mạng của quần chúng nhân dân"},{"key":"B","text":"Việc kết hợp giữa chủ nghĩa Mác – Lênin và truyền thống yêu nước"},{"key":"C","text":"Truyền thống yêu nước, nhân nghĩa, đoàn kết của dân tộc được hình thành trong quá trình dựng nước và giữ nước"},{"key":"D","text":"Vai trò của giai cấp công nhân và liên minh công - nông - trí thức"}]},{"n":30,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, việc xử lý các mối quan hệ lợi ích trong xã hội Việt Nam nhằm mục tiêu gì?","answer":"D","options":[{"key":"A","text":"Nhằm tạo ra sự cạnh tranh tích cực giữa các giai cấp và tầng lớp xã hội"},{"key":"B","text":"Nhằm thúc đẩy phát triển kinh tế - xã hội theo định hướng xã hội chủ nghĩa"},{"key":"C","text":"Nhằm phát huy vai trò trung tâm của giai cấp công nhân và giai cấp nông dân"},{"key":"D","text":"Nhằm tìm ra điểm tương đồng, lợi ích chung để đoàn kết các lực lượng"}]},{"n":31,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Lòng khoan dung, độ lượng trong đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh được hiểu là gì?","answer":"C","options":[{"key":"A","text":"Dung túng cho mọi hành vi sai trái nếu họ đã từng có đóng góp với cách mạng"},{"key":"B","text":"Không truy cứu trách nhiệm những người từng chống đối cách mạng nếu họ biết ăn năn"},{"key":"C","text":"Trân trọng phần thiện dù nhỏ nhất ở mỗi người để quy tụ và cảm hóa họ vì lợi ích cách mạng"},{"key":"D","text":"Tha thứ cho tất cả những người có lỗi mà không cần điều kiện nào để giữ khối đoàn kết"}]},{"n":32,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Hồ Chí Minh khẳng định: “Đã là con Lạc cháu Hồng thì ai cũng có ít hay nhiều lòng ái quốc”. Điều này nhấn mạnh đến yếu tố nào?","answer":"D","options":[{"key":"A","text":"Niềm tin vào khả năng lãnh đạo của các tầng lớp trong xã hội"},{"key":"B","text":"Vai trò của truyền thống lịch sử trong việc xác định phẩm chất con người"},{"key":"C","text":"Ý nghĩa của việc kết nối lịch sử dân tộc với quá trình cách mạng hiện tại"},{"key":"D","text":"Lòng khoan dung, độ lượng và sự tin tưởng vào bản chất yêu nước của mỗi người Việt"}]},{"n":33,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, truyền thống đoàn kết dân tộc có ý nghĩa gì trong việc xây dựng khối đại đoàn kết?","answer":"B","options":[{"key":"A","text":"Là nền tảng để phân loại các đối tượng cần quy tụ trong cách mạng"},{"key":"B","text":"Là giá trị bền vững, là cội nguồn sức mạnh để chiến thắng mọi kẻ thù và thiên tai"},{"key":"C","text":"Là tiêu chí để xây dựng các tổ chức chính trị - xã hội vững mạnh"},{"key":"D","text":"Là nguyên tắc được xác lập từ Hiến pháp và các chính sách của nhà nước Việt Nam"}]},{"n":34,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Theo Hồ Chí Minh, vì sao cần trân trọng phần thiện dù nhỏ nhất ở mỗi con người?","answer":"C","options":[{"key":"A","text":"Vì đó là dấu hiệu cho thấy sự chuyển hóa tích cực từ tư tưởng phản động sang cách mạng"},{"key":"B","text":"Vì mỗi người đều có thể trở thành cán bộ nếu được giác ngộ cách mạng"},{"key":"C","text":"Vì điều đó giúp tập hợp, quy tụ rộng rãi mọi lực lượng phục vụ cho sự nghiệp cách mạng"},{"key":"D","text":"Vì Nhà nước cần phát huy sức mạnh nhân lực trong quá trình xây dựng chủ nghĩa xã hội"}]},{"n":35,"sec":"3. Điều kiện để xây dựng khối đại đoàn kết toàn dân tộc","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh từng căn dặn đồng bào: “Năm ngón tay cũng có (_____), (_____). Nhưng văn dài đều họp nhau lại nơi bàn tay. Trong mấy triệu người cũng có người thế này hay thế khác, nhưng thế này hay thế khác đều dòng dõi của tổ tiên ta. Vậy nên ta phải khoan hồng đại độ (Hồ Chí Minh: Toàn tập,Nxb Chính trị quốc gia, Hà Nội, 2011, t.4, tr.280-281).","answer":"C","options":[{"key":"A","text":"Ngón to, ngón nhỏ"},{"key":"B","text":"Ngón cứng, ngón mềm"},{"key":"C","text":"Ngón vắn, ngón dài"},{"key":"D","text":"Ngón khỏe, ngón yếu"}]},{"n":36,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo Hồ Chí Minh, Mặt trận dân tộc thống nhất có vai trò như thế nào trong khối đại đoàn kết toàn dân tộc?","answer":"C","options":[{"key":"A","text":"Là tổ chức lãnh đạo trực tiếp phong trào cách mạng trên cả nước"},{"key":"B","text":"Là hình thức tập hợp toàn dân chủ yếu dựa trên cơ sở giai cấp công nhân"},{"key":"C","text":"Là nơi quy tụ mọi tổ chức và cá nhân yêu nước, tạo nên sức mạnh tổng hợp của dân tộc"},{"key":"D","text":"Là cơ quan thuộc hệ thống chính trị chịu sự điều hành trực tiếp của nhà nước"}]},{"n":37,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo Hồ Chí Minh, để khối đại đoàn kết toàn dân tộc trở thành lực lượng to lớn, có sức mạnh, cần điều kiện nào sau đây?","answer":"A","options":[{"key":"A","text":"Phải được tổ chức lại thành một khối vững chắc, đó là Mặt trận dân tộc thống nhất"},{"key":"B","text":"Phải có sự lãnh đạo của quân đội nhân dân Việt Nam"},{"key":"C","text":"Phải tập trung toàn bộ lực lượng vào đấu tranh giai cấp"},{"key":"D","text":"Phải xây dựng mô hình nhà nước pháp quyền xã hội chủ nghĩa"}]},{"n":38,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Mặt trận dân tộc thống nhất theo tư tưởng Hồ Chí Minh KHÔNG có đặc điểm nào sau đây?","answer":"B","options":[{"key":"A","text":"Là nơi quy tụ mọi giai cấp, tầng lớp, tổ chức, cá nhân yêu nước"},{"key":"B","text":"Là hình thức chính trị xã hội duy nhất để tiến hành cải cách kinh tế"},{"key":"C","text":"Là tổ chức bao trùm lên các hội đoàn, tổ chức yêu nước khác"},{"key":"D","text":"Là tổ chức hoạt động trên nguyên tắc tự nguyện, đoàn kết và mục tiêu chung"}]},{"n":39,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Mặt trận dân tộc thống nhất trong từng giai đoạn lịch sử có thể mang tên gọi khác nhau, nhưng thực chất là?","answer":"C","options":[{"key":"A","text":"Các tổ chức riêng biệt phục vụ các nhiệm vụ chuyên ngành khác nhau"},{"key":"B","text":"Tập hợp các lực lượng công – nông – trí thức phục vụ sản xuất"},{"key":"C","text":"Một tổ chức chính trị – xã hội rộng rãi với mục tiêu chung là độc lập, thống nhất của Tổ quốc và tự do, hạnh phúc của nhân dân"},{"key":"D","text":"Các hình thức liên kết hành chính nhằm kiểm soát địa phương và các tổ chức xã hội"}]},{"n":40,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Tên gọi nào sau đây KHÔNG phải là tên gọi của Mặt trận dân tộc thống nhất qua các thời kỳ?","answer":"B","options":[{"key":"A","text":"Mặt trận Nhân dân phản đế Đông Dương"},{"key":"B","text":"Mặt trận Xã hội Chủ nghĩa Việt Nam"},{"key":"C","text":"Mặt trận Liên Việt"},{"key":"D","text":"Hội Phản đế đồng minh"}]},{"n":41,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo tư tưởng Hồ Chí Minh, đối tượng nào được kêu gọi tham gia vào Mặt trận dân tộc thống nhất?","answer":"C","options":[{"key":"A","text":"Chỉ nhân dân trong nước có hộ khẩu và đăng ký tổ chức hội"},{"key":"B","text":"Chủ yếu là lực lượng vũ trang và công nhân trong các khu công nghiệp"},{"key":"C","text":"Cả nhân dân trong nước và kiều bào Việt Nam ở nước ngoài yêu nước"},{"key":"D","text":"Các tổ chức hợp pháp được nhà nước công nhận và có giấy phép hoạt động"}]},{"n":42,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Tên gọi \"Mặt trận Tổ quốc Việt Nam\" được sử dụng chính thức vào những năm nào?","answer":"B","options":[{"key":"A","text":"1945 và 1954"},{"key":"B","text":"1955 và 1976"},{"key":"C","text":"1960 và 1986"},{"key":"D","text":"1930 và 1941"}]},{"n":43,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo tư tưởng Hồ Chí Minh, nền tảng để xây dựng Mặt trận dân tộc thống nhất là gì?","answer":"A","options":[{"key":"A","text":"Liên minh giữa giai cấp công nhân, nông dân và đội ngũ trí thức dưới sự lãnh đạo của Đảng"},{"key":"B","text":"Sự đồng thuận giữa các tổ chức chính trị – xã hội cấp cơ sở và trung ương"},{"key":"C","text":"Cơ sở pháp lý do Nhà nước ban hành và bảo đảm thực thi thông qua luật pháp"},{"key":"D","text":"Cơ chế phân quyền giữa các lực lượng vũ trang và lực lượng dân sự trong hệ thống mặt trận"}]},{"n":44,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Hoạt động của Mặt trận dân tộc thống nhất phải dựa trên nguyên tắc nào?","answer":"A","options":[{"key":"A","text":"Hiệp thương dân chủ"},{"key":"B","text":"Tập trung dân chủ"},{"key":"C","text":"Dân chủ trực tiếp"},{"key":"D","text":"Quyết định theo biểu quyết đa số"}]},{"n":45,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Nguyên tắc “hiệp thương dân chủ” trong hoạt động của Mặt trận dân tộc thống nhất được Hồ Chí Minh hiểu là?","answer":"B","options":[{"key":"A","text":"Các tầng lớp nhân dân được tự do bầu chọn đại diện trong tổ chức Mặt trận"},{"key":"B","text":"Mọi vấn đề của Mặt trận đều phải được đem ra để tất cả các thành viên cùng nhau bàn bạc công khai, để đi đến nhất trí, loại trừ mọi sự áp đặt hoặc dân chủ hình thức"},{"key":"C","text":"Các vấn đề trong Mặt trận được quyết định bằng hình thức biểu quyết đa số tuyệt đối"},{"key":"D","text":"Tất cả các ý kiến phản đối đều phải được gỡ bỏ nhằm bảo đảm sự đồng thuận cao nhất"}]},{"n":46,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo Hồ Chí Minh, vì sao liên minh công – nông là nền tảng chủ yếu của Mặt trận dân tộc thống nhất?","answer":"B","options":[{"key":"A","text":"Vì đây là hai lực lượng có khả năng kiểm soát kinh tế và chính trị trong xã hội"},{"key":"B","text":"Vì họ có vai trò to lớn trong sản xuất, số lượng đông và bị áp bức nặng nề nhất"},{"key":"C","text":"Vì họ là lực lượng duy nhất có truyền thống yêu nước và tinh thần dân tộc mạnh mẽ"},{"key":"D","text":"Vì các giai cấp khác thường không có lập trường cách mạng rõ ràng và ổn định"}]},{"n":47,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Hồ Chí Minh căn dặn, bên cạnh liên minh công – nông, còn cần liên minh với lực lượng nào?","answer":"C","options":[{"key":"A","text":"Các tầng lớp tiểu tư sản thành thị và địa chủ yêu nước"},{"key":"B","text":"Quân đội và công an nhân dân để bảo vệ tổ chức mặt trận"},{"key":"C","text":"Đội ngũ trí thức để phát huy sức mạnh tổng hợp của dân tộc"},{"key":"D","text":"Các cán bộ trung cao cấp đã từng học tập ở nước ngoài"}]},{"n":48,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Nguyên tắc nào KHÔNG PHẢI là nguyên tắc xây dựng và hoạt động của Mặt trận dân tộc thống nhất theo tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Hoạt động theo nguyên tắc hiệp thương dân chủ"},{"key":"B","text":"Phải đặt dưới sự lãnh đạo của Đảng"},{"key":"C","text":"Phải do Chính phủ trực tiếp tổ chức và chỉ đạo"},{"key":"D","text":"Đoàn kết lâu dài, chặt chẽ, chân thành và tiến bộ cùng nhau"}]},{"n":49,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Trong tư tưởng Hồ Chí Minh, Mặt trận dân tộc thống nhất cần được xây dựng và hoạt động trên cơ sở các nguyên tắc nào?","answer":"D","options":[{"key":"A","text":"Phải được xây dựng trên nền tảng liên minh công nhân - nông dân - trí thức và đặt dưới sự lãnh đạo của Đảng"},{"key":"B","text":"Phải hoạt động theo nguyên tắc hiệp thương dân chủ"},{"key":"C","text":"Phải đoàn kết lâu dài, chặt chẽ, đoàn kết thật sự, chân thành, thân ái giúp đỡ nhau cùng tiến bộ"},{"key":"D","text":"Cả A, B và C"}]},{"n":50,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Theo tư tưởng Hồ Chí Minh, đoàn kết trong Mặt trận dân tộc thống nhất cần đạt được điều kiện nào?","answer":"C","options":[{"key":"A","text":"Đoàn kết hình thức nhưng phải có sự phân biệt rõ ràng về lập trường và lợi ích"},{"key":"B","text":"Đoàn kết tạm thời để phục vụ các mục tiêu chiến lược ngắn hạn"},{"key":"C","text":"Đoàn kết thực sự nghĩa là vừa đoàn kết, vừa đấu tranh, góp ý chân thành vì nước, vì dân"},{"key":"D","text":"Đoàn kết một chiều, không chấp nhận sự phản biện gây chia rẽ nội bộ"}]},{"n":51,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Hồ Chí Minh nhấn mạnh phương châm nào để duy trì đoàn kết trong Mặt trận dân tộc thống nhất?","answer":"C","options":[{"key":"A","text":"“Lấy phê bình để kiểm soát lẫn nhau giữa các tổ chức trong Mặt trận”"},{"key":"B","text":"“Lấy đấu tranh làm tiền đề, lấy chia rẽ làm phương pháp để tiến tới đoàn kết thực chất”"},{"key":"C","text":"“Cầu đồng tồn dị”, lấy cái chung để hạn chế cái riêng, cái khác biệt"},{"key":"D","text":"“Chống tư tưởng hữu khuynh và tả khuynh trong mọi hoạt động của Mặt trận”"}]},{"n":52,"sec":"4. Hình thức, nguyên tắc tổ chức của khối đại đoàn kết toàn dân tộc – Mặt","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh nêu rõ: “Đoàn kết thực sự nghĩa là mục đích phải nhất trí và lập trường cũng phải nhất trí. Đoàn kết thực sự nghĩa là vừa (_____), vừa (_____), học những cái tốt của nhau, (_____) những cái sai của nhau và phê bình trên lập trường thân ái, vì nước, vì dân” (Hồ Chí Minh, Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.11, tr.362)","answer":"B","options":[{"key":"A","text":"Yêu thương - đoàn kết - bỏ qua"},{"key":"B","text":"Đoàn kết - đấu tranh - phê bình"},{"key":"C","text":"Đoàn kết - xây dựng - tha thứ"},{"key":"D","text":"Thống nhất - đấu tranh - né tránh"}]},{"n":53,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Hồ Chí Minh coi đoàn kết, đại đoàn kết như một mục tiêu, một nhiệm vụ hàng đầucủa Đảng. Để thực hiện mục tiêu đó thì phải làm tốt công tác nào?","answer":"A","options":[{"key":"A","text":"Công tác vận động quần chúng (dân vận)"},{"key":"B","text":"Công tác tuyên giáo trong Đảng và hệ thống chính trị"},{"key":"C","text":"Công tác phát triển tổ chức cơ sở Đảng ở địa phương"},{"key":"D","text":"Công tác đào tạo cán bộ lãnh đạo chủ chốt các cấp"}]},{"n":54,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Hồ Chí Minh nhấn mạnh yếu tố quan trọng nhất trong công tác dân vận là gì?","answer":"C","options":[{"key":"A","text":"Tuyên truyền chính sách Nhà nước đến mọi tầng lớp xã hội"},{"key":"B","text":"Giúp nhân dân hiểu rõ vai trò của các tổ chức quần chúng"},{"key":"C","text":"Giải thích cho dân hiểu rằng việc làm cách mạng là vì lợi ích của họ"},{"key":"D","text":"Tổ chức hoạt động đoàn thể gắn với đời sống cộng đồng"}]},{"n":55,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Theo Hồ Chí Minh, để vận động được quần chúng, cần chú trọng điều gì?","answer":"D","options":[{"key":"A","text":"Nắm vững lý luận chủ nghĩa xã hội khoa học"},{"key":"B","text":"Áp dụng cách tiếp cận hiện đại và chuyên môn hóa"},{"key":"C","text":"Đặt lợi ích tập thể lên trên quyền lợi cá nhân"},{"key":"D","text":"Phải phù hợp với tâm tư, nguyện vọng và thực tế trình độ của quần chúng"}]},{"n":56,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Tổ chức nào đóng vai trò hạt nhân trong khối đại đoàn kết toàn dân theo tư tưởng Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Đảng Cộng sản Việt Nam"},{"key":"B","text":"Mặt trận dân tộc thống nhất"},{"key":"C","text":"Quốc hội và Chính phủ"},{"key":"D","text":"Tổ chức cơ sở Đảng ở địa phương"}]},{"n":57,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Vì sao theo Hồ Chí Minh, cần phải thành lập các tổ chức, đoàn thể quần chúng?","answer":"B","options":[{"key":"A","text":"Để thuận lợi trong quản lý nhà nước và chính quyền địa phương"},{"key":"B","text":"Để tập hợp, giáo dục và phát huy sức mạnh của các tầng lớp nhân dân"},{"key":"C","text":"Để nhân dân quen với các mô hình tổ chức hiện đại"},{"key":"D","text":"Để phân chia nhiệm vụ rõ ràng giữa các vùng, miền"}]},{"n":58,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Các phương thức xây dựng khối đại đoàn kết dân tộc?","answer":"D","options":[{"key":"A","text":"Làm tốt công tác vận động quần chúng (Dân vận)"},{"key":"B","text":"Thành lập đoàn thể, tổ chức quần chúng phù hợp với từng đối tượng để tập hợp quần chúng"},{"key":"C","text":"Các đoàn thể, tổ chức quần chúng được tập hợp và đoàn kết trong Mặt trận dân tộc thống nhất"},{"key":"D","text":"Cả A, B và C"}]},{"n":59,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Trong ba phương thức xây dựng khối đại đoàn kết dân tộc, nội dung nào sau đây là đúng theo Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Ưu tiên giáo dục pháp luật trước khi tổ chức vận động"},{"key":"B","text":"Thực hiện đồng thời công tác dân vận, thành lập đoàn thể và xây dựng Mặt trận dân tộc thống nhất"},{"key":"C","text":"Phát triển các phong trào thi đua trước khi thành lập các đoàn thể"},{"key":"D","text":"Tổ chức quần chúng theo hướng quản lý hành chính hiện đại"}]},{"n":60,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Hồ Chí Minh khẳng định vai trò của Mặt trận dân tộc thống nhất là gì?","answer":"C","options":[{"key":"A","text":"Là cơ quan ra chính sách quan trọng nhất trong hệ thống chính trị"},{"key":"B","text":"Là nơi thực hiện quyền giám sát của nhân dân với Nhà nước"},{"key":"C","text":"Là sợi dây gắn kết Đảng với nhân dân, vận động các tầng lớp cùng tham gia cách mạng"},{"key":"D","text":"Là tổ chức độc lập đại diện cho lợi ích giai cấp công nhân"}]},{"n":61,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Để giáo dục và vận động quần chúng hiệu quả, Hồ Chí Minh yêu cầu cán bộ, đảng viên cần?","answer":"D","options":[{"key":"A","text":"Kêu gọi sự ủng hộ chính trị bằng cách tuyên truyền khẩu hiệu"},{"key":"B","text":"Thực hiện các chiến dịch truyền thông đại chúng nhanh chóng"},{"key":"C","text":"Phát triển các dự án hỗ trợ nhân dân thông qua đầu tư cơ sở vật chất"},{"key":"D","text":"Biết tuyên truyền, hướng dẫn, giúp đỡ và vận động quần chúng thực hiện chủ trương, chính sách"}]},{"n":62,"sec":"5. Phương thức xây dựng khối đại đoàn kết dân tộc","stem":"Phát biểu nào dưới đây là của Hồ Chí Minh thể hiện quan điểm về công tác dân vận?","answer":"B","options":[{"key":"A","text":"“Cán bộ là cái gốc của mọi công việc”"},{"key":"B","text":"“Cần phải chịu khó tìm đủ cách giải thích cho họ hiểu rằng: những việc đó là vì ích lợi của họ mà phải làm”"},{"key":"C","text":"“Không có gì quý hơn độc lập tự do”"},{"key":"D","text":"“Học tập là chìa khóa mở ra cánh cửa tri thức”"}]},{"n":63,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, mục đích của việc thực hiện đoàn kết quốc tế là gì?","answer":"B","options":[{"key":"A","text":"Đưa Việt Nam thành quốc gia trung tâm của phong trào giải phóng dân tộc"},{"key":"B","text":"Kết hợp sức mạnh dân tộc với sức mạnh thời đại để tạo ra sức mạnh tổng hợp cho cách mạng"},{"key":"C","text":"Mở rộng ảnh hưởng của chủ nghĩa xã hội đến khu vực Đông Nam Á"},{"key":"D","text":"Cạnh tranh và khẳng định vai trò quốc tế của cách mạng Việt Nam"}]},{"n":64,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Theo tư tưởng Hồ Chí Minh, sức mạnh dân tộc Việt Nam là gì?","answer":"D","options":[{"key":"A","text":"Sức mạnh của giai cấp công nhân dưới sự lãnh đạo của Đảng"},{"key":"B","text":"Sức mạnh của khối liên minh giai cấp công nhân - nông dân - trí thức dưới sự lãnh đạo của Đảng"},{"key":"C","text":"Sức mạnh tổng hợp của các yếu tố nội sinh và ngoại sinh"},{"key":"D","text":"Sức mạnh tổng hợp của các yếu tố vật chất và tinh thần"}]},{"n":65,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, sức mạnh dân tộc được tạo nên trước hết từ đâu?","answer":"C","options":[{"key":"A","text":"Sự đoàn kết giữa các dân tộc trên toàn thế giới"},{"key":"B","text":"Lực lượng lao động và nguồn tài nguyên trong nước"},{"key":"C","text":"Sức mạnh của chủ nghĩa yêu nước và ý thức tự lực, tự cường dân tộc"},{"key":"D","text":"Hệ thống chính trị vững mạnh và chủ trương của Đảng"}]},{"n":66,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Khái niệm “sức mạnh thời đại” theo Hồ Chí Minh chủ yếu bao gồm yếu tố nào?","answer":"B","options":[{"key":"A","text":"Sự phát triển của công nghiệp hóa và toàn cầu hóa"},{"key":"B","text":"Sức mạnh của phong trào cách mạng thế giới và sức mạnh của chủ nghĩa Mác – Lênin được xác lập bởi thắng lợi của Cách mạng Tháng Mười Nga năm 1917"},{"key":"C","text":"Tư tưởng nhân đạo toàn cầu và chính sách viện trợ quốc tế"},{"key":"D","text":"Khả năng vận động quốc tế hóa các giá trị truyền thống"}]},{"n":67,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, mối quan hệ giữa đại đoàn kết toàn dân tộc và đoàn kết quốc tế như thế nào?","answer":"C","options":[{"key":"A","text":"Đoàn kết quốc tế là nền tảng để xây dựng đoàn kết toàn dân tộc"},{"key":"B","text":"Hai yếu tố này độc lập và không có ảnh hưởng lẫn nhau"},{"key":"C","text":"Đại đoàn kết toàn dân tộc là cơ sở để thực hiện đoàn kết quốc tế"},{"key":"D","text":"Đoàn kết quốc tế giúp tăng cường tính độc lập trong nội bộ dân tộc"}]},{"n":68,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, chủ nghĩa yêu nước chân chính cần gắn liền với?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa dân tộc cực đoan và tự chủ kinh tế"},{"key":"B","text":"Chủ nghĩa quốc tế vô sản và đoàn kết quốc tế"},{"key":"C","text":"Tự lực tự cường và mở rộng thị trường trong nước"},{"key":"D","text":"Độc lập về tư tưởng và không liên minh quốc tế"}]},{"n":69,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Hồ Chí Minh cho rằng đoàn kết quốc tế không chỉ vì thắng lợi của cách mạng mỗi nước mà còn vì?","answer":"C","options":[{"key":"A","text":"Lợi ích an ninh của các quốc gia liên minh"},{"key":"B","text":"Giữ gìn bản sắc văn hoá truyền thống"},{"key":"C","text":"Sự nghiệp chung của nhân loại tiến bộ"},{"key":"D","text":"Xây dựng quan hệ ngoại giao bền vững"}]},{"n":70,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Một trong những yêu cầu mà Hồ Chí Minh đặt ra để tăng cường đoàn kết quốc tế là?","answer":"D","options":[{"key":"A","text":"Tập trung vào phát triển kinh tế đối nội"},{"key":"B","text":"Xây dựng nền quốc phòng vững mạnh trước tiên"},{"key":"C","text":"Mở rộng hợp tác với các cường quốc phương Tây"},{"key":"D","text":"Chống lại chủ nghĩa vị kỷ dân tộc và chủ nghĩa sô-vanh"}]},{"n":71,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Trong tư tưởng Hồ Chí Minh, việc kết hợp chủ nghĩa yêu nước với chủ nghĩa quốc tế vô sản nhằm?","answer":"A","options":[{"key":"A","text":"Góp phần cùng nhân dân thế giới thực hiện thắng lợi các mục tiêu cách mạng của thời đại"},{"key":"B","text":"Tăng cường giao lưu văn hoá với các quốc gia phát triển"},{"key":"C","text":"Phát triển kinh tế xã hội gắn với hội nhập quốc tế"},{"key":"D","text":"Tham gia vào các tổ chức quốc tế vì mục tiêu hoà bình"}]},{"n":72,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Hồ Chí Minh xác định vận mệnh của mỗi dân tộc không thể tách rời vận mệnh?","answer":"C","options":[{"key":"A","text":"Kinh tế khu vực"},{"key":"B","text":"Chính trị của các nước láng giềng"},{"key":"C","text":"Chung của cả loài người"},{"key":"D","text":"Văn hóa khu vực châu Á"}]},{"n":73,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Hồ Chí Minh cho rằng thắng lợi của cách mạng Việt Nam là?","answer":"A","options":[{"key":"A","text":"Thắng lợi của độc lập dân tộc gắn liền với chủ nghĩa xã hội"},{"key":"B","text":"Sự thành công của chiến lược quân sự dài hạn"},{"key":"C","text":"Thắng lợi của việc vận dụng linh hoạt ngoại giao quốc tế"},{"key":"D","text":"Kết quả của chính sách trung lập và giữ gìn hòa bình"}]},{"n":74,"sec":"1. Sự cần thiết phải đoàn kết quốc tế","stem":"Một nguyên tắc trong tư tưởng Hồ Chí Minh để tăng cường đoàn kết quốc tế là?","answer":"B","options":[{"key":"A","text":"Giao lưu quốc tế trên cơ sở đôi bên cùng có lợi"},{"key":"B","text":"Kiên trì đấu tranh chống lại mọi khuynh hướng cơ hội, vị kỷ dân tộc"},{"key":"C","text":"Hợp tác có điều kiện với các quốc gia phát triển"},{"key":"D","text":"Tăng cường hỗ trợ kinh tế cho các nước láng giềng"}]},{"n":75,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Lực lượng đoàn kết quốc tế trong tư tưởng Hồ Chí Minh bao gồm?","answer":"D","options":[{"key":"A","text":"Phong trào cộng sản và công nhân quốc tế,"},{"key":"B","text":"Phong trào đấu tranh giải phóng dân tộc"},{"key":"C","text":"Các lực lượng tiến bộ, những người yêu chuộng hoà bình, dân chủ, tự do và công lý"},{"key":"D","text":"Cả A, B và C"}]},{"n":76,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Theo tư tưởng Hồ Chí Minh, phong trào nào dưới đây KHÔNG nằm trong lực lượng đoàn kết quốc tế cần thiết?","answer":"D","options":[{"key":"A","text":"Phong trào cộng sản và công nhân quốc tế"},{"key":"B","text":"Phong trào đấu tranh giải phóng dân tộc"},{"key":"C","text":"Các lực lượng tiến bộ, những người yêu chuộng hoà bình, dân chủ, tự do và công lý"},{"key":"D","text":"Các phong trào cải cách kinh tế tự do kiểu phương Tây"}]},{"n":77,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Hồ Chí Minh cho rằng, sự đoàn kết giữa giai cấp công nhân quốc tế là?","answer":"C","options":[{"key":"A","text":"Chiến lược ngắn hạn nhằm mở rộng ảnh hưởng chính trị"},{"key":"B","text":"Biện pháp tạm thời để tránh bị cô lập trên trường quốc tế"},{"key":"C","text":"Bảo đảm vững chắc cho thắng lợi của chủ nghĩa cộng sản"},{"key":"D","text":"Một hình thức vận động ngoại giao linh hoạt ở thời chiến"}]},{"n":78,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Trong tư tưởng Hồ Chí Minh, chủ nghĩa tư bản được coi là?","answer":"C","options":[{"key":"A","text":"Lực lượng có thể hợp tác nếu vì mục tiêu hoà bình"},{"key":"B","text":"Đối tác kinh tế chiến lược trong giai đoạn chuyển tiếp"},{"key":"C","text":"Lực lượng phản động quốc tế, kẻ thù chung của nhân dân lao động toàn thế giới"},{"key":"D","text":"Mô hình chính trị cạnh tranh cần đối thoại để tránh xung đột"}]},{"n":79,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Tinh thần “bốn phương vô sản đều là anh em” trong tư tưởng Hồ Chí Minh thể hiện rõ?","answer":"B","options":[{"key":"A","text":"Kỳ vọng xây dựng liên minh quốc phòng khu vực châu Á"},{"key":"B","text":"Quan điểm về sự đồng tâm hiệp lực của giai cấp công nhân toàn thế giới"},{"key":"C","text":"Thực hiện nguyên tắc bất can thiệp của các quốc gia"},{"key":"D","text":"Tinh thần phát triển kinh tế song hành giữa các quốc gia"}]},{"n":80,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh đề nghị Quốc tế Cộng sản, bằng mọi cách phải “làm cho đội quân tiên phong của lao động thuộc địa tiếp xúc (_____) với giai cấp (_____) phương Tây để dọn đường cho một sự hợp tác thật sự sau này; chỉ có sự hợp tác này mới bảo đảm cho giai cấp công nhân quốc tế giành thắng lợi cuối cùng” (Hồ Chí Minh:Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.2, tr.124).","answer":"B","options":[{"key":"A","text":"Gắn bó - công nhân"},{"key":"B","text":"Mật thiết - vô sản"},{"key":"C","text":"Thường xuyên - nhân dân"},{"key":"D","text":"Trực tiếp - lao động"}]},{"n":81,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Trong tư tưởng Hồ Chí Minh, để tranh thủ sự ủng hộ quốc tế, cuộc đấu tranh giành độc lập dân tộc cần gắn với?","answer":"C","options":[{"key":"A","text":"Việc thúc đẩy tăng trưởng kinh tế bền vững"},{"key":"B","text":"Mục tiêu hoà bình, tự do, công lý và bình đẳng"},{"key":"C","text":"Mục tiêu bảo vệ hoà bình, tự do, công lý và bình đẳng"},{"key":"D","text":"Phát triển văn hóa truyền thống và giao lưu quốc tế"}]},{"n":82,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh khẳng định: Chính vì đã biết kết hợp phong trào cách mạng nước ta với phong trào cách mạng của giai cấp (_____) và của (_____), mà Đảng đã vượt qua được mọi khó khăn, đưa giai cấp công nhân và nhân dân ta đến những thắng lợi vẻ vang.","answer":"C","options":[{"key":"A","text":"Vô sản - các quốc gia châu Á"},{"key":"B","text":"Nông dân - phong trào dân chủ thế giới"},{"key":"C","text":"Công nhân - các dân tộc bị áp bức"},{"key":"D","text":"Trí thức - các tầng lớp tiến bộ phương Tây"}]},{"n":83,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Đoàn kết quốc tế trong tư tưởng Hồ Chí Minh không phải là vấn đề sách lược, một thủ đoạn chính trị nhất thời mà là?","answer":"A","options":[{"key":"A","text":"Vấn đề có tính nguyên tắc, một đòi hỏi khách quan của cách mạng Việt Nam"},{"key":"B","text":"Một chiến thuật tạm thời nhằm tranh thủ ngoại giao quốc tế"},{"key":"C","text":"Một thủ đoạn chính trị linh hoạt theo từng giai đoạn lịch sử"},{"key":"D","text":"Một sách lược mềm dẻo để xây dựng quan hệ kinh tế"}]},{"n":84,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Theo tư tưởng Hồ Chí Minh, đoàn kết quốc tế là?","answer":"D","options":[{"key":"A","text":"Một chiến thuật tạm thời nhằm tranh thủ ngoại giao quốc tế"},{"key":"B","text":"Một thủ đoạn chính trị linh hoạt theo từng giai đoạn lịch sử"},{"key":"C","text":"Một sách lược mềm dẻo để xây dựng quan hệ kinh tế"},{"key":"D","text":"Một đòi hỏi khách quan có tính nguyên tắc của cách mạng Việt Nam"}]},{"n":85,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Từ năm 1924, Hồ Chí Minh đã đưa ra quan điểm về việc thành lập tổ chức nào để chống chủ nghĩa đế quốc?","answer":"B","options":[{"key":"A","text":"Liên minh các nước xã hội chủ nghĩa độc lập"},{"key":"B","text":"Mặt trận thống nhất của nhân dân chính quốc và thuộc địa"},{"key":"C","text":"Hội liên hiệp các dân tộc châu Á"},{"key":"D","text":"Hội đồng bảo vệ nền hoà bình quốc tế"}]},{"n":86,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Mặt trận Việt Nam Độc lập Đồng minh (Việt Minh) được thành lập năm nào?","answer":"B","options":[{"key":"A","text":"Năm 1930"},{"key":"B","text":"Năm 1941"},{"key":"C","text":"Năm 1945"},{"key":"D","text":"Năm 1954"}]},{"n":87,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Theo Hồ Chí Minh, cả ba dân tộc Việt Nam, Lào, Campuchia có điểm chung là?","answer":"C","options":[{"key":"A","text":"Có nền kinh tế phụ thuộc và dân số tương đương"},{"key":"B","text":"Có nguồn gốc văn hóa riêng biệt và chỉnh thể tương đồng"},{"key":"C","text":"Có chung một kẻ thù là thực dân Pháp"},{"key":"D","text":"Có trình độ phát triển đồng đều và mục tiêu độc lập khác nhau"}]},{"n":88,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Tư tưởng đoàn kết Việt - Lào - Campuchia được thể hiện qua việc thành lập?","answer":"C","options":[{"key":"A","text":"Mặt trận Liên hiệp Đông Dương vì tự do"},{"key":"B","text":"Mặt trận nhân dân Đông Nam Á thống nhất"},{"key":"C","text":"Mặt trận nhân dân ba nước Đông Dương"},{"key":"D","text":"Mặt traanh thống nhất chống chủ nghĩa tư bản"}]},{"n":89,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Hồ Chí Minh từng chỉ rõ rằng nền hòa bìn h thế giới chỉ được đảm bảo khi?","answer":"B","options":[{"key":"A","text":"Các quốc gia lớn từ bỏ vũ khí hạt nhân"},{"key":"B","text":"Các dân tộc châu Á giành được độc lập"},{"key":"C","text":"Các tổ chức quốc tế kiểm soát mâu thuẫn khu vực"},{"key":"D","text":"Các phong trào dân chủ phương Tây phát triển mạnh"}]},{"n":90,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Hội Liên hiệp các dân tộc bị áp bức tại Trung Quốc do Hồ Chí Minh tham gia sáng lập là?","answer":"B","options":[{"key":"A","text":"Tổ chức văn hóa liên Á"},{"key":"B","text":"Hình thức sơ khai của mặt trận thống nhất các dân tộc bị áp bức theo xu hướng vô sản"},{"key":"C","text":"Mặt trận nhân dân châu Á – Âu vì hòa bình"},{"key":"D","text":"Liên minh dân tộc châu Á – Phi – Mỹ La Tinh"}]},{"n":91,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Từ những năm 20 của thế kỷ XX, cùng với việc sáng lập Hội Liên hiệp thuộc địa tại Pháp, Hồ Chí Minh đã tham gia sáng lập tổ chức nào? Tại đâu ?","answer":"A","options":[{"key":"A","text":"Hội Liên hiệp các dân tộc bị áp bức - tại Trung Quốc"},{"key":"B","text":"Quốc tế Cộng sản – tại Pháp"},{"key":"C","text":"Hội Việt Nam Cách mạng Thanh niên – tại Trung Quốc"},{"key":"D","text":"Tân Việt Cách mạng Đảng - tại Trung Quốc"}]},{"n":92,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Trong kháng chiến chống Pháp và chống Mỹ, Hồ Chí Minh đã tranh thủ được đồng tình, ủng hộ của?","answer":"B","options":[{"key":"A","text":"Chỉ các nước trong khối xã hội chủ nghĩa"},{"key":"B","text":"Các nước xã hội chủ nghĩa, của bạn bè quốc tế và nhân loại tiến bộ, trong đó có cả nhân dân yêu chuộng hoà bình Pháp và cả nhân dân yêu chuộng hoà bình Mỹ"},{"key":"C","text":"Các lực lượng tiến bộ trên thế giới, kể cả nhân dân Pháp và Mỹ"},{"key":"D","text":"Chỉ các nước châu Á và châu Phi"}]},{"n":93,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Tư tưởng đoàn kết quốc tế của Hồ Chí Minh đã định hướng cho việc hình thành mấy tầng mặt trận?","answer":"C","options":[{"key":"A","text":"2 tầng mặt trận"},{"key":"B","text":"3 tầng mặt trận"},{"key":"C","text":"4 tầng mặt trận"},{"key":"D","text":"5 tầng mặt trận"}]},{"n":94,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Tư tưởng đoàn kết quốc tế của Hồ Chí Minh đã định hướng cho việc hình thành bốn tầng mặt trận. Đó là?","answer":"D","options":[{"key":"A","text":"Mặt trận đại đoàn kết dân tộc; Mặt trận đoàn kết Việt Nam - Lào - Campuchia"},{"key":"B","text":"Mặt trận nhân dân Á - Phi đoàn kết với Việt Nam"},{"key":"C","text":"Mặt trận nhân dân thế giới đoàn kết với Việt Nam chống đế quốc xâm lược"},{"key":"D","text":"Cả A, B và C"}]},{"n":95,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Một trong những tổ chức quốc tế đầu tiên Hồ Chí Minh tham gia sáng lập tại Pháp là?","answer":"B","options":[{"key":"A","text":"Hội đồng Giải phóng các nước thuộc địa"},{"key":"B","text":"Hội liên hiệp thuộc địa"},{"key":"C","text":"Liên minh Á – Âu vì tự do"},{"key":"D","text":"Tổ chức Lao động Quốc tế Xã hội chủ nghĩa"}]},{"n":96,"sec":"2. Lực lượng đoàn kết quốc tế và hình thức tổ chức","stem":"Sự phát triển rực rỡ nhất và thắng lợi to lớn nhất của tư tưởng Hồ Chí Minh về đại đoàn kết là ?","answer":"C","options":[{"key":"A","text":"Sự tham gia các Hội nghị quốc tế"},{"key":"B","text":"Việc thiết lập quan hệ ngoại giao đã phương"},{"key":"C","text":"Hình thành 4 tầng mặt trận đoàn kết"},{"key":"D","text":"Xây dựng chính sách ngoại giao trung lập"}]},{"n":97,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, nguyên tắc cốt lõi để thực hiện đoàn kết quốc tế là gì?","answer":"B","options":[{"key":"A","text":"Tập hợp tất cả các lực lượng chính trị để hình thành khối đồng minh thống nhất"},{"key":"B","text":"Xây dựng đoàn kết dựa trên nền tảng thống nhất mục tiêu và lợi ích; có lý, có tình"},{"key":"C","text":"Phát triển mối quan hệ đối ngoại dựa trên chủ nghĩa hiện thực và lợi ích chiến lược"},{"key":"D","text":"Hợp tác trên cơ sở cạnh tranh phát triển và tương trợ xã hội quốc tế"}]},{"n":98,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Hồ Chí Minh cho rằng, để tranh thủ được sự ủng hộ quốc tế, điều gì là quan trọng nhất?","answer":"C","options":[{"key":"A","text":"Phụ thuộc vào viện trợ kinh tế và kỹ thuật từ các nước xã hội chủ nghĩa"},{"key":"B","text":"Có đường lối đối ngoại mềm dẻo để thích nghi với thời cuộc"},{"key":"C","text":"Phải có đường lối độc lập, tự chủ và đúng đắn"},{"key":"D","text":"Phải có đường lối độc lập, tự chủ và đúng đắn"}]},{"n":99,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Quan điểm “Tự lực cánh sinh, dựa vào sức mình là chính” của Hồ Chí Minh phản ánh nguyên tắc nào?","answer":"D","options":[{"key":"A","text":"Tăng cường nội lực để xuất khẩu cách mạng ra thế giới"},{"key":"B","text":"Độc lập dân tộc gắn liền với tự do kinh tế và chủ quyền tài chính"},{"key":"C","text":"Phát triển sức mạnh quân sự làm nền tảng cho đối ngoại đa phương"},{"key":"D","text":"Đoàn kết quốc tế trên cơ sở độc lập, tự chủ"}]},{"n":100,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Điền từ còn thiếu vào (_____)? Trong quan hệ quốc tế, Người nhấn mạnh: phải có (_____), thực lực là cái (_____), ngoại giao là cái (_____), chiêng có to tiếng mới lớn…","answer":"A","options":[{"key":"A","text":"Thực lực - chiêng - tiếng"},{"key":"B","text":"Nội lực - chuông - thanh"},{"key":"C","text":"Sức mạnh - cồng - vang"},{"key":"D","text":"Tự chủ - trống - lời"}]},{"n":101,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Trong quan hệ giữa các đảng cộng sản, Hồ Chí Minh nhấn mạnh điều gì?","answer":"C","options":[{"key":"A","text":"Các đảng phải phục tùng tổ chức lãnh đạo chung để giữ vững kỷ luật quốc tế"},{"key":"B","text":"Các đảng cộng sản cần liên minh chặt chẽ để đảm bảo sự đồng bộ trong cách mạng"},{"key":"C","text":"Mỗi đảng đều độc lập và bình đẳng, đồng thời đoàn kết giúp đỡ lẫn nhau"},{"key":"D","text":"Mỗi đảng phải ưu tiên lợi ích quốc tế hơn lợi ích dân tộc của mình"}]},{"n":102,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Hồ Chí Minh từng phát biểu: “Làm bạn với tất cả mọi nước dân chủ và không gây thù oán với một ai” vào thời điểm nào?","answer":"C","options":[{"key":"A","text":"Khi tham dự Hội nghị Potsdam"},{"key":"B","text":"Trong Lời kêu gọi toàn quốc kháng chiến năm 1946"},{"key":"C","text":"Khi trả lời nhà báo Mỹ tháng 9 năm 1947"},{"key":"D","text":"Trong Thư gửi Quốc hội Pháp năm 1946"}]},{"n":103,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, điều gì giúp tạo ra nền tảng cho sự đoàn kết quốc tế vững chắc?","answer":"B","options":[{"key":"A","text":"Việc xây dựng các tổ chức chính trị - xã hội liên quốc gia mạnh"},{"key":"B","text":"Việc tìm ra sự tương đồng về mục tiêu và lợi ích giữa các lực lượng cách mạng"},{"key":"C","text":"Việc thống nhất chiến lược quân sự giữa các quốc gia xã hội chủ nghĩa"},{"key":"D","text":"Việc phân chia vai trò và trách nhiệm cụ thể giữa các quốc gia lớn"}]},{"n":104,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Hồ Chí Minh đã kết hợp lợi ích của cách mạng Việt Nam với gì?","answer":"A","options":[{"key":"A","text":"Trào lưu cách mạng thế giới"},{"key":"B","text":"Mục tiêu của các cường quốc XHCN"},{"key":"C","text":"Quy luật phát triển khách quan của lịch sử"},{"key":"D","text":"Mô hình nhà nước dân chủ nhân dân"}]},{"n":105,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, muốn được độc lập thì trước hết dân tộc phải?","answer":"C","options":[{"key":"A","text":"Có quan hệ ngoại giao tốt với các nước lớn"},{"key":"B","text":"Có cơ sở vật chất hiện đại"},{"key":"C","text":"Tự giúp mình trước khi trông chờ vào người khác"},{"key":"D","text":"Tham gia vào các khối quân sự và chính trị"}]},{"n":106,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo tư tưởng Hồ Chí Minh, mục đích của đoàn kết quốc tế là?","answer":"B","options":[{"key":"A","text":"Mở rộng thị trường và giao lưu văn hóa"},{"key":"B","text":"Tranh thủ đồng tình và giúp đỡ quốc tế, tăng thêm nội lực cách mạng"},{"key":"C","text":"Thiết lập vị thế lãnh đạo quốc tế cho Việt Nam"},{"key":"D","text":"Bảo đảm thắng lợi trong đàm phán và hợp tác khu vực"}]},{"n":107,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo tư tưởng Hồ Chí Minh, để đoàn kết tốt phải có?","answer":"C","options":[{"key":"A","text":"Niềm tin tuyệt đối vào sự giúp đỡ của bạn bè quốc tế, coi đó là yếu tố quyết định"},{"key":"B","text":"Sự tương đồng về thể chế chính trị và mô hình phát triển kinh tế"},{"key":"C","text":"Nội lực tốt"},{"key":"D","text":"Chiến lược linh hoạt trong hợp tác quốc tế nhằm thích ứng với thời đại"}]},{"n":108,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Trong đấu tranh cách mạng, Hồ Chí Minh luôn nêu cao khẩu hiệu nào?","answer":"D","options":[{"key":"A","text":"Liên kết toàn cầu, hợp tác toàn diện để đi tới thắng lợi"},{"key":"B","text":"Đoàn kết là sức mạnh, tranh thủ tối đa nguồn lực quốc tế"},{"key":"C","text":"Cải cách nội bộ, mở rộng đối ngoại để giành độc lập"},{"key":"D","text":"Tự lực cánh sinh, dựa vào sức mình là chính"}]},{"n":109,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, điều kiện để nguồn lực ngoại sinh phát huy hiệu quả là gì?","answer":"B","options":[{"key":"A","text":"Phải thông qua sự phân bổ chiến lược của tổ chức quốc tế"},{"key":"B","text":"Phải gắn liền với nguồn lực nội sinh"},{"key":"C","text":"Phải có sự bảo lãnh từ các nước lớn"},{"key":"D","text":"Phải do trung ương điều phối theo cơ chế đặc thù"}]},{"n":110,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Hồ Chí Minh cho rằng, nền hòa bình thật sự là?","answer":"D","options":[{"key":"A","text":"Nền hòa bình có sự can thiệp quốc tế để giữ ổn định"},{"key":"B","text":"Hòa bình xây dựng trên cơ sở trung lập hóa các quốc gia nhỏ"},{"key":"C","text":"Nền hòa bình được đảm bảo bởi các hiệp định chính trị"},{"key":"D","text":"Nền hòa bình chân chính, xây trên công bình và lý tưởng dân chủ"}]},{"n":111,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Phong trào nhân dân thế giới ủng hộ Việt Nam trong kháng chiến chống Pháp và Mỹ xuất phát từ?","answer":"B","options":[{"key":"A","text":"Chính sách chia sẻ kinh nghiệm chiến tranh của Việt Nam"},{"key":"B","text":"Lòng thiết tha hòa bình và sự tôn trọng độc lập dân tộc của Việt Nam"},{"key":"C","text":"Chiến lược ngoại giao kinh tế đa phương của Việt Nam"},{"key":"D","text":"Việc Việt Nam tích cực tham gia các tổ chức toàn cầu"}]},{"n":112,"sec":"3. Nguyên tắc đoàn kết quốc tế","stem":"Theo Hồ Chí Minh, mỗi dân tộc - quốc gia cần được đảm bảo quyền gì?","answer":"A","options":[{"key":"A","text":"Quyền độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ và tự quyết"},{"key":"B","text":"Quyền gia nhập tổ chức quốc tế và quyền khai thác tài nguyên chung"},{"key":"C","text":"Quyền mở rộng ảnh hưởng văn hóa và tôn giáo"},{"key":"D","text":"Quyền hợp tác kinh tế và quyền can thiệp nhân đạo"}]},{"n":113,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Theo tư tưởng Hồ Chí Minh, trong giai đoạn hiện nay, sức mạnh của đại đoàn kết toàn dân tộc cần được phát huy để?","answer":"B","options":[{"key":"A","text":"Củng cố quan hệ quốc phòng và an ninh khu vực"},{"key":"B","text":"Chiến thắng nghèo nàn và lạc hậu, xây dựng đất nước phát triển"},{"key":"C","text":"Mở rộng ảnh hưởng tư tưởng ra thế giới"},{"key":"D","text":"Hợp tác toàn cầu trên cơ sở lợi ích chiến lược"}]},{"n":114,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Điền từ còn thiếu vào (_____)? Đại hội lần thứ XII của Đảng (2 016) khẳng định: “Đại đoàn kết dân tộc là đường lối (_____) của cách mạng Việt Nam, là (_____) và (_____) to lớn trong xây dựng và bảo vệ Tổ quốc” (Đảng Cộng sản Việt Nam: Văn kiện Đại hội đại biểu toàn quốc lần thứ XII, Nxb Chính trị quốc gia, Hà Nội, 2016, tr. 158).","answer":"A","options":[{"key":"A","text":"Chiến lược, động lực, nguồn lực"},{"key":"B","text":"Chủ chốt, giải pháp, nền tảng"},{"key":"C","text":"Trọng điểm, điều kiện, yêu cầu"},{"key":"D","text":"Ngắn hạn, mục tiêu, động cơ"}]},{"n":115,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Đại hội XII đã đề ra phương hướng, nhiệm vụ tăng cường khối đại đoàn kết toàn dân tộc trên nền tảng nào?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa Mác - Lênin kết hợp văn hóa phương Tây"},{"key":"B","text":"Liên minh giai cấp công nhân với giai cấp nông dân và đội ngũ trí thức do Đảng lãnh đạo"},{"key":"C","text":"Sự thống nhất các tôn giáo trong cộng đồng dân cư"},{"key":"D","text":"Hệ thống chính sách kinh tế thị trường định hướng XHCN"}]},{"n":116,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Tinh thần “muốn là bạn”, “sẵn sàng là bạn”, “là bạn và đối tác tin cậy” phản ánh gì trong chính sách đối ngoại?","answer":"C","options":[{"key":"A","text":"Định hướng chuyển đổi cơ cấu ngoại giao nhân văn"},{"key":"B","text":"Chiến lược đối ngoại mềm dẻo trong hợp tác quốc phòng"},{"key":"C","text":"Quá trình hội nhập quốc tế toàn diện và sâu rộng"},{"key":"D","text":"Tăng cường hợp tác công nghệ và đổi mới sáng tạo"}]},{"n":117,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Để tăng cường khối đại đoàn kết toàn dân tộc, một trong những giải pháp quan trọng là?","answer":"B","options":[{"key":"A","text":"Chuyển giao quyền lãnh đạo cho Mặt trận Tổ quốc Việt Nam"},{"key":"B","text":"Giải quyết tốt quan hệ lợi ích giữa các giai cấp, tầng lớp xã hội"},{"key":"C","text":"Tập trung phát triển các ngành kinh tế trọng điểm"},{"key":"D","text":"Hạn chế mâu thuẫn xã hội bằng biện pháp cưỡng chế tập thể"}]},{"n":118,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Để nâng cao hiệu quả hợp tác quốc tế, Đảng ta chủ trương nêu cao nguyên tắc nào?","answer":"B","options":[{"key":"A","text":"Đoàn kết và phụ thuộc chiến lược vào các quốc gia phát triển"},{"key":"B","text":"Độc lập, tự chủ, tự lực tự cường, kết hợp sức mạnh dân tộc và thời đại"},{"key":"C","text":"Thỏa hiệp trên cơ sở cùng có lợi với các nước trong khu vực"},{"key":"D","text":"Ưu tiên lợi ích của đối tác nhằm thu hút đầu tư và viện trợ"}]},{"n":119,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Một trong những nguyên tắc quan trọng trong đoàn kết quốc tế theo tư tưởng Hồ Chí Minh là gì?","answer":"C","options":[{"key":"A","text":"Phát triển ngoại giao song phương để hỗ trợ chính sách quốc phòng"},{"key":"B","text":"Coi trọng kinh tế đối ngoại hơn chính trị đối ngoại"},{"key":"C","text":"Gắn lợi ích dân tộc với nghĩa vụ quốc tế"},{"key":"D","text":"Đặt yêu cầu đối ngoại trên yêu cầu phát triển trong nước"}]},{"n":120,"sec":"III. VẬN DỤNG TƯ TƯỞNG HỒ CHÍ MINH VỀ ĐẠI ĐOÀN KẾT TOÀN","stem":"Theo tư tưởng Hồ Chí Minh, cách mạng Việt Nam là?","answer":"B","options":[{"key":"A","text":"Một cuộc cách mạng hoàn toàn biệt lập với thế giới"},{"key":"B","text":"Một bộ phận không thể tách rời của cách mạng thế giới"},{"key":"C","text":"Một mô hình độc đáo, không phụ thuộc vào hoàn cảnh quốc tế"},{"key":"D","text":"Cuộc cách mạng định hướng thị trường trong thời kỳ hội nhậ"}]}]},{"id":"VI","title":"TƯ TƯỞNG HỒ CHÍ MINH VỀ VĂN HÓA, ĐẠO ĐỨC, CON NGƯỜI","questions":[{"n":1,"sec":"","stem":"Hồ Chí Minh được UNESCO công nhận là “Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất Việt Nam” trong nghị quyết nào?","answer":"A","options":[{"key":"A","text":"Nghị quyết 24C/18.6.5 của khóa họp 24 Đại Hội đồng UNESCO"},{"key":"B","text":"Nghị quyết 21A/17.2.6 của Hội đồng Văn hóa Thế giới"},{"key":"C","text":"Nghị quyết 22B/19.5.3 của Đại hội đồng Liên Hợp Quốc"},{"key":"D","text":"Nghị quyết 25D/16.7.4 của Hội đồng Hòa bình và H ữu nghị Quốc tế"}]},{"n":2,"sec":"","stem":"Theo UNESCO, Hồ Chí Minh đã để lại dấu ấn trong quá trình phát triển của nhân loại vì mục tiêu nào sau đây?","answer":"A","options":[{"key":"A","text":"Vì hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội"},{"key":"B","text":"Vì công cuộc công nghiệp hóa, hiện đại hóa và hội nhập quốc tế"},{"key":"C","text":"Vì cách mạng khoa học – kỹ thuật và phát triển kinh tế toàn cầu"},{"key":"D","text":"Vì phát triển thương mại, giao lưu văn hóa và hợp tác quốc tế"}]},{"n":3,"sec":"","stem":"Trong tư tưởng Hồ Chí Minh, “chống giặc dốt” được xem là một nhiệm vụ?","answer":"A","options":[{"key":"A","text":"Văn hóa cơ bản, nhằm nâng cao dân trí, bồi dưỡng nhân lực cho cách mạng"},{"key":"B","text":"Chính trị trọng tâm, nhằm củng cố nhà nước của dân, do dân, vì dân"},{"key":"C","text":"Kinh tế then chốt, để mở rộng thị trường và phát triển sản xuất"},{"key":"D","text":"Quân sự thiết yếu, nhằm bảo vệ nền độc lập dân tộc"}]},{"n":4,"sec":"","stem":"Tổ chức UNESCO công nhận Hồ Chí Minh là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất Việt Nam vào thời gian nào?","answer":"A","options":[{"key":"A","text":"Từ ngày 20-10-1987 đến ngày 20-11-1987"},{"key":"B","text":"Từ ngày 02-9-1985 đến ngày 02-12-1985"},{"key":"C","text":"Từ ngày 10-10-1986 đến ngày 10-11-1986"},{"key":"D","text":"Từ ngày 05-5-1988 đến ngày 05-6-1988"}]},{"n":5,"sec":"","stem":"Nghị quyết của UNESCO về Hồ Chí Minh được thông qua tại khóa họp thứ mấy của Đại hội đồng UNESCO?","answer":"A","options":[{"key":"A","text":"Khóa họp thứ 24"},{"key":"B","text":"Khóa họp thứ 25"},{"key":"C","text":"Khóa họp thứ 27"},{"key":"D","text":"Khóa họp thứ 28"}]},{"n":6,"sec":"","stem":"Nghị quyết 24C/18.6.5 của UNESCO khẳng định điều gì về Chủ tịch Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Người là nhà cách mạng kiên trung, chiến sĩ cộng sản mẫu mực của phong trào cộng sản quốc tế"},{"key":"B","text":"Người để lại dấu ấn trong quá trình phát triển nhân loại vì hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội"},{"key":"C","text":"Người là vị lãnh tụ có công khai sinh nền giáo dục Việt Nam hiện đại"},{"key":"D","text":"Người là biểu tượng cho tinh thần yêu nước của các dân tộc châu Á"}]},{"n":7,"sec":"","stem":"Theo UNESCO, tư tưởng Hồ Chí Minh là sự kết tinh của điều gì?","answer":"C","options":[{"key":"A","text":"Tinh thần đoàn kết của nhân dân Việt Nam trong kháng chiến"},{"key":"B","text":"Giá trị triết học của các nền văn hóa phương Đông"},{"key":"C","text":"Truyền thống văn hóa hàng ngàn năm của dân tộc Việt Nam"},{"key":"D","text":"Chủ nghĩa duy vật biện chứng trong lĩnh vực văn hóa"}]},{"n":8,"sec":"","stem":"Hồ Chí Minh đã đưa ra quan niệm nhấn mạnh ý nghĩa của văn hóa trong hoàn cảnh nào?","answer":"A","options":[{"key":"A","text":"Tháng 8-1943, khi còn ở trong nhà tù của Tưởng Giới Thạch"},{"key":"B","text":"Khi hoạt động ở Pháp, năm 1919"},{"key":"C","text":"Khi lãnh đạo phong trào Việt Minh năm 1941"},{"key":"D","text":"Khi tham dự Hội nghị Fontainebleau năm 1946"}]},{"n":9,"sec":"","stem":"Theo Hồ Chí Minh, văn hóa bao gồm những yếu tố nào sau đây?","answer":"D","options":[{"key":"A","text":"Tổ chức chính trị, kinh tế, xã hội và quân sự"},{"key":"B","text":"Tài nguyên thiên nhiên, địa lý, và phong tục tập quán"},{"key":"C","text":"Phong trào cách mạng, chính sách xã hội, và tư tưởng triết học"},{"key":"D","text":"Ngôn ngữ, chữ viết, đạo đức, pháp luật, khoa học, tôn giáo, văn học, nghệ thuật, những công cụ cho sinh hoạt hằng ngày về mặc, ăn, ở và các phương thức sử dụng"}]},{"n":10,"sec":"","stem":"Hồ Chí Minh có bao nhiêu cách tiếp cận chủ yếu về văn hóa?","answer":"C","options":[{"key":"A","text":"2 cách tiếp cận"},{"key":"B","text":"3 cách tiếp cận"},{"key":"C","text":"4 cách tiếp cận"},{"key":"D","text":"5 cách tiếp cận"}]},{"n":11,"sec":"","stem":"Một trong các cách tiếp cận của Hồ Chí Minh về văn hóa là?","answer":"A","options":[{"key":"A","text":"Tiếp cận theo nghĩa rộng – tổng hợp mọi phương thức sinh hoạt của con người"},{"key":"B","text":"Tiếp cận theo nghĩa chính trị – phản ánh mối quan hệ giai cấp"},{"key":"C","text":"Tiếp cận theo nghĩa dân tộc – phản ánh bản sắc vùng miền"},{"key":"D","text":"Tiếp cận theo nghĩa kinh tế – biểu hiện của cơ sở hạ tầng"}]},{"n":12,"sec":"","stem":"Hồ Chí Minh nhấn mạnh văn hóa phải gắn liền với lĩnh vực nào?","answer":"B","options":[{"key":"A","text":"Kinh tế, giáo dục, quân sự"},{"key":"B","text":"Chính trị, kinh tế, xã hội"},{"key":"C","text":"Xã hội, môi trường, nhân khẩu học"},{"key":"D","text":"Nghệ thuật, tôn giáo, thể thao"}]},{"n":13,"sec":"","stem":"Quan niệm văn hóa theo nghĩa rộng của Hồ Chí Minh được viết trong hoàn cảnh?","answer":"D","options":[{"key":"A","text":"Sau khi giành độc lập, trong thời kỳ kháng chiến chống Pháp"},{"key":"B","text":"Trong giai đoạn xây dựng chủ nghĩa xã hội ở miền Bắc"},{"key":"C","text":"Khi đất nước thống nhất sau năm 1975"},{"key":"D","text":"Khi UNESCO chưa thành lập, cả nước đang tập trung cho nhiệm vụ giải phóng dân tộc"}]},{"n":14,"sec":"","stem":"Sau Cách mạng Tháng Tám, Hồ Chí Minh bàn đến văn hóa theo nghĩa nào?","answer":"A","options":[{"key":"A","text":"Theo nghĩa hẹp, với ý nghĩa là kiến trúc thượng tầng, là toàn bộ đời sống tinh thần của xã hội"},{"key":"B","text":"Nghĩa rộng - bao gồm cả vật chất và tinh thần"},{"key":"C","text":"Nghĩa khoa học – gắn liền với nghiên cứu triết học"},{"key":"D","text":"Nghĩa chính trị – phục vụ mục tiêu cách mạng"}]},{"n":15,"sec":"","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh viết: “Vì lẽ sinh tồn cũng như mục đích của cuộc sống, loài người mới sáng tạo và phát minh ra (_____), (_____), (_____), pháp luật, khoa học, tôn giáo, văn học, nghệ thuật, những công cụ cho sinh hoạt hằng ngày về mặc, ăn, ở và các phương thức sử dụng. Toàn bộ những sáng tạo và phát minh đó tức là văn hóa. Văn hóa là sự tổng hợp của mọi phương thức sinh hoạt cùng với biểu hiện của nó mà loài người đã sản sinh ra nhằm thích ứng những nhu cầu đời sống và đòi hỏi của sự sinh tồn (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.3, tr.458).","answer":"B","options":[{"key":"A","text":"Chính trị, kinh tế, xã hội"},{"key":"B","text":"Ngôn ngữ, chữ viết, đạo đức"},{"key":"C","text":"Tổ chức, phong tục, tập quán"},{"key":"D","text":"Giáo dục, nghệ thuật, tôn giáo"}]},{"n":16,"sec":"","stem":"Theo Hồ Chí Minh, văn hóa có vai trò gì trong đời sống xã hội?","answer":"D","options":[{"key":"A","text":"Văn hóa là mục tiêu, động lực của sự nghiệp cách mạng"},{"key":"B","text":"Văn hóa là một mặt trận"},{"key":"C","text":"Văn hóa phục vụ quần chúng nhân dân"},{"key":"D","text":"Cả A, B và C"}]},{"n":17,"sec":"","stem":"Theo Hồ Chí Minh, trong đời sống xã hội có mấy vấn đề quan trọng ngang nhau và tác động lẫn nhau?","answer":"B","options":[{"key":"A","text":"Ba vấn đề: kinh tế, chính trị, văn hóa"},{"key":"B","text":"Bốn vấn đề: chính trị, kinh tế, văn hóa, xã hội"},{"key":"C","text":"Năm vấn đề: chính trị, kinh tế, văn hóa, giáo dục, khoa học"},{"key":"D","text":"Hai vấn đề: chính trị và kinh tế"}]},{"n":18,"sec":"","stem":"Hồ Chí Minh đặt văn hóa ngang hàng với các lĩnh vực nào?","answer":"D","options":[{"key":"A","text":"Chính trị"},{"key":"B","text":"Kinh tế"},{"key":"C","text":"Xã hội"},{"key":"D","text":"Kinh tế, chính trị, xã hội"}]},{"n":19,"sec":"","stem":"Trong điều kiện ở nước Việt Nam thuộc địa, Hồ Chí Minh cho rằng nhiệm vụ nào cần tiến hành trước hết?","answer":"A","options":[{"key":"A","text":"Phải tiến hành cách mạng giải phóng dân tộc, giành độc lập dân tộc, xóa ách nô lệ, thiết lập nhà nước của dân, do dân, vì dân."},{"key":"B","text":"Phát triển văn hóa giáo dục để nâng cao dân trí"},{"key":"C","text":"Cải cách ruộng đất và phát triển kinh tế nông nghiệp"},{"key":"D","text":"Xây dựng nhà nước pháp quyền xã hội chủ nghĩa"}]},{"n":20,"sec":"","stem":"Theo Hồ Chí Minh, sự giải phóng chính trị có ý nghĩa như thế nào đối với văn hóa?","answer":"A","options":[{"key":"A","text":"Là điều kiện mở đường cho văn hóa phát triển"},{"key":"B","text":"Là một bộ phận cấu thành của văn hóa"},{"key":"C","text":"Là yếu tố phụ thuộc vào văn hóa"},{"key":"D","text":"Là kết quả của phát triển văn hóa"}]},{"n":21,"sec":"","stem":"Khi nói “văn hóa phải ở trong chính trị”, Hồ Chí Minh muốn nhấn mạnh điều gì?","answer":"D","options":[{"key":"A","text":"Văn hóa là công cụ quản lý của tổ chức chính trị"},{"key":"B","text":"Văn hóa chỉ tồn tại trong hoạt động tuyên truyền của Đảng"},{"key":"C","text":"Văn hóa phụ thuộc hoàn toàn vào quyền lực nhà nước"},{"key":"D","text":"Văn hóa phải phục vụ nhiệm vụ chính trị, không tách rời chính trị"}]},{"n":22,"sec":"","stem":"Hồ Chí Minh cho rằng mọi hoạt động của các tổ chức và nhà chính trị phải như thế nào?","answer":"A","options":[{"key":"A","text":"Có hàm lượng văn hóa"},{"key":"B","text":"Đặt lợi ích kinh tế lên hàng đầu"},{"key":"C","text":"Dựa hoàn toàn vào lý luận giai cấp"},{"key":"D","text":"Phục vụ mục tiêu văn nghệ"}]},{"n":23,"sec":"","stem":"Trong mối quan hệ với kinh tế, Hồ Chí Minh khẳng định văn hóa thuộc?","answer":"B","options":[{"key":"A","text":"Cơ sở hạ tầng"},{"key":"B","text":"Kiến trúc thượng tầng"},{"key":"C","text":"Hình thái ý thức xã hội thứ yếu"},{"key":"D","text":"Nền tảng vật chất của xã hội"}]},{"n":24,"sec":"","stem":"Theo Hồ Chí Minh, điều kiện để văn hóa kiến thiết và phát triển là gì?","answer":"A","options":[{"key":"A","text":"Cơ sở hạ tầng kinh tế – xã hội được xây dựng"},{"key":"B","text":"Chính trị phát triển trước, kinh tế sau"},{"key":"C","text":"Văn học nghệ thuật đạt thành tựu nổi bật"},{"key":"D","text":"Giáo dục đào tạo phát triển đồng đều"}]},{"n":25,"sec":"","stem":"Hồ Chí Minh cho rằng văn hóa có quan hệ như thế nào với kinh tế?","answer":"A","options":[{"key":"A","text":"Có tác động qua lại, hỗ trợ, thúc đẩy lẫn nhau"},{"key":"B","text":"Văn hóa phụ thuộc hoàn toàn vào kinh tế"},{"key":"C","text":"Kinh tế quyết định tất yếu mọi mặt của văn hóa"},{"key":"D","text":"Văn hóa chỉ là kết quả của tăng trưởng kinh tế"}]},{"n":26,"sec":"","stem":"Trong chế độ nô lệ, Hồ Chí Minh cho rằng văn nghệ Việt Nam bị gì?","answer":"C","options":[{"key":"A","text":"Bị xóa bỏ hoàn toàn"},{"key":"B","text":"Phát triển mạnh mẽ và tự do"},{"key":"C","text":"Bị nô lệ, không thể phát triển"},{"key":"D","text":"Được bảo hộ bởi thực dân"}]},{"n":27,"sec":"","stem":"Bản sắc văn hóa dân tộc theo Hồ Chí Minh là gì?","answer":"A","options":[{"key":"A","text":"Những giá trị văn hóa bền vững của cộng đồng các dân tộc Việt Nam; là thành quả của quá trình lao động, sản xuất, chiến đấu và giao lưu của con người Việt Nam"},{"key":"B","text":"Những yếu tố văn hóa du nhập từ các nền văn minh tiên tiến"},{"key":"C","text":"Những tập quán xã hội tồn tại trong thời kỳ phong kiến"},{"key":"D","text":"Hệ giá trị tinh thần chịu ảnh hưởng của phương Tây"}]},{"n":28,"sec":"","stem":"Về nội dung, bản sắc văn hóa dân tộc được thể hiện ở?","answer":"B","options":[{"key":"A","text":"Những yếu tố kinh tế – xã hội mang tính vật chất"},{"key":"B","text":"Lòng yêu nước, tinh thần độc lập, tự cường, tự tôn dân tộc"},{"key":"C","text":"Sự hòa nhập hoàn toàn vào văn hóa phương Tây"},{"key":"D","text":"Tư tưởng dân tộc thuần túy, khép kín với thế giới"}]},{"n":29,"sec":"","stem":"Về hình thức, cốt cách văn hóa dân tộc biểu hiện ở?","answer":"A","options":[{"key":"A","text":"Ngôn ngữ, phong tục, tập quán, lễ hội, truyền thống, cách cảm và nghĩ"},{"key":"B","text":"Các yếu tố tôn giáo, tín ngưỡng ngoại lai"},{"key":"C","text":"Hệ thống tổ chức chính trị – xã hội"},{"key":"D","text":"Nền kinh tế nông nghiệp truyền thống"}]},{"n":30,"sec":"","stem":"Theo Hồ Chí Minh, “dân ta phải biết sử ta” nhằm mục đích gì?","answer":"A","options":[{"key":"A","text":"Để hiểu rõ gốc tích dân tộc, phát huy truyền thống yêu nước"},{"key":"B","text":"Để sưu tầm di sản văn hóa dân gian"},{"key":"C","text":"Để nghiên cứu khoa học lịch sử chuyên sâu"},{"key":"D","text":"Để so sánh với văn hóa phương Tây"}]},{"n":31,"sec":"","stem":"Hồ Chí Minh nhấn mạnh: “Càng thấm nhuần chủ nghĩa Mác – Lênin càng phải coi trọng điều gì?”","answer":"A","options":[{"key":"A","text":"Để hiểu rõ gốc tích dân tộc, phát huy truyền thống yêu nước"},{"key":"B","text":"Sự khác biệt của các nền văn hóa thế giới"},{"key":"C","text":"Tính hiện đại của nghệ thuật phương Tây"},{"key":"D","text":"Thành tựu khoa học – kỹ thuật của nhân loại"}]},{"n":32,"sec":"","stem":"Câu nói “Mỗi dân tộc cần phải chăm lo đặc tính dân tộc mình trong nghệ thuật” thể hiện quan điểm gì?","answer":"C","options":[{"key":"A","text":"Loại bỏ yếu tố dân tộc trong sáng tạo nghệ thuật"},{"key":"B","text":"Hòa tan văn hóa dân tộc trong quốc tế hóa"},{"key":"C","text":"Giữ gìn và phát huy bản sắc văn hóa dân tộc"},{"key":"D","text":"Ưu tiên ảnh hưởng văn hóa phương Tây"}]},{"n":33,"sec":"","stem":"Hồ Chí Minh khẳng định, việc tiếp thu tinh hoa văn hóa nhân loại có mục đích là?","answer":"A","options":[{"key":"A","text":"Làm giàu cho văn hóa Việt Nam, xây dựng văn hóa hợp với tinh thần dân chủ"},{"key":"B","text":"Thay thế văn hóa truyền thống bằng văn hóa hiện đại"},{"key":"C","text":"Mở rộng giao lưu văn hóa để hội nhập kinh tế"},{"key":"D","text":"Thực hiện đồng hóa văn hóa phương Tây"}]},{"n":34,"sec":"","stem":"Theo Hồ Chí Minh, nội dung tiếp thu văn hóa nhân loại là?","answer":"A","options":[{"key":"A","text":"Toàn diện – Đông, Tây, kim, cổ"},{"key":"B","text":"Giới hạn – chỉ phương Đông"},{"key":"C","text":"Trọng tâm – văn hóa châu Âu hiện đại"},{"key":"D","text":"Có chọn lọc – chỉ lĩnh vực nghệ thuật"}]},{"n":35,"sec":"","stem":"Hồ Chí Minh nhấn mạnh, các nhà cách mạng cần “tẩy trừ mọi di hại thuộc địa” nhằm?","answer":"C","options":[{"key":"A","text":"Tiếp thu ảnh hưởng văn hóa phương Tây sâu rộng hơn"},{"key":"B","text":"Phát triển văn hóa tư sản để hội nhập quốc tế"},{"key":"C","text":"Giữ gìn sự trong sáng, độc lập của văn hóa dân tộc"},{"key":"D","text":"Đưa văn hóa phương Đông thay thế phương Tây"}]},{"n":36,"sec":"","stem":"Theo Hồ Chí Minh, giữ gìn và phát huy bản sắc văn hóa dân tộc có ý nghĩa?","answer":"A","options":[{"key":"A","text":"Là cơ sở tinh thần của độc lập dân tộc và phát triển bền vững"},{"key":"B","text":"Là hoạt động mang tính hình thức trong giáo dục"},{"key":"C","text":"Là nhiệm vụ riêng của giới trí thức"},{"key":"D","text":"Là công việc của ngành văn nghệ"}]},{"n":37,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo quan điểm Hồ Chí Minh, văn hóa là mục tiêu của cách mạng vì?","answer":"C","options":[{"key":"A","text":"Văn hóa phản ánh đời sống tinh thần, là kết quả của phát triển kinh tế"},{"key":"B","text":"Văn hóa chỉ tồn tại khi kinh tế phát triển ở mức cao"},{"key":"C","text":"Văn hóa là quyền sống, quyền tự do, quyền mưu cầu hạnh phúc của con người"},{"key":"D","text":"Văn hóa là hoạt động của giới trí thức trong xã hội"}]},{"n":38,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Mục tiêu văn hóa trong tư tưởng Hồ Chí Minh gắn liền với?","answer":"A","options":[{"key":"A","text":"Độc lập dân tộc và chủ nghĩa xã hội"},{"key":"B","text":"Xây dựng xã hội tiêu thụ hiện đại"},{"key":"C","text":"Nâng cao đời sống vật chất cho tầng lớp trung lưu"},{"key":"D","text":"Phát triển công nghiệp hóa và hiện đại hóa đơn thuần"}]},{"n":39,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, văn hóa là động lực phát triển vì?","answer":"B","options":[{"key":"A","text":"Văn hóa tạo ra sự cân bằng giữa cá nhân và tập thể"},{"key":"B","text":"Văn hóa thúc đẩy, soi đường và định hướng hành động cách mạng"},{"key":"C","text":"Văn hóa chủ yếu phục vụ nhu cầu giải trí của nhân dân"},{"key":"D","text":"Văn hóa tồn tại độc lập, không phụ thuộc vào chính trị và kinh tế"}]},{"n":40,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, văn hóa chính trị có vai trò gì trong sự nghiệp cách mạng?","answer":"C","options":[{"key":"A","text":"Giúp nâng cao năng suất lao động"},{"key":"B","text":"Là phương tiện tuyên truyền đơn thuần của chính quyền"},{"key":"C","text":"Là động lực soi đường cho quốc dân đi, lãnh đạo quốc dân thực hiện độc lập tự cường"},{"key":"D","text":"Là yếu tố phụ thuộc vào trình độ dân trí"}]},{"n":41,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Trong tư tưởng Hồ Chí Minh, “trồng người” thuộc về loại hình văn hóa nào?","answer":"B","options":[{"key":"A","text":"Văn hóa văn nghệ"},{"key":"B","text":"Văn hóa giáo dục"},{"key":"C","text":"Văn hóa đạo đức"},{"key":"D","text":"Văn hóa pháp luật"}]},{"n":42,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"“Kháng chiến hóa văn hóa, văn hóa hóa kháng chiến” thể hiện tư tưởng gì của Hồ Chí Minh?","answer":"D","options":[{"key":"A","text":"Xem văn hóa là lĩnh vực riêng biệt, không can dự chính trị"},{"key":"B","text":"Chỉ phát triển văn hóa khi đất nước hòa bình"},{"key":"C","text":"Tách văn nghệ khỏi cuộc sống thực tế của nhân dân"},{"key":"D","text":"Gắn bó mật thiết giữa văn hóa và chính trị trong thời kỳ đấu tranh cách mạng"}]},{"n":43,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, văn hóa pháp luật có vai trò?","answer":"B","options":[{"key":"A","text":"Thúc đẩy tự do cá nhân tuyệt đối"},{"key":"B","text":"Bảo đảm dân chủ, trật tự, kỷ cương, phép nước"},{"key":"C","text":"Hạn chế quyền lực nhà nước"},{"key":"D","text":"Thể hiện hình thức văn hóa truyền thống"}]},{"n":44,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Chiến sĩ văn nghệ trong tư tưởng Hồ Chí Minh có nhiệm vụ gì ?","answer":"A","options":[{"key":"A","text":"Phụng sự Tổ quốc, phục vụ nhân dân, phò chính trừ tà"},{"key":"B","text":"Truyền bá văn hóa nước ngoài hiện đại"},{"key":"C","text":"Giải trí cho quần chúng sau lao động"},{"key":"D","text":"Tạo ra sản phẩm thương mại hóa văn hóa"}]},{"n":45,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Hồ Chí Minh coi văn hóa là nền tảng tinh thần của xã hội vì?","answer":"C","options":[{"key":"A","text":"Văn hóa chỉ là sản phẩm của kinh tế’"},{"key":"B","text":"Văn hóa là công cụ của giai cấp cầm quyền"},{"key":"C","text":"Văn hóa định hướng, điều chỉnh hành vi và thúc đẩy sự phát triển xã hội"},{"key":"D","text":"Văn hóa tồn tại độc lập, không liên quan đến con người"}]},{"n":46,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, văn hóa giáo dục góp phần vào?","answer":"D","options":[{"key":"A","text":"Đưa tri thức nước ngoài thay thế văn hóa dân tộc"},{"key":"B","text":"Phổ biến văn hóa giải trí và nghệ thuật"},{"key":"C","text":"Phát triển kinh tế thị trường định hướng xã hội chủ nghĩa"},{"key":"D","text":"Diệt giặc dốt, xóa mù chữ, đào tạo con người mới"}]},{"n":47,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Nội dung nào sau đây KHÔNG phản ánh đúng quan điểm của Hồ Chí Minh về văn hóa?","answer":"C","options":[{"key":"A","text":"Văn hóa là mục tiêu, động lực của cách mạng"},{"key":"B","text":"Văn hóa là một mặt trận đấu tranh tư tưởng"},{"key":"C","text":"Văn hóa là lĩnh vực tách biệt với chính trị và kinh tế"},{"key":"D","text":"Văn hóa góp phần nâng cao phẩm giá con người"}]},{"n":48,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, động lực phát triển đất nước quy tụ ở?","answer":"A","options":[{"key":"A","text":"Con người"},{"key":"B","text":"Vật chất"},{"key":"C","text":"Tài nguyên thiên nhiên"},{"key":"D","text":"Cơ chế quản lý"}]},{"n":49,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, tư tưởng văn hóa của Người hướng tới mục tiêu nào?","answer":"B","options":[{"key":"A","text":"Thể hiện quyền lực của trí thức trong sáng tạo nghệ thuật"},{"key":"B","text":"Phản ánh khát vọng hạnh phúc và tự do của nhân dân"},{"key":"C","text":"Phục vụ lợi ích của tầng lớp lãnh đạo và nhà nước"},{"key":"D","text":"Đề cao giá trị vật chất hơn tinh thần trong đời sống"}]},{"n":50,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, tư tưởng văn hóa của Người hướng tới mục tiêu nào?","answer":"A","options":[{"key":"A","text":"Phản ánh khát vọng hạnh phúc và tự do của nhân dân"},{"key":"B","text":"Thể hiện quyền lực của trí thức trong sáng tạo nghệ thuật"},{"key":"C","text":"Phục vụ lợi ích của tầng lớp lãnh đạo và nhà nước"},{"key":"D","text":"Đề cao giá trị vật chất hơn tinh thần trong đời sống"}]},{"n":51,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Hồ Chí Minh khẳng định, văn hóa phải “trở về với cuộc sống thực tại của quần chúng” nghĩa là?","answer":"B","options":[{"key":"A","text":"Văn hóa chỉ cần mô tả cuộc sống của tầng lớp trí thức"},{"key":"B","text":"Văn hóa phải phản ánh chân thật đời sống, tư tưởng, khát vọng của nhân dân"},{"key":"C","text":"Văn hóa nên hướng đến đề tài hiện đại hóa kỹ thuật"},{"key":"D","text":"Văn hóa phải tránh phản ánh hiện thực, chỉ nói lý tưởng"}]},{"n":52,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Câu nói “Viết cho ai? Mục đích viết? Lấy tài liệu đâu mà viết?” thể hiện yêu cầu nào trong sáng tạo văn hóa theo Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Phải viết theo yêu cầu của nhà nước để tuyên truyền"},{"key":"B","text":"Phải viết thiết thực, xuất phát từ quần chúng, phục vụ quần chúng"},{"key":"C","text":"Phải viết thật nhiều để phổ biến rộng rãi"},{"key":"D","text":"Phải viết nhằm thử nghiệm các hình thức nghệ thuật mới"}]},{"n":53,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, nói và viết trong hoạt động văn hóa phải như thế nào để quần chúng thích?","answer":"A","options":[{"key":"A","text":"Ít nhưng sâu sắc, chân thật, dễ hiểu và thấm thía"},{"key":"B","text":"Dài dòng, dùng nhiều thuật ngữ học thuật"},{"key":"C","text":"Sử dụng nhiều yếu tố biểu tượng trừu tượng"},{"key":"D","text":"Cầu kỳ, phức tạp để thể hiện trình độ học vấn"}]},{"n":54,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, nhân dân có vai trò gì trong sự phát triển văn hóa?","answer":"D","options":[{"key":"A","text":"Là đối tượng thụ động tiếp nhận sản phẩm văn hóa"},{"key":"B","text":"Là người tiêu thụ sản phẩm văn hóa thương mại"},{"key":"C","text":"Là đối tượng được tuyên truyền chính trị đơn thuần"},{"key":"D","text":"Là người sáng tạo, cung cấp tư liệu và thẩm định sản phẩm văn hóa"}]},{"n":55,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo tư tưởng Hồ Chí Minh, mục tiêu cuối cùng của hoạt động văn hóa là?","answer":"A","options":[{"key":"A","text":"Phục vụ nhân dân, làm cho nhân dân được hưởng thụ văn hóa"},{"key":"B","text":"Tăng doanh thu và phát triển công nghiệp văn hóa"},{"key":"C","text":"Quảng bá hình ảnh của tầng lớp trí thức xã hội"},{"key":"D","text":"Phục vụ công tác tuyên truyền ngắn hạn của chính quyền"}]},{"n":56,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, người chiến sĩ văn hóa cần có phẩm chất nào để phục vụ nhân dân hiệu quả?","answer":"B","options":[{"key":"A","text":"Sáng tạo cá nhân độc lập, không chịu ràng buộc xã hội"},{"key":"B","text":"Hiểu quần chúng, gắn bó với đời sống và có lập trường tư tưởng vững vàng"},{"key":"C","text":"Quan tâm đến lợi nhuận kinh tế của sản phẩm văn hóa"},{"key":"D","text":"Tập trung vào giá trị hình thức và kỹ thuật nghệ thuật"}]},{"n":57,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, quần chúng nhân dân không chỉ là người tiếp nhận văn hóa mà còn là:","answer":"A","options":[{"key":"A","text":"Chủ thể sáng tạo và đánh giá chân thực giá trị văn hóa"},{"key":"B","text":"Đối tượng cần được giáo dục để tiếp thu văn hóa mới"},{"key":"C","text":"Người tiêu thụ sản phẩm văn hóa nghệ thuật"},{"key":"D","text":"Nhóm công chúng cần hướng dẫn về đạo đức truyền thống"}]},{"n":58,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Yêu cầu “tránh cái lối viết rau muống mà ham dùn g chữ” của Hồ Chí Minh phê phán điều gì?","answer":"C","options":[{"key":"A","text":"Phong cách nghệ thuật truyền thống của dân tộc"},{"key":"B","text":"Việc sử dụng ngôn ngữ dân gian trong sáng tác văn hóa"},{"key":"C","text":"Cách viết cầu kỳ, sáo rỗng, xa rời đời sống thực tế của nhân dân"},{"key":"D","text":"Lối viết ngắn gọn, dễ hiểu, giản dị"}]},{"n":59,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Chiến sĩ văn hóa, theo Hồ Chí Minh, là người?","answer":"D","options":[{"key":"A","text":"Là cán bộ quản lý nhà nước trong lĩnh vực tuyên truyền"},{"key":"B","text":"Là người giữ gìn thuần phong mỹ tục truyền thống"},{"key":"C","text":"Là nhà phê bình nghệ thuật chuyên nghiệp"},{"key":"D","text":"Hoạt động trên mặt trận tư tưởng – văn hóa, phục vụ nhân dân"}]},{"n":60,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Theo Hồ Chí Minh, giá trị chân, thiện, mỹ của văn hóa phải được định hướng cho?","answer":"C","options":[{"key":"A","text":"Cán bộ lãnh đạo"},{"key":"B","text":"Nhà nghiên cứu"},{"key":"C","text":"Quần chúng nhân dân"},{"key":"D","text":"Giới văn nghệ sĩ"}]},{"n":61,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của văn hóa","stem":"Tư tưởng “Văn hóa phục vụ quần chúng nhân dân” của Hồ Chí Minh hướng đến mục tiêu cao nhất là?","answer":"A","options":[{"key":"A","text":"Làm cho nhân dân được hưởng thụ, sáng tạo và sống trong môi trường văn hóa lành mạnh"},{"key":"B","text":"Xây dựng tầng lớp trí thức văn nghệ sĩ lớn mạnh"},{"key":"C","text":"Tăng sản lượng các sản phẩm văn hóa công nghiệp"},{"key":"D","text":"Đưa văn hóa Việt Nam hòa nhập toàn cầu nhanh nhất"}]},{"n":62,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Theo Hồ Chí Minh, việc xây dựng nền văn hóa dân tộc được Người đề cập lần đầu tiên vào thời điểm nào?","answer":"A","options":[{"key":"A","text":"Tháng 8 năm 1943, trong bối cảnh chuẩn bị Cách mạng Tháng Tám"},{"key":"B","text":"Năm 1941, trong bản Chỉ thị về khởi nghĩa toàn dân"},{"key":"C","text":"Năm 1945, ngay sau khi giành được độc lập"},{"key":"D","text":"Năm 1942, trong Nhật ký trong tù"}]},{"n":63,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Trong năm nội dung xây dựng văn hóa dân tộc năm 1943, “xây dựng tâm lý” theo Hồ Chí Minh là?","answer":"A","options":[{"key":"A","text":"Bồi dưỡng tinh thần độc lập tự cường của dân tộc"},{"key":"B","text":"Nâng cao trình độ học vấn cho mọi tầng lớp"},{"key":"C","text":"Hình thành nếp sống tập thể trong lao động"},{"key":"D","text":"Phát triển đời sống vật chất, kinh tế cá nhân"}]},{"n":64,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Theo Hồ Chí Minh, “xây dựng luân lý” trong năm nội dung của văn hóa dân tộc là?","answer":"B","options":[{"key":"A","text":"Nâng cao đạo đức nghề nghiệp trong sản xuất"},{"key":"B","text":"Bồi dưỡng tinh thần hy sinh vì lợi ích của quần chúng nhân dân"},{"key":"C","text":"Giữ gìn phong tục, tập quán truyền thống cổ xưa"},{"key":"D","text":"Đề cao cá nhân trong các hoạt động xã hội"}]},{"n":65,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"“Xây dựng chính trị” trong tư tưởng Hồ Chí Minh về văn hóa năm 1943 là?","answer":"C","options":[{"key":"A","text":"Mở rộng quan hệ quốc tế trong lĩnh vực chính trị"},{"key":"B","text":"Đào tạo đội ngũ cán bộ lãnh đạo có trình độ cao"},{"key":"C","text":"Xây dựng chế độ dân quyền, phát huy quyền làm chủ của nhân dân"},{"key":"D","text":"Xây dựng hệ thống pháp luật hoàn thiện và hiện đại"}]},{"n":66,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Trong năm nội dung xây dựng văn hóa dân tộc năm 1943, “xây dựng kinh tế” có ý nghĩa gì?","answer":"A","options":[{"key":"A","text":"Là nền tảng vật chất của đời sống văn hóa, bảo đảm phúc lợi nhân dân"},{"key":"B","text":"Là mục tiêu chính để mở rộng quan hệ thương mại quốc tế"},{"key":"C","text":"Là phương tiện để phát triển công nghiệp hóa đất nước"},{"key":"D","text":"Là yếu tố phụ thuộc hoàn toàn vào chính trị và xã hội"}]},{"n":67,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Trong kháng chiến chống Pháp, Hồ Chí Minh khẳng định phương châm xây dựng nền văn hóa mới là?","answer":"A","options":[{"key":"A","text":"Dân tộc, khoa học, đại chúng"},{"key":"B","text":"Độc lập, tự chủ, nhân văn"},{"key":"C","text":"Truyền thống, sáng tạo, hòa nhập"},{"key":"D","text":"Chính trị, kinh tế, xã hội"}]},{"n":68,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Tính “dân tộc” trong nền văn hóa mới theo Hồ Chí Minh được hiểu là?","answer":"A","options":[{"key":"A","text":"Dân tộc, khoa học, đại chúng"},{"key":"B","text":"Độc lập, tự chủ, nhân văn"},{"key":"C","text":"Truyền thống, sáng tạo, hòa nhập"},{"key":"D","text":"Chính trị, kinh tế, xã hội"}]},{"n":69,"sec":"3. Quan điểm Hồ Chí Minh về xây dựng nền văn hóa mới","stem":"Vì sao Hồ Chí Minh coi xây dựng nền văn hóa mới là yêu cầu tất yếu của cách mạng Việt Nam?","answer":"D","options":[{"key":"A","text":"Vì văn hóa là phương tiện tuyên truyền phục vụ chính trị"},{"key":"B","text":"Vì văn hóa là công cụ để bảo vệ lợi ích giai cấp cầm quyền"},{"key":"C","text":"Vì văn hóa chỉ là yếu tố trang trí cho xã hội văn minh"},{"key":"D","text":"Vì văn hóa là sức mạnh tinh thần, nền tảng cho sự phát triển bền vững của đất nước"}]},{"n":70,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Theo Hồ Chí Minh, đạo đức giữ vai trò gì trong đời sống con người?","answer":"A","options":[{"key":"A","text":"Là gốc, là nền tảng tinh thần, là nguồn nuôi dưỡng và phát triển con người"},{"key":"B","text":"Là yếu tố phụ thuộc vào trình độ văn hóa của xã hội"},{"key":"C","text":"Là công cụ điều chỉnh hành vi tạm thời trong tổ chức"},{"key":"D","text":"Là sản phẩm của tôn giáo và tín ngưỡng dân gian"}]},{"n":71,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Hồ Chí Minh ví đạo đức của người cách mạng như?","answer":"B","options":[{"key":"A","text":"Mặt trời soi sáng con đường cách mạng"},{"key":"B","text":"Gốc của cây, ngọn nguồn của sông suối"},{"key":"C","text":"Bông hoa nở rộ trong vườn nhân cách"},{"key":"D","text":"Ngọn đèn dẫn đường cho trí tuệ con người"}]},{"n":72,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Điền từ còn thiếu vào (_____)? Hồ Chí Minh nhiều lần khẳng định đạo đức là (_____), là (_____), là (_____), là (_____) của người cách mạng.","answer":"A","options":[{"key":"A","text":"Gốc, nền tảng, sức mạnh, tiêu chuẩn hàng đầu"},{"key":"B","text":"Mục tiêu, động lực, nguyên tắc, phương tiện"},{"key":"C","text":"Lý tưởng, hành động, niềm tin, ý chí phấn đấu"},{"key":"D","text":"Căn bản, phẩm chất, ý thức, tinh thần phục vụ"}]},{"n":73,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Hồ Chí Minh xác định yếu tố nào là gốc của người cán bộ cách mạng?","answer":"B","options":[{"key":"A","text":"Tài"},{"key":"B","text":"Đức"},{"key":"C","text":"Thể"},{"key":"D","text":"Trí"}]},{"n":74,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Điền từ còn thiếu vào (_____)? Trong tác phẩm Sửa đối lối làm việc (1947), Người viết: “Cũng như sông thì có (_____) mới có nước, không có nguồn thì sông cạn. Cây phải có (_____), không có gốc thì cây héo. Người cách mạng phải có (_____), không có đạo đức thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân.” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.5, tr.292-293)","answer":"A","options":[{"key":"A","text":"nguồn - gốc - đạo đức"},{"key":"B","text":"cội - rễ - niềm tin"},{"key":"C","text":"mạch - thân - chí hướng"},{"key":"D","text":"đầu - cành - ý chí"}]},{"n":75,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Trong tác phẩm Sửa đổi lối làm việc (1947), Hồ Chí Minh khẳng định?","answer":"B","options":[{"key":"A","text":"“Người cách mạng cần học tập, rèn luyện đạo đức suốt đời.”"},{"key":"B","text":"“Người cách mạng phải có đạo đức, không có đạo đức thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân.”"},{"key":"C","text":"“Đạo đức là nền tảng của văn hóa dân tộc.”"},{"key":"D","text":"“Đạo đức là thước đo của trình độ chính trị.”"}]},{"n":76,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Theo Hồ Chí Minh, đạo đức giữ vai trò gì trong đời sống con người?","answer":"A","options":[{"key":"A","text":"Là gốc, là nền tảng tinh thần, là nguồn nuôi dưỡng và phát triển con người"},{"key":"B","text":"Là yếu tố phụ thuộc vào trình độ văn hóa của xã hội"},{"key":"C","text":"Là công cụ điều chỉnh hành vi tạm thời trong tổ chức"},{"key":"D","text":"Là sản phẩm của tôn giáo và tín ngưỡng dân gian"}]},{"n":77,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Hồ Chí Minh ví đạo đức của người cách mạng như?","answer":"A","options":[{"key":"A","text":"Gốc của cây, ngọn nguồn của sông suối"},{"key":"B","text":"Mặt trời soi sáng con đường cách mạng"},{"key":"C","text":"Bông hoa nở rộ trong vườn nhân cách"},{"key":"D","text":"Ngọn đèn dẫn đường cho trí tuệ con người"}]},{"n":78,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Theo Hồ Chí Minh, người cách mạng không có đạo đức thì?","answer":"D","options":[{"key":"A","text":"Có thể dựa vào tập thể để bù đắp sự thiếu sót cá nhân"},{"key":"B","text":"Cần được bồi dưỡng thêm về kỹ năng chính trị"},{"key":"C","text":"Vẫn có thể hoàn thành nhiệm vụ nếu có năng lực"},{"key":"D","text":"Dù tài giỏi mấy cũng không lãnh đạo được nhân dân"}]},{"n":79,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Trong tác phẩm Đạo đức cách mạng (1958), Hồ Chí Minh nhấn mạnh?","answer":"B","options":[{"key":"A","text":"Đạo đức là tiêu chuẩn duy nhất để đánh giá con người"},{"key":"B","text":"Người cách mạng phải có đạo đức cách mạng làm nền tảng, mới hoàn thành được nhiệm vụ vẻ vang"},{"key":"C","text":"Đạo đức là điều kiện phụ trong công tác lãnh đạo"},{"key":"D","text":"Cán bộ cần đặt lợi ích cá nhân sau tập thể"}]},{"n":80,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Hồ Chí Minh yêu cầu người cán bộ cách mạng phải có đạo đức cách mạng, bởi vì?","answer":"C","options":[{"key":"A","text":"Có đạo đức mới thấu hiểu nhân dân"},{"key":"B","text":"Đạo đức là điều kiện để được đề bạt"},{"key":"C","text":"Mọi việc thành hay bại chủ yếu do cán bộ có thấm nhuần đạo đức cách mạng hay không"},{"key":"D","text":"Đạo đức giúp người cán bộ giữ uy tín chính trị"}]},{"n":81,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"“Cũng như sông có nguồn thì mới có nước, không có nguồn thì sông cạn. Cây phải có gốc, không có gốc thì cây héo. Người cách mạng phải có đạo đức, không có đạo đức thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân”. Câu nói trên được trích trong tác phẩm nào của Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Đường Kách mệnh"},{"key":"B","text":"Sửa đổi lối làm việc"},{"key":"C","text":"Nhật ký trong tù"},{"key":"D","text":"Đạo đức cách mạng"}]},{"n":82,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Chuẩn mực đạo đức của người cách mạng theo Tư tưởng Hồ Chí Minh là?","answer":"D","options":[{"key":"A","text":"Trung với nước hiếu với dân; yêu thương con người"},{"key":"B","text":"Cần, kiệm, liêm, chính, chí công vô tư"},{"key":"C","text":"Có tinh thần quốc tế trong sáng"},{"key":"D","text":"Cả A, B và C"}]},{"n":83,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"“Cũng như sông có nguồn thì mới có nước, không có nguồn thì sông cạn. Cây phải có gốc, không có gốc thì cây héo. Người cách mạng phải có đạo đức, không có đạo đức thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân”. Câu nói trên được trích trong tác phẩm nào của Hồ Chí Minh?","answer":"B","options":[{"key":"A","text":"Đường Kách mệnh"},{"key":"B","text":"Sửa đổi lối làm việc"},{"key":"C","text":"Nhật ký trong tù"},{"key":"D","text":"Đạo đức cách mạng"}]},{"n":84,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Khi viết tác phẩm “Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân”, Hồ Chí Minh lấy bút danh là gì?","answer":"B","options":[{"key":"A","text":"Hồ Chí Minh"},{"key":"B","text":"Trần Lực"},{"key":"C","text":"Già Thu"},{"key":"D","text":"Văn Ba"}]},{"n":85,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Hãy cho biết câu nói dưới đây là của ai? “Việc học không bao giờ cùng, còn sống còn phải học”.","answer":"B","options":[{"key":"A","text":"V.I. Lênin"},{"key":"B","text":"Hồ Chí Minh"},{"key":"C","text":"Quản Trọng."},{"key":"D","text":"Khổng Tử"}]},{"n":86,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"“Người mà không liêm, không bằng súc vật”. Câu nói trên là của ai?","answer":"A","options":[{"key":"A","text":"Khổng Tử"},{"key":"B","text":"Mạnh Tử"},{"key":"C","text":"Các Mác"},{"key":"D","text":"Hồ Chí Minh"}]},{"n":87,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Tác phẩm “Đạo đức cách mạng” của Hồ Chí Minh được in lần đầu tiên trên tạp chí nào?","answer":"B","options":[{"key":"A","text":"Tạp chí Quân đội nhân dân"},{"key":"B","text":"Tạp chí Học tập"},{"key":"C","text":"Tạp chí Những vấn đề hòa bình và chủ nghĩa xã hội"},{"key":"D","text":"Tạp chí Xây dựng Đảng"}]},{"n":88,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Trong các phẩm chất đạo đức cơ bản của con người Việt Nam trong thời đại mới, phẩm chất đạo đức nào quan trọng nhất, bao trùm nhất?","answer":"C","options":[{"key":"A","text":"Yêu thương con người"},{"key":"B","text":"Cần, kiệm, liêm, chính, chí công vô tư"},{"key":"C","text":"Trung với nước, hiếu với dân"},{"key":"D","text":"Tinh thần quốc tế trong sáng"}]},{"n":89,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Lối sống ích kỷ, chỉ biết có riêng mình, thu vén cho riêng mình, chỉ thấy công lao của mình mà quên công lao của người khác. Theo Hồ Chí Minh là gì?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa cá nhân"},{"key":"B","text":"Chủ nghĩa vị kỷ"},{"key":"C","text":"Chủ nghĩa tư bản"},{"key":"D","text":"Phong cách tiểu tư sản"}]},{"n":90,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Theo Hồ Chí Minh, nếu người cách mạng không có đạo đức thì hậu quả gì xảy ra?","answer":"C","options":[{"key":"A","text":"Dễ bị quần chúng xa lánh, mất uy tín."},{"key":"B","text":"Không thể học tập và tiến bộ"},{"key":"C","text":"Dù tài giỏi mấy cũng không làm nổi việc lớn"},{"key":"D","text":"Chỉ có thể làm công việc nhỏ, không thể lãnh đạo"}]},{"n":91,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Trong Di chúc, Hồ Chí Minh căn dặn cán bộ, đảng viên phải?","answer":"B","options":[{"key":"A","text":"Luôn rèn luyện về tư duy chính trị và năng lực công tác"},{"key":"B","text":"Thật sự thấm nhuần đạo đức cách mạng, cần kiệm liêm chính, chí công vô tư"},{"key":"C","text":"Biết vận dụng linh hoạt các chủ trương của Đảng"},{"key":"D","text":"Gắn bó mật thiết với nhân dân trong sản xuất"}]},{"n":92,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Theo Hồ Chí Minh, mối quan hệ giữa đức và tài là?","answer":"A","options":[{"key":"A","text":"Đức là mục tiêu, tài là phương tiện để đạt mục tiêu"},{"key":"B","text":"Đức quan trọng hơn tài, tài chỉ là phụ"},{"key":"C","text":"Đức và tài tách biệt, không liên quan."},{"key":"D","text":"Tài là nền tảng, đức là kết quả"}]},{"n":93,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Trong tư tưởng Hồ Chí Minh, “hồng” và “chuyên” tương ứng với?","answer":"C","options":[{"key":"A","text":"Đạo đức và trí tuệ"},{"key":"B","text":"Chính trị và kỹ năng"},{"key":"C","text":"Đức và tài"},{"key":"D","text":"Trung thành và sáng tạo"}]},{"n":94,"sec":"1. Đạo đức là gốc, là nền tảng tinh thần của xã hội, của người cách","stem":"Điền từ còn thiếu vào (_____)? Trong bài Đạo đức cách mạng (1955), Hồ Chí Minh viết: “Tuy năng lực và công việc của mỗi người khác nhau, người làm việc to, người làm việc nhỏ; nhưng ai giữ được (_____) đều là người cao thượng” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.14, tr.400).","answer":"A","options":[{"key":"A","text":"Đạo đức"},{"key":"B","text":"Tài năng"},{"key":"C","text":"Tinh thần"},{"key":"D","text":"Ý chí"}]},{"n":95,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, phẩm chất đạo đức bao trùm và quan trọng nhất trong đạo đức cách mạng là gì?","answer":"B","options":[{"key":"A","text":"Cần, kiệm, liêm, chính"},{"key":"B","text":"Trung với nước, hiếu với dân"},{"key":"C","text":"Chí công vô tư"},{"key":"D","text":"Yêu nước, thương dân"}]},{"n":96,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh đã kế thừa và phát triển quan niệm đạo đức truyền thống “Trung với vua, hiếu với cha mẹ” thành?","answer":"B","options":[{"key":"A","text":"Trung với Đảng, hiếu với nhân dân"},{"key":"B","text":"Trung với nước, hiếu với dân"},{"key":"C","text":"Trung thành với lãnh tụ, tận tụy với nhân dân"},{"key":"D","text":"Trung thực với tổ chức, hiếu nghĩa với đồng bào"}]},{"n":97,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, “Trung với nước” có nghĩa là?","answer":"C","options":[{"key":"A","text":"Trung thành với triều đình và giai cấp thống trị"},{"key":"B","text":"Trung thực trong công tác, tận tụy trong nhiệm vụ được giao"},{"key":"C","text":"Trung thành tuyệt đối với sự nghiệp dựng nước, giữ nước, vì Tổ quốc, vì nhân dân"},{"key":"D","text":"Trung thành với người lãnh đạo và cơ quan nhà nước"}]},{"n":98,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Trong đạo đức mới mà Hồ Chí Minh nêu, “Hiếu với dân” được hiểu là?","answer":"A","options":[{"key":"A","text":"Thương dân, tin dân, thân dân, học hỏi dân, lấy trí tuệ ở dân, kính trọng dân, lấy dân làm gốc, hết lòng hết sức phục vụ nhân dân."},{"key":"B","text":"Kính trọng nhân dân nhưng chỉ ở mức độ hình thức"},{"key":"C","text":"Giúp đỡ nhân dân trong những việc cần thiết"},{"key":"D","text":"Quan tâm đến nhân dân trong phạm vi địa phương mình"}]},{"n":99,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Câu nói của Hồ Chí Minh: “Bao nhiêu lợi ích đều vì dân, bao nhiêu quyền hạn đều của dân” thể hiện tư tưởng nào?","answer":"A","options":[{"key":"A","text":"Tư tưởng dân làm chủ, dân là gốc"},{"key":"B","text":"Tư tưởng dân chủ xã hội chủ nghĩa"},{"key":"C","text":"Tư tưởng trung thành với Đảng"},{"key":"D","text":"Tư tưởng đoàn kết toàn dân"}]},{"n":100,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh cho rằng, “Cần, kiệm, liêm, chính, chí công vô tư” là?","answer":"A","options":[{"key":"A","text":"Phẩm chất đạo đức cơ bản của người cách mạng"},{"key":"B","text":"Chuẩn mực đạo đức của tầng lớp trí thức"},{"key":"C","text":"Yêu cầu đạo đức của người dân trong thời chiến"},{"key":"D","text":"Tư tưởng đạo đức mang tính truyền thống Nho giáo"}]},{"n":101,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Cần” trong tư tưởng Hồ Chí Minh có nghĩa là?","answer":"A","options":[{"key":"A","text":"Lao động siêng năng, sáng tạo, có kế hoạch và hiệu quả"},{"key":"B","text":"Chăm chỉ làm việc theo chỉ thị của cấp trên"},{"key":"C","text":"Nỗ lực trong công việc nhưng không cần kế hoạch"},{"key":"D","text":"Làm việc với cường độ cao mà không quan tâm kết quả"}]},{"n":102,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Kiệm” theo Hồ Chí Minh được hiểu là?","answer":"B","options":[{"key":"A","text":"Tiết kiệm mọi chi tiêu cá nhân, không quan tâm lợi ích chung"},{"key":"B","text":"Tiết kiệm sức lao động, thời gian, tiền của, không hoang phí"},{"key":"C","text":"Không sử dụng bất kỳ tài sản nào của tập thể"},{"key":"D","text":"Tự hạn chế mọi nhu cầu chính đáng của bản thân"}]},{"n":103,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh khẳng định: “Cần với Kiệm phải đi đôi với nhau, như hai chân của con người”. Ý nghĩa là?","answer":"A","options":[{"key":"A","text":"Hai đức tính này bổ sung cho nhau, không thể tách rời"},{"key":"B","text":"Cần quan trọng hơn Kiệm trong xây dựng đạo đức"},{"key":"C","text":"Kiệm chỉ có ý nghĩa khi Cần được thực hiện triệt để"},{"key":"D","text":"Cần và Kiệm là hai đức tính đối lập nhau"}]},{"n":104,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh khẳng định “Cần với Kiệm phải đi đôi với nhau như hai chân của con người”, bởi vì?","answer":"D","options":[{"key":"A","text":"Cần mà không Kiệm thì không thể phát huy được sức lao động"},{"key":"B","text":"Kiệm mà không Cần thì dễ trở nên bủn xỉn, bảo thủ"},{"key":"C","text":"Hai đức tính này hỗ trợ, bổ sung cho nhau trong mọi hoạt động"},{"key":"D","text":"Cả A, B và C"}]},{"n":105,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Liêm” theo Hồ Chí Minh được hiểu là?","answer":"A","options":[{"key":"A","text":"Trong sạch, không tham lam, không hủ hóa"},{"key":"B","text":"Cứng rắn, kiên định, không khuất phục trước khó khăn"},{"key":"C","text":"Khiêm nhường, chân thành, tôn trọng đồng chí"},{"key":"D","text":"Vị tha, thương người, biết sẻ chia"}]},{"n":106,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Liêm phải đi đôi với Kiệm” – điều này thể hiện ý nghĩa gì?","answer":"A","options":[{"key":"A","text":"Có Kiệm mới có thể Liêm được, vì biết quý trọng của cải"},{"key":"B","text":"Hai đức tính này cùng tạo nên tinh thần dũng cảm"},{"key":"C","text":"Người Kiệm ắt sẽ có tính nhân ái"},{"key":"D","text":"Liêm và Kiệm là phẩm chất riêng của cán bộ quản lý"}]},{"n":107,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo tư tưởng Hồ Chí Minh, chữ “Chính” được hiểu là?","answer":"B","options":[{"key":"A","text":"Kiên định, trung thành, có ý chí mạnh mẽ"},{"key":"B","text":"Nghĩa là không tà, nghĩa là thẳng thắn, đứng đắn"},{"key":"C","text":"Biết yêu thương đồng bào, đồng chí"},{"key":"D","text":"Không gian dối, biết tiết kiệm của công"}]},{"n":108,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh yêu cầu người “Chính” phải thế nào trong mối quan hệ với bản thân?","answer":"D","options":[{"key":"A","text":"Giữ lòng nhân hậu, sẵn sàng giúp đỡ người khác"},{"key":"B","text":"Sống giản dị, khiêm tốn, hòa đồng với nhân dân"},{"key":"C","text":"Luôn cố gắng vượt qua khó khăn, thử thách"},{"key":"D","text":"Không tự kiêu, tự đại, phải biết tự phê bình và sửa chữa"}]},{"n":109,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Trong mối quan hệ với người khác, “Chính” được thể hiện như thế nào?","answer":"C","options":[{"key":"A","text":"Biết sống hòa nhã, tôn trọng và giúp đỡ đồng chí"},{"key":"B","text":"Phải công bằng, công tâm trong xử lý công việc"},{"key":"C","text":"Không nịnh hót người trên, không khinh người dưới, thái độ chân thành, khiêm tốn"},{"key":"D","text":"Không để tình cảm cá nhân chi phối hành động"}]},{"n":110,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, “Chí công vô tư” là?","answer":"A","options":[{"key":"A","text":"Hoàn toàn vì lợi ích chung, không vì tư lợi cá nhân"},{"key":"B","text":"Tận tụy trong công việc, biết tiết kiệm và khiêm tốn"},{"key":"C","text":"Làm việc vì danh dự, không màng địa vị"},{"key":"D","text":"Đặt quyền lợi cá nhân dưới quyền lợi gia đình"}]},{"n":111,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Chí công vô tư” có quan hệ như thế nào với “Cần, kiệm, liêm, chính”?","answer":"C","options":[{"key":"A","text":"Là biểu hiện thấp hơn trong đạo đức cách mạng"},{"key":"B","text":"Là một nội dung hoàn toàn tách biệt, độc lập"},{"key":"C","text":"Là sự kế thừa và phát triển cao hơn của bốn đức tính đó"},{"key":"D","text":"Là một phẩm chất chỉ áp dụng cho cán bộ lãnh đạo"}]},{"n":112,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh nhấn mạnh: “Có quyền mà thiếu lương tâm là có dịp…” – cụm từ còn thiếu là gì?","answer":"B","options":[{"key":"A","text":"“Tham ô, lãng phí, quan liêu”"},{"key":"B","text":"“Đục khoét, dĩ công vi tư”"},{"key":"C","text":"“Lười biếng, vô trách nhiệm”"},{"key":"D","text":"“Tự cao, tự đại”"}]},{"n":113,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh coi “Cần, kiệm, liêm, chính” như bốn yếu tố nào của tự nhiên?","answer":"A","options":[{"key":"A","text":"Bốn mùa của trời, bốn phương của đất"},{"key":"B","text":"Bốn trụ cột của nhân cách con người"},{"key":"C","text":"Bốn nguyên tắc sống đạo đức"},{"key":"D","text":"Bốn gốc rễ của tư tưởng cách mạng"}]},{"n":114,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, “Thiếu một đức thì không thành người” – Người muốn nhấn mạnh điều gì?","answer":"D","options":[{"key":"A","text":"Mất một đức tính sẽ làm suy yếu nhân cách đạo đức"},{"key":"B","text":"Cần kết hợp đạo đức cá nhân và đạo đức xã hội"},{"key":"C","text":"Mỗi phẩm chất đều có vai trò ngang nhau trong cuộc sống"},{"key":"D","text":"Các phẩm chất cần, kiệm, liêm, chính có quan hệ mật thiết, không thể tách rời"}]},{"n":115,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh cho rằng dân tộc biết cần, kiệm, liêm là?","answer":"A","options":[{"key":"A","text":"Dân tộc giàu về vật chất, mạnh về tinh thần, văn minh tiến bộ"},{"key":"B","text":"Dân tộc có nền văn hóa phong phú, nhân đạo và nhân văn"},{"key":"C","text":"Dân tộc đoàn kết, nghĩa tình, có tinh thần tự lực tự cường"},{"key":"D","text":"Dân tộc có nền kinh tế phát triển, chính trị ổn định"}]},{"n":116,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh yêu cầu cán bộ phải “thực hành chữ Liêm trước” vì?","answer":"A","options":[{"key":"A","text":"Dân tộc giàu về vật chất, mạnh về tinh thần, văn minh tiến bộ"},{"key":"B","text":"Dân tộc có nền văn hóa phong phú, nhân đạo và nhân văn"},{"key":"C","text":"Dân tộc đoàn kết, nghĩa tình, có tinh thần tự lực tự cường"},{"key":"D","text":"Dân tộc có nền kinh tế phát triển, chính trị ổn định"}]},{"n":117,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"“Cần, kiệm, liêm , chính, chí công vô tư” phản ánh phẩm chất nào của người cách mạng?","answer":"A","options":[{"key":"A","text":"Trung với nước, hiếu với dân"},{"key":"B","text":"Tận tụy, kiên định, sáng tạo"},{"key":"C","text":"Giản dị, khiêm tốn, nhân ái"},{"key":"D","text":"Dũng cảm, trung thực, đoàn kết"}]},{"n":118,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, nền tảng đạo đức cách mạng trước hết phải được xây dựng trên phẩm chất nào?","answer":"C","options":[{"key":"A","text":"Trung thực với bản thân, kiên định với lý tưởng cá nhân"},{"key":"B","text":"Sống giản dị, khiêm tốn, cần kiệm trong lao động"},{"key":"C","text":"Thương yêu con người, sống có tình có nghĩa"},{"key":"D","text":"Phát huy chủ nghĩa yêu nước gắn với chủ nghĩa anh hùng cách mạng"}]},{"n":119,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Nguồn gốc hình thành tư tưởng \"thương yêu con người\" của Hồ Chí Minh xuất phát từ đâu?","answer":"A","options":[{"key":"A","text":"Kế thừa truyền thống nhân nghĩa của dân tộc, kết hợp với chủ nghĩa nhân đạo cộng sản"},{"key":"B","text":"Kết hợp tư tưởng phương Đông và tinh thần duy lý phương Tây trong tu dưỡng đạo đức cá nhân"},{"key":"C","text":"Từ giáo lý của các tôn giáo lớn ở Việt Nam và tinh thần dân tộc"},{"key":"D","text":"Ảnh hưởng của triết học phương Tây và chủ nghĩa hiện sinh nhân bản"}]},{"n":120,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, tình yêu thương con người trước hết phải hướng tới ai?","answer":"C","options":[{"key":"A","text":"Những người có công với cách mạng"},{"key":"B","text":"Những người lao động, tầng lớp trí thức tiến bộ"},{"key":"C","text":"Những người nghèo khổ, những người bị mất quyền, bị áp bức, bị bóc lột"},{"key":"D","text":"Những người có tinh thần tập thể và ý thức cộng đồng cao"}]},{"n":121,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh quan niệm thế nào là “hiểu chủ nghĩa Mác – Lênin”?","answer":"D","options":[{"key":"A","text":"Là nắm vững lý luận cách mạng và vận dụng vào thực tiễn"},{"key":"B","text":"Là đấu tranh không khoan nhượng với các thế lực phản động"},{"key":"C","text":"Là trung thành tuyệt đối với Đảng và nhân dân"},{"key":"D","text":"Là phải sống với nhau có tình có nghĩa"}]},{"n":122,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, “hiểu (_____) là phải sống với nhau có tình có nghĩa. Nếu thuộc bao nhiêu sách mà sống không có tình có nghĩa thì sao gọi là hiểu chủ nghĩa Mác - Lênin được” (Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.15, tr.668).","answer":"B","options":[{"key":"A","text":"Chủ nghĩa nhân đạo cộng sản"},{"key":"B","text":"Chủ nghĩa Mác – Lênin"},{"key":"C","text":"Tư tưởng Hồ Chí Minh"},{"key":"D","text":"Chủ nghĩa xã hội khoa học"}]},{"n":123,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, tình thương yêu con người phải được thể hiện như thế nào?","answer":"B","options":[{"key":"A","text":"Qua lời nói chân thành và sự chia sẻ tinh thần"},{"key":"B","text":"Ở hành động cụ thể, thiết thực trong quan hệ hằng ngày"},{"key":"C","text":"Bằng thái độ tôn trọng luật pháp và quy tắc xã hội"},{"key":"D","text":"Thông qua công tác giáo dục và tuyên truyền đạo đức"}]},{"n":124,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Tình thương yêu con người của Hồ Chí Minh khác với “dĩ hòa vi quý” ở điểm nào?","answer":"A","options":[{"key":"A","text":"Không chấp nhận điều ác, không dung túng cái sai"},{"key":"B","text":"Luôn giữ thái độ mềm mỏng, khoan dung vô điều kiện"},{"key":"C","text":"Nhấn mạnh sự hòa thuận trong mọi quan hệ xã hội"},{"key":"D","text":"Xem trọng sự yên ổn hơn là đấu tranh cho lẽ phải"}]},{"n":125,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, chủ nghĩa quốc tế là phẩm chất đạo đức của?","answer":"C","options":[{"key":"A","text":"Mọi công dân yêu nước chân chính"},{"key":"B","text":"Mọi người yêu hòa bình và công lý"},{"key":"C","text":"Người cộng sản chân chính"},{"key":"D","text":"Người hoạt động trong lĩnh vực ngoại giao"}]},{"n":126,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh kết hợp nhuần nhuyễn giữa hai yếu tố nào trong tư tưởng đạo đức?","answer":"B","options":[{"key":"A","text":"Chủ nghĩa quốc tế và tinh thần tự do cá nhân"},{"key":"B","text":"Chủ nghĩa yêu nước chân chính và chủ nghĩa quốc tế vô sản"},{"key":"C","text":"Tình yêu nhân loại và lòng trung thành với giai cấp"},{"key":"D","text":"Tinh thần độc lập dân tộc và chính trị hòa bình"}]},{"n":127,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Nội dung chủ nghĩa quốc tế trong tư tưởng Hồ Chí Minh KHÔNG bao gồm điều nào dưới đây?","answer":"C","options":[{"key":"A","text":"Tôn trọng, hiểu biết, đoàn kết với các dân tộc bị áp bức"},{"key":"B","text":"Chống lại mọi biểu hiện của phân biệt chủng tộc và bá quyền"},{"key":"C","text":"Đặt lợi ích dân tộc lên trên mọi lợi ích khác của nhân loại"},{"key":"D","text":"Ủng hộ đấu tranh vì hòa bình, độc lập dân tộc, dân chủ"}]},{"n":128,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Câu thơ “Quan sơn muôn dặm một nhà, Bốn phương vô sản đều là anh em” thể hiện tư tưởng nào?","answer":"B","options":[{"key":"A","text":"Tinh thần hòa bình, hữu nghị giữa các dân tộc"},{"key":"B","text":"Tinh thần quốc tế trong sáng"},{"key":"C","text":"Lý tưởng cộng sản toàn cầu"},{"key":"D","text":"Tình đoàn kết giữa nhân dân Việt Nam và bạn bè thế giới"}]},{"n":129,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Trong quan hệ quốc tế, Hồ Chí Minh chủ trương thay “đối đầu” bằng điều gì?","answer":"A","options":[{"key":"A","text":"Đối thoại"},{"key":"B","text":"Thỏa hiệp"},{"key":"C","text":"Cạnh tranh"},{"key":"D","text":"Liên kết"}]},{"n":130,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh phản đối những biểu hiện nào trong quan hệ quốc tế?","answer":"B","options":[{"key":"A","text":"Hòa bình, hợp tác, phát triển"},{"key":"B","text":"Dân tộc hẹp hòi, sôvanh, biệt lập, bành trướng bá quyền"},{"key":"C","text":"Độc lập, tự chủ, tự cường"},{"key":"D","text":"Liên minh vì lợi ích chung"}]},{"n":131,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Theo Hồ Chí Minh, tinh thần quốc tế trong sáng phải gắn liền với?","answer":"C","options":[{"key":"A","text":"Tình cảm cá nhân sâu sắc với bạn bè thế giới"},{"key":"B","text":"Chính sách ngoại giao hòa bình của Việt Nam"},{"key":"C","text":"Bản chất cách mạng và khoa học của chủ nghĩa Mác – Lênin"},{"key":"D","text":"Tình cảm tôn giáo và lòng bác ái phổ quát"}]},{"n":132,"sec":"2. Quan điểm của Hồ Chí Minh về những chuẩn mực đạo đức cách mạng","stem":"Hồ Chí Minh luôn kêu gọi tăng cường đoàn kết quốc tế để?","answer":"B","options":[{"key":"A","text":"Mở rộng hợp tác thương mại toàn cầu"},{"key":"B","text":"Thúc đẩy phong trào cách mạng thế giới vì hòa bình, độc lập dân tộc và tiến bộ xã hội"},{"key":"C","text":"Củng cố vị thế chính trị của Việt Nam trên trường quốc tế"},{"key":"D","text":"Nâng cao uy tín của các tổ chức quốc tế"}]},{"n":133,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, nguyên tắc quan trọng bậc nhất trong xây dựng nền đạo đức mới là gì?","answer":"C","options":[{"key":"A","text":"Học đi đôi với hành, lý luận gắn với thực tiễn"},{"key":"B","text":"Sống giản dị, trung thực và nhân ái"},{"key":"C","text":"Nói đi đôi với làm"},{"key":"D","text":"Xây dựng tập thể đoàn kết, thống nhất"}]},{"n":134,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"“Nói đi đôi với làm” thể hiện sự thống nhất giữa điều gì?","answer":"B","options":[{"key":"A","text":"Tư tưởng và hành động của cá nhân"},{"key":"B","text":"Lý luận và thực tiễn trong đạo đức cách mạng"},{"key":"C","text":"Động cơ và kết quả trong giáo dục đạo đức"},{"key":"D","text":"Lời nói và hành vi trong công tác tuyên truyền"}]},{"n":135,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Trong tác phẩm Đường cách mệnh, khi đề cập tư cáchmột người cách mệnh, Hồ Chí Minh yêu cầu?","answer":"C","options":[{"key":"A","text":"Giữ gìn phẩm chất và đạo đức cá nhân"},{"key":"B","text":"Nói ít, làm nhiều, làm đúng lời đã nói"},{"key":"C","text":"“Nói thì phải làm”"},{"key":"D","text":"“Sống trung thực, giản dị, tiết kiệm”"}]},{"n":136,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh cho rằng “đảng viên đi trước, làng nước theo sau” thể hiện nguyên tắc gì?","answer":"C","options":[{"key":"A","text":"Đề cao trách nhiệm nêu gương của cán bộ, đảng viên"},{"key":"B","text":"Tăng cường mối quan hệ giữa Đảng và nhân dân"},{"key":"C","text":"Xây dựng đạo đức xã hội chủ nghĩa"},{"key":"D","text":"Bồi dưỡng đạo đức tập thể"}]},{"n":137,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, “nói đi đôi với làm” đối lập với điều gì?","answer":"B","options":[{"key":"A","text":"Lối sống thực dụng và vụ lợi cá nhân"},{"key":"B","text":"Thói đạo đức giả, nói một đằng làm một nẻo"},{"key":"C","text":"Bệnh chủ nghĩa cá nhân và quan liêu"},{"key":"D","text":"Sự thiếu gương mẫu trong học tập và công tác"}]},{"n":138,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Câu “miệng thì nói dân chủ, nhưng làm việc thì theo lối quan chủ” Hồ Chí Minh dùng để phê phán?","answer":"B","options":[{"key":"A","text":"Cách làm việc bảo thủ và quan liêu"},{"key":"B","text":"Thói đạo đức giả, nói mà không làm"},{"key":"C","text":"Chủ nghĩa cá nhân trong công tác cán bộ"},{"key":"D","text":"Sự yếu kém trong giáo dục đạo đức"}]},{"n":139,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh khẳng định: “Một tấm gương sống còn có giá trị hơn...” điều gì?","answer":"A","options":[{"key":"A","text":"Một trăm bài diễn văn tuyên truyền"},{"key":"B","text":"Một ngàn lời giáo huấn"},{"key":"C","text":"Một kho tàng lý luận cách mạng"},{"key":"D","text":"Một trăm quyển sách đạo đức"}]},{"n":140,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"“Muốn hướng dẫn nhân dân, mình phải làm mực thước cho người ta bắt chước” là luận điểm về?","answer":"B","options":[{"key":"A","text":"Tự tu dưỡng đạo đức cá nhân"},{"key":"B","text":"Nêu gương sáng trong xây dựng đạo đức cách mạng"},{"key":"C","text":"Vai trò của cán bộ trong công tác quần chúng"},{"key":"D","text":"Xây dựng phẩm chất của người lãnh đạo"}]},{"n":141,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Nguyên tắc “xây đi đôi với chống” thể hiện điều gì trong tư tưởng Hồ Chí Minh?","answer":"C","options":[{"key":"A","text":"Sự kiên định giữa lý tưởng đạo đức và hành vi thực tiễn"},{"key":"B","text":"Tinh thần đoàn kết giữa cá nhân và tập thể"},{"key":"C","text":"Tính nhân đạo chiến đấu của đạo đức cách mạng"},{"key":"D","text":"Sự kết hợp giữa đạo đức truyền thống và hiện đại"}]},{"n":142,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, “xây” trong nguyên tắc “xây đi đôi với chống” nghĩa là gì?","answer":"A","options":[{"key":"A","text":"Xây dựng các giá trị và chuẩn mực đạo đức mới"},{"key":"B","text":"Xây dựng cơ chế kiểm soát đạo đức xã hội"},{"key":"C","text":"Xây dựng hệ thống giáo dục và pháp luật nghiêm minh"},{"key":"D","text":"Xây dựng ý thức đạo đức gắn với kỷ luật tổ chức"}]},{"n":143,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"“Chống” trong nguyên tắc “xây đi đôi với chống” nhằm mục đích gì?","answer":"B","options":[{"key":"A","text":"Loại bỏ những tàn dư của xã hội cũ"},{"key":"B","text":"Chống các hành vi vô đạo đức, suy thoái đạo đức"},{"key":"C","text":"Đấu tranh chống các biểu hiện tư tưởng phản cách mạng"},{"key":"D","text":"Ngăn ngừa sự tha hóa trong quản lý xã hội"}]},{"n":144,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, việc giáo dục đạo đức cần gắn liền với?","answer":"C","options":[{"key":"A","text":"Tuyên truyền chính trị và pháp luật nghiêm minh"},{"key":"B","text":"Phát triển khoa học, giáo dục, văn hóa"},{"key":"C","text":"Xây dựng ý thức đạo đức lành mạnh ở mỗi người"},{"key":"D","text":"Thực hành cần, kiệm, liêm, chính trong đời sống"}]},{"n":145,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Người ví việc phát huy cái tốt, hạn chế cái xấu trong con người như?","answer":"B","options":[{"key":"A","text":"Gieo hạt giống thiện lành để trổ hoa"},{"key":"B","text":"Làm cho phần tốt nảy nở như hoa mùa Xuân"},{"key":"C","text":"Đánh thức lương tâm trong sáng của mỗi người"},{"key":"D","text":"Rèn luyện bản thân như mài ngọc cho sáng"}]},{"n":146,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Điền từ còn thiếu vào (_____)? “Đạo đức cách mạng không phải trên trời sa xuống. Nó do (_____), (_____) bền bỉ hằng ngày mà phát triển và củng cố. Cũng như ngọc càng mài càng sáng, vàng càng luyện càng trong” ( Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.11, tr.612.)","answer":"A","options":[{"key":"A","text":"Đấu tranh, rèn luyện"},{"key":"B","text":"Học tập và tu dưỡng"},{"key":"C","text":"Đấu tranh và học tập"},{"key":"D","text":"Rèn luyện và phấn đấu"}]},{"n":147,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Điền từ còn thiếu vào (_____)? “Một dân tộc, một đảng và mỗi con người, ngày hôm qua là vĩ đại, có sức hấp dẫn lớn, không nhất định hôm nay và ngày mai vẫn được mọi người yêu mến và ca ngợi, nếu lòng dạ không trong sáng nữa, nếu sa vào (_____)” ( Hồ Chí Minh: Toàn tập, Nxb Chính trị quốc gia, Hà Nội, 2011, t.15, tr.672).","answer":"A","options":[{"key":"A","text":"Chủ nghĩa cá nhân"},{"key":"B","text":"Tham ô, lãng phí, quan liêu"},{"key":"C","text":"Bệnh hình thức"},{"key":"D","text":"Thói tự mãn và kiêu ngạo cách mạng"}]},{"n":148,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Đâu là chuẩn mực đạo đức cách mạng trong tư tưởng Hồ Chí Minh?","answer":"A","options":[{"key":"A","text":"Trung với nước, hiếu với dân; cần, kiệm, liêm, chính, chí công vô tư; yêu thương con người sống, có tình có nghĩa; có tinh thần quốc tế trong sáng"},{"key":"B","text":"Trung với dân, hiếu với nước; cần, kiệm, liêm, chính, chí công vô tư; yêu thương con người, sống có tình có nghĩa; có tinh thần quốc tế trong sáng"},{"key":"C","text":"Trung với nước, hiếu với dân; cần, kiệm, liêm, chính, chí công vô tư; yêu thương con người, sống có tình có lý; có tinh thần quốc tế trong sáng"},{"key":"D","text":"Trung với dân, hiếu với nước; cần, kiệm, liêm, chính, chí công vô tư; yêu thương con người, sống có tình có lý; có tinh thần quốc tế trong sáng"}]},{"n":149,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh cho rằng: “Học để làm việc, (…), làm cán bộ”","answer":"C","options":[{"key":"A","text":"Làm thầy"},{"key":"B","text":"Làm cách mạng"},{"key":"C","text":"Làm người"},{"key":"D","text":"Làm đầy tớ"}]},{"n":150,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh cho rằng đạo đức cách mạng phải:","answer":"D","options":[{"key":"A","text":"Tự mình tu dưỡng mà thành"},{"key":"B","text":"Tự mình phấn đấu mà thành"},{"key":"C","text":"Tự mình học tập mà thành"},{"key":"D","text":"Tự mình rèn luyện mà thành"}]},{"n":151,"sec":"3. Quan điểm về những nguyên tắc xây dựng đạo đức cách mạng","stem":"Lối sống ích kỷ, chỉ biết có riêng mình, thu vén cho riêng mình, chỉ thấy công lao của mình mà quên công lao của người khác. Theo Hồ Chí Minh là gì?","answer":"A","options":[{"key":"A","text":"Chủ nghĩa cá nhân"},{"key":"B","text":"Chủ nghĩa vị kỷ"},{"key":"C","text":"Chủ nghĩa tư bản"},{"key":"D","text":"Phong cách tiểu tư sản"}]},{"n":152,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Theo Hồ Chí Minh, con người là một chỉnh thể thống nhất của các yếu tố nào?","answer":"B","options":[{"key":"A","text":"Thể lực, đạo đức và trí tuệ"},{"key":"B","text":"Trí lực, tâm lực, thể lực"},{"key":"C","text":"Tư tưởng, tình cảm và hành động"},{"key":"D","text":"Sinh lý, tâm lý và xã hội học"}]},{"n":153,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Hồ Chí Minh giải thích “chữ người” như thế nào?","answer":"C","options":[{"key":"A","text":"Là khái niệm chỉ con người nói chung"},{"key":"B","text":"Nghĩa hẹp là cá nhân, nghĩa rộng là đồng loại"},{"key":"C","text":"Nghĩa hẹp là gia đình, anh em, bè bạn; nghĩa rộng là đồng bào cả nước, rộng hơn nữa là cả loài người"},{"key":"D","text":"Nghĩa hẹp là công dân, nghĩa rộng là dân tộc"}]},{"n":154,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Hồ Chí Minh nhìn nhận con người không phải là con người trừu tượng mà là?","answer":"A","options":[{"key":"A","text":"Con người lịch sử – cụ thể"},{"key":"B","text":"Con người đạo đức – nhân văn"},{"key":"C","text":"Con người tinh thần – tâm linh"},{"key":"D","text":"Con người xã hội – tư tưởng"}]},{"n":155,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Quan niệm “dân dĩ thực vi thiên” của Hồ Chí Minh thể hiện tư tưởng gì?","answer":"C","options":[{"key":"A","text":"Xem dân là gốc của nước"},{"key":"B","text":"Coi dân là lực lượng sản xuất chủ yếu"},{"key":"C","text":"Đề cao yếu tố vật chất, nhu cầu sinh tồn của con người"},{"key":"D","text":"Khẳng định vai trò của kinh tế trong đạo đức xã hội"}]},{"n":156,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Khi giải quyết vấn đề con người, Hồ Chí Minh kết hợp hài hòa giữa hai mối quan hệ nào?","answer":"C","options":[{"key":"A","text":"Dân tộc và nhân loại"},{"key":"B","text":"Dân tộc và tôn giáo"},{"key":"C","text":"Dân tộc và giai cấp"},{"key":"D","text":"Dân tộc và văn hóa"}]},{"n":157,"sec":"1. Quan niệm của Hồ Chí Minh về con người","stem":"Nét đặc sắc trong tư tưởng Hồ Chí Minh về con người là gì?","answer":"C","options":[{"key":"A","text":"Kết hợp giữa yếu tố sinh học và xã hội trong con người"},{"key":"B","text":"Xem con người là chủ thể sáng tạo lịch sử"},{"key":"C","text":"Nhìn nhận con người Việt Nam trong hoàn cảnh lịch sử, xã hội cụ thể, gắn với dân tộc và giai cấp"},{"key":"D","text":"Đặt con người ở trung tâm của mọi học thuyết triết học"}]},{"n":158,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Theo Hồ Chí Minh, con người là gì trong sự nghiệp cách mạng?","answer":"B","options":[{"key":"A","text":"Là công cụ của cách mạng"},{"key":"B","text":"Là mục tiêu và động lực của cách mạng"},{"key":"C","text":"Là sản phẩm của cách mạng"},{"key":"D","text":"Là yếu tố phụ thuộc vào hoàn cảnh"}]},{"n":159,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Mục tiêu “con người là trung tâm” được Hồ Chí Minh cụ thể hóa trong mấy giai đoạn cách mạng?","answer":"B","options":[{"key":"A","text":"Hai giai đoạn"},{"key":"B","text":"Ba giai đoạn"},{"key":"C","text":"Bốn giai đoạn"},{"key":"D","text":"Năm giai đoạn"}]},{"n":160,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Giải phóng dân tộc theo Hồ Chí Minh là?","answer":"C","options":[{"key":"A","text":"Giải phóng giai cấp công nhân"},{"key":"B","text":"Giải phóng con người khỏi đói nghèo"},{"key":"C","text":"Xóa bỏ ách thống trị của chủ nghĩa đế quốc, giành độc lập dân tộc"},{"key":"D","text":"Giành chính quyền về tay công nông"}]},{"n":161,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Giải phóng xã hội theo tư tưởng Hồ Chí Minh là?","answer":"B","options":[{"key":"A","text":"Xóa bỏ giai cấp và tư hữu"},{"key":"B","text":"Xây dựng xã hội không có người bóc lột người, mọi người làm chủ và hạnh phúc"},{"key":"C","text":"Xây dựng xã hội dân chủ nhân dân"},{"key":"D","text":"Giải phóng sản xuất khỏi ràng buộc phong kiến"}]},{"n":162,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Giải phóng con người theo Hồ Chí Minh là gì?","answer":"B","options":[{"key":"A","text":"Giải phóng cá nhân khỏi cám dỗ vật chất"},{"key":"B","text":"Xóa bỏ mọi áp bức, bóc lột, tha hóa; phát huy năng lực sáng tạo và tự do của con người"},{"key":"C","text":"Giải phóng trí tuệ và tinh thần"},{"key":"D","text":"Giải phóng lao động khỏi sự lệ thuộc tư bản"}]},{"n":163,"sec":"2. Quan điểm của Hồ Chí Minh về vai trò của con người","stem":"Điền từ còn thiếu vào (_____)? Theo Hồ Chí Minh, (_____) là vốn quý nhất, động lực, nhân tố quyết định thành công của sự nghiệp cách mạng.","answer":"B","options":[{"key":"A","text":"Nhân dân"},{"key":"B","text":"Con người"},{"key":"C","text":"Cán bộ"},{"key":"D","text":"Giai cấp công nhân"}]},{"n":164,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Theo Hồ Chí Minh, xây dựng con người là yêu cầu như thế nào của sự nghiệp cách mạng?","answer":"C","options":[{"key":"A","text":"Ngắn hạn và trước mắt"},{"key":"B","text":"Thuộc lĩnh vực giáo dục riêng biệt"},{"key":"C","text":"Vừa cấp bách vừa lâu dài, có ý nghĩa chiến lược"},{"key":"D","text":"Là nhiệm vụ của thời kỳ hòa bình"}]},{"n":165,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Hồ Chí Minh khẳng định: “Vì lợi ích trăm năm thì phải (_____)”.","answer":"B","options":[{"key":"A","text":"Dạy học"},{"key":"B","text":"Trồng người"},{"key":"C","text":"Bồi dưỡng nhân tài"},{"key":"D","text":"Xây dựng xã hội"}]},{"n":166,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Theo Hồ Chí Minh, “trồng người” là công việc của lĩnh vực nào?","answer":"C","options":[{"key":"A","text":"Chính trị"},{"key":"B","text":"Kinh tế"},{"key":"C","text":"Văn hóa – giáo dục"},{"key":"D","text":"Xã hội học"}]},{"n":167,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Hồ Chí Minh nhấn mạnh: “Muốn xây dựng chủ nghĩa xã hội, trước hết cần phải có (_____)”?","answer":"B","options":[{"key":"A","text":"Nền tảng kinh tế xã hội chủ nghĩa"},{"key":"B","text":"Con người xã hội chủ nghĩa"},{"key":"C","text":"Đảng cách mạng kiểu mới"},{"key":"D","text":"Giai cấp công nhân tiên phong"}]},{"n":168,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Theo Hồ Chí Minh, con người xã hội chủ nghĩa có đặc điểm nổi bật nào sau đây?","answer":"A","options":[{"key":"A","text":"Có lý tưởng, đạo đức, lối sống, tác phong xã hội chủ nghĩa"},{"key":"B","text":"Có tri thức sâu rộng về khoa học tự nhiên"},{"key":"C","text":"Có khả năng lãnh đạo chính trị"},{"key":"D","text":"Có tài năng nghệ thuật và sáng tạo"}]},{"n":169,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Khi nói “trước hết cần có những con người xã hội chủ nghĩa”, Hồ Chí Minh muốn nhấn mạnh đến?","answer":"A","options":[{"key":"A","text":"Vai trò của những cá nhân tiên phong, làm gương, lôi cuốn quần chúng"},{"key":"B","text":"Sự phát triển đồng đều của xã hội"},{"key":"C","text":"Vai trò của Đảng và Nhà nước"},{"key":"D","text":"Tầm quan trọng của giáo dục tập thể"}]},{"n":170,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Nội dung xây dựng con người toàn diện theo Hồ Chí Minh là con người?","answer":"B","options":[{"key":"A","text":"Có tri thức và thể lực khỏe mạnh"},{"key":"B","text":"Vừa “hồng” vừa “chuyên”"},{"key":"C","text":"Có năng lực chuyên môn sâu"},{"key":"D","text":"Có đạo đức tôn giáo thuần túy"}]},{"n":171,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"“Hồng” và “chuyên” trong tư tưởng Hồ Chí Minh về con người toàn diện được hiểu là?","answer":"A","options":[{"key":"A","text":"Đức và tài"},{"key":"B","text":"Chính trị và văn hóa"},{"key":"C","text":"Lao động và học tập"},{"key":"D","text":"Lý luận và thực tiễn"}]},{"n":172,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Hồ Chí Minh yêu cầu xây dựng con người có tinh thần tập thể xã hội chủ nghĩa với tư tưởng?","answer":"B","options":[{"key":"A","text":"“Cá nhân trên hết, tập thể vì cá nhân”"},{"key":"B","text":"“Một người vì mọi người, mọi người vì mình”"},{"key":"C","text":"“Làm theo năng lực, hưởng theo nhu cầu”"},{"key":"D","text":"“Mỗi người vì mình, tất cả vì lợi ích chung”"}]},{"n":173,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Theo Hồ Chí Minh, yếu tố nào được đặc biệt chú trọng trong việc xây dựng con người mới?","answer":"A","options":[{"key":"A","text":"Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân"},{"key":"B","text":"Nâng cao trình độ sản xuất"},{"key":"C","text":"Xây dựng nền kinh tế tập thể"},{"key":"D","text":"Phát triển năng lực quản lý xã hội"}]},{"n":174,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Một trong những phương pháp quan trọng để xây dựng con người theo Hồ Chí Minh là?","answer":"B","options":[{"key":"A","text":"Tuyên truyền lý luận cách mạng"},{"key":"B","text":"Tự rèn luyện, tu dưỡng kết hợp với nêu gương"},{"key":"C","text":"Thi đua sản xuất đạt năng suất cao"},{"key":"D","text":"Cải tạo bằng pháp luật"}]},{"n":175,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Hồ Chí Minh thường nói: “Tu thân, chính tâm thì mới có thể (_____)”.","answer":"A","options":[{"key":"A","text":"Trị quốc, bình thiên hạ"},{"key":"B","text":"Đem lại hạnh phúc cho bản thân"},{"key":"C","text":"Làm gương cho người khác"},{"key":"D","text":"Giúp ích cho xã hội"}]},{"n":176,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Theo Hồ Chí Minh, “một tấm gương sống có giá trị hơn”?","answer":"C","options":[{"key":"A","text":"Một khóa học lý luận chính trị"},{"key":"B","text":"Mười lời khuyên đạo đức"},{"key":"C","text":"Một trăm bài diễn văn tuyên truyền"},{"key":"D","text":"Một bài học kinh nghiệm"}]},{"n":177,"sec":"3. Quan điểm của Hồ Chí Minh về xây dựng con người","stem":"Hồ Chí Minh cho rằng “hiền, dữ của con người không phải là tính sẵn. Phần nhiều do (_____) mà nên.”","answer":"A","options":[{"key":"A","text":"Giáo dục"},{"key":"B","text":"Môi trường xã hội"},{"key":"C","text":"Di truyền"},{"key":"D","text":"Rèn luyện cá nhân"}]},{"n":178,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Nghị quyết Hội nghị Trung ương 5 khóa VIII (7-1998) xác định văn hóa là gì trong đời sống xã hội?","answer":"B","options":[{"key":"A","text":"Là một bộ phận của đời sống tinh thần, có tác dụng bổ trợ cho kinh tế"},{"key":"B","text":"Là nền tảng tinh thần của xã hội, vừa là mục tiêu vừa là động lực phát triển"},{"key":"C","text":"Là lĩnh vực sáng tạo nghệ thuật phản ánh đời sống xã hội"},{"key":"D","text":"Là công cụ tuyên truyền, cổ động cho chính trị và kinh tế"}]},{"n":179,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Theo Cương lĩnh 2011, nền văn hóa Việt Nam cần được xây dựng theo định hướng nào?","answer":"B","options":[{"key":"A","text":"Hiện đại hóa nhanh chóng, hội nhập toàn cầu, đề cao tính cá nhân sáng tạo"},{"key":"B","text":"Tiên tiến, đậm đà bản sắc dân tộc, phát triển toàn diện, thấm nhuần tinh thần nhân văn, dân chủ, tiến bộ"},{"key":"C","text":"Đậm chất truyền thống, hạn chế tiếp thu yếu tố ngoại lai"},{"key":"D","text":"Gắn liền với công nghiệp hóa, lấy kinh tế làm trung tâm duy nhất"}]},{"n":180,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Cương lĩnh 2011 khẳng định: Con người là gì trong chiến lược phát triển?","answer":"B","options":[{"key":"A","text":"Là công cụ để đạt mục tiêu phát triển xã hội."},{"key":"B","text":"Là trung tâm của chiến lược phát triển, đồng thời là chủ thể phát triển"},{"key":"C","text":"Là đối tượng thụ hưởng thành quả của công nghiệp hóa"},{"key":"D","text":"Là nguồn lao động trong nền kinh tế tri thức"}]},{"n":181,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Nhiệm vụ xây dựng con người Việt Nam theo Hội nghị Trung ương 5 khóa VIII là gì?","answer":"C","options":[{"key":"A","text":"Xây dựng con người Việt Nam có lối sống hiện đại, năng động, hội nhập"},{"key":"B","text":"Hình thành con người Việt Nam với ý thức tiêu dùng văn minh, thân thiện môi trường"},{"key":"C","text":"Xây dựng con người Việt Nam có tinh thần yêu nước, tự cường dân tộc, lối sống lành mạnh, cần kiệm, trung thực, nhân nghĩa"},{"key":"D","text":"Đào tạo con người Việt Nam thành lao động kỹ thuật cao trong nền kinh tế mở"}]},{"n":182,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Đại hội XII của Đảng (2016) xác định nhiệm vụ hàng đầu trong xây dựng văn hóa, con người là gì?","answer":"A","options":[{"key":"A","text":"Xây dựng con người Việt Nam phát triển toàn diện, hướng đến chân – thiện – mỹ"},{"key":"B","text":"Phát triển công nghiệp văn hóa và thị trường văn hóa"},{"key":"C","text":"Cải thiện đời sống vật chất – tinh thần của nhân dân"},{"key":"D","text":"Đổi mới công tác quản lý báo chí, xuất bản"}]},{"n":183,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Mục tiêu cuối cùng của xây dựng văn hóa, con người theo Đại hội XII là gì?","answer":"B","options":[{"key":"A","text":"Tạo ra một nền văn hóa thống nhất, khép kín, đậm đặc tính dân tộc."},{"key":"B","text":"Vì mục tiêu “dân giàu, nước mạnh, dân chủ, công bằng, văn minh”"},{"key":"C","text":"Đưa Việt Nam trở thành quốc gia phát triển, hội nhập toàn cầu"},{"key":"D","text":"Nâng cao đời sống vật chất, tinh thần cho toàn dân"}]},{"n":184,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Theo tư tưởng Hồ Chí Minh, văn hóa phải đóng vai trò như thế nào trong phát triển xã hội?","answer":"D","options":[{"key":"A","text":"Là phương tiện để củng cố niềm tin của nhân dân vào Đảng"},{"key":"B","text":"Là công cụ phục vụ công nghiệp hóa, hiện đại hóa"},{"key":"C","text":"Là bộ phận phụ trợ cho chính trị và kinh tế"},{"key":"D","text":"Là nền tảng tinh thần, là động lực nội sinh của sự phát triển"}]},{"n":185,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Hội nghị Trung ương 9 khóa XI (2014) nêu rõ mục tiêu xây dựng con người Việt Nam như thế nào?","answer":"A","options":[{"key":"A","text":"Phát triển con người toàn diện, hướng đến các giá trị chân – thiện – mỹ"},{"key":"B","text":"Hình thành con người lao động sáng tạo, năng động, hội nhập quốc tế"},{"key":"C","text":"Bồi dưỡng con người có ý thức công dân và trách nhiệm xã hội"},{"key":"D","text":"Xây dựng con người mới xã hội chủ nghĩa trong thời kỳ hội nhập"}]},{"n":186,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"“Văn hóa còn thì chế độ còn” thể hiện mối quan hệ nào?","answer":"A","options":[{"key":"A","text":"Giữa văn hóa với chính trị và kinh tế"},{"key":"B","text":"Giữa văn hóa với quốc phòng, an ninh"},{"key":"C","text":"Giữa văn hóa với giáo dục và truyền thông"},{"key":"D","text":"Giữa văn hóa với môi trường và xã hội"}]},{"n":187,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Để phát triển bền vững, vai trò của văn hóa cần được hiểu như thế nào?","answer":"D","options":[{"key":"A","text":"Là yếu tố hỗ trợ quá trình hội nhập quốc tế"},{"key":"B","text":"Là công cụ mềm để quảng bá hình ảnh quốc gia"},{"key":"C","text":"Là hoạt động tinh thần song song với kinh tế"},{"key":"D","text":"Là sức mạnh nội sinh quan trọng bảo đảm sự phát triển bền vững"}]},{"n":188,"sec":"1. Xây dựng và phát triển văn hóa, con người","stem":"Một trong các nhiệm vụ cụ thể Đại hội XII nêu ra là gì?","answer":"B","options":[{"key":"A","text":"Xây dựng phong trào thi đua yêu nước trong văn nghệ sĩ"},{"key":"B","text":"Xây dựng môi trường văn hóa lành mạnh, phù hợp với phát triển kinh tế thị trường"},{"key":"C","text":"Phát triển du lịch văn hóa thành ngành kinh tế mũi nhọn"},{"key":"D","text":"Mở rộng hợp tác quốc tế trong lĩnh vực xuất bản"}]},{"n":189,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Đạo đức Hồ Chí Minh được mô tả là:","answer":"A","options":[{"key":"A","text":"Đạo đức của bậc “đại nhân, đại trí, đại dũng”, của một lãnh tụ cách mạng, một người cộng sản ưu tú"},{"key":"B","text":"Đạo đức chỉ của tầng lớp tri thức, không phổ biến cho mọi người dân"},{"key":"C","text":"Đạo đức mang tính truyền thống cổ xưa, chỉ gói gọn trong nghi lễ và lễ nghĩa"},{"key":"D","text":"Đạo đức học thuật, chủ yếu phục vụ nghiên cứu khoa học và giáo dục"}]},{"n":190,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, muốn vươn tới sự hoàn thiện bản thân, con người phải?","answer":"A","options":[{"key":"A","text":"Tự tu dưỡng hoàn thiện mình về đạo đức"},{"key":"B","text":"Chỉ tập trung vào học tập và nghiên cứu kỹ năng nghề nghiệp"},{"key":"C","text":"Phụ thuộc hoàn toàn vào môi trường và hoàn cảnh sống để định hình nhân cách"},{"key":"D","text":"Dựa vào tiền bạc và quyền lực để chứng minh giá trị bản thân"}]},{"n":191,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh từng dạy về đạo đức thanh niên rằng?","answer":"A","options":[{"key":"A","text":"“Thanh niên phải có đức, có tài”"},{"key":"B","text":"“Thanh niên chỉ cần học để giàu sang”"},{"key":"C","text":"“Thanh niên không cần lý tưởng, chỉ cần sức khỏe”"},{"key":"D","text":"“Thanh niên chỉ chú ý đến danh vọng cá nhân”"}]},{"n":192,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, thế hệ trẻ là?","answer":"A","options":[{"key":"A","text":"Người chủ tương lai của nước nhà, góp phần quyết định sự thịnh hay suy của đất nước"},{"key":"B","text":"Chỉ là lực lượng hỗ trợ cho người già, không cần có trách nhiệm chính trị"},{"key":"C","text":"Chỉ quan tâm đến lợi ích cá nhân, không liên quan vận mệnh quốc gia"},{"key":"D","text":"Là nhóm chịu ảnh hưởng hoàn toàn từ phương Tây và chủ nghĩa tiêu dùng"}]},{"n":193,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Học tập và làm theo đạo đức Hồ Chí Minh là nhằm?","answer":"C","options":[{"key":"A","text":"Chỉ phục vụ mục đích kinh tế và lợi ích riêng"},{"key":"B","text":"“Thanh niên chỉ cần học để giàu sang”"},{"key":"C","text":"Làm cho mỗi người trở thành công dân tốt hơn, biết trọng danh dự và trách nhiệm"},{"key":"D","text":"Thể hiện quyền lực chính trị và địa vị xã hội"}]},{"n":194,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Trong nền kinh tế thị trường và hội nhập quốc tế, đạo đức mới hình thành là?","answer":"A","options":[{"key":"A","text":"Nguồn động lực quan trọng thúc đẩy sự phát triển đất nước"},{"key":"B","text":"Chỉ mang tính biểu tượng, không ảnh hưởng thực chất tới hành vi con người"},{"key":"C","text":"Là đạo đức bị chi phối hoàn toàn bởi lợi ích vật chất"},{"key":"D","text":"Không cần thiết vì thị trường tự điều chỉnh mọi vấn đề"}]},{"n":195,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Theo Hồ Chí Minh, đức khiêm tốn là?","answer":"A","options":[{"key":"A","text":"Một đạo đức mà mọi người cách mạng phải luôn trau dồi, không tự mãn, không kiêu ngạo"},{"key":"B","text":"Một phẩm chất không quan trọng, chỉ cần trình độ chuyên môn"},{"key":"C","text":"Chỉ áp dụng cho quan chức, không áp dụng cho thanh niên"},{"key":"D","text":"Chỉ là hình thức lễ nghi, không ảnh hưởng đời sống thực tiễn"}]},{"n":196,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Trung thực trong tư tưởng đạo đức Hồ Chí Minh là?","answer":"B","options":[{"key":"A","text":"Chỉ cần trung thực với bản thân, không cần với dân và xã hội"},{"key":"B","text":"Phẩm chất cao quý của người cộng sản, gắn liền với trách nhiệm công việc"},{"key":"C","text":"Chỉ là tuân thủ luật pháp mà không cần đạo đức"},{"key":"D","text":"Chỉ là một khái niệm hình thức, không có giá trị thực tế"}]},{"n":197,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Hồ Chí Minh dạy về trách nhiệm rằng?","answer":"C","options":[{"key":"A","text":"Chỉ cần thực hiện trách nhiệm khi có lợi cho cá nhân"},{"key":"B","text":"Tránh nhận trách nhiệm trong mọi trường hợp để bảo toàn quyền lợi"},{"key":"C","text":"Trước hết là trách nhiệm với Tổ quốc, Đảng, nhân dân, sau đó là bản thân và gia đình"},{"key":"D","text":"Chỉ cần trách nhiệm hình thức, không thực hiện thực chất"}]},{"n":198,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Tình thương yêu con người trong đạo đức Hồ Chí Minh gắn liền với?","answer":"A","options":[{"key":"A","text":"Niềm tin tuyệt đối vào sức mạnh và trí tuệ của nhân dân"},{"key":"B","text":"Chỉ quan tâm gia đình, không cần xã hội"},{"key":"C","text":"Thể hiện quyền lực và uy quyền cá nhân"},{"key":"D","text":"Duy trì khoảng cách với nhân dân để giữ địa vị"}]},{"n":199,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Đề cập tới những phẩm chất đạo đức mà sinh viên cần phải rèn luyện để đạt được, Hồ Chí Minh đã khái quát trong “sáu cái yêu”. Sáu cái yêu đó là gì?","answer":"A","options":[{"key":"A","text":"Yêu Tổ quốc, yêu nhân dân, yêu chủ nghĩa xã hội, yêu lao động, yêu khoa học và kỷ luật"},{"key":"B","text":"Yêu Tổ quốc, yêu nông dân, yêu chủ nghĩa xã hội, yêu lao động, yêu khoa học và kỹ thuật"},{"key":"C","text":"Yêu Tổ quốc, yêu đồng bào, yêu chủ nghĩa xã hội, yêu lao động, yêu khoa học và kỷ luật"},{"key":"D","text":"Yêu Tổ quốc, yêu nhân dân, yêu chế độ mới, yêu lao động, yêu khoa học và kỷ luật"}]},{"n":200,"sec":"2. Xây dựng đạo đức cách mạng","stem":"Đối với Hồ Chí Minh, dân ta tài năng, trí tuệ và sáng tạo, họ biết giải quyết nhiều vấn đề một cách giản đơn, mau chóng, đầy đủ mà những người tài giỏi, những đoàn thể to lớn,…”?","answer":"A","options":[{"key":"A","text":"Nghĩ mãi không ra"},{"key":"B","text":"Nghĩ mãi mới ra"},{"key":"C","text":"Làm mãi không được"},{"key":"D","text":"Làm mãi mới được"}]}]}]};
